    qty_safety = fields.Float(string="Qty Safety", tracking=True)
    qty_maximum = fields.Float(string="Qty Maximum", tracking=True)
    default_supplier_id = fields.Many2one('res.partner',string='Default Supplier', tracking=True)
    default_pack_id = fields.Many2one('eproc.pack',string='Default Pack', tracking=True)
    default_purchase_type_id = fields.Many2one('eproc.type', string='Default Procurement Type', tracking=True)
    default_approval_type_id = fields.Many2one('eproc.approval.type', string='Default Approval Type', tracking=True)
    default_user_id = fields.Many2one('res.users', string='Default Responsible', tracking=True)
