class EprocStockQuant(models.Model):
    _name = 'eproc.stock.quant'
    _description = 'E-Proc Stock Quant'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'product_tmpl_id'


    sync_type = sync.type
    sync_date = sync.date
    sync_id = sync.id
    sync_id_api = sync.id_api
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date
    calculated_date = fields.Datetime(string='Calculated Date', readonly=True)
    product_tmpl_id = fields.Many2one('product.template', string='Product', readonly=True)
    category_id = fields.Many2one('product.category', string='Category', related='product_tmpl_id.categ_id', readonly=True)
    uom_id = fields.Many2one('uom.uom', string='UoM', related='product_tmpl_id.uom_id', readonly=True)
    uom_quantity = fields.Float(string='UoM Quantity', readonly=True)
    location_id = fields.Many2one('stock.location', string='Location', readonly=True)
    lot_id = fields.Many2one('eproc.stock.lot', string='Batch No', readonly=True)
    company_id = fields.Many2one('res.company', string='Company', readonly=True)
    quantity = fields.Float(string="Quantity", readonly=True)
    active = fields.Boolean(string='Active', default=True, readonly=True)
    cost_unit = fields.Float(string='Cost Unit', readonly=True)
    cost_total = fields.Float(string='Cost Total', readonly=True)

    _sql_constraints = [
        (
            'eproc_stock_quant_key_uniq',
            'unique(company_id, product_tmpl_id, location_id, lot_id)',
            'Stock quant must be unique by company, product, location, and lot.',
        ),
    ]

    @api.model_create_multi
    def create(self, vals_list):
        if not self.env.context.get('from_system'):
            raise UserError(_('Stock quant records are calculated by the system only.'))
        return super().create(vals_list)

    def write(self, vals):
        if not self.env.context.get('from_system'):
            raise UserError(_('Stock quant records cannot be edited manually.'))
        return super().write(vals)

    def unlink(self):
        raise UserError(_('Stock quant records cannot be deleted.'))

    def _move_quantity_delta(self, move):
        quantity = move.uom_quantity or 0.0
        if move.move_type == 'GOODS_RECEIVE':
            return abs(quantity)
        if move.move_type == 'GOODS_RETURN':
            return -abs(quantity)
        return quantity

    def _update_from_stock_move(self, move):
        if move.state != 'done' or not move.active:
            return self.env['eproc.stock.quant']
        if not move.company_id or not move.product_tmpl_id or not move.location_id:
            raise UserError(_('Company, product, and location are required to update Stock Quant.'))

        Quant = self.sudo().with_context(from_system=True)
        domain = [
            ('active', '=', True),
            ('company_id', '=', move.company_id.id),
            ('product_tmpl_id', '=', move.product_tmpl_id.id),
            ('location_id', '=', move.location_id.id),
            ('lot_id', '=', move.lot_id.id if move.lot_id else False),
        ]
        quant = Quant.search(domain, limit=1)
        delta = self._move_quantity_delta(move)
        rounding = move.uom_id.rounding if move.uom_id else 0.01
        now = fields.Datetime.now()
        if quant:
            new_qty = (quant.uom_quantity or 0.0) + delta
            values = {
                'uom_quantity': 0.0 if float_is_zero(new_qty, precision_rounding=rounding) else new_qty,
                'calculated_date': now,
            }
            if 'quantity' in quant._fields:
                values['quantity'] = values['uom_quantity']
            quant.write(values)
            return quant

        create_qty = 0.0 if float_is_zero(delta, precision_rounding=rounding) else delta
        values = {
            'company_id': move.company_id.id,
            'product_tmpl_id': move.product_tmpl_id.id,
            'location_id': move.location_id.id,
            'lot_id': move.lot_id.id if move.lot_id else False,
            'uom_quantity': create_qty,
            'calculated_date': now,
            'active': True,
        }
        if 'quantity' in Quant._fields:
            values['quantity'] = create_qty
        return Quant.create(values)

    @api.model
    def _apply_stock_moves(self, moves):
        quants = self.env['eproc.stock.quant']
        for move in moves.filtered(lambda rec: rec.state == 'done' and rec.active):
            quants |= self._update_from_stock_move(move)
        return quants

    @api.model
    def action_recompute_from_done_moves(self):
        Quant = self.sudo().with_context(from_system=True)
        now = fields.Datetime.now()
        reset_values = {
            'uom_quantity': 0.0,
            'calculated_date': now,
        }
        if 'quantity' in self._fields:
            reset_values['quantity'] = 0.0
        Quant.search([('active', '=', True)]).write(reset_values)

        moves = self.env['eproc.stock.move'].sudo().search([
            ('active', '=', True),
            ('state', '=', 'done'),
        ], order='id')
        self._apply_stock_moves(moves)
        return len(moves)

    @api.model
    def _update_eproc_stock_quant(self, line, qty_delta):
        receipt = line.receipt_id
        rounding = line.uom_id.rounding if line.uom_id else 0.01
        Quant = self.sudo().with_context(from_system=True)
        eproc_lot = line.lot_id.sudo() if line.lot_id else False
        domain = [
            ('active', '=', True),
            ('product_tmpl_id', '=', line.product_tmpl_id.id),
            ('location_id', '=', receipt.location_receipt_id.id),
            ('lot_id', '=', eproc_lot.id if eproc_lot else False),
            ('company_id', '=', receipt.company_id.id),
        ]
        quant = Quant.search(domain, limit=1)
        now = fields.Datetime.now()
        if quant:
            current_qty = quant.uom_quantity or 0.0
            if float_is_zero(current_qty, precision_rounding=rounding) and 'quantity' in quant._fields:
                current_qty = quant.quantity or 0.0
            new_qty = current_qty + qty_delta
            if float_compare(new_qty, 0.0, precision_rounding=rounding) < 0:
                raise UserError(_('Stock quant cannot become negative for %s.') % line.product_tmpl_id.display_name)
            values = {
                'uom_quantity': 0.0 if float_is_zero(new_qty, precision_rounding=rounding) else new_qty,
                'calculated_date': now,
            }
            if 'quantity' in quant._fields:
                values['quantity'] = values['uom_quantity']
            quant.write(values)
            return quant
        if float_compare(qty_delta, 0.0, precision_rounding=rounding) < 0:
            raise UserError(
                _('Return cannot reduce stock because no quant exists for %s.') % line.product_tmpl_id.display_name)
        create_qty = 0.0 if float_is_zero(qty_delta, precision_rounding=rounding) else qty_delta
        values = {
            'product_tmpl_id': line.product_tmpl_id.id,
            'location_id': receipt.location_receipt_id.id,
            'lot_id': eproc_lot.id if eproc_lot else False,
            'company_id': receipt.company_id.id,
            'uom_quantity': create_qty,
            'calculated_date': now,
            'active': True,
        }
        if 'quantity' in Quant._fields:
            values['quantity'] = create_qty
        return Quant.create(values)



class EprocStockInventory(models.Model):
    _name = 'eproc.stock.inventory'
    _description = 'E-Proc Stock Valuation'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _check_company_auto = True

    _CALCULATION_BATCH_SIZE = 1000

    sync_type = sync.type
    sync_date = sync.date
    sync_id = sync.id
    sync_id_api = sync.id_api
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date
    calculated_date = fields.Datetime(string='Calculated Date', readonly=True)
    cutoff_date = fields.Date(string='Cutoff Date', readonly=True, required=True, index=True)
    product_tmpl_id = fields.Many2one('product.template', string='Product', readonly=True, required=True, index=True)
    category_id = fields.Many2one('product.category', related='product_tmpl_id.item_category_id', string='Item Category', readonly=True, store=True, index=True)
    value_type = fields.Selection(related='product_tmpl_id.value_type', string='Value Type', readonly=True)
    medical_type = fields.Selection(related='product_tmpl_id.medical_type', string='Medical Type', readonly=True)
    uom_id = fields.Many2one('uom.uom', string='UoM', related='product_tmpl_id.uom_id', readonly=True)
    uom_quantity = fields.Float(string='UoM Quantity', readonly=True, digits='Product Unit of Measure')
    cost_unit = fields.Float(string='Cost Unit', readonly=True)
    cost_total = fields.Float(string='Cost Total', readonly=True)
    location_id = fields.Many2one('stock.location', string='Location', readonly=True, required=True, index=True, check_company=True)
    lot_id = fields.Many2one('eproc.stock.lot', string='Batch No', readonly=True, index=True, check_company=True)
    company_id = fields.Many2one('res.company', string='Company', readonly=True, required=True, default=lambda self: self.env.company, index=True)
    active = fields.Boolean(string='Active', default=True, readonly=True)

    @api.model_create_multi
    def create(self, vals_list):
        if not (self.env.context.get('from_system') or self.env.context.get('inventory_calculation')):
            raise UserError(_('Stock valuation records are calculated by the system only.'))
        return super().create(vals_list)

    def write(self, vals):
        if not (self.env.context.get('from_system') or self.env.context.get('inventory_calculation')):
            raise UserError(_('Stock valuation records cannot be edited manually.'))
        return super().write(vals)

    def unlink(self):
        if not (self.env.context.get('from_system') or self.env.context.get('inventory_calculation')):
            raise UserError(_('Stock valuation records cannot be deleted manually.'))
        return super().unlink()

    def copy(self, default=None):
        raise UserError(_('Stock valuation records cannot be duplicated.'))

    @api.model
    def action_calculation(self, cutoff_date, company_id=None, force=False):
        if not cutoff_date:
            raise UserError(_('Cutoff Date is required.'))
        company = self.env['res.company'].browse(company_id) if company_id else self.env.company
        if not company:
            raise UserError(_('Company is required.'))

        cutoff = fields.Date.to_date(cutoff_date)
        existing_domain = [
            ('active', '=', True),
            ('company_id', '=', company.id),
            ('cutoff_date', '=', cutoff),
        ]
        Inventory = self.sudo().with_context(inventory_calculation=True, from_system=True)
        if force or self.env.context.get('force_recompute'):
            stale = Inventory.search(existing_domain)
            for offset in range(0, len(stale), self._CALCULATION_BATCH_SIZE):
                stale[offset:offset + self._CALCULATION_BATCH_SIZE].unlink()
                self.env.invalidate_all()
        else:
            existing = Inventory.search(existing_domain, limit=1)
            if existing:
                return Inventory.search_count(existing_domain)

        cutoff_end = datetime.combine(cutoff, time(23, 59, 59))

        # Aggregate in PostgreSQL to avoid loading all stock moves into memory.
        self.env.cr.execute("""
            SELECT m.company_id,
                   m.product_tmpl_id,
                   m.location_id,
                   m.lot_id,
                   CAST(SUM(COALESCE(m.uom_quantity, 0.0)) AS double precision) AS quantity,
                   CAST(SUM(COALESCE(m.cost_total, 0.0)) AS double precision) AS cost_total
              FROM eproc_stock_move m
             WHERE m.active = TRUE
               AND m.state = 'done'
               AND m.company_id = %s
               AND m.move_datetime <= %s
               AND m.product_tmpl_id IS NOT NULL
               AND m.location_id IS NOT NULL
             GROUP BY m.company_id, m.product_tmpl_id, m.location_id, m.lot_id
        """, [company.id, cutoff_end])
        grouped = {
            (company_key, product_id, location_id, lot_id or False): {
                'quantity': quantity or 0.0,
                'cost_total': cost_total or 0.0,
                'latest_cost_unit': 0.0,
            }
            for company_key, product_id, location_id, lot_id, quantity, cost_total
            in self.env.cr.fetchall()
        }

        self.env.cr.execute("""
            SELECT DISTINCT ON (m.company_id, m.product_tmpl_id, m.location_id, m.lot_id)
                   m.company_id,
                   m.product_tmpl_id,
                   m.location_id,
                   m.lot_id,
                   m.cost_unit
              FROM eproc_stock_move m
             WHERE m.active = TRUE
               AND m.state = 'done'
               AND m.company_id = %s
               AND m.move_datetime <= %s
               AND m.product_tmpl_id IS NOT NULL
               AND m.location_id IS NOT NULL
               AND m.cost_unit IS NOT NULL
               AND m.cost_unit != 0.0
             ORDER BY m.company_id, m.product_tmpl_id, m.location_id, m.lot_id,
                      m.move_datetime DESC, m.id DESC
        """, [company.id, cutoff_end])
        for company_key, product_id, location_id, lot_id, cost_unit in self.env.cr.fetchall():
            bucket = grouped.get((company_key, product_id, location_id, lot_id or False))
            if bucket:
                bucket['latest_cost_unit'] = cost_unit or 0.0

        values_list = []
        now = fields.Datetime.now()
        for (company_key, product_id, location_id, lot_id), values in grouped.items():
            quantity = values['quantity']
            if float_is_zero(quantity, precision_rounding=0.000001):
                continue
            cost_total = values['cost_total']
            if float_is_zero(cost_total, precision_rounding=0.000001) and values['latest_cost_unit']:
                cost_total = quantity * values['latest_cost_unit']
            cost_unit = cost_total / quantity if not float_is_zero(quantity, precision_rounding=0.000001) else 0.0
            values_list.append({
                'calculated_date': now,
                'cutoff_date': cutoff,
                'product_tmpl_id': product_id,
                'uom_quantity': quantity,
                'cost_unit': cost_unit,
                'cost_total': cost_total,
                'location_id': location_id,
                'lot_id': lot_id,
                'company_id': company_key,
                'active': True,
            })
        if values_list:
            # Skip chatter for system-generated valuation rows.
            Inventory = Inventory.with_context(
                tracking_disable=True,
                mail_notrack=True,
                mail_create_nolog=True,
                mail_create_nosubscribe=True,
            )
            for offset in range(0, len(values_list), self._CALCULATION_BATCH_SIZE):
                Inventory.create(values_list[offset:offset + self._CALCULATION_BATCH_SIZE])
                self.env.invalidate_all()
        return len(values_list)


