class ProductTemplate(models.Model):
    _inherit = 'product.template'

    def _requires_medical_equipment_budget(self):
        """Classify by the assigned Item Category, never by stock/procurement type.

        Master data owns the category. No database ID, inferred category code,
        translated display name, substring or ancestor matching is involved.
        """
        self.ensure_one()
        category = self.item_category_id.with_context(lang=False)
        return bool(category and ' '.join((category.name or '').split()).casefold() == 'medical equipment')

