    def action_archive(self):
        self.ensure_one()
        return self.write({'active': not self.active})

    @api.model
    def create(self, vals):
        product_tmpl = super(ProductTemplate, self).create(vals)
        if product_tmpl.eproc_subtype == 'drugs':
            product_tmpl.default_code = self.env['ir.sequence'].sudo().next_by_code('SEQ.ERP.MDM.ITEM.DRUG')
        elif product_tmpl.eproc_subtype == 'consumable':
            product_tmpl.default_code = self.env['ir.sequence'].sudo().next_by_code('SEQ.ERP.MDM.ITEM.CONSUMABLE')
        elif product_tmpl.eproc_subtype == 'consignment':
            product_tmpl.default_code = self.env['ir.sequence'].sudo().next_by_code('SEQ.ERP.MDM.ITEM.CONSIGNMENT')
        elif product_tmpl.eproc_subtype == 'procedure':
            product_tmpl.default_code = self.env['ir.sequence'].sudo().next_by_code('SEQ.ERP.MDM.ITEM.PROCEDURE')
        elif product_tmpl.eproc_subtype == 'item':
            product_tmpl.default_code = self.env['ir.sequence'].sudo().next_by_code('SEQ.ERP.MDM.ITEM')

        # 3. LOGIKA OTOMATISASI EPROC.PACK (Safe-Check)
        # Cek apakah eproc_pack_ids kosong dalam vals
        # (Odoo 16 biasanya mengirim [(6, 0, [])] atau False jika kosong)
        has_packs = False
        if vals.get('eproc_pack_ids'):
            # Jika ada data (bukan list kosong), set True
            has_packs = True

        if not has_packs:
            self.env['eproc.pack'].create({
                'product_tmpl_id': product_tmpl.id,
                'uom_id': product_tmpl.uom_id.id,
                'sequence': 1,
                'name': f"1 {product_tmpl.uom_id.name} = 1 {product_tmpl.uom_id.name}".upper(),
                'rate_value': 1.0,
                'is_default': True,
                'enable': True,
            })

        return product_tmpl

    def write(self, vals):
        if 'uom_id' in vals:
            for product in self:
                packs = self.env['eproc.pack'].sudo().search([
                    ('product_tmpl_id', '=', product.id)
                ])

                for pack in packs:
                    has_transaction = (
                            self.env['eproc.request.line'].sudo().search_count([
                                ('pack_id', '=', pack.id)
                            ]) > 0
                            or
                            self.env['eproc.order.line'].sudo().search_count([
                                ('pack_id', '=', pack.id)
                            ]) > 0
                            or
                            self.env['eproc.receipt.line'].sudo().search_count([
                                ('pack_id', '=', pack.id)
                            ]) > 0
                            or
                            self.env['eproc.agreement.line'].sudo().search_count([
                                ('pack_id', '=', pack.id)
                            ]) > 0
                    )

                    if has_transaction:
                        raise UserError(
                            "UoM tidak dapat diubah karena UoM sudah digunakan dalam transaksi."
                        )

        result = super().write(vals)

        if 'uom_id' in vals:
            for product in self:
                packs = product.eproc_pack_ids

                packs.write({
                    'common_uom_id': product.uom_id.id
                })

                for pack in packs:
                    pack.name = pack._generate_name()

        return result

    def _eproc_stock_lookup(self, company_id, pack_id):
        self.ensure_one()
        orderpoint = self.sudo().env['eproc.orderpoint'].search(
            [('company_id', '=', company_id), ('product_tmpl_id', '=', self.id)], limit=1)
        quants = self.sudo().env['eproc.stock.quant'].search([('product_tmpl_id', '=', self.id)])

        uom_min = orderpoint.qty_safety or 0.0
        uom_max = orderpoint.qty_maximum or 0.0
        uom_on_hand = sum(quants.mapped('quantity')) or 0.0

        pack_rate = pack_id.rate_value or 1.0
        return {
            'pack_id': pack_id.id,
            'pack_min': uom_min / pack_rate,
            'pack_max': uom_max / pack_rate,
            'pack_on_hand': uom_on_hand / pack_rate,
            'pack_rate': pack_rate,
            'uom_id': self.uom_id.id,
            'uom_min': uom_min,
            'uom_max': uom_max,
            'uom_on_hand': uom_on_hand
        }

    def _eproc_pricelist_lookup(self, agreement_id, pack_id, qty_order):
        self.ensure_one()
        agreement_line = self.env['eproc.agreement.line'].sudo().search(
            [('agreement_id', '=', agreement_id.id), ('agreement_id.state', '=', 'validated'),
             ('product_tmpl_id', '=', self.id), ('uom_min', '<=', qty_order), ('uom_max', '>=', qty_order)],
            order='uom_min desc', limit=1)

        if not agreement_line:
            agreement_line = self.env['eproc.agreement.line'].sudo().search(
                [('agreement_id', '=', agreement_id.id), ('agreement_id.state', '=', 'validated'),
                 ('product_tmpl_id', '=', self.id)], limit=1, order='uom_min asc')
        if not agreement_line:
            return {}

        pack_rate = pack_id.rate_value or 1.0
        uom_price = agreement_line.uom_price or 0.0
        uom_netprice = agreement_line.uom_netprice or 0.0

        return {
            'agreement_id': agreement_id.id,
            'agreement_line_id': agreement_line.id,
            'product_tmpl_id': self.id,
            'disc_rate': agreement_line.disc_rate or 0.0,
            'tax_ids': agreement_line.tax_ids.ids,
            'pack_id': pack_id.id,
            'pack_price': uom_price * pack_rate,
            'pack_netprice': uom_netprice * pack_rate,
            'pack_min': agreement_line.uom_min / pack_rate if pack_rate else 0.0,
            'pack_max': agreement_line.uom_max / pack_rate if pack_rate else 0.0,
            'pack_rate': pack_rate,
            'uom_id': self.uom_id.id,
            'uom_price': uom_price,
            'uom_netprice': uom_netprice,
            'uom_min': agreement_line.uom_min,
            'uom_max': agreement_line.uom_max,
        }

    def _eproc_amount_lookup(self, price, qty, disc_rate, tax_ids):
        # Logika Kalkulasi Pajak:
        # - Rate Negatif: Tax Include (Harga sudah termasuk pajak)
        # - Rate Positif: Tax Exclude (Pajak ditambah ke harga)

        total_price = price * qty
        # Kalkulasi diskon nominal
        total_discount = total_price * (disc_rate / 100.0)

        # Basis DPP (Dasar Pengenaan Pajak) setelah diskon
        dpp = total_price - total_discount

        tax_exclusive_amount = 0.0
        tax_inclusive_amount = 0.0

        for tax in tax_ids:
            if tax.rate < 0:
                # Logika Tax Include: DPP = Total / (1 + rate_abs)
                # tax_amount = Total - DPP
                rate_abs = abs(tax.rate) / 100.0
                actual_dpp = dpp / (1.0 + rate_abs)
                tax_inclusive_amount += (dpp - actual_dpp)
            else:
                # Logika Tax Exclude: tax_amount = DPP * rate
                tax_exclusive_amount += (dpp * (tax.rate / 100.0))

                # Total pajak secara akumulatif
        total_taxes = tax_exclusive_amount + tax_inclusive_amount

        # Sesuai request: total_netprice = price - disc + (taxes jika exclude)
        # Jika pajak inclusive, netprice tidak bertambah lagi karena sudah di dalam harga
        total_netprice = dpp + tax_exclusive_amount
        netprice = total_netprice / qty if qty else 1.0

        return {
            'price': price,
            'qty': qty,
            'disc_rate': disc_rate,
            'tax_ids': tax_ids.ids,
            'total_price': total_price,
            'total_discount': total_discount,
            'total_taxes': total_taxes,
            'total_netprice': total_netprice,
            'netprice': netprice,
        }


