class EprocAgreement(models.Model):
    _name = 'eproc.agreement'
    _description = 'Vendor Agreement'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'name'

    @api.model
    def _get_company(self):
        return self.env.company.id

    def _default_user(self):
        return self.env.user.id

    sync_type = sync.type
    sync_date = sync.date
    sync_id = sync.id
    sync_id_api = sync.id_api
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    code = fields.Char(string='Code', readonly=True, default='/', copy=False)
    type = fields.Selection([
        ('rate', 'Rate Contract'),
        ('tender', 'Call for Tender')
    ], string='Type', required=True, tracking=True, default='rate')
    ref = fields.Char(string='Reference', required=True, tracking=True)
    purchase_type_id = fields.Many2one('eproc.type', string='Procurement Type', required=True, tracking=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', tracking=True)
    lead_time = fields.Integer(string='Lead Time')
    date_start = fields.Date(string='Start Date', required=True, tracking=True)
    date_end = fields.Date(string='End Date', required=True, tracking=True)
    amount_limit = fields.Float(string='Amount Limit')
    amount_consume = fields.Float(string='Amount Consume', compute='_compute_amount_consume', store=True)
    term_id = fields.Many2one('eproc.term', string='Terms', tracking=True)
    state = fields.Selection([
        ('draft', 'Draft'),
        ('tender', 'Tender'),
        ('approval', 'Approval'),
        ('rejected', 'Rejected'),
        ('cancelled', 'Cancelled'),
        ('validated', 'Validated'),
    ], string='State', default='draft', tracking=True)
    approval_type_id = fields.Many2one(
        'eproc.approval.type',
        string='Approval Type',
        required=True,
        tracking=True,
    )
    approval_rule_id = fields.Many2one('eproc.approval.rule', string='Approval Rule', readonly=True)
    approval_rule_sequence = fields.Integer(string='Approval Rule No', readonly=True)
    approval_next_stored = fields.Char(string='Approval Next Stored', readonly=True)
    user_id = fields.Many2one('res.users', string='Responsible', default=_default_user)
    company_id = fields.Many2one('res.company', string='Company', required=True, default=_get_company)
    line_ids = fields.One2many('eproc.agreement.line', 'agreement_id', string='Items')
    evaluation_ids = fields.One2many('eproc.agreement.evaluation', 'agreement_id', string='Evaluation')
    approval_ids = fields.One2many('eproc.approval.log', 'agreement_id', string='Approval Logs')
    purchase_ids = fields.One2many('eproc.order', 'agreement_id', string='Purchase(s)')
    name = fields.Char(string='Title', compute='_compute_name', store=True)
    active = fields.Boolean(string='Active', default=True, tracking=True)

    @api.depends('code', 'supplier_id.name')
    def _compute_name(self):
        for record in self:
            code = record.code or '/'
            record.name = "%s %s" % (code, record.supplier_id.name) if record.supplier_id else code

    @api.depends('purchase_ids.total_netprice', 'purchase_ids.state')
    def _compute_amount_consume(self):
        consumed_states = ['approval', 'purchase', 'partial', 'done', 'expired']
        for record in self:
            amount = 0.0
            for purchase in record.purchase_ids:
                if getattr(purchase, 'state', False) in consumed_states:
                    amount += getattr(purchase, 'total_netprice', 0.0) or 0.0
            record.amount_consume = amount

    @api.onchange('supplier_id')
    def _onchange_supplier_id(self):
        for record in self:
            record.lead_time = getattr(record.supplier_id, 'eproc_lead_time', 0) or 0

    @api.constrains('date_start', 'date_end')
    def _check_dates(self):
        for record in self:
            if record.date_start and record.date_end and record.date_start > record.date_end:
                raise UserError(_('Start Date must be earlier than or equal to End Date.'))
            invalid_lines = record.line_ids.filtered(lambda line: (
                not line.effective_date
                or (record.date_start and line.effective_date < record.date_start)
                or (record.date_end and line.effective_date > record.date_end)
            ))
            if invalid_lines:
                raise ValidationError(_('Agreement dates must contain every existing line Effective Date.'))

    @api.constrains('type', 'supplier_id')
    def _check_supplier_required(self):
        for record in self:
            if record.type == 'rate' and not record.supplier_id:
                raise UserError(_('Supplier is required for Rate Contract agreements.'))

    @api.model
    def _sequence_unit_code(self, company):
        unit_code = getattr(company, 'company_code', False) or 'gen'
        return str(unit_code).upper().replace(' ', '')

    @api.model
    def _next_agreement_code(self, company):
        unit_code = self._sequence_unit_code(company)
        sequence_code = 'SEQ.ERP.PMM.%s.VENDOR.AGREEMENT' % unit_code
        code = self.env['ir.sequence'].with_company(company).next_by_code(sequence_code)
        if not code:
            raise UserError(
                _("No Vendor Agreement sequence found for unit %s with code %s.") % (unit_code, sequence_code))
        return code

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            if not vals.get('company_id'):
                vals['company_id'] = self.env.company.id
            if not vals.get('user_id'):
                vals['user_id'] = self.env.user.id
            if vals.get('supplier_id') and not vals.get('lead_time'):
                supplier = self.env['res.partner'].browse(vals['supplier_id'])
                vals['lead_time'] = getattr(supplier, 'eproc_lead_time', 0) or 0
            if not vals.get('code') or vals.get('code') == '/':
                company = self.env['res.company'].browse(vals['company_id'])
                vals['code'] = self._next_agreement_code(company)
        return super(EprocAgreement, self).create(vals_list)

    def write(self, vals):
        if vals.get('supplier_id') and 'lead_time' not in vals:
            supplier = self.env['res.partner'].browse(vals['supplier_id'])
            vals['lead_time'] = getattr(supplier, 'eproc_lead_time', 0) or 0
        if not self.env.context.get('skip_draft_check'):
            self._check_write_allowed(vals)
        return super(EprocAgreement, self).write(vals)

    def _check_write_allowed(self, vals):
        technical_fields = {
            'state', 'approval_rule_id', 'approval_rule_sequence', 'approval_next_stored',
            'approval_ids', 'active', 'message_follower_ids', 'message_ids',
            'activity_ids', 'message_main_attachment_id',
        }
        if vals and all(
                field in technical_fields or field.startswith('message_') or field.startswith('activity_') for field in
                vals):
            return
        locked = self.filtered(lambda rec: rec.state != 'draft')
        if locked:
            raise UserError(_('Only Draft Vendor Agreement records can be edited.'))

    def unlink(self):
        raise UserError(_('Vendor Agreement records cannot be deleted. Please archive the record instead.'))

    def copy(self, default=None):
        raise UserError(_('Vendor Agreement records cannot be duplicated.'))

    def _check_overlapping_validated(self):
        self.ensure_one()
        if not (self.supplier_id and self.purchase_type_id and self.date_start and self.date_end):
            return
        overlap = self.search([
            ('id', '!=', self.id), ('supplier_id', '=', self.supplier_id.id),
            ('purchase_type_id', '=', self.purchase_type_id.id), ('state', '=', 'validated'),
            ('date_start', '<=', self.date_end), ('date_end', '>=', self.date_start),
        ], limit=1)
        if overlap:
            raise ValidationError(_('Agreement %s overlaps validated agreement %s for the same supplier and procurement type.') % (self.code, overlap.code))

    def _validate_confirm_ready(self):
        for record in self:
            if record.type == 'rate' and not record.supplier_id:
                raise UserError(_('Supplier is required for Rate Contract agreements.'))
            if not record.line_ids:
                raise UserError(_('At least one item line is required before confirmation.'))
            if record.date_start and record.date_end and record.date_start > record.date_end:
                raise UserError(_('Start Date must be earlier than or equal to End Date.'))

    def _get_enabled_approval_rules(self):
        self.ensure_one()
        if not self.approval_type_id:
            return self.env['eproc.approval.rule']
        if 'rule_ids' not in self.approval_type_id._fields:
            return self.env['eproc.approval.rule']
        rules = self.approval_type_id.rule_ids
        rule_fields = rules._fields
        if 'sequence' not in rule_fields or 'position_id' not in rule_fields:
            raise UserError(
                _('Approval configuration is not fully implemented yet. Please configure the approval module before using approval rules.'))
        if 'enabled' in rules._fields:
            rules = rules.filtered(lambda rule: rule.enabled)
        return rules.sorted(key=lambda rule: rule.sequence or 0)

    def action_confirm(self):
        for record in self:
            if record.state != 'draft':
                raise UserError(_('Only Draft agreements can be confirmed.'))
            record._validate_confirm_ready()
            record._check_overlapping_validated()
            if record.type == 'tender':
                record.with_context(skip_draft_check=True).write({'state': 'tender'})
                record.message_post(body=_('Vendor Agreement moved to Tender.'))
                continue
            rules = record._get_enabled_approval_rules()
            if not rules:
                record.with_context(skip_draft_check=True).write({
                    'state': 'validated',
                    'approval_next_stored': 'Completed',
                    'approval_rule_id': False,
                    'approval_rule_sequence': 0,
                })
                record.message_post(body=_('Vendor Agreement validated without approval rules.'))
                continue
            record._create_approval_logs(rules)
            record.with_context(skip_draft_check=True).write({'state': 'approval'})
            record._update_approval_flags()
            record.action_notify_approver()
        return True

    def _create_approval_logs(self, rules):
        self.ensure_one()
        log_fields = self.env['eproc.approval.log']._fields
        required_log_fields = {'state', 'sequence', 'position_id'}
        if not required_log_fields.issubset(set(log_fields)):
            raise UserError(
                _('Approval log configuration is not fully implemented yet. Please configure the approval module before using approval rules.'))
        existing_logs = self.approval_ids
        if 'active' in log_fields:
            existing_logs = existing_logs.filtered(lambda log: log.active)
        if 'state' in log_fields:
            existing_logs = existing_logs.filtered(lambda log: log.state == 'pending')
        if existing_logs:
            if 'active' in log_fields:
                existing_logs.with_context(skip_draft_check=True).write({'active': False})
        values_list = []
        for rule in rules:
            position = getattr(rule, 'position_id', False)
            if not position:
                raise UserError(_('Approval rule %s has no position configured.') % (rule.display_name or rule.id))
            responsible_user = self._find_user_for_position(position)
            values = {
                'agreement_id': self.id,
                'approval_type_id': self.approval_type_id.id,
                'approval_rule_id': rule.id,
                'sequence': rule.sequence or 0,
                'position_id': position.id if position else False,
                'delegate_user_id': rule.delegate_user_id.id if getattr(rule, 'delegate_user_id', False) else False,
                'amount_snapshot': self.amount_limit or 0.0,
                'state': 'pending',
                'active': True,
            }
            values_list.append({field: value for field, value in values.items() if field in log_fields})
        if values_list:
            self.env['eproc.approval.log'].create(values_list)

    def _find_user_for_position(self, position):
        self.ensure_one()
        if not position:
            return self.env['res.users']
        domain = [('active', '=', True), ('position_id', '=', position.id)]
        if self.company_id:
            domain.append(('company_ids', 'in', [self.company_id.id]))
        return self.env['res.users'].search(domain, limit=1)

    def _get_current_approval_log(self):
        self.ensure_one()
        logs = self._get_current_pending_logs()
        if 'sequence' in logs._fields:
            return logs.sorted(key=lambda log: log.sequence or 0)[:1]
        return logs[:1]

    def _get_current_pending_logs(self):
        self.ensure_one()
        logs = self.approval_ids
        log_fields = self.env['eproc.approval.log']._fields
        if 'state' not in log_fields:
            return self.env['eproc.approval.log']
        if 'active' in log_fields:
            logs = logs.filtered(lambda log: log.active)
        return logs.filtered(lambda log: log.state == 'pending')

    def _update_approval_flags(self):
        for record in self:
            current_log = record._get_current_approval_log()
            if current_log:
                next_name = _('Unknown')
                if 'position_id' in current_log._fields and current_log.position_id:
                    next_name = current_log.position_id.name
                elif 'user_id' in current_log._fields and current_log.user_id:
                    next_name = current_log.user_id.name
                record.with_context(skip_draft_check=True).write({
                    'approval_rule_id': current_log.approval_rule_id.id if 'approval_rule_id' in current_log._fields and current_log.approval_rule_id else False,
                    'approval_rule_sequence': current_log.sequence if 'sequence' in current_log._fields else 0,
                    'approval_next_stored': next_name,
                })
            else:
                record.with_context(skip_draft_check=True).write({
                    'approval_rule_id': False,
                    'approval_rule_sequence': 0,
                    'approval_next_stored': 'Completed',
                })
        return True

    def _is_admin_user(self):
        return self.env.user.has_group('base.group_system')

    def _is_current_approver(self, approval_log):
        user = self.env.user
        if self._is_admin_user():
            return True
        position_ids = []
        if getattr(user, 'position_id', False):
            position_ids.append(user.position_id.id)
        if getattr(user, 'second_position_id', False):
            position_ids.append(user.second_position_id.id)
        if 'position_id' in approval_log._fields and approval_log.position_id and approval_log.position_id.id in position_ids:
            return True
        if 'delegate_user_id' in approval_log._fields and approval_log.delegate_user_id and approval_log.delegate_user_id.id == user.id:
            return True
        return False

    def action_approve(self):
        for record in self:
            if record.state != 'approval':
                raise UserError(_('Only agreements in Approval state can be approved.'))
            record._check_overlapping_validated()
            current_log = record._get_current_approval_log()
            if not current_log:
                record._update_approval_flags()
                record.with_context(skip_draft_check=True).write({'state': 'validated'})
                continue
            if not record._is_current_approver(current_log):
                raise UserError(_('Only the current approver can approve this agreement.'))
            approve_values = {
                'state': 'approved',
                'action_user_id': self.env.user.id,
                'approval_date': fields.Datetime.now(),
            }
            current_log.with_context(skip_draft_check=True).write({
                field: value for field, value in approve_values.items() if field in current_log._fields
            })
            if record._get_current_approval_log():
                record._update_approval_flags()
                record.action_notify_approver()
            else:
                record._update_approval_flags()
                record.with_context(skip_draft_check=True).write({'state': 'validated'})
                record.action_notify_approver(message=_('Vendor Agreement approval completed.'))
        return True

    def action_reject(self):
        for record in self:
            if record.state != 'approval':
                raise UserError(_('Only agreements in Approval state can be rejected.'))
            current_log = record._get_current_approval_log()
            can_reject = self._is_admin_user() or record.user_id == self.env.user or record.create_uid == self.env.user
            if current_log and record._is_current_approver(current_log):
                can_reject = True
            if not can_reject:
                raise UserError(_('Only the current approver, creator, or administrator can reject this agreement.'))
            if current_log:
                reject_values = {
                    'state': 'rejected',
                    'action_user_id': self.env.user.id,
                    'approval_date': fields.Datetime.now(),
                }
                current_log.with_context(skip_draft_check=True).write({
                    field: value for field, value in reject_values.items() if field in current_log._fields
                })
            pending_logs = record._get_current_pending_logs()
            if 'active' in self.env['eproc.approval.log']._fields and pending_logs:
                pending_logs.with_context(skip_draft_check=True).write({'active': False})
            record.with_context(skip_draft_check=True).write({
                'state': 'rejected',
                'approval_next_stored': _('Rejected by %s') % self.env.user.name,
            })
            record.message_post(body=_('Vendor Agreement rejected by %s.') % self.env.user.name)
        return True

    def action_cancel(self):
        if not any(self.env.user.has_group(group) for group in (
                'mayapada.mayapada_procurement_corporate',
                'mayapada.mayapada_procurement_manager',
                'mayapada.mayapada_all_access',
                'base.group_system',
        )):
            raise AccessError(_('You are not allowed to cancel Vendor Agreements.'))
        for record in self:
            if record.state not in ('approval', 'validated', 'tender'):
                raise UserError(_('Only Approval, Tender, or Validated agreements can be cancelled.'))
            pending_logs = record._get_current_pending_logs()
            if 'active' in self.env['eproc.approval.log']._fields and pending_logs:
                pending_logs.with_context(skip_draft_check=True).write({'active': False})
            record.with_context(skip_draft_check=True).write({
                'state': 'cancelled',
                'approval_next_stored': _('Cancelled by %s') % self.env.user.name,
            })
            record.message_post(body=_('Vendor Agreement cancelled by %s.') % self.env.user.name)
        return True

    def action_draft(self):
        for record in self:
            if record.state not in ('rejected', 'cancelled'):
                raise UserError(_('Only Rejected or Cancelled agreements can be reset to Draft.'))
            if record.state == 'cancelled' and not (self._is_admin_user() or record.user_id == self.env.user or record.create_uid == self.env.user):
                raise UserError(_('Only the creator or administrator can reset a cancelled agreement.'))
            log_fields = self.env['eproc.approval.log']._fields
            rejecting_users = self.env['res.users']
            if 'state' in log_fields and 'action_user_id' in log_fields:
                rejected_logs = record.approval_ids.filtered(lambda log: log.state == 'rejected')
                rejecting_users = rejected_logs.mapped('action_user_id')
            if not (
                    self._is_admin_user() or record.user_id == self.env.user or record.create_uid == self.env.user or self.env.user in rejecting_users):
                raise UserError(_('Only the creator, rejecting authority, or administrator can reset this agreement.'))
            active_logs = record.approval_ids
            if 'active' in self.env['eproc.approval.log']._fields:
                active_logs = active_logs.filtered(lambda log: log.active)
                if active_logs:
                    active_logs.with_context(skip_draft_check=True).write({'active': False})
            record.with_context(skip_draft_check=True).write({
                'state': 'draft',
                'approval_rule_id': False,
                'approval_rule_sequence': 0,
                'approval_next_stored': False,
            })
            record.message_post(body=_('Vendor Agreement reset to Draft.'))
        return True

    def action_archive(self):
        for record in self:
            record.with_context(skip_draft_check=True).write({'active': not record.active})
        return True

    def action_notify_approver(self, message=False):
        for record in self:
            current_log = record._get_current_approval_log()
            partner_ids = set(record.user_id.partner_id.ids)
            if current_log:
                if 'user_id' in current_log._fields and current_log.user_id:
                    partner_ids.update(current_log.user_id.partner_id.ids)
                if 'position_id' in current_log._fields and current_log.position_id:
                    users = record._find_user_for_position(current_log.position_id)
                    partner_ids.update(users.mapped('partner_id').ids)
            if message:
                body = message
            elif current_log:
                body = _('Vendor Agreement %s is waiting for approval by %s.') % (record.code,
                                                                                  record.approval_next_stored or _(
                                                                                      'next approver'))
            else:
                body = _('Vendor Agreement %s approval completed.') % record.code
            record.message_post(body=body, partner_ids=list(partner_ids))
        return True

    def action_import(self):
        self.ensure_one()
        if not self.id or self.state != 'draft':
            raise UserError(_('Only saved Draft Agreements can be imported.'))
        return {
            'type': 'ir.actions.act_window', 'name': _('Vendor Agreement - Import'),
            'res_model': 'eproc.agreement.wizard', 'view_mode': 'form',
            'view_id': self.env.ref('mayapada.view_eproc_agreement_wizard_form').id,
            'target': 'new', 'context': {'default_agreement_id': self.id, 'default_company_id': self.company_id.id, 'dialog_size': 'extra-large'},
        }


class EprocAgreementLine(models.Model):
    _name = 'eproc.agreement.line'
    _description = 'Vendor Agreement Line'
    _inherit = ['mail.thread']

    agreement_id = fields.Many2one('eproc.agreement', string='Agreement Type', required=True, ondelete='cascade')
    company_id = fields.Many2one('res.company', related='agreement_id.company_id', store=True, readonly=True)
    supplier_product_ids = fields.Many2many(
        'product.template',
        related='agreement_id.supplier_id.eproc_item_ids',
        string='Supplier Products',
        readonly=True,
    )
    product_tmpl_id = fields.Many2one('product.template', string='Product', required=True,
                                      domain=[('is_eproc', '=', True), ('eproc_type', '=', 'stock')], tracking=True)
    name = fields.Char(string='Description', required=True)
    pack_id = fields.Many2one('eproc.pack', string='Pack Type', required=True, tracking=True)
    pack_min = fields.Float(string='Pack Min', required=True, tracking=True)
    pack_max = fields.Float(string='Pack Max', tracking=True)
    pack_price = fields.Float(string='Pack Price', required=True, tracking=True)
    pack_netprice = fields.Float(string='Pack NetPrice', compute='_compute_pack_netprice', store=True, tracking=True)
    pack_rate = fields.Float(string='Pack Rate', tracking=True)
    uom_id = fields.Many2one('uom.uom', related='product_tmpl_id.uom_id', store=True, readonly=True)
    uom_min = fields.Float(string='UoM Min', compute='_compute_uom_values', store=True)
    uom_max = fields.Float(string='UoM Max', compute='_compute_uom_values', store=True)
    uom_price = fields.Float(string='UoM Price', compute='_compute_uom_values', store=True)
    uom_netprice = fields.Float(string='UoM NetPrice', compute='_compute_uom_values', store=True)
    disc_rate = fields.Float(string='Disc.Rate', tracking=True)
    tax_ids = fields.Many2many('eproc.taxes', 'eproc_taxes_rel', 'agreement_line_id', 'tax_id', string='Taxes',
                               tracking=True)
    pack_max_ordered = fields.Float(string='Pack Max Ordered')
    pack_total_ordered = fields.Float(string='Pack Total Ordered')
    effective_date = fields.Date(string='Effective Date', required=True)

    @api.onchange('agreement_id')
    def _onchange_agreement_id_effective_date(self):
        for record in self:
            if not record.effective_date and record.agreement_id.date_start:
                record.effective_date = record.agreement_id.date_start

    @api.constrains('effective_date', 'agreement_id')
    def _check_effective_date(self):
        for record in self:
            agreement = record.agreement_id
            if not record.effective_date:
                raise ValidationError(_('Effective Date is required.'))
            if agreement:
                if agreement.date_start and record.effective_date < agreement.date_start:
                    raise ValidationError(_('Effective Date cannot be before the Agreement Start Date.'))
                if agreement.date_end and record.effective_date > agreement.date_end:
                    raise ValidationError(_('Effective Date cannot be after the Agreement End Date.'))

    @api.constrains('agreement_id', 'product_tmpl_id', 'pack_id', 'pack_min', 'pack_max', 'effective_date')
    def _check_unique_identity(self):
        for record in self:
            # Tender lines are bid inputs and may repeat the same item identity.
            if record.agreement_id.type == 'tender':
                continue
            duplicate = self.search([
                ('id', '!=', record.id), ('agreement_id', '=', record.agreement_id.id),
                ('product_tmpl_id', '=', record.product_tmpl_id.id), ('pack_id', '=', record.pack_id.id),
                ('pack_min', '=', record.pack_min), ('pack_max', '=', record.pack_max),
                ('effective_date', '=', record.effective_date),
            ], limit=1)
            if duplicate:
                raise ValidationError(_('Duplicate Agreement Item identity for product %s and effective date %s.') % (record.product_tmpl_id.display_name, record.effective_date))

    @api.constrains('agreement_id', 'product_tmpl_id', 'pack_id', 'pack_min', 'pack_max', 'pack_price')
    def _check_line_business_rules(self):
        for record in self:
            if record.agreement_id and record.agreement_id.state == 'draft' and record.product_tmpl_id:
                product = record.product_tmpl_id
                agreement = record.agreement_id
                if not (product.is_eproc and product.eproc_type == 'stock'):
                    raise ValidationError(_('Product must be an E-Proc stock product.'))
                if agreement.company_id not in product.eproc_company_ids:
                    raise ValidationError(_('Product %s is not mapped to Agreement company %s.') % (product.display_name, agreement.company_id.display_name))
                if agreement.supplier_id and product not in agreement.supplier_id.eproc_item_ids:
                    raise ValidationError(_('Product %s is not mapped to supplier %s.') % (product.display_name, agreement.supplier_id.display_name))
                if record.pack_id.product_tmpl_id != product or not record.pack_id.enable:
                    raise ValidationError(_('Pack must be enabled and belong to the selected product.'))
                if record.pack_max and record.pack_max < record.pack_min:
                    raise ValidationError(_('Pack Max must be greater than or equal to Pack Min.'))

    @api.onchange('product_tmpl_id')
    def _onchange_product_tmpl_id(self):
        for record in self:
            product = record.product_tmpl_id
            if not product:
                record.pack_id = False
                record.pack_rate = 0.0
                continue
            description = getattr(product, 'description', False) or getattr(product, 'description_purchase',
                                                                            False) or product.name
            record.name = description
            enabled_packs = product.eproc_pack_ids
            enabled_packs = enabled_packs.filtered(lambda pack: pack.enable)
            if enabled_packs:
                record.pack_id = enabled_packs[0]
                record.pack_rate = record._get_pack_rate(enabled_packs[0])
            else:
                record.pack_id = False
                record.pack_rate = 0.0
        if self.product_tmpl_id:
            enabled_packs = self.product_tmpl_id.eproc_pack_ids
            enabled_packs = enabled_packs.filtered(lambda pack: pack.enable)
            return {'domain': {'pack_id': [('id', 'in', enabled_packs.ids)]}}
        return {'domain': {'pack_id': [('id', 'in', [])]}}

    @api.onchange('pack_id')
    def _onchange_pack_id(self):
        for record in self:
            record.pack_rate = record._get_pack_rate(record.pack_id)

    def _get_pack_rate(self, pack):
        if not pack:
            return 0.0
        return pack.rate_value or 0.0

    def _first_product_pack(self, product):
        if not product:
            return self.env['eproc.pack']
        packs = product.eproc_pack_ids
        packs = packs.filtered(lambda pack: pack.enable)
        return packs[:1]

    @api.depends('pack_price', 'disc_rate', 'tax_ids')
    def _compute_pack_netprice(self):
        for record in self:
            discounted_price = (record.pack_price or 0.0) * (1 - ((record.disc_rate or 0.0) / 100.0))
            tax_rate = 0.0
            for tax in record.tax_ids:
                tax_rate += tax.rate or 0.0
            record.pack_netprice = discounted_price + (discounted_price * tax_rate / 100.0)

    @api.depends('pack_min', 'pack_max', 'pack_price', 'pack_netprice', 'pack_rate')
    def _compute_uom_values(self):
        for record in self:
            rate = record.pack_rate or 0.0
            record.uom_min = (record.pack_min or 0.0) * rate
            record.uom_max = (record.pack_max or 0.0) * rate
            record.uom_price = (record.pack_price or 0.0) / rate if rate > 0 else 0.0
            record.uom_netprice = (record.pack_netprice or 0.0) / rate if rate > 0 else 0.0

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            agreement = self.env['eproc.agreement'].browse(vals.get('agreement_id'))
            if agreement and not vals.get('effective_date'):
                vals['effective_date'] = agreement.date_start
            if agreement and not vals.get('effective_date'):
                raise ValidationError(_('Effective Date is required when creating an Agreement Item.'))
            if agreement and agreement.state != 'draft' and not self.env.context.get('skip_draft_check'):
                raise UserError(_('Agreement lines can only be added while the agreement is Draft.'))
            if vals.get('product_tmpl_id') and not vals.get('name'):
                product = self.env['product.template'].browse(vals['product_tmpl_id'])
                vals['name'] = getattr(product, 'description', False) or getattr(product, 'description_purchase',
                                                                                 False) or product.name
            if vals.get('product_tmpl_id') and not vals.get('pack_id'):
                product = self.env['product.template'].browse(vals['product_tmpl_id'])
                pack = self._first_product_pack(product)
                if pack:
                    vals['pack_id'] = pack.id
            if vals.get('pack_id') and not vals.get('pack_rate'):
                vals['pack_rate'] = self._get_pack_rate(self.env['eproc.pack'].browse(vals['pack_id']))
        return super(EprocAgreementLine, self).create(vals_list)

    def write(self, vals):
        if not self.env.context.get('skip_draft_check') and self.mapped('agreement_id').filtered(
                lambda agreement: agreement.state != 'draft'):
            raise UserError(_('Agreement lines can only be edited while the agreement is Draft.'))
        if vals.get('pack_id') and 'pack_rate' not in vals:
            vals['pack_rate'] = self._get_pack_rate(self.env['eproc.pack'].browse(vals['pack_id']))
        return super(EprocAgreementLine, self).write(vals)

    def unlink(self):
        if not self.env.context.get('skip_draft_check') and self.mapped('agreement_id').filtered(
                lambda agreement: agreement.state != 'draft'):
            raise UserError(_('Agreement lines can only be removed while the agreement is Draft.'))
        return super(EprocAgreementLine, self).unlink()


