class EprocAgreementWizard(models.Model):
    _name = 'eproc.agreement.wizard'
    _description = 'Vendor Agreement Import'

    company_id = fields.Many2one('res.company', required=True, default=lambda self: self.env.company)
    agreement_id = fields.Many2one('eproc.agreement', required=True)
    file_id = fields.Binary(string='Excel File', attachment=True)
    file_name = fields.Char(string='File Name')
    line_ids = fields.One2many('eproc.agreement.temp', 'wizard_id', string='Preview Lines')
    uploaded = fields.Boolean(readonly=True)
    total_rows = fields.Integer(compute='_compute_preview_summary')
    valid_rows = fields.Integer(compute='_compute_preview_summary')
    invalid_rows = fields.Integer(compute='_compute_preview_summary')

    @api.depends('line_ids.validation_status')
    def _compute_preview_summary(self):
        for wizard in self:
            wizard.total_rows = len(wizard.line_ids)
            wizard.valid_rows = len(wizard.line_ids.filtered(lambda line: line.validation_status == 'valid'))
            wizard.invalid_rows = len(wizard.line_ids.filtered(lambda line: line.validation_status == 'invalid'))

    @api.model
    def default_get(self, fields_list):
        vals = super().default_get(fields_list)
        agreement = self.env['eproc.agreement'].browse(self.env.context.get('default_agreement_id') or self.env.context.get('active_id')).exists()
        if agreement:
            vals.update({'agreement_id': agreement.id, 'company_id': agreement.company_id.id})
        return vals

    def _ensure_draft(self):
        self.ensure_one()
        if not self.agreement_id or not self.agreement_id.exists():
            raise UserError(_('A saved Agreement is required.'))
        if self.company_id != self.agreement_id.company_id:
            raise UserError(_('Import company must match the Agreement company.'))
        if self.agreement_id.state != 'draft':
            raise UserError(_('Only Draft Agreements can be imported.'))

    def _headers(self):
        return ['Agreement Code', 'Product', 'Pack', 'Effective Date', 'Pack Min', 'Pack Max', 'Pack Price', 'Pack Max Order', 'Discount Rate', 'Taxes']

    def action_download_template(self):
        self.ensure_one()
        self._ensure_draft()
        import xlwt
        from io import BytesIO
        workbook = xlwt.Workbook()
        sheet = workbook.add_sheet('Import')
        instructions = workbook.add_sheet('Instructions')
        style = xlwt.easyxf('font: bold on; pattern: pattern solid, fore_colour gray25;')
        wrap_style = xlwt.easyxf('align: wrap on, vert top;')
        headers = self._headers()
        for col, header in enumerate(headers):
            sheet.write(0, col, header, style)
            sheet.col(col).width = max(16, len(header) + 4) * 256
        sheet.write(1, 0, self.agreement_id.code or self.agreement_id.ref or '')

        instruction_headers = ['Column', 'Required', 'Format / Accepted Value', 'Example', 'Notes']
        for col, header in enumerate(instruction_headers):
            instructions.write(0, col, header, style)
        instruction_rows = [
            ('Agreement Code', 'Yes', 'Prefilled Agreement Code or Agreement Reference', self.agreement_id.code or self.agreement_id.ref or '', 'Must match the current Agreement. Do not change it. It does not select another Agreement.'),
            ('Product', 'Yes', 'Exact existing Product Code or Product Name', 'Existing product code or name', 'Must be an E-Proc stock product mapped to the Agreement supplier and company.'),
            ('Pack', 'Yes', 'Exact enabled Pack name for the selected Product', 'Existing pack name, e.g. 1 BOX = 10 PCS', 'Must belong to the selected Product and be enabled.'),
            ('Effective Date', 'Yes', 'Excel date, or YYYY-MM-DD, DD/MM/YYYY, MM/DD/YYYY, DD-MM-YYYY, MM-DD-YYYY', '2026-09-01', 'Must be within the Agreement start and end dates.'),
            ('Pack Min', 'Yes', 'Numeric value', '1', 'Minimum pack quantity.'),
            ('Pack Max', 'No', 'Numeric value; blank is allowed', '10', 'Maximum pack quantity; when supplied, must be at least Pack Min.'),
            ('Pack Price', 'Yes', 'Numeric value', '150000', 'Price per pack.'),
            ('Pack Max Order', 'No', 'Numeric value; blank is allowed', '100', 'Maximum ordered pack quantity, if applicable.'),
            ('Discount Rate', 'No', 'Numeric percentage points; blank is allowed', '5', '5 means 5% discount, not 0.05.'),
            ('Taxes', 'No', 'Active tax name or code; separate multiple values with commas', 'PPN11,PPN10', 'Each value must resolve to one active tax. Blank means no taxes.'),
        ]
        for row, values in enumerate(instruction_rows, 1):
            for col, value in enumerate(values):
                instructions.write(row, col, value, wrap_style)
        for col, width in enumerate((20, 12, 52, 32, 90)):
            instructions.col(col).width = width * 256
        instructions.set_panes_frozen(True)
        instructions.set_horz_split_pos(1)

        calculated_row = len(instruction_rows) + 2
        instructions.write(calculated_row, 0, 'Automatically calculated after import', style)
        instructions.write(calculated_row, 1, 'Do not enter', style)
        instructions.write(calculated_row, 2, 'pack_rate, uom_id, uom_min, uom_max, uom_price, uom_netprice, pack_netprice', wrap_style)
        instructions.write(calculated_row, 4, 'These Agreement Line values are calculated by the existing ORM logic after import.', wrap_style)
        output = BytesIO()
        workbook.save(output)
        attachment = self.env['ir.attachment'].create({
            'name': 'vendor_agreement_%s_import_template.xls' % self.agreement_id.code,
            'type': 'binary', 'datas': base64.b64encode(output.getvalue()),
            'res_model': self._name, 'res_id': self.id,
            'mimetype': 'application/vnd.ms-excel',
        })
        return {'type': 'ir.actions.act_url', 'url': '/web/content/%s?download=true' % attachment.id, 'target': 'self'}

    def _text(self, value):
        if value in (None, ''):
            return ''
        if isinstance(value, float) and value.is_integer():
            return str(int(value))
        return str(value).strip()

    def _date(self, value, datemode, row_no):
        if value in (None, ''):
            raise UserError(_('Effective Date is required.'))
        if isinstance(value, datetime):
            return value.date()
        if isinstance(value, (int, float)):
            return xldate_as_datetime(value, datemode).date()
        for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%m/%d/%Y', '%d-%m-%Y', '%m-%d-%Y'):
            try:
                return datetime.strptime(self._text(value), fmt).date()
            except ValueError:
                continue
        raise UserError(_('Invalid Effective Date.'))

    def _number(self, value, label, row_no, required=False):
        if value in (None, ''):
            if required:
                raise UserError(_('%s is required.') % label)
            return 0.0
        try:
            return float(value)
        except (TypeError, ValueError):
            raise UserError(_('%s must be numeric.') % label)

    def _find_unique(self, model, value, label, row_no, domain=None, fields_to_check=None):
        text = self._text(value)
        if not text:
            raise UserError(_('%s is required.') % label)
        domain = list(domain or [])
        fields_to_check = fields_to_check or ['name']
        candidates = self.env[model]
        for field_name in fields_to_check:
            if field_name in candidates._fields:
                found = candidates.search(domain + [(field_name, '=', text)])
                if len(found) > 1:
                    raise UserError(_('%s "%s" is ambiguous.') % (label, text))
                if found:
                    return found
        raise UserError(_('%s "%s" was not found.') % (label, text))

    def _product(self, value, row_no):
        agreement = self.agreement_id
        domain = [('is_eproc', '=', True), ('eproc_type', '=', 'stock'),
                  ('eproc_company_ids', 'in', agreement.company_id.id)]
        candidates = self.env['product.template'].search(domain)
        if not agreement.supplier_id:
            raise UserError(_('Agreement supplier is required to resolve Product.'))
        candidates = candidates.filtered(lambda p: p in agreement.supplier_id.eproc_item_ids)
        text = self._text(value)
        matches = candidates.filtered(lambda p: p.default_code == text or p.name == text)
        if len(matches) != 1:
            raise UserError(_('Product "%s" must resolve to one applicable product.') % text)
        return matches

    def _taxes(self, value, row_no):
        result = self.env['eproc.taxes']
        Tax = self.env['eproc.taxes']
        for name in [part.strip() for part in self._text(value).split(',') if part.strip()]:
            matches = Tax.search([
                ('active', '=', True), '|', ('name', '=', name), ('code', '=', name),
            ])
            if len(matches) > 1:
                raise UserError(_('Tax "%s" is ambiguous.') % name)
            if not matches:
                raise UserError(_('Tax "%s" was not found.') % name)
            result |= matches
        return result

    def _rows(self):
        if not self.file_id:
            raise UserError(_('Please attach an Excel file first.'))
        workbook = open_workbook(file_contents=base64.b64decode(self.file_id))
        headers_required = {re.sub(r'[^a-z0-9]+', '_', h.lower()).strip('_'): h for h in self._headers()}
        for sheet in workbook.sheets():
            if sheet.name.strip().lower() == 'instructions':
                continue
            if sheet.nrows < 2:
                continue
            headers = {re.sub(r'[^a-z0-9]+', '_', self._text(sheet.cell(0, col).value).lower()).strip('_'): col for col in range(sheet.ncols)}
            missing = [label for key, label in headers_required.items() if key not in headers]
            if missing:
                raise UserError(_('Missing column(s): %s.') % ', '.join(missing))
            for row_index in range(1, sheet.nrows):
                row = [sheet.cell(row_index, col).value for col in range(sheet.ncols)]
                if not any(value not in (None, '') for value in row):
                    continue
                yield row_index + 1, row, headers, workbook.datemode

    def _value(self, row, headers, label):
        key = re.sub(r'[^a-z0-9]+', '_', label.lower()).strip('_')
        return row[headers[key]]

    def _preview_vals(self, row_no, row, headers, datemode):
        errors = []
        get = lambda label: self._value(row, headers, label)
        product_value = self._text(get('Product'))
        pack_value = self._text(get('Pack'))
        effective_value = self._text(get('Effective Date'))
        taxes_value = self._text(get('Taxes'))
        agreement_code = self._text(get('Agreement Code'))
        if not agreement_code:
            errors.append(_('Agreement Code is required.'))
        elif agreement_code not in (self.agreement_id.code, self.agreement_id.ref):
            errors.append(_('Agreement Code does not match the current Agreement.'))

        product = self.env['product.template']
        try:
            product = self._product(product_value, row_no)
        except UserError as error:
            errors.append(str(error).replace(' on row %s.' % row_no, '').replace(' on row %s' % row_no, ''))
        pack = self.env['eproc.pack']
        if product:
            try:
                pack = self._find_unique('eproc.pack', pack_value, 'Pack', row_no,
                                         [('product_tmpl_id', '=', product.id), ('enable', '=', True)], ['name'])
            except UserError as error:
                errors.append(str(error).replace(' on row %s.' % row_no, '').replace(' on row %s' % row_no, ''))
        elif pack_value:
            errors.append(_('Pack requires a valid Product.'))

        effective_date = False
        try:
            effective_date = self._date(get('Effective Date'), datemode, row_no)
            if ((self.agreement_id.date_start and effective_date < self.agreement_id.date_start)
                    or (self.agreement_id.date_end and effective_date > self.agreement_id.date_end)):
                errors.append(_('Effective Date is outside the Agreement date range.'))
        except UserError as error:
            errors.append(str(error).replace(' on row %s.' % row_no, '').replace(' on row %s' % row_no, ''))

        numbers = {}
        for label, required in (('Pack Min', True), ('Pack Max', False), ('Pack Price', True),
                                ('Pack Max Order', False), ('Discount Rate', False)):
            try:
                numbers[label] = self._number(get(label), label, row_no, required)
            except UserError as error:
                numbers[label] = 0.0
                errors.append(str(error).replace(' on row %s.' % row_no, '').replace(' on row %s' % row_no, ''))
        if numbers.get('Pack Max') and numbers['Pack Max'] < numbers.get('Pack Min', 0.0):
            errors.append(_('Pack Max must be >= Pack Min.'))

        taxes = self.env['eproc.taxes']
        try:
            taxes = self._taxes(get('Taxes'), row_no)
        except UserError as error:
            errors.append(str(error).replace(' on row %s.' % row_no, '').replace(' on row %s' % row_no, ''))
        return {
            'agreement_id': self.agreement_id.id, 'excel_row': row_no,
            'validation_status': 'invalid' if errors else 'valid',
            'validation_message': '\n'.join(errors),
            'product_input': product_value, 'pack_input': pack_value,
            'effective_date_input': effective_value, 'taxes_input': taxes_value,
            'product_tmpl_id': product.id or False, 'pack_id': pack.id or False,
            'effective_date': effective_date,
            'pack_min': numbers.get('Pack Min', 0.0), 'pack_max': numbers.get('Pack Max', 0.0),
            'pack_price': numbers.get('Pack Price', 0.0), 'pack_max_order': numbers.get('Pack Max Order', 0.0),
            'disc_rate': numbers.get('Discount Rate', 0.0), 'taxes_ids': [(6, 0, taxes.ids)],
        }, errors

    def _load_preview(self):
        self.ensure_one()
        values = []
        identities = {}
        for row_no, row, headers, datemode in self._rows():
            line_values, _errors = self._preview_vals(row_no, row, headers, datemode)
            identity_fields = ('agreement_id', 'product_tmpl_id', 'pack_id', 'pack_min', 'pack_max', 'effective_date')
            identity = tuple(line_values[field] for field in identity_fields)
            line_values['mode'] = 'insert'
            if identity[1] and identity[2] and identity[5]:
                if identity in identities:
                    line_values['validation_status'] = 'invalid'
                    line_values['validation_message'] = (line_values['validation_message'] + '\n' if line_values['validation_message'] else '') + _(
                        'Duplicate of Excel row %s.') % identities[identity]
                else:
                    identities[identity] = row_no
                existing = self.env['eproc.agreement.line'].search([
                    ('agreement_id', '=', identity[0]),
                    ('product_tmpl_id', '=', identity[1]),
                    ('pack_id', '=', identity[2]),
                    ('pack_min', '=', identity[3]),
                    ('pack_max', '=', identity[4]),
                    ('effective_date', '=', identity[5]),
                ], limit=1)
                if existing:
                    line_values['mode'] = 'update'
            values.append((0, 0, line_values))
        if not values:
            raise UserError(_('No data row found in the attached Excel file.'))
        self.line_ids.unlink()
        self.write({'line_ids': values, 'uploaded': False})
        return len(values)

    def action_view_data(self):
        self.ensure_one()
        self._ensure_draft()
        count = self._load_preview()
        return self._reopen(_('Successfully loaded %s row(s).') % count)

    def action_import(self):
        self.ensure_one()
        self._ensure_draft()
        # Reparse the current upload so Import Data cannot use a stale preview.
        self._load_preview()
        if self.invalid_rows:
            raise UserError(_('Import cannot continue because %s row(s) are invalid. Please correct the Excel file and run View Data again.') % self.invalid_rows)
        Line = self.env['eproc.agreement.line']
        count = 0
        for temp in self.line_ids:
            key = [('agreement_id', '=', self.agreement_id.id), ('product_tmpl_id', '=', temp.product_tmpl_id.id), ('pack_id', '=', temp.pack_id.id), ('pack_min', '=', temp.pack_min), ('pack_max', '=', temp.pack_max), ('effective_date', '=', temp.effective_date)]
            vals = {'agreement_id': self.agreement_id.id, 'product_tmpl_id': temp.product_tmpl_id.id, 'pack_id': temp.pack_id.id, 'pack_min': temp.pack_min, 'pack_max': temp.pack_max, 'pack_price': temp.pack_price, 'pack_max_ordered': temp.pack_max_order, 'disc_rate': temp.disc_rate, 'tax_ids': [(6, 0, temp.taxes_ids.ids)], 'effective_date': temp.effective_date}
            existing = Line.search(key, limit=1)
            if existing:
                existing.write(vals)
            else:
                Line.create(vals)
            count += 1
        self.uploaded = True
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': _('Success'),
                'message': _('Successfully imported %s row(s).') % count,
                'type': 'success',
                'sticky': False,
                'next': {'type': 'ir.actions.act_window_close'},
            },
        }

    def action_clear(self):
        self.ensure_one()
        self.line_ids.unlink()
        self.file_id = False
        self.file_name = False
        self.uploaded = False
        return self._reopen()

    def action_close(self):
        return {'type': 'ir.actions.act_window_close'}

    def _reopen(self, message=False):
        if message:
            return {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': {'title': _('Success'), 'message': message, 'type': 'success', 'sticky': False, 'next': {'type': 'ir.actions.act_window', 'res_model': self._name, 'res_id': self.id, 'view_mode': 'form', 'views': [(False, 'form')], 'target': 'new', 'context': {'dialog_size': 'extra-large'}}}}
        return {'type': 'ir.actions.act_window', 'res_model': self._name, 'res_id': self.id, 'view_mode': 'form', 'views': [(False, 'form')], 'target': 'new', 'context': {'dialog_size': 'extra-large'}}


