class EprocTabulationWizard(models.TransientModel):
    _name = 'eproc.tabulation.wizard'
    _description = 'E-Procurement Tabulation Wizard'

    company_id = fields.Many2one('res.company', string='Company', required=True, default=lambda self: self.env.company)
    user_id = fields.Many2one('res.users', string='Responsible', required=True, default=lambda self: self.env.user)
    agreement_id = fields.Many2one('eproc.agreement', string='Agreement Type', required=True)
    purchase_type_id = fields.Many2one('eproc.type', string='Procurement Type', related='agreement_id.purchase_type_id',
                                       readonly=True)
    date_start = fields.Date(string='Start Date', related='agreement_id.date_start', readonly=True)
    date_end = fields.Date(string='End Date', related='agreement_id.date_end', readonly=True)
    line_ids = fields.One2many('eproc.tabulation.line', 'wizard_id', string='Items')
    order_ids = fields.One2many('eproc.tabulation.order', 'wizard_id', string='RFQs')
    allowed_winner_ids = fields.Many2many('eproc.order', compute='_compute_allowed_winner_ids',
                                          string='Allowed Winners')
    winner_id = fields.Many2one('eproc.order', string='Set Winner', required=True)
    reason = fields.Text(string='Reason', required=True)

    @api.depends('order_ids.order_id')
    def _compute_allowed_winner_ids(self):
        for record in self:
            record.allowed_winner_ids = record.order_ids.mapped('order_id')

    @api.onchange('company_id')
    def _onchange_company_id(self):
        for record in self:
            if record.agreement_id and record.agreement_id.company_id != record.company_id:
                record.agreement_id = False
                record.line_ids = [(5, 0, 0)]
                record.order_ids = [(5, 0, 0)]
                record.winner_id = False

    @api.onchange('agreement_id')
    def _onchange_agreement_id(self):
        for record in self:
            record.line_ids = [(5, 0, 0)]
            record.order_ids = [(5, 0, 0)]
            record.winner_id = False

            agreement = record.agreement_id
            if not agreement:
                return {'domain': {'winner_id': [('id', '=', False)]}}

            orders = record._get_agreement_orders(agreement)
            record.order_ids = [(0, 0, {'order_id': order.id}) for order in orders]
            record.line_ids = record._prepare_tabulation_line_commands(agreement, orders)

            return {'domain': {'winner_id': [('id', 'in', orders.ids), ('state', '=', 'tender')]}}

    def _get_agreement_orders(self, agreement):
        self.ensure_one()
        return self.env['eproc.order'].search([
            ('company_id', '=', self.company_id.id),
            ('agreement_id', '=', agreement.id),
            ('state', '=', 'tender'),
        ], order='order_no, id')

    def _prepare_tabulation_line_commands(self, agreement, orders):
        self.ensure_one()
        commands = []
        order_lines = orders.mapped('line_ids').filtered(
            lambda line: line.active
                         and line.order_id.company_id == self.company_id
                         and line.order_id.agreement_id == agreement
                         and line.agreement_line_id
                         and line.agreement_line_id.agreement_id == agreement
        )

        current_product = False
        for order_line in order_lines.sorted(key=lambda line: (
                line.product_tmpl_id.display_name or '',
                line.order_id.order_no or '',
                line.sequence or 0,
                line.id,
        )):
            product = order_line.product_tmpl_id
            if product != current_product:
                current_product = product
                commands.append((0, 0, {
                    'display_type': 'line_section',
                    'name': product.display_name or _('No Product'),
                }))
            commands.append((0, 0, {
                'agreement_line_id': order_line.agreement_line_id.id,
                'name': order_line.agreement_line_id.name or order_line.name or product.display_name,
                'order_id': order_line.order_id.id,
                'order_line_id': order_line.id,
            }))

        return commands

    def _validate_tabulation(self, orders=None):
        self.ensure_one()
        agreement = self.agreement_id
        if not agreement:
            raise UserError(_('Please select a Blanket Agreement.'))
        orders = orders or self._get_agreement_orders(agreement)
        if agreement.company_id != self.company_id:
            raise UserError(_('Agreement company must match wizard company.'))
        if agreement.type != 'tender':
            raise UserError(_('Only tender agreements can be finalized from Bid Tabulation.'))
        if agreement.state != 'tender':
            raise UserError(_('Only agreements in Tender state can be finalized from Bid Tabulation.'))
        if agreement.evaluation_ids:
            raise UserError(_("Only tender agreements that haven't been evaluated can be finalized."))
        invalid_orders = orders.filtered(lambda
                                             order: order.company_id != self.company_id or order.agreement_id != agreement or order.state != 'tender')
        if invalid_orders:
            raise UserError(
                _('All listed RFQs must belong to the selected Tender agreement and still be in Tender state.'))
        if not self.winner_id:
            raise UserError(_('Please select a tender winner.'))
        if self.winner_id not in orders:
            raise UserError(_('Winner must be one of the RFQs listed in this tabulation.'))
        if self.winner_id.company_id != self.company_id or self.winner_id.agreement_id != agreement:
            raise UserError(_('Winner RFQ must belong to the selected agreement and company.'))
        if self.winner_id.state != 'tender':
            raise UserError(_('Only Tender RFQs can be selected as tender winner.'))
        if not self.reason:
            raise UserError(_('Reason is required.'))

    def _sync_tender_evaluations(self, agreement, orders):
        self.ensure_one()
        evaluation_model = self.env['eproc.agreement.evaluation']
        existing_evaluations = agreement.evaluation_ids.filtered(lambda evaluation: evaluation.order_id in orders)
        existing_by_order = {evaluation.order_id.id: evaluation for evaluation in existing_evaluations}
        create_values = []

        for order in orders:
            values = {
                'is_winner': order == self.winner_id,
                'reason': self.reason if order == self.winner_id else False,
            }
            evaluation = existing_by_order.get(order.id)
            if evaluation:
                evaluation.write(values)
            else:
                values.update({
                    'agreement_id': agreement.id,
                    'order_id': order.id,
                })
                create_values.append(values)

        stale_evaluations = agreement.evaluation_ids - existing_evaluations
        if stale_evaluations:
            stale_evaluations.write({
                'is_winner': False,
                'reason': False,
            })
        if create_values:
            evaluation_model.create(create_values)

    def action_validation(self):
        self.ensure_one()
        agreement = self.agreement_id
        orders = self.order_ids.mapped('order_id')
        if not orders:
            raise UserError(_('There are no RFQs for the selected agreement.'))
        self._validate_tabulation(orders)
        locked_losers = orders.filtered(
            lambda order: order != self.winner_id and order.state in ('purchase', 'partial', 'done', 'expired'))
        if locked_losers:
            raise UserError(_('Confirmed or completed PO cannot be cancelled: %s') % ', '.join(
                locked_losers.mapped('display_name')))

        self._sync_tender_evaluations(agreement, orders)

        agreement.with_context(skip_draft_check=True).write({
            'state': 'validated',
            'approval_next_stored': 'Completed',
        })

        loser_reason = _('Cancelled by Bid Tabulation. Winner: %s') % (
                    self.winner_id.display_name or self.winner_id.order_no)
        loser_orders = orders.filtered(lambda order: order != self.winner_id and order.state != 'cancelled')
        if loser_orders:
            loser_orders.with_context(skip_order_lock=True).write({
                'state': 'cancelled',
                'cancel_reason': loser_reason,
                'cancel_datetime': fields.Datetime.now(),
                'approval_next_stored': _('Cancelled by Bid Tabulation'),
            })

        self.winner_id.action_confirm()
        orders.mapped('line_ids.request_line_id.request_id')._sync_realization_state_from_lines()
        action = self.env.ref('mayapada.action_erp_pmm_master_vendor_agreement').read()[0]
        form_view = self.env.ref('mayapada.view_erp_pmm_master_vendor_agreement_form')
        action.update({
            'res_id': agreement.id,
            'view_mode': 'form',
            'views': [(form_view.id, 'form')],
            'target': 'current',
        })
        return action


