    delegate_user_id = fields.Many2one('res.users', string="Delegate User")
    notes = fields.Char(string="Notes")
    enabled = fields.Boolean(default=True, string='Enable')
    type = fields.Selection(
        [('check', 'Checking'), ('approve', 'Approval'), ('verify', 'Verifying'), ('review', 'Review')],
        default='approve', string='Type')
    show = fields.Boolean(default=False, string='Show Printout')
    approval_type_id = fields.Many2one('eproc.approval.type', string='Approval Type')

    def name_get(self):
        result = []
        for rec in self:
            result.append((rec.id, rec.position_id.name or 'New'))
        return result

    @api.onchange('position_id')
    def onchange_position_id(self):
        user_id = self.env['res.users'].sudo().search([('position_id.name', '=', self.position_id.name)],
                                                      order='id asc', limit=1)
        if user_id:
            self.user_id = user_id.id

