        for rec in self:
            if rec.approval_type_id and rec.approval_type_id.id:
                raise UserError(
                    "Rule tidak boleh dihapus setelah Approval Type disimpan. Harap menggunakan tombol Enabled untuk menonaktifkan rules."
                )
        return super().unlink()


