    _sql_constraints = [
        ('order_no_company_unique', 'unique(order_no, company_id)', 'RFQ number must be unique per company.'),
        ('order_purchase_no_company_unique', 'unique(order_purchase_no, company_id)',
         'PO number must be unique per company.'),
    ]

    order_expiry_date = fields.Date(string='Order Expiry Date', readonly=True, copy=False, tracking=True)
    rebalance_log_ids = fields.One2many('eproc.order.rebalance.log', 'order_id', string='PR Rebalance History')

    @api.model
    def _business_today(self):
        return fields.Date.context_today(self.with_context(tz=BUSINESS_TZ))

    def _lock_lifecycle(self):
        """Private shared lock; enforce ORM rights before issuing row-lock SQL."""
        if not self:
            return
        self.check_access_rights('write')
        self.check_access_rule('write')
        allowed = self.env.companies & self.env.user.company_ids
        if any(order.company_id not in allowed for order in self):
            raise AccessError(_('The PO company must be one of your allowed companies.'))
        self.mapped('line_ids.budget_item_id')._lock_tracking()
        self.env.flush_all()
        self.env.cr.execute('SELECT id FROM eproc_order WHERE id IN %s ORDER BY id FOR UPDATE',
                            [tuple(self.ids)])
        self.invalidate_recordset()
        lines = self.with_context(active_test=False).mapped('line_ids')
        lines.check_access_rights('write')
        lines.check_access_rule('write')
        if lines:
            self.env.cr.execute('SELECT id FROM eproc_order_line WHERE id IN %s ORDER BY id FOR UPDATE',
                                [tuple(lines.ids)])
            lines.invalidate_recordset()
        # Different POs may allocate the same PR: serialize stored PR recomputes too.
        requests = lines.mapped('request_line_id.request_id')
        request_lines = lines.mapped('request_line_id')
        for table, records in (('eproc_request', requests), ('eproc_request_line', request_lines)):
            if records:
                records.check_access_rights('write')
                records.check_access_rule('write')
                self.env.cr.execute('SELECT id FROM ' + table + ' WHERE id IN %s ORDER BY id FOR UPDATE',
                                    [tuple(records.ids)])
                records.invalidate_recordset()
        self.check_access_rule('write')
        if any(order.company_id not in allowed for order in self):
            raise AccessError(_('The PO company must be one of your allowed companies.'))

    @api.model
    def action_expire_orders(self, order_ids=None):
        """Expire eligible POs; None selects a batch, a list restricts its scope.

        An empty list is a no-op. IDs must be positive integers (not booleans).
        Expiry day itself remains valid (Asia/Jakarta).
        """
        if order_ids is not None:
            if not isinstance(order_ids, list) or any(type(order_id) is not int or order_id <= 0
                                                       for order_id in order_ids):
                raise ValidationError(_('order_ids must be a list of positive integer PO IDs, or None for batch processing.'))
            if not order_ids:
                return []
        today = self._business_today()
        domain = [
            ('company_id', 'in', (self.env.companies & self.env.user.company_ids).ids),
            ('state', '=', 'purchase'), ('order_expiry_date', '!=', False),
            ('order_expiry_date', '<', today),
        ]
        if order_ids is not None:
            domain.append(('id', 'in', order_ids))
        orders = self.search(domain, order='id')
        orders._lock_lifecycle()
        expired = orders.filtered(lambda order: order.state == 'purchase'
                                  and order.order_expiry_date and order.order_expiry_date < today)
        for order in expired:
            order.write({'state': 'expired'})
            order.line_ids.filtered(lambda line: line.state == 'ready').write({'state': 'expired'})
            order.message_post(body=_('PO expired after its expiry date (Asia/Jakarta).'))
        return expired.ids

    def action_rebalance(self):
        self.ensure_one()
        self._lock_lifecycle()
        if self.state not in REBALANCE_STATES:
            raise UserError(_('Only a released, expired, or completed PO can be rebalanced.'))
        return {
            'type': 'ir.actions.act_window', 'name': _('PR Item Rebalance'),
            'res_model': 'eproc.order.rebalance.wizard', 'view_mode': 'form', 'target': 'new',
            'context': dict(self.env.context, default_order_id=self.id),
        }

    @api.depends('order_no', 'order_purchase_no', 'order_revise')
    def _compute_name(self):
        for record in self:
            base = record.order_purchase_no or record.order_no or _('Draft')
            if record.order_revise:
                base = '%sR%s' % (base, record.order_revise)
            record.name = base

    def name_get(self):
        result = []
        for record in self:
            result.append((record.id, record.name or record.order_no or _('Draft')))
        return result

    @api.depends('line_ids.total_price', 'line_ids.total_discount', 'line_ids.total_taxes', 'line_ids.total_netprice')
    def _compute_total_price(self):
        for record in self:
            record.total_price = sum(record.line_ids.mapped('total_price'))
            record.total_discount = sum(record.line_ids.mapped('total_discount'))
            record.total_taxes = sum(record.line_ids.mapped('total_taxes'))
            record.total_netprice = sum(record.line_ids.mapped('total_netprice'))

    @api.depends('line_ids.request_line_id')
    def _compute_related_request_data(self):
        for record in self:
            request_lines = record.line_ids.mapped('request_line_id')
            record.request_line_ids = request_lines
            record.request_ids = request_lines.mapped('request_id')
            record.request_count = len(request_lines)

    @api.depends('line_ids')
    def _compute_line_count(self):
        for record in self:
            record.line_count = len(record.line_ids.filtered(lambda line: line.active))

    @api.depends('line_ids.receipt_line_ids', 'line_ids.receipt_line_ids.receipt_id')
    def _compute_related_receipt_data(self):
        for record in self:
            receipt_lines = record.line_ids.mapped('receipt_line_ids')
            record.receipt_line_ids = receipt_lines
            record.receipt_ids = receipt_lines.mapped('receipt_id')
            record.receipt_count = len(receipt_lines)

    @api.model
    def _sequence_unit_code(self, company):
        unit_code = getattr(company, 'company_code', False) or 'GEN'
        return str(unit_code).upper().replace(' ', '')

    @api.model
    def _next_order_sequence(self, company, kind, purchase_type):
        sequence_config = {
            'rfq': {
                'code': 'SEQ.ERP.PMM.%s.REQUEST.QUOTATION',
                'fallback_code': 'SEQ.ERP.PMM.REQUEST.QUOTATION',
                'prefix_field': 'order_prefix',
                'prefix_label': _('RFQ Prefix'),
            },
            'po': {
                'code': 'SEQ.ERP.PMM.%s.PURCHASE.ORDER',
                'fallback_code': 'SEQ.ERP.PMM.PURCHASE.ORDER',
                'prefix_field': 'order_valid_prefix',
                'prefix_label': _('PO Prefix'),
            },
        }
        config = sequence_config.get(kind)
        if not config:
            raise UserError(_('Unsupported RFQ/PO sequence type: %s.') % kind)
        if not purchase_type:
            raise UserError(_('Procurement Type is required before generating an RFQ/PO number.'))
        document_prefix = purchase_type[config['prefix_field']]
        if not document_prefix:
            raise UserError(
                _('%s is not configured for Procurement Type %s.')
                % (config['prefix_label'], purchase_type.display_name)
            )
        if len(document_prefix) != 4:
            raise UserError(_('%s must contain exactly 4 characters.') % config['prefix_label'])

        company_code = getattr(company, 'company_code', False)
        if not company_code:
            raise UserError(_('Company code is required before generating an RFQ/PO number.'))
        unit_code = self._sequence_unit_code(company)
        if len(unit_code) < 2:
            raise UserError(_('Company code %s must contain at least 2 characters.') % unit_code)
        unit_prefix = unit_code[-2:]
        sequence_code = config['code'] % unit_code
        used_sequence_code = sequence_code
        raw_sequence = self.env['ir.sequence'].with_company(company).next_by_code(sequence_code)
        if not raw_sequence:
            fallback = self.env['ir.sequence'].with_company(company).next_by_code(config['fallback_code'])
            raw_sequence = '%s%s' % (unit_prefix, fallback) if fallback else False
            used_sequence_code = config['fallback_code']
        if not raw_sequence:
            raise UserError(_('No sequence found for %s using code %s.') % (unit_code, sequence_code))
        if not re.fullmatch(r'%s\d{11,}' % re.escape(unit_prefix), raw_sequence):
            raise UserError(
                _('Sequence %s produced an invalid raw number %s. Expected %s followed by year, month, and running number.')
                % (used_sequence_code, raw_sequence, unit_prefix)
            )
        return '%s.%s' % (document_prefix, raw_sequence)

    def _update_date_planned(self):
        for order in self:
            base_date = order.order_valid_date or order.order_date or fields.Datetime.now()
            planned = fields.Datetime.to_datetime(base_date) + timedelta(days=order.lead_time or 0)
            if not order.id:
                # Onchange records (including edits of an existing RFQ) have NewId
                # identifiers. Update only their cache, never the saved origin.
                values = {'date_planned': planned}
                if not order.order_date:
                    values['order_date'] = base_date
                order.update(values)
                for line in order.line_ids:
                    line.update({'date_planned': planned})
                continue
            if not order.order_date:
                order.with_context(skip_order_lock=True).write({'order_date': base_date})
            order.with_context(skip_order_lock=True).write({
                'date_planned': planned,
            })

    def _is_confirm_date_inside_agreement_range(self):
        self.ensure_one()
        agreement = self.agreement_id
        if not agreement:
            return True
        confirm_date = fields.Date.context_today(self)
        date_start = fields.Date.to_date(agreement.date_start) if agreement.date_start else False
        date_end = fields.Date.to_date(agreement.date_end) if agreement.date_end else False
        return not ((date_start and confirm_date < date_start) or (date_end and confirm_date > date_end))

    def _open_agreement_date_range_confirm_wizard(self):
        self.ensure_one()
        agreement = self.agreement_id
        date_start = fields.Date.to_date(agreement.date_start) if agreement and agreement.date_start else False
        date_end = fields.Date.to_date(agreement.date_end) if agreement and agreement.date_end else False
        return {
            'name': _('Agreement Validity Warning'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order.agreement.date.confirm.wizard',
            'view_mode': 'form',
            'target': 'new',
            'context': dict(self.env.context, **{
                'default_order_id': self.id,
                'default_agreement_id': agreement.id,
                'default_confirm_date': fields.Date.to_string(fields.Date.context_today(self)),
                'default_date_start': fields.Date.to_string(date_start) if date_start else False,
                'default_date_end': fields.Date.to_string(date_end) if date_end else False,
                'default_message': _('The confirmation date is outside the selected agreement validity period. Do you want to continue?'),
            }),
        }

    def _get_qty_multiple_mismatches(self):
        self.ensure_one()
        return [
            mismatch
            for mismatch in (
                line._get_qty_multiple_mismatch()
                for line in self.line_ids.filtered(lambda order_line: order_line.active)
            )
            if mismatch
        ]

    @api.model
    def _format_qty_multiple_value(self, value):
        return ('%.6f' % (value or 0.0)).rstrip('0').rstrip('.') or '0'

    def _open_qty_multiple_confirm_wizard(self, mismatches):
        self.ensure_one()

        detail_blocks = []

        for index, mismatch in enumerate(mismatches, start=1):
            values = dict(mismatch)

            values.update({
                'index': index,
                'product': escape(mismatch.get('product') or ''),
                'pack_qty': escape(
                    self._format_qty_multiple_value(
                        mismatch['pack_qty']
                    )
                ),
                'rate_value': escape(
                    self._format_qty_multiple_value(
                        mismatch['rate_value']
                    )
                ),
                'smallest_qty': escape(
                    self._format_qty_multiple_value(
                        mismatch['smallest_qty']
                    )
                ),
                'qty_multiple': escape(
                    self._format_qty_multiple_value(
                        mismatch['qty_multiple']
                    )
                ),
                'base_uom': escape(
                    mismatch.get('base_uom') or ''
                ),
                'pack_uom': escape(
                    mismatch.get('pack_uom') or ''
                ),
            })

            detail = _(
                """
                <div style="margin-bottom: 16px;">
                    <div>
                        <strong>%(index)s. %(product)s</strong>
                    </div>

                    <div>
                        Pack Qty: %(pack_qty)s
                    </div>

                    <div>
                        Pack Conversion:
                        %(rate_value)s %(base_uom)s / %(pack_uom)s
                    </div>

                    <div>
                        Smallest Quantity:
                        <span style="color: #dc3545; font-weight: 600;">
                            %(smallest_qty)s %(base_uom)s
                        </span>
                    </div>

                    <div>
                        Qty Multiple:
                        %(qty_multiple)s %(base_uom)s
                    </div>
                </div>
                """
            ) % values

            detail_blocks.append(detail)

        return {
            'name': _('Quantity Multiple Warning'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order.qty.multiple.confirm.wizard',
            'view_mode': 'form',
            'target': 'new',
            'context': dict(
                self.env.context,
                **{
                    'default_order_id': self.id,
                    'default_message': _(
                        'Some order items do not match '
                        'the configured quantity multiple.'
                    ),
                    'default_mismatch_details': ''.join(
                        detail_blocks
                    ),
                    'default_question': _(
                        'The ordered quantities above do not match '
                        'their product quantity multiples. '
                        'Do you want to continue processing this RFQ?'
                    ),
                }
            ),
        }

    def _get_agreement_order_date(self):
        self.ensure_one()
        order_datetime = fields.Datetime.to_datetime(self.order_date) if self.order_date else False
        return order_datetime.date() if order_datetime else False

    def _is_valid_rate_agreement(self, agreement, supplier=False):
        self.ensure_one()
        supplier = supplier or self.supplier_id
        order_date = self._get_agreement_order_date()
        return bool(
            agreement
            and order_date
            and agreement.company_id == self.company_id
            and agreement.supplier_id == supplier
            and agreement.purchase_type_id == self.purchase_type_id
            and agreement.type == 'rate'
            and agreement.state == 'validated'
            and agreement.date_start
            and agreement.date_end
            and agreement.date_start <= order_date
            and agreement.date_end >= order_date
        )

    def _lookup_default_agreement(self, supplier=False):
        self.ensure_one()
        supplier = supplier or self.supplier_id
        order_date = self._get_agreement_order_date()
        if self.stock_type == 'non_stock' or not supplier or not self.purchase_type_id or not order_date:
            return self.env['eproc.agreement']
        agreement = supplier.default_agreement_id
        if self._is_valid_rate_agreement(agreement, supplier=supplier):
            return agreement
        domain = [
            ('company_id', '=', self.company_id.id),
            ('supplier_id', '=', supplier.id),
            ('purchase_type_id', '=', self.purchase_type_id.id),
            ('type', '=', 'rate'),
            ('state', '=', 'validated'),
            ('date_start', '<=', order_date),
            ('date_end', '>=', order_date),
        ]
        return self.env['eproc.agreement'].search(domain, order='date_start desc, id desc', limit=1)

    def _get_approval_type_domain(self):
        self.ensure_one()
        amount = self.total_netprice or 0.0
        return [
            ('type', '=', 'order'),
            ('purchase_type_id', '=', self.purchase_type_id.id if self.purchase_type_id else False),
            ('min_amount', '<=', amount),
            ('max_amount', '>=', amount),
            '|', ('company_id', '=', False), ('company_id', '=', self.company_id.id),
        ]

    def _get_eproc_order_domains(self):
        self.ensure_one()
        order_date = self._get_agreement_order_date()
        return {
            'supplier_id': [
                ('is_eproc', '=', True),
                ('supplier', '=', True),
                ('eproc_type_id', '=', self.purchase_type_id.id if self.purchase_type_id else False),
                ('supplier_hospital_ids.company_id', '=', self.company_id.id),
            ],
            'agreement_id': [
                ('company_id', '=', self.company_id.id),
                ('purchase_type_id', '=', self.purchase_type_id.id if self.purchase_type_id else False),
                '|',
                '&', '&', '&', '&',
                ('type', '=', 'rate'),
                ('supplier_id', '=', self.supplier_id.id if self.supplier_id else False),
                ('state', '=', 'validated'),
                ('date_start', '<=', order_date),
                ('date_end', '>=', order_date),
                '&', ('type', '=', 'tender'), ('state', 'in', ('tender', 'validated')),
            ],
            'approval_type_id': self._get_approval_type_domain(),
        }

    def _is_valid_supplier_for_purchase_type(self):
        self.ensure_one()
        return not (
                    self.supplier_id and self.purchase_type_id) or self.supplier_id.eproc_type_id == self.purchase_type_id

    def _get_supplier_company_mapping(self, supplier=False, company=False):
        self.ensure_one()
        supplier = supplier or self.supplier_id
        company = company or self.company_id
        if not supplier or not company:
            return self.env['eproc.supplier.mapping']
        return supplier._get_eproc_company_mapping(company)

    def _is_valid_supplier_for_company(self):
        self.ensure_one()
        return not (self.supplier_id and self.company_id) or bool(self._get_supplier_company_mapping())

    def _is_valid_agreement_for_order(self):
        self.ensure_one()
        agreement = self.agreement_id
        if not agreement:
            return True
        if agreement.type == 'tender':
            return (
                    agreement.purchase_type_id == self.purchase_type_id
                    and agreement.company_id == self.company_id
                    and agreement.state in ('tender', 'validated')
            )
        return self._is_valid_rate_agreement(agreement)

    def _is_valid_approval_type_for_order(self):
        self.ensure_one()
        approval_type = self.approval_type_id
        amount = self.total_netprice or 0.0
        if not approval_type:
            return True
        if not self.line_ids:
            return True
        return (
                approval_type.type == 'order'
                and approval_type.purchase_type_id == self.purchase_type_id
                and (not approval_type.company_id or approval_type.company_id == self.company_id)
                and (approval_type.min_amount or 0.0) <= amount
                and (approval_type.max_amount or 0.0) >= amount
        )

    def _is_editable_for_agreement_pricing(self):
        self.ensure_one()
        return self.state in ('draft', 'tender', 'rejected')

    def _is_stock_order(self):
        self.ensure_one()
        return self.stock_type != 'non_stock'

    def _refresh_agreement_pricing_lines(self, write_existing=True):
        for record in self.filtered(
                lambda order: order._is_stock_order() and order._is_editable_for_agreement_pricing()):
            lines = record.line_ids.filtered(lambda line: line.product_tmpl_id and line.pack_id and line.pack_qty)
            lines._apply_agreement_pricing(write_existing=write_existing)
            record._compute_total_price()

    def _prepare_supplier_defaults(self, supplier):
        self.ensure_one()
        mapping = self._get_supplier_company_mapping(supplier=supplier)
        return {
            'location_receipt_id': mapping.receipt_location_id.id if mapping else False,
            'location_supplier_id': mapping.supplier_location_id.id if mapping else False,
        }

    def _validate_required_locations(self):
        for record in self:
            if not record.location_receipt_id:
                raise UserError(_('Receipt Location is required.'))
            if not record.location_supplier_id:
                raise UserError(_('Supplier Location is required.'))

    @api.onchange('purchase_type_id')
    def _onchange_purchase_type_id(self):
        for record in self:
            if record.supplier_id and not record._is_valid_supplier_for_purchase_type():
                record.supplier_id = False
                record.term_id = False
                record.location_receipt_id = False
                record.location_supplier_id = False
                record.lead_time = 0
                record.date_planned = False
            if record.agreement_id and not record._is_valid_agreement_for_order():
                record.agreement_id = False
            if (
                    record._is_stock_order()
                    and record.state != 'tender'
                    and record.supplier_id
                    and not record.agreement_id
            ):
                agreement = record._lookup_default_agreement()
                record.agreement_id = agreement.id
                record.lead_time = agreement.lead_time or getattr(record.supplier_id, 'eproc_lead_time', 0) or 0
                record._update_date_planned()
            record._refresh_agreement_pricing_lines(write_existing=False)
            if record.approval_type_id and not record._is_valid_approval_type_for_order():
                record.approval_type_id = False
            return {'domain': record._get_eproc_order_domains()}

    @api.onchange('supplier_id')
    def _onchange_supplier_id(self):
        for record in self:
            if record._origin and record._origin.id and record._origin.line_ids and record.supplier_id != record._origin.supplier_id:
                # Odoo onchange cannot open an act_window confirmation without custom JS.
                # Keep this direct edit safe and use action_change_supplier_confirm for the modal flow.
                record.supplier_id = record._origin.supplier_id
                return {
                    'warning': {
                        'title': _('Supplier change requires confirmation'),
                        'message': _(
                            'This PO already has item lines. Use the Change Supplier button to confirm deleting existing lines.'),
                    },
                    'domain': record._get_eproc_order_domains(),
                }
            supplier = record.supplier_id
            if supplier and not record._get_supplier_company_mapping(supplier=supplier):
                supplier_name = supplier.display_name
                company_name = record.company_id.display_name
                record.supplier_id = False
                record.term_id = False
                record.agreement_id = False
                record.location_receipt_id = False
                record.location_supplier_id = False
                record.lead_time = 0
                record.date_planned = False
                return {
                    'warning': {
                        'title': _('Supplier is not applicable'),
                        'message': _('Supplier %s is not mapped to company %s.') % (supplier_name, company_name),
                    },
                    'domain': record._get_eproc_order_domains(),
                }
            record.term_id = getattr(supplier, 'eproc_term_id', False).id if supplier and getattr(supplier,
                                                                                                  'eproc_term_id',
                                                                                                  False) else False
            supplier_defaults = record._prepare_supplier_defaults(supplier)
            record.location_receipt_id = supplier_defaults['location_receipt_id']
            record.location_supplier_id = supplier_defaults['location_supplier_id']
            tender_agreement = record.agreement_id.filtered(
                lambda agreement: agreement.type == 'tender' and record._is_valid_agreement_for_order()
            )
            agreement = tender_agreement or (
                record._lookup_default_agreement(supplier) if supplier else record.env['eproc.agreement']
            )
            record.agreement_id = agreement.id
            record.lead_time = agreement.lead_time or getattr(supplier, 'eproc_lead_time', 0) or 0
            record._update_date_planned()
            record._refresh_agreement_pricing_lines(write_existing=False)
            if record.approval_type_id and not record._is_valid_approval_type_for_order():
                record.approval_type_id = False
            return {'domain': record._get_eproc_order_domains()}

    @api.onchange('company_id')
    def _onchange_company_supplier_mapping(self):
        for record in self:
            if record.supplier_id and not record._is_valid_supplier_for_company():
                record.supplier_id = False
                record.term_id = False
                record.agreement_id = False
                record.lead_time = 0
                record.date_planned = False
                record.location_receipt_id = False
                record.location_supplier_id = False
            elif record.supplier_id:
                supplier_defaults = record._prepare_supplier_defaults(record.supplier_id)
                record.location_receipt_id = supplier_defaults['location_receipt_id']
                record.location_supplier_id = supplier_defaults['location_supplier_id']
            return {'domain': record._get_eproc_order_domains()}

    @api.onchange('agreement_id')
    def _onchange_agreement_id(self):
        for record in self:
            agreement = record.agreement_id

            if agreement and agreement.type == 'rate':
                if not agreement.supplier_id._get_eproc_company_mapping(record.company_id):
                    supplier_name = agreement.supplier_id.display_name
                    company_name = record.company_id.display_name
                    record.agreement_id = False
                    record.supplier_id = False
                    record.location_receipt_id = False
                    record.location_supplier_id = False
                    return {
                        'warning': {
                            'title': _('Supplier is not applicable'),
                            'message': _('Supplier %s is not mapped to company %s.')
                                       % (supplier_name, company_name),
                        },
                        'domain': record._get_eproc_order_domains(),
                    }
                record.supplier_id = agreement.supplier_id.id
                supplier_defaults = record._prepare_supplier_defaults(agreement.supplier_id)
                record.location_receipt_id = supplier_defaults['location_receipt_id']
                record.location_supplier_id = supplier_defaults['location_supplier_id']
                record.lead_time = agreement.lead_time or getattr(agreement.supplier_id, 'eproc_lead_time', 0) or 0
            elif agreement:
                record.lead_time = agreement.lead_time or getattr(record.supplier_id, 'eproc_lead_time', 0) or 0
            elif record.supplier_id:
                record.lead_time = getattr(record.supplier_id, 'eproc_lead_time', 0) or 0

            record._update_date_planned()

            # Re-apply pricing untuk semua line berdasarkan agreement baru.
            lines = record.line_ids.filtered(
                lambda line: line.product_tmpl_id and line.pack_id and line.pack_qty
            )
            warning = lines._apply_agreement_pricing(
                show_warning=True,
                write_existing=False,
            ) if lines and record._is_stock_order() else False

            record._compute_total_price()

            if record.approval_type_id and not record._is_valid_approval_type_for_order():
                record.approval_type_id = False

            result = {
                'domain': record._get_eproc_order_domains(),
            }
            if warning:
                result['warning'] = warning

            return result

    @api.onchange('lead_time', 'order_date')
    def _onchange_lead_time_order_date(self):
        for record in self:
            if record._is_editable_for_agreement_pricing() and record.agreement_id.type == 'rate':
                if not record._is_valid_rate_agreement(record.agreement_id):
                    agreement = record._lookup_default_agreement() if record._is_stock_order() else record.env['eproc.agreement']
                    record.agreement_id = agreement.id
                    record.lead_time = agreement.lead_time or getattr(record.supplier_id, 'eproc_lead_time', 0) or 0
            elif (
                    record._is_editable_for_agreement_pricing()
                    and record._is_stock_order()
                    and record.state != 'tender'
                    and record.supplier_id
                    and not record.agreement_id
            ):
                agreement = record._lookup_default_agreement()
                record.agreement_id = agreement.id
                record.lead_time = agreement.lead_time or getattr(record.supplier_id, 'eproc_lead_time', 0) or 0
            record._update_date_planned()
            record._refresh_agreement_pricing_lines(write_existing=False)
            return {'domain': record._get_eproc_order_domains()}

    @api.onchange('stock_type')
    def _onchange_stock_type(self):
        for record in self:
            if record._is_stock_order() and record._is_editable_for_agreement_pricing():
                if record.state != 'tender' and (
                        not record.agreement_id
                        or (
                            record.agreement_id.type == 'rate'
                            and not record._is_valid_rate_agreement(record.agreement_id)
                        )
                ):
                    agreement = record._lookup_default_agreement()
                    record.agreement_id = agreement.id
                    record.lead_time = agreement.lead_time or getattr(record.supplier_id, 'eproc_lead_time', 0) or 0
                record._update_date_planned()
                record._refresh_agreement_pricing_lines(write_existing=False)
            return {'domain': record._get_eproc_order_domains()}

    @api.onchange('line_ids', 'line_ids.total_netprice', 'total_netprice')
    def _onchange_total_netprice(self):
        for record in self:
            if record.approval_type_id and not record._is_valid_approval_type_for_order():
                record.approval_type_id = False
            return {'domain': {'approval_type_id': record._get_approval_type_domain()}}

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            company = self.env['res.company'].browse(vals.get('company_id')) if vals.get(
                'company_id') else self.env.company
            purchase_type = self.env['eproc.type'].browse(vals.get('purchase_type_id')).exists() if vals.get(
                'purchase_type_id') else self.env['eproc.type']
            if not purchase_type:
                raise UserError(_('Procurement Type is required before creating an RFQ.'))
            if vals.get('supplier_id'):
                supplier = self.env['res.partner'].browse(vals['supplier_id'])
                mapping = supplier._get_eproc_company_mapping(company)
                if not mapping:
                    raise ValidationError(
                        _('Supplier %s is not mapped to company %s.')
                        % (supplier.display_name, company.display_name)
                    )
                if 'location_receipt_id' not in vals:
                    vals['location_receipt_id'] = mapping.receipt_location_id.id or False
                if 'location_supplier_id' not in vals:
                    vals['location_supplier_id'] = mapping.supplier_location_id.id or False
            if not vals.get('order_no') or vals.get('order_no') == '/':
                vals['order_no'] = self._next_order_sequence(company, 'rfq', purchase_type)
            vals.setdefault('code', vals['order_no'])
            vals.setdefault('user_id', self.env.user.id)
            vals.setdefault('department_id', self.env.user.department_id.id)
            vals.setdefault('order_date', fields.Datetime.now())
            if vals.get('order_type') == 'auto':
                vals['order_type'] = 'auto'
            if vals.get('lead_time') is not None and not vals.get('date_planned'):
                vals['date_planned'] = fields.Datetime.to_string(
                    fields.Datetime.from_string(vals['order_date']) + timedelta(days=vals.get('lead_time') or 0))
        records = super(EprocOrder, self).create(vals_list)
        records.filtered(lambda order: order.state in ('approval', 'purchase', 'partial', 'done', 'expired'))._check_budget_ceiling()
        return records

    def write(self, vals):
        if {'state', 'company_id', 'purchase_type_id', 'active', 'line_ids'} & set(vals):
            self.mapped('line_ids.budget_item_id')._lock_tracking()
        if vals.get('state') in ('approval', 'purchase', 'partial', 'done', 'expired'):
            entering = self.filtered(lambda order: order.state not in ('approval', 'purchase', 'partial', 'done', 'expired'))
            if entering:
                entering.filtered(lambda order: bool(order.line_ids.mapped('budget_item_id')))._lock_lifecycle()
                entering._check_budget_ceiling()
        if len(self) > 1 and {'supplier_id', 'company_id', 'agreement_id'} & set(vals):
            for record in self:
                record.write(dict(vals))
            return True

        agreement_change = 'agreement_id' in vals

        if vals.get('supplier_id') and not self.env.context.get('confirm_supplier_change') and not agreement_change:
            new_supplier = self.env['res.partner'].browse(vals['supplier_id'])
            blocked = self.filtered(lambda rec: rec.supplier_id and rec.supplier_id != new_supplier and rec.line_ids)
            if blocked:
                raise UserError(
                    _('Changing supplier on a PO with existing lines requires confirmation. Use the Change Supplier button.'))
        if vals.get('supplier_id'):
            supplier = self.env['res.partner'].browse(vals['supplier_id'])
            if len(self) == 1 and 'agreement_id' not in vals:
                agreement = (
                    self._lookup_default_agreement(supplier)
                    if vals.get('stock_type', self.stock_type) != 'non_stock'
                    else self.env['eproc.agreement']
                )
                vals['agreement_id'] = agreement.id if agreement else False
                vals['lead_time'] = agreement.lead_time or getattr(supplier, 'eproc_lead_time', 0) or 0
        if 'agreement_id' in vals and 'lead_time' not in vals:
            agreement = self.env['eproc.agreement'].browse(vals['agreement_id']) if vals.get('agreement_id') else \
            self.env['eproc.agreement']
            if agreement:
                if agreement.type == 'rate':
                    vals.setdefault('supplier_id', agreement.supplier_id.id)
                supplier = self.env['res.partner'].browse(vals.get('supplier_id')) if vals.get(
                    'supplier_id') else (self.supplier_id if len(self) == 1 else agreement.supplier_id)
                vals['lead_time'] = agreement.lead_time or getattr(supplier, 'eproc_lead_time', 0) or 0
            elif len(self) == 1:
                supplier = self.env['res.partner'].browse(vals['supplier_id']) if vals.get(
                    'supplier_id') else self.supplier_id
                vals['lead_time'] = getattr(supplier, 'eproc_lead_time', 0) or 0
        if {'supplier_id', 'company_id'} & set(vals):
            supplier = (
                self.env['res.partner'].browse(vals['supplier_id'])
                if vals.get('supplier_id')
                else (self.supplier_id if 'supplier_id' not in vals else self.env['res.partner'])
            )
            company = (
                self.env['res.company'].browse(vals['company_id'])
                if vals.get('company_id')
                else (self.company_id if 'company_id' not in vals else self.env['res.company'])
            )
            mapping = supplier._get_eproc_company_mapping(company) if supplier and company else self.env[
                'eproc.supplier.mapping']
            if supplier and company and not mapping:
                raise ValidationError(
                    _('Supplier %s is not mapped to company %s.')
                    % (supplier.display_name, company.display_name)
                )
            if 'location_receipt_id' not in vals:
                vals['location_receipt_id'] = mapping.receipt_location_id.id if mapping else False
            if 'location_supplier_id' not in vals:
                vals['location_supplier_id'] = mapping.supplier_location_id.id if mapping else False
        if {'company_id', 'purchase_type_id'} & set(vals):
            for record in self.filtered(lambda order: bool(order.line_ids.mapped('budget_item_id'))):
                if any(key in vals and (vals[key] or False) != record[key].id for key in ('company_id', 'purchase_type_id')):
                    raise AccessError(_('The company and procurement type of a budget-linked RFQ cannot be changed.'))
        locked = self.filtered(lambda rec: rec.state not in ('draft', 'tender', 'rejected'))
        protected = set(vals) - {'state', 'approval_rule_id', 'approval_rule_sequence', 'approval_next_stored',
                                 'approval_ids', 'order_purchase_no', 'order_valid_date', 'cancel_datetime',
                                 'cancel_reason', 'active', 'message_follower_ids', 'message_ids', 'activity_ids'}
        if locked and protected and not self.env.context.get('skip_order_lock'):
            raise UserError(_('RFQ/PO data can only be edited in Draft, Tender, or Rejected state.'))
        res = super(EprocOrder, self).write(vals)
        if any(key in vals for key in ('supplier_id', 'agreement_id', 'lead_time', 'order_date')):
            for record in self.filtered(lambda rec: rec.state in ('draft', 'tender', 'rejected')):
                if not vals.get('date_planned'):
                    record.with_context(skip_order_lock=True)._update_date_planned()
        if any(key in vals for key in ('supplier_id', 'agreement_id', 'order_date', 'stock_type')):
            self._refresh_agreement_pricing_lines()
        if vals.get('state') == 'purchase':
            for record in self:
                record._release_purchase_order()
        if vals.get('state') == 'cancelled':
            self.mapped('line_ids').with_context(skip_order_line_lock=True).write({'state': 'cancelled'})
        if 'state' in vals:
            self.mapped('line_ids.request_line_id.request_id')._sync_realization_state_from_lines()
            self._sync_orderpoint_logs_from_state(vals.get('state'))
        if 'date_planned' in vals:
            for order in self:
                order.line_ids.with_context(skip_order_line_lock=True).write({'date_planned': order.date_planned})
        if {'state', 'active', 'line_ids'} & set(vals):
            self.mapped('line_ids.budget_item_id')._check_commitment_ceiling()
        return res

    def _sync_orderpoint_logs_from_state(self, state=False):
        for record in self:
            logs = record.line_ids.mapped('orderpoint_log_id').filtered(lambda log: log)
            if not logs:
                continue
            if (state or record.state) == 'cancelled':
                logs.with_context(allow_orderpoint_log_realize_write=True).write({
                    'state': 'draft',
                    'order_id': False,
                })
            elif (state or record.state) in ('approval', 'purchase', 'partial', 'done', 'expired'):
                logs.with_context(allow_orderpoint_log_realize_write=True).write({
                    'state': 'auto_rfq',
                    'order_id': record.id,
                })

    def unlink(self):
        raise UserError(_('RFQ/PO records cannot be deleted. Please archive them instead.'))

    def copy(self, default=None):
        raise UserError(_('RFQ/PO records cannot be duplicated. Please create a new RFQ instead.'))

    @api.constrains('supplier_id', 'purchase_type_id', 'agreement_id', 'approval_type_id', 'total_netprice',
                    'company_id', 'location_receipt_id', 'location_supplier_id')
    def _check_order_selection_domains(self):
        for record in self:
            if not record._is_valid_supplier_for_company():
                raise ValidationError(
                    _('Supplier %s is not mapped to company %s.')
                    % (record.supplier_id.display_name, record.company_id.display_name)
                )
            if not record._is_valid_supplier_for_purchase_type():
                raise ValidationError(_('Supplier must match the selected procurement type.'))
            if not record._is_valid_agreement_for_order():
                raise ValidationError(_('Agreement must match the supplier, company, and procurement type on this PO.'))
            if not record._is_valid_approval_type_for_order():
                raise ValidationError(_('Approval Type must match the procurement type and total net amount range.'))
            for location, label in (
                    (record.location_receipt_id, _('Receipt Location')),
                    (record.location_supplier_id, _('Supplier Location'))):
                if location and (location.company_id != record.company_id or not location.is_eproc):
                    raise ValidationError(_('%s must be an E-Proc location belonging to the order company.') % label)
            if record.state not in ('draft', 'tender', 'rejected', 'cancelled'):
                record._validate_required_locations()

    @api.constrains('state')
    def _check_processed_order_mapping_and_locations(self):
        for record in self.filtered(lambda order: order.state not in ('draft', 'tender', 'rejected', 'cancelled')):
            if not record._is_valid_supplier_for_company():
                raise ValidationError(
                    _('Supplier %s is not mapped to company %s.')
                    % (record.supplier_id.display_name, record.company_id.display_name)
                )
            record._validate_required_locations()

    def action_change_supplier_confirm(self):
        self.ensure_one()
        if self.state not in ('draft', 'tender'):
            raise UserError(_('Supplier can only be changed with line reset while the PO is Draft or Tender.'))
        return {
            'name': _('Change Supplier'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order.change.supplier.wizard',
            'view_mode': 'form',
            'target': 'new',
            'context': {
                'default_order_id': self.id,
                'default_purchase_type_id': self.purchase_type_id.id,
            },
        }

    def action_change_agreement_confirm(self):
        self.ensure_one()
        if self.state not in ('draft', 'tender'):
            raise UserError(_('Agreement can only be changed with line reset while the RFQ is Draft or Tender.'))
        return {
            'name': _('Change Agreement'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order.change.agreement.wizard',
            'view_mode': 'form',
            'target': 'new',
            'context': {
                'default_order_id': self.id,
                'default_purchase_type_id': self.purchase_type_id.id,
                'default_supplier_id': self.supplier_id.id,
                'default_current_agreement_id': self.agreement_id.id,
            },
        }

    def open_request_item(self):
        self.ensure_one()
        return {
            'name': _('Related PR Item(s)'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.request.line',
            'view_mode': 'tree,form',
            'domain': [('id', 'in', self.line_ids.mapped('request_line_id').ids)],
            'context': dict(self._context, create=False, delete=False, edit=False),
        }

    def open_receipt_item(self):
        self.ensure_one()
        return {
            'name': _('Related Receipt Item(s)'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.receipt.line',
            'view_mode': 'tree,form',
            'domain': [('id', 'in', self.line_ids.mapped('receipt_line_ids').ids)],
            'context': dict(self._context, create=False, delete=False, edit=False),
        }

    def open_line_item(self):
        self.ensure_one()
        return {
            'name': _('RFQs Items'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order.line',
            'view_mode': 'tree,form',
            'domain': [('order_id', '=', self.id)],
            'context': dict(self._context, create=False, delete=True, edit=False),
        }

    def _get_enabled_approval_rules(self):
        self.ensure_one()
        return self.approval_type_id.rule_ids.filtered(lambda rule: rule.enabled).sorted('sequence')

    def _create_approval_logs(self, rules):
        self.ensure_one()
        values = []
        for rule in rules:
            values.append({
                'order_id': self.id,
                'approval_type_id': self.approval_type_id.id,
                'approval_rule_id': rule.id,
                'sequence': int(rule.sequence or 0),
                'position_id': rule.position_id.id,
                'delegate_user_id': rule.delegate_user_id.id,
                'amount_snapshot': self.total_netprice or 0.0,
                'type': rule.type,
                'show': rule.show,
                'state': 'pending',
                'active': True,
            })
        if values:
            self.env['eproc.approval.log'].create(values)

    def _get_current_approval_log(self):
        self.ensure_one()
        return self.approval_ids.filtered(lambda log: log.state == 'pending' and log.active).sorted('sequence')[:1]

    def _update_approval_flags(self):
        for record in self:
            next_log = record._get_current_approval_log()
            if next_log:
                next_name = next_log.position_id.name or next_log.delegate_user_id.name or next_log.user_id.name
                record.with_context(skip_order_lock=True).write({
                    'approval_rule_id': next_log.approval_rule_id.id,
                    'approval_rule_sequence': next_log.sequence,
                    'approval_next_stored': next_name,
                })
            else:
                record.with_context(skip_order_lock=True).write({
                    'approval_rule_id': False,
                    'approval_rule_sequence': 0,
                    'approval_next_stored': 'Completed',
                })

    def _is_current_approver(self, approval_log):
        user = self.env.user
        admin = self.env.ref('base.user_admin', raise_if_not_found=False)
        if admin and user.id == admin.id:
            return True
        position_ids = [getattr(user, 'position_id', False).id, getattr(user, 'second_position_id', False).id]
        position_ids = [pos_id for pos_id in position_ids if pos_id]
        return bool(
            (approval_log.position_id and approval_log.position_id.id in position_ids)
            or approval_log.user_id == user
            or approval_log.delegate_user_id == user
        )

    def _release_purchase_order(self):
        # Existing release is also called when a partial PO returns to purchase.
        # Only an initial release gets a snapshot; never backfill legacy POs here.
        initial = self.filtered(lambda order: not order.order_purchase_no and not order.order_valid_date)
        for record in self:
            values = {}
            if not record.order_purchase_no:
                values['order_purchase_no'] = record._next_order_sequence(
                    record.company_id, 'po', record.purchase_type_id
                )
            if not record.order_valid_date:
                values['order_valid_date'] = fields.Datetime.now()
            if values:
                record.with_context(skip_order_lock=True).write(values)
            record.line_ids.filtered(lambda line: line.state == 'draft').with_context(skip_order_line_lock=True).write(
                {'state': 'ready'})
        for order in initial:
            valid_datetime = fields.Datetime.to_datetime(order.order_valid_date)
            valid_date = fields.Datetime.context_timestamp(
                order.with_context(tz=BUSINESS_TZ), valid_datetime).date()
            days = order.purchase_type_id.order_expiration_days
            order.with_context(skip_order_lock=True).write({
                'order_expiry_date': valid_date + timedelta(days=days) if days else False,
            })
            order._update_date_planned()

    @api.constrains('state', 'company_id', 'line_ids')
    def _check_budget_line_sources(self):
        # Related-field recomputation alone does not run child constraints when
        # a header changes state/company. Cover approval and direct ORM writes.
        self.mapped('line_ids')._check_budget_source()

    def _check_budget_ceiling(self):
        lines = self.mapped('line_ids').filtered('active')
        for order in self:
            order.line_ids.mapped('request_line_id')._check_budget_tracking(require_validated=True, committed_pr=True)
            if any(line.product_tmpl_id and line.product_tmpl_id._requires_medical_equipment_budget()
                   and not line.budget_item_id for line in order.line_ids.filtered('active')):
                raise ValidationError(_('CapEx Medical Equipment RFQs must originate from budget-linked PR items.'))
        lines.mapped('budget_item_id')._check_commitment_ceiling(proposed_orders=self)

    def action_confirm(self):
        self.filtered(lambda order: bool(order.line_ids.mapped('budget_item_id')))._lock_lifecycle()
        self._check_budget_ceiling()
        for record in self:
            if record.state not in ('draft', 'tender', 'rejected'):
                raise UserError(_('Only Draft, Tender, or Rejected RFQ can be confirmed.'))
            if not self.env.context.get('skip_qty_multiple_warning'):
                mismatches = record._get_qty_multiple_mismatches()
                if mismatches:
                    return record._open_qty_multiple_confirm_wizard(mismatches)
            if (
                    not self.env.context.get('skip_agreement_date_range_warning')
                    and record.agreement_id
                    and not record._is_confirm_date_inside_agreement_range()
            ):
                return record._open_agreement_date_range_confirm_wizard()
        for record in self:
            record._validate_required_locations()
            record._validate_stock_agreement_pricing()
            record._check_order_selection_domains()
            if not record.approval_type_id:
                raise UserError(_('Please select an approval type to proceed.'))
            if not record.line_ids:
                raise UserError(_('Please add at least one order item.'))
            rules = record._get_enabled_approval_rules()
            last_reject_log = record.approval_ids.filtered(lambda log: log.state == 'rejected').sorted('approval_date',
                                                                                                       reverse=True)[:1]
            restart_approval = True
            comment = _('New submission, please approve this transaction %s.') % record.order_no
            if last_reject_log and float_compare(record.total_netprice, last_reject_log.amount_snapshot,
                                                 precision_digits=2) == 0:
                restart_approval = False
                comment = _(
                    'Revision accepted with consistent amount, please continue approval for %s.') % record.order_no
            if not rules:
                record.with_context(skip_order_lock=True).write(
                    {'state': 'purchase', 'approval_next_stored': 'Completed',
                     'order_request_date': fields.Datetime.now()})
                record.message_post(body=_('New submission completed without approval.'))
                continue
            if restart_approval:
                record.approval_ids.write({'active': False})
                record._create_approval_logs(rules)
            elif last_reject_log:
                last_reject_log.write(
                    {'state': 'pending', 'active': True, 'notes': _('Revision accepted with no amount change.')})
                record.approval_ids.filtered(lambda log: log.sequence > last_reject_log.sequence).write(
                    {'active': True})
            record.with_context(skip_order_lock=True).write({
                'state': 'approval', 'order_request_date': fields.Datetime.now()})
            record._update_approval_flags()
            record.action_notify_approver(comment=comment)
        return True

    def _validate_stock_agreement_pricing(self):
        for record in self.filtered(lambda order: order._is_stock_order()):
            if not record.agreement_id:
                raise UserError(_('Agreement is required for Stock RFQ/PO.'))
            # Tender RFQs keep their existing Bid Tabulation pricing flow.
            if record.agreement_id.type == 'tender':
                continue
            if not record._is_valid_rate_agreement(record.agreement_id):
                raise UserError(
                    _('The selected Rate Agreement is not valid for this RFQ supplier, procurement type, company, and order date.')
                )
            for line in record.line_ids.filtered(lambda order_line: order_line.active):
                agreement_line = line._get_agreement_line()
                if not agreement_line:
                    order_date = record._get_agreement_order_date()
                    raise UserError(_(
                        'No valid agreement price was found for product %s, pack %s, quantity %s, and order date %s.'
                    ) % (
                        line.product_tmpl_id.display_name,
                        line.pack_id.display_name,
                        line.pack_qty,
                        fields.Date.to_string(order_date) if order_date else '',
                    ))
                line._apply_agreement_pricing()
            record._compute_total_price()

    def action_approve(self):
        for record in self:
            if record.state != 'approval':
                raise UserError(_('Only RFQ in Approval state can be approved.'))
            current_log = record._get_current_approval_log()
            if not current_log:
                raise UserError(_('There is no pending approval queue for this document.'))
            if not record._is_current_approver(current_log):
                raise UserError(_('Authority Denied. This document requires approval from position: %s.') % (
                            current_log.position_id.name or _('Undefined')))
            user_pos_name = current_log.position_id.name or _('Authorized Position')
            user_name = self.env.user.partner_id.name or self.env.user.name
            comment = _('Approved by %s as %s.') % (user_name, user_pos_name)
            current_log.write({
                'state': 'approved',
                'action_user_id': self.env.user.id,
                'approval_date': fields.Datetime.now(),
                'amount_snapshot': record.total_netprice,
                'notes': comment,
            })
            if record._get_current_approval_log():
                record._update_approval_flags()
                record.action_notify_approver(comment=_('%s Awaiting next approval.') % comment)
            else:
                record._update_approval_flags()
                record.with_context(skip_order_lock=True).write({'state': 'purchase'})
                record.action_notify_approver(
                    comment=_('Approval completed by %s as %s. PO released.') % (user_name, user_pos_name))
        return True

    def action_reject_confirm(self):
        self.ensure_one()
        return self._open_approval_dialog('reject')

    def action_cancel_confirm(self):
        self.ensure_one()
        return self._open_approval_dialog('cancel')

    def _open_approval_dialog(self, action_type):
        self.ensure_one()
        return {
            'name': _('Reject Confirmation') if action_type == 'reject' else _(
                'Cancel Confirmation (Cannot be undone)'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.approval.dialog',
            'view_mode': 'form',
            'target': 'new',
            'context': {
                'default_model_id': self._name,
                'default_res_id': self.id,
                'default_action_type': action_type,
                'active_id': self.id,
            },
        }

    def action_reject(self, reason=False):
        for record in self:
            if record.state != 'approval':
                raise UserError(_('Only RFQ in Approval state can be rejected.'))
            current_log = record._get_current_approval_log()
            if not current_log:
                raise UserError(_('There is no pending approval queue for this document.'))
            if not (record._is_current_approver(current_log) or self.env.user == record.user_id):
                raise UserError(_('Authority Denied. Only the Creator or Current Approver can reject this request.'))
            reason = reason or _('No reason provided')
            current_log.write({
                'state': 'rejected',
                'action_user_id': self.env.user.id,
                'approval_date': fields.Datetime.now(),
                'amount_snapshot': record.total_netprice,
                'notes': reason,
            })
            record.approval_ids.filtered(lambda log: log.state == 'pending').write({'active': False})
            record.with_context(skip_order_lock=True).write({
                'state': 'rejected',
                'approval_next_stored': _('Rejected by %s') % self.env.user.name,
            })
            record.action_notify_approver(comment=_('REJECTED: %s') % reason, action_type='reject')
        return True

    def action_cancel(self, reason=False):
        self._lock_lifecycle()
        for record in self:
            if record.state == 'purchase':
                raise UserError(_('Confirmed PO cannot be cancelled.'))
            if record.state not in ('approval', 'purchase', 'partial'):
                raise UserError(_('Only RFQ/PO in Approval, Purchase, or Partial state can be cancelled.'))
            current_log = record._get_current_approval_log()
            allowed = current_log and record._is_current_approver(current_log)
            if not allowed and self.env.user != record.user_id:
                admin = self.env.ref('base.user_admin', raise_if_not_found=False)
                allowed = admin and self.env.user.id == admin.id
            if not allowed:
                raise UserError(_('Authority Denied. Only the Creator or Current Approver can cancel this request.'))
            reason = reason or _('No reason provided')
            if current_log:
                current_log.write({
                    'state': 'cancelled',
                    'action_user_id': self.env.user.id,
                    'approval_date': fields.Datetime.now(),
                    'amount_snapshot': record.total_netprice,
                    'notes': reason,
                })
            else:
                self.env['eproc.approval.log'].create({
                    'order_id': record.id,
                    'approval_type_id': record.approval_type_id.id,
                    'sequence': (max(record.approval_ids.mapped('sequence')) or 0) + 1,
                    'user_id': record.user_id.id,
                    'action_user_id': self.env.user.id,
                    'approval_date': fields.Datetime.now(),
                    'amount_snapshot': record.total_netprice,
                    'notes': reason,
                    'state': 'cancelled',
                    'active': True,
                })
            record.approval_ids.filtered(lambda log: log.state == 'pending').write({'active': False})
            record.with_context(skip_order_lock=True).write({
                'state': 'cancelled',
                'cancel_reason': reason,
                'cancel_datetime': fields.Datetime.now(),
                'approval_next_stored': _('Cancelled by %s') % self.env.user.name,
            })
            record.action_notify_approver(comment=_('CANCELLED: %s') % reason, action_type='cancel')
        return True

    def action_draft(self):
        for record in self:
            if record.state != 'rejected':
                raise UserError(_("Only documents with 'Rejected' status can be set back to Draft."))
            last_reject_log = record.approval_ids.filtered(lambda log: log.state == 'rejected').sorted('approval_date',
                                                                                                       reverse=True)[:1]
            last_rejecter = last_reject_log.action_user_id if last_reject_log else self.env['res.users']
            if self.env.user not in (record.user_id | last_rejecter):
                raise UserError(_('Only the Creator or the Rejecting Authority can set this document back to Draft.'))
            record.approval_ids.sudo().unlink()
            record.with_context(skip_order_lock=True).write({
                'state': 'draft',
                'order_revise': record.order_revise + 1,
                'approval_rule_id': False,
                'approval_rule_sequence': 0,
                'approval_next_stored': False,
            })
            record.action_notify_approver(comment=_('Document reverted to Draft for revision.'), action_type='draft')
        return True

    def action_done(self):
        self._lock_lifecycle()
        for record in self:
            if record.state not in ('purchase', 'partial'):
                raise UserError(_('Only released PO can be completed.'))
            record.line_ids.filtered(lambda line: line.state in ('ready', 'partial')).with_context(
                skip_order_line_lock=True).write({'state': 'closed'})
            record.with_context(skip_order_lock=True).write({'state': 'done'})
        return True

    def _sync_state_from_lines(self):
        for record in self:
            if record.state not in ('purchase', 'partial'):
                continue
            active_lines = record.line_ids.filtered(lambda line: line.active)
            if not active_lines:
                continue
            if all(line.state in ('done', 'closed', 'cancelled') for line in active_lines):
                record.with_context(skip_order_lock=True).write({'state': 'done'})
            elif any(line.state == 'partial' for line in active_lines) or any(
                    (line.pack_qty_processed or 0.0) > 0.0 for line in active_lines):
                record.with_context(skip_order_lock=True).write({'state': 'partial'})
            elif record.state == 'partial':
                record.with_context(skip_order_lock=True).write({'state': 'purchase'})

    def action_notify_approver(self, comment=False, action_type='approve'):
        self.ensure_one()
        if not comment:
            comment = _('Approval status updated.')
        partner_ids = []
        subscriber_ids = []
        if self.user_id.partner_id:
            partner_ids.append(self.user_id.partner_id.id)
            subscriber_ids.append(self.user_id.partner_id.id)
        next_log = self._get_current_approval_log()
        if next_log and action_type == 'approve':
            users = self.env['res.users'].search(['|', ('position_id', '=', next_log.position_id.id),
                                                  ('second_position_id', '=', next_log.position_id.id)])
            for user in users.filtered('partner_id'):
                partner_ids.append(user.partner_id.id)
            if next_log.delegate_user_id.partner_id:
                partner_ids.append(next_log.delegate_user_id.partner_id.id)
        if subscriber_ids:
            self.message_subscribe(partner_ids=list(set(subscriber_ids)))
        self.message_post(body=comment, partner_ids=list(set(partner_ids)))

    def _get_purchase_type_print_key(self):
        self.ensure_one()
        purchase_type_name = (self.purchase_type_id.name or '').lower()
        normalized_name = (
            purchase_type_name
            .replace('-', ' ')
            .replace('_', ' ')
            .replace('/', ' ')
        )
        normalized_name = ' '.join(normalized_name.split())
        if 'non stock' in normalized_name or 'nonstock' in normalized_name:
            return 'nonstock'
        if 'stock' in normalized_name:
            return 'stock'
        return False

    def action_print_rfq(self):
        self.ensure_one()
        if self.state == 'cancelled':
            raise UserError(_('Cannot print cancelled RFQ.'))
        # if self.state != 'draft':
        #     raise UserError(_('Print Draft RFQ hanya bisa untuk RFQ dengan state Draft.'))
        return self.env['eproc.dialog.preview'].open_jasper_preview(
            title=_('Print Draft RFQ'),
            report_unit='/Mayapada/Eproc/RFQs_to_Purchase_Order',
            params={'order_id': self.id},
            company=self.company_id,
        )

    def action_print_po_nonstock(self):
        self.ensure_one()

        if self.state == 'cancelled':
            raise UserError(_('Cannot print cancelled PO.'))

        if self.state not in ('purchase', 'partial', 'done', 'expired'):
            raise UserError(_('Print PO hanya bisa untuk data yang sudah release menjadi Purchase Order.'))

        report_unit = '/Mayapada/Eproc/purchase_order_nonstock'
        title = _('Print PO Non Stock')

        signature_base_url = request.env['ir.config_parameter'].sudo().get_param(
            'eproc.jasper_base_url'
        ) or ''

        signature_token = request.env['ir.config_parameter'].sudo().get_param(
            'eproc.jasper_signature_token'
        ) or ''

        return self.env['eproc.dialog.preview'].open_jasper_preview(
            title=title,
            report_unit=report_unit,
            params={
                'order_id': self.id,
                'ODOO_BASE_URL': signature_base_url,
                'SIGNATURE_TOKEN': signature_token,
            },
            company=self.company_id,
        )

    def action_print_po_stock(self):
        self.ensure_one()

        if self.state == 'cancelled':
            raise UserError(_('Cannot print cancelled PO.'))

        if self.state not in ('purchase', 'partial', 'done', 'expired'):
            raise UserError(_('Print PO hanya bisa untuk data yang sudah release menjadi Purchase Order.'))

        report_unit = '/Mayapada/Eproc/purchase_order_stock'
        title = _('Print PO Stock')

        signature_base_url = request.env['ir.config_parameter'].sudo().get_param(
            'eproc.jasper_base_url'
        ) or ''

        signature_token = request.env['ir.config_parameter'].sudo().get_param(
            'eproc.jasper_signature_token'
        ) or ''

        return self.env['eproc.dialog.preview'].open_jasper_preview(
            title=title,
            report_unit=report_unit,
            params={
                'order_id': self.id,
                'ODOO_BASE_URL': signature_base_url,
                'SIGNATURE_TOKEN': signature_token,
            },
            company=self.company_id,
        )

    def action_print_rfq_po(self):
        self.ensure_one()
        if self.state == 'cancelled':
            raise UserError(_("Cannot print cancelled RFQ/PO."))
        if self.state in ('draft', 'tender'):
            return self.action_print_rfq()
        if self.state in ('purchase', 'partial', 'done', 'expired'):
            return self.action_print_po()
        raise UserError(_(
            'RFQ/PO hanya dapat dicetak saat RFQ masih Draft/Tender atau PO sudah release.'
        ))

    def _open_preview_dialog(self, report_type):
        self.ensure_one()
        if self.state == 'cancelled':
            raise UserError(_("Cannot print cancelled RFQ/PO."))
        wizard = self.env['eproc.order.preview.wizard'].create({
            'order_id': self.id,
            'report_code': report_type,
        })
        return {
            'name': _('Print Preview'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order.preview.wizard',
            'view_mode': 'form',
            'res_id': wizard.id,
            'target': 'new',
            'context': {
                'dialog_size': 'extra-large',
            },
        }

    def _is_stock_order(self):
        self.ensure_one()
        product_types = self.line_ids.mapped('product_tmpl_id.eproc_type')
        return bool(product_types) and all(product_type == 'stock' for product_type in product_types)


