class EprocOrderpointLog(models.Model):
    _name = 'eproc.orderpoint.log'
    _description = 'E-Proc Orderpoint Log'
    _inherit = ['mail.thread', 'mail.activity.mixin']

    @api.model
    def _get_company(self):
        return self.env.company.id

    code = fields.Char(string='Code', readonly=True, default='/', copy=False, tracking=True)
    orderpoint_id = fields.Many2one('eproc.orderpoint', string='Orderpoint Rule', required=True)
    product_tmpl_id = fields.Many2one('product.template', string='Product')
    product_uom_id = fields.Many2one('uom.uom', string='Product UoM')
    company_id = fields.Many2one('res.company', string='Company')
    calculated_date = fields.Datetime(string='Calculated Date', default=fields.Datetime.now)
    usage_in_7 = fields.Float(string='Usage in Last 7 Day(s)')
    usage_in_14 = fields.Float(string='Usage in Last 14 Day(s)')
    usage_in_30 = fields.Float(string='Usage in Last 30 Day(s)')
    usage_in_90 = fields.Float(string='Usage in Last 90 Day(s)')
    move_type = fields.Selection([
        ('5', 'Fast'),
        ('4', 'Medium Fast'),
        ('3', 'Medium'),
        ('2', 'Medium Slow'),
        ('1', 'Slow'),
        ('0', 'Very Slow'),
    ], string='Move Type')
    days_safety = fields.Float(string='Days Safety')
    days_inventory = fields.Float(string='Days of Inventory')
    days_out = fields.Float(string='Days of Stock Out')
    days_average = fields.Float(string='Days Average')
    qty_on_hand = fields.Float(string='Qty On Hand')
    qty_max_day = fields.Float(string='Qty Max Day')
    qty_min_order = fields.Float(string='Qty Min Order')
    qty_average = fields.Float(string='Qty Average')
    qty_safety = fields.Float(string='Qty Safety')
    qty_maximum = fields.Float(string='Qty Maximum')
    qty_suggested = fields.Float(string='Qty Suggested')
    qty_multiple = fields.Float(string="Multiple QTY")
    pack_id = fields.Many2one('eproc.pack', string='Pack Type')
    pack_rate = fields.Float(string='Pack Rate', compute='_compute_pack_values', store=True)
    pack_order_qty = fields.Float(string='Pack Order Qty', compute='_compute_pack_values', store=True)
    supplier_ids = fields.One2many('eproc.orderpoint.supplier', 'log_id', string='Supplier Suggestions')
    pr_count = fields.Integer(string='Requests Count', compute='_compute_realization_counts')
    pr_ids = fields.One2many('eproc.request.line', 'orderpoint_log_id', string='Requests')
    request_id = fields.Many2one('eproc.request', string='Created Request', readonly=True, copy=False, required=False)
    state = fields.Selection([
        ('draft', 'Draft'),
        ('auto_pr', 'PR Creation'),
        ('cancel', 'Cancelled'),
    ], string='State', default='draft', tracking=True)
    name = fields.Char(string='Title', compute='_compute_name', store=True)
    active = fields.Boolean(string='Active', default=True, tracking=True)

    @api.depends('code', 'product_tmpl_id.name')
    def _compute_name(self):
        for record in self:
            record.name = "%s %s" % (record.code or '/', record.product_tmpl_id.name or '')

    @api.depends('pack_id.rate_value', 'qty_suggested')
    def _compute_pack_values(self):
        for record in self:
            rate = record.pack_id.rate_value or 0.0
            record.pack_rate = rate
            qty = (record.qty_suggested or 0.0) / rate if rate else 0.0
            record.pack_order_qty = math.ceil(qty) if qty > 0.0 else 0.0

    @api.model
    def _qty_on_hand_for_orderpoint(self, orderpoint):
        domain = [('product_tmpl_id', '=', orderpoint.product_tmpl_id.id)]
        if 'company_id' in self.env['eproc.stock.quant']._fields and orderpoint.company_id:
            domain.append(('company_id', '=', orderpoint.company_id.id))
        return sum(self.env['eproc.stock.quant'].sudo().search(domain).mapped('quantity'))

    @api.model
    def _suggested_qty_for_orderpoint(self, orderpoint, qty_on_hand):
        qty_safety = orderpoint.qty_safety or 0.0
        qty_maximum = orderpoint.qty_maximum or 0.0
        if qty_on_hand >= qty_safety:
            return 0.0
        suggested = qty_maximum - qty_on_hand
        if suggested <= 0.0:
            suggested = qty_safety - qty_on_hand
        return max(suggested, 0.0)

    @api.depends('pr_ids.active')
    def _compute_realization_counts(self):
        for record in self:
            record.pr_count = len(record.pr_ids.filtered(lambda line: line.active))

    @api.model
    def _sequence_unit_code(self, company):
        unit_code = getattr(company, 'company_code', False) or 'gen'
        return str(unit_code).upper().replace(' ', '')

    @api.model
    def _next_orderpoint_code(self, company):
        unit_code = self._sequence_unit_code(company)
        sequence_code = 'SEQ.ERP.PMM.%s.ORDERPOINT' % unit_code
        code = self.env['ir.sequence'].with_company(company).next_by_code(sequence_code)
        if not code:
            raise UserError(_("No Orderpoint sequence found for unit %s with code %s.") % (unit_code, sequence_code))
        return code

    def _first_product_pack(self, product):
        if not product:
            return self.env['eproc.pack']
        return product.eproc_pack_ids.filtered(lambda pack: pack.enable)[:1]

    def _snapshot_values_from_orderpoint(self, orderpoint, qty_on_hand=False, qty_suggested=False):
        return {
            'product_tmpl_id': orderpoint.product_tmpl_id.id,
            'product_uom_id': orderpoint.product_uom_id.id,
            'company_id': orderpoint.company_id.id,
            'usage_in_7': orderpoint.usage_in_7,
            'usage_in_14': orderpoint.usage_in_14,
            'usage_in_30': orderpoint.usage_in_30,
            'usage_in_90': orderpoint.usage_in_90,
            'move_type': orderpoint.move_type,
            'days_safety': orderpoint.days_safety,
            'days_inventory': orderpoint.days_inventory,
            'days_out': orderpoint.days_out,
            'days_average': orderpoint.days_average,
            'qty_on_hand': qty_on_hand if qty_on_hand is not False else orderpoint.qty_on_hand,
            'qty_max_day': orderpoint.qty_max_day,
            'qty_min_order': orderpoint.qty_min_order,
            'qty_average': orderpoint.qty_average,
            'qty_safety': orderpoint.qty_safety,
            'qty_maximum': orderpoint.qty_maximum,
            'qty_suggested': qty_suggested if qty_suggested is not False else 0.0,
        }

    def _prepare_supplier_suggestions(self):
        self.ensure_one()
        domain = [
            ('agreement_id.company_id', '=', self.company_id.id),
            ('agreement_id.state', '=', 'validated'),
            ('agreement_id.type', '=', 'rate'),
            ('product_tmpl_id', '=', self.product_tmpl_id.id),
        ]
        if self.pack_id:
            domain.append(('pack_id', '=', self.pack_id.id))
        lines = self.env['eproc.agreement.line'].search(domain, order='uom_netprice asc, id asc')
        commands = [(5, 0, 0)]
        for priority, line in enumerate(lines, start=1):
            supplier = line.agreement_id.supplier_id
            commands.append((0, 0, {
                'supplier_id': supplier.id,
                'agreement_line_id': line.id,
                'lead_time': line.agreement_id.lead_time or getattr(supplier, 'eproc_lead_time', 0) or 0,
                'uom_price': line.uom_price,
                'tax_ids': [(6, 0, line.tax_ids.ids)],
                'disc_rate': line.disc_rate,
                'uom_netprice': line.uom_netprice,
                'priority': priority,
            }))
        return commands

    @api.onchange('orderpoint_id')
    def _onchange_orderpoint_id(self):
        for record in self:
            if record.orderpoint_id and not record.pack_id:
                record.pack_id = record._first_product_pack(record.orderpoint_id.product_tmpl_id)

    @api.model
    def _generate_orderpoint_logs(self, company=False):
        company = company or self.env.company
        orderpoint_domain = []
        if company:
            orderpoint_domain.append(('company_id', '=', company.id))
        if 'active' in self.env['eproc.orderpoint']._fields:
            orderpoint_domain.append(('active', '=', True))
        if 'type' in self.env['eproc.orderpoint']._fields:
            orderpoint_domain.append(('type', '=', 'auto'))

        created_logs = self.env['eproc.orderpoint.log']
        for orderpoint in self.env['eproc.orderpoint'].sudo().search(orderpoint_domain):
            if not orderpoint.product_tmpl_id or not orderpoint.company_id:
                continue
            qty_on_hand = self._qty_on_hand_for_orderpoint(orderpoint)
            qty_suggested = self._suggested_qty_for_orderpoint(orderpoint, qty_on_hand)
            if qty_suggested <= 0.0:
                continue
            duplicate = self.sudo().search([
                ('active', '=', True),
                ('state', '=', 'draft'),
                ('company_id', '=', orderpoint.company_id.id),
                ('orderpoint_id', '=', orderpoint.id),
                ('product_tmpl_id', '=', orderpoint.product_tmpl_id.id),
            ], limit=1)
            if duplicate:
                continue
            pack = self._first_product_pack(orderpoint.product_tmpl_id)
            values = self._snapshot_values_from_orderpoint(orderpoint, qty_on_hand, qty_suggested)
            values.update({
                'orderpoint_id': orderpoint.id,
                'calculated_date': fields.Datetime.now(),
                'pack_id': pack.id if pack else False,
                'state': 'draft',
            })
            # The rule action is intentionally not executed here; this pass keeps
            # generated logs as draft suggestions for the manual realization wizard.
            created_logs |= self.sudo().with_context(allow_orderpoint_log_create=True).create(values)
        return created_logs

    @api.model_create_multi
    def create(self, vals_list):
        if not self.env.su and not self.env.context.get('allow_orderpoint_log_create'):
            raise UserError(_('Orderpoint logs are generated by system logic and cannot be created manually.'))
        for vals in vals_list:
            orderpoint = self.env['eproc.orderpoint'].browse(vals.get('orderpoint_id'))
            company = orderpoint.company_id or self.env.company
            for key, value in self._snapshot_values_from_orderpoint(orderpoint).items():
                vals.setdefault(key, value)
            duplicate = self.sudo().search([
                ('active', '=', True),
                ('state', '=', 'draft'),
                ('orderpoint_id', '=', orderpoint.id),
                ('product_tmpl_id', '=', orderpoint.product_tmpl_id.id),
                ('company_id', '=', company.id),
            ], limit=1)
            if duplicate:
                raise UserError(_('A draft Orderpoint Log already exists for %s.') % (
                            orderpoint.product_tmpl_id.display_name or orderpoint.display_name))
            if not vals.get('pack_id') and orderpoint.product_tmpl_id:
                pack = self._first_product_pack(orderpoint.product_tmpl_id)
                if pack:
                    vals['pack_id'] = pack.id
            if not vals.get('code') or vals.get('code') == '/':
                vals['code'] = self._next_orderpoint_code(company)
        records = super(EprocOrderpointLog, self).create(vals_list)
        for record in records.filtered(lambda rec: not rec.supplier_ids):
            suggestions = record._prepare_supplier_suggestions()
            if len(suggestions) > 1:
                record.with_context(allow_orderpoint_log_write=True).supplier_ids = suggestions
        return records

    def write(self, vals):
        allowed = self.env.su or self.env.context.get('allow_orderpoint_log_write') or self.env.context.get(
            'allow_orderpoint_log_realize_write')
        if not allowed:
            raise UserError(_('Orderpoint logs are audit records and cannot be edited manually.'))
        return super(EprocOrderpointLog, self).write(vals)

    def unlink(self):
        if not self.env.su and not self.env.context.get('allow_orderpoint_log_unlink'):
            raise UserError(_('Orderpoint logs are audit records and cannot be deleted manually.'))
        return super(EprocOrderpointLog, self).unlink()

    def copy(self, default=None):
        if not self.env.su and not self.env.context.get('allow_orderpoint_log_copy'):
            raise UserError(_('Orderpoint logs are audit records and cannot be duplicated manually.'))
        return super(EprocOrderpointLog, self).copy(default=default)

    def open_orderpoint_pr(self):
        self.ensure_one()
        return {
            'name': _('Purchase Request from %s') % self.code,
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.request.line',
            'view_mode': 'tree,form',
            'domain': [('orderpoint_log_id', '=', self.id)],
            'context': {'create': False, 'edit': False, 'delete': False},
            'target': 'current',
        }

    def action_go_to_orderpoint_document(self):
        self.ensure_one()
        if self.state == 'auto_pr':
            documents = (
                    self.request_id
                    | self.pr_ids.filtered(lambda line: line.active and line.request_id).mapped('request_id')
                    | self.env['eproc.request'].search([('orderpoint_log_ids', 'in', self.id)])
            ).filtered(lambda request: request.active)
            if not documents:
                raise UserError(_('No active Purchase Request found for this Orderpoint Log.'))
            action = self.env.ref('mayapada.action_erp_pmm_transaction_purchase_request').read()[0].copy()
            form_view = self.env.ref('mayapada.view_erp_pmm_transaction_purchase_request_form')
            tree_view = self.env.ref('mayapada.view_erp_pmm_transaction_purchase_request_tree')

        else:
            raise UserError(_('No related document navigation is available for this Orderpoint Log state.'))

        if len(documents) == 1:
            action.update({
                'res_id': documents.id,
                'domain': [('id', '=', documents.id)],
                'view_mode': 'form',
                'views': [(form_view.id, 'form')],
                'view_id': form_view.id,
                'target': 'current',
            })
        else:
            action.update({
                'domain': [('id', 'in', documents.ids)],
                'view_mode': 'tree,form,pivot',
                'views': [(tree_view.id, 'tree'), (form_view.id, 'form')],
                'view_id': tree_view.id,
                'target': 'current',
            })
        return action


    def open_orderpoint_stock(self):
        self.ensure_one()
        domain = [('product_tmpl_id', '=', self.product_tmpl_id.id)]
        if 'company_id' in self.env['eproc.stock.quant']._fields and self.company_id:
            domain.append(('company_id', '=', self.company_id.id))
        return {
            'name': _('Current Stock for %s') % (self.product_tmpl_id.name or ''),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.stock.quant',
            'view_mode': 'tree,form',
            'domain': domain,
            'context': {'create': False, 'edit': False, 'delete': False},
            'target': 'current',
        }

    def open_creation_wizard(self):
        self.ensure_one()
        return {
            'name': _('Orderpoint to New PR Creation Wizard'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.orderpoint.realize.wizard',
            'view_mode': 'form',
            'context': {'default_log_ids': [(6, 0, [self.id])]},
            'target': 'new',
        }


class EprocOrderpointSupplier(models.Model):
    _name = 'eproc.orderpoint.supplier'
    _description = 'E-Proc Orderpoint Supplier Suggestion'

    log_id = fields.Many2one('eproc.orderpoint.log', string='Suggestion', required=True, ondelete='cascade')
    orderpoint_id = fields.Many2one('eproc.orderpoint', string='Orderpoint Rule', related='log_id.orderpoint_id',
                                    store=True, readonly=True)
    product_tmpl_id = fields.Many2one('product.template', string='Product', related='log_id.product_tmpl_id',
                                      store=True, readonly=True)
    product_uom_id = fields.Many2one('uom.uom', string='Product UoM', related='log_id.product_uom_id', store=True,
                                     readonly=True)
    company_id = fields.Many2one('res.company', string='Company', related='log_id.company_id', store=True,
                                 readonly=True)
    qty_suggested = fields.Float(string='Qty Suggestion', related='log_id.qty_suggested', store=True, readonly=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', required=True)
    agreement_line_id = fields.Many2one('eproc.agreement.line', string='Agreement Item')
    lead_time = fields.Integer(string='Lead Time')
    uom_price = fields.Float(string='UoM Price')
    tax_ids = fields.Many2many('eproc.taxes', 'eproc_orderpoint_supplier_tax_rel', 'supplier_suggestion_id', 'tax_id',
                               string='Taxes')
    disc_rate = fields.Float(string='Disc. Rate')
    uom_netprice = fields.Float(string='UoM NetPrice')
    total_netprice = fields.Float(string='Total Price', compute='_compute_total_netprice', store=True)
    priority = fields.Integer(string='Priority', default=1)

    @api.depends('uom_netprice', 'qty_suggested')
    def _compute_total_netprice(self):
        for record in self:
            record.total_netprice = (record.uom_netprice or 0.0) * (record.qty_suggested or 0.0)

    @api.onchange('agreement_line_id')
    def _onchange_agreement_line_id(self):
        for record in self:
            record._sync_from_agreement_line()

    def _sync_from_agreement_line(self):
        for record in self:
            line = record.agreement_line_id
            if not line:
                continue
            record.supplier_id = line.agreement_id.supplier_id
            record.lead_time = line.agreement_id.lead_time or getattr(line.agreement_id.supplier_id, 'eproc_lead_time',
                                                                      0) or 0
            record.uom_price = line.uom_price
            record.tax_ids = [(6, 0, line.tax_ids.ids)]
            record.disc_rate = line.disc_rate
            record.uom_netprice = line.uom_netprice

    @api.model_create_multi
    def create(self, vals_list):
        records = super(EprocOrderpointSupplier, self).create(vals_list)
        records._sync_from_agreement_line()
        return records

    def write(self, vals):
        res = super(EprocOrderpointSupplier, self).write(vals)
        if 'agreement_line_id' in vals:
            self._sync_from_agreement_line()
        return res


class EprocRequest(models.Model):
    _name = 'eproc.request'
    _description = 'E-Proc Request'
    _inherit = ['mail.thread', 'mail.activity.mixin']

    code = fields.Char(string='Code', readonly=True, default='/', copy=False)
    request_no = fields.Char(string='Request No.', readonly=True, default='/', copy=False)
    request_revise = fields.Integer(string='Request Revise', default=0, readonly=True)
    company_id = fields.Many2one('res.company', string='Company', default=lambda self: self.env.company, tracking=True)
    purchase_type_id = fields.Many2one('eproc.type', string='Procurement Type', tracking=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', tracking=True)
    approval_type_id = fields.Many2one('eproc.approval.type', string='Approval Type', tracking=True)
    approval_rule_id = fields.Many2one('eproc.approval.rule', string='Approval Rule', readonly=True, copy=False)
    approval_rule_sequence = fields.Integer(string='Approval Rule Sno', readonly=True, copy=False)
    approval_next_stored = fields.Char(string='Approval Next Stored', readonly=True, copy=False)
    user_id = fields.Many2one('res.users', string='Responsible', default=lambda self: self.env.user, tracking=True)
    department_id = fields.Many2one('hr.department', string='Department',
                                    default=lambda self: self.env.user.department_id, tracking=True)
    request_date = fields.Datetime(string='Request Date', default=fields.Datetime.now)
    request_valid_date = fields.Datetime(string='Request Valid Date', readonly=True, copy=False)
    request_expiry_date = fields.Date(
        string='Request Expiry Date',
        compute='_compute_request_expiry_date',
        store=True,
        readonly=True,
        copy=False,
    )
    request_ref = fields.Char(string='Reference')
    request_type = fields.Selection([('normal', 'Normal'), ('repeat', 'Repeat Order'), ('auto', 'Auto PR'),
                                     ('budgeted', 'Budgeted')], string='Request Type', default='normal', tracking=True)
    budget_category_id = fields.Many2one('eproc.budget.group', string='Budget Category',
        domain="[('type', '=', 'category'), ('active', '=', True), ('user_ids', 'in', [uid])]")
    budget_group_id = fields.Many2one('eproc.budget.group', string='Budget Department',
        domain="[('type', '=', 'group'), ('active', '=', True), ('user_ids', 'in', [uid])]")
    line_ids = fields.One2many('eproc.request.line', 'request_id', string='Lines')
    approval_ids = fields.One2many('eproc.approval.log', 'request_id', string='Approval Logs')
    line_count = fields.Integer(string='Items Count', compute='_compute_line_count')
    rfq_ids = fields.Many2many('eproc.order', compute='_compute_rfq_data', string='RFQs')
    rfq_count = fields.Integer(string='RFQs Count', compute='_compute_rfq_data')
    total_price = fields.Float(string='Total Price', compute='_compute_total_price', store=True)
    orderpoint_log_ids = fields.Many2many('eproc.orderpoint.log', string='Suggestion Items')
    notes = fields.Text(string='Notes')
    cancel_reason = fields.Text(string='Cancel Reason')
    cancel_datetime = fields.Datetime(string='Cancel Datetime', readonly=True, copy=False)
    state = fields.Selection([
        ('draft', 'Draft'),
        ('approval', 'Approval'),
        ('ready', 'Ready to Procure'),
        ('partial', 'Partial'),
        ('done', 'Completed'),
        ('rejected', 'Rejected'),
        ('cancelled', 'Cancelled'),
        ('expired', 'Expired'),
    ], string='State', default='draft', tracking=True)
    active = fields.Boolean(string='Active', default=True)

    def _check_budget_header(self):
        for record in self.filtered(lambda req: req.request_type == 'budgeted'):
            allowed = self.env.companies & self.env.user.company_ids
            for field_name, expected_type in (('budget_group_id', 'group'), ('budget_category_id', 'category')):
                value = record[field_name]
                if (not value or value.type != expected_type or not value.active
                        or record.user_id not in value.user_ids or record.company_id not in allowed):
                    raise ValidationError(_('Select an active Budget Department and Category assigned to the PR responsible user.'))
            if any(item.company_id != record.company_id or item.budget_group_id != record.budget_group_id
                   or item.budget_category_id != record.budget_category_id
                   for item in record.line_ids.filtered(lambda line: line.active).mapped('budget_item_id')):
                raise ValidationError(_('Every Budget Item must match the PR company, Budget Department and Category.'))

    @api.constrains('request_type', 'budget_group_id', 'budget_category_id', 'company_id', 'line_ids', 'state')
    def _check_budget_header_assignment(self):
        self._check_budget_header()

    @api.onchange('request_type', 'company_id', 'department_id', 'budget_category_id', 'budget_group_id', 'purchase_type_id')
    def _onchange_approval_domain(self):
        for record in self:
            domain = [('company_id', '=', record.company_id.id), ('type', '=', 'request'), ('active', '=', True)]
            if record.purchase_type_id:
                domain.append(('purchase_type_id', '=', record.purchase_type_id.id))
            if record.request_type == 'budgeted':
                domain += [('budget_group_id', '=', record.budget_group_id.id),
                           ('budget_category_id', '=', record.budget_category_id.id)]
            else:
                domain.append(('department_id', '=', record.department_id.id))
            if record.approval_type_id and not self.env['eproc.approval.type'].search_count(domain + [('id', '=', record.approval_type_id.id)]):
                record.approval_type_id = False
            return {'domain': {'approval_type_id': domain}}

    @api.onchange('request_type', 'budget_group_id', 'budget_category_id')
    def _onchange_budget_header(self):
        for record in self:
            if record.request_type != 'budgeted':
                record.budget_group_id = False
                record.budget_category_id = False
            record.line_ids.filtered('budget_item_id').budget_item_id = False
        return {'domain': {'budget_group_id': [('type', '=', 'group'), ('active', '=', True), ('user_ids', 'in', [self.env.uid])],
                           'budget_category_id': [('type', '=', 'category'), ('active', '=', True), ('user_ids', 'in', [self.env.uid])]}}

    @api.depends('request_valid_date', 'purchase_type_id.request_expiration_days')
    def _compute_request_expiry_date(self):
        for record in self:
            if record.request_valid_date and record.purchase_type_id:
                valid_date = fields.Datetime.to_datetime(record.request_valid_date).date()
                record.request_expiry_date = valid_date + timedelta(
                    days=record.purchase_type_id.request_expiration_days or 0
                )
            else:
                record.request_expiry_date = False

    @api.depends('line_ids', 'line_ids.active')
    def _compute_line_count(self):
        for record in self:
            record.line_count = len(record.line_ids.filtered(lambda line: line.active))

    @api.depends('line_ids.total_price', 'line_ids.active')
    def _compute_total_price(self):
        for record in self:
            record.total_price = sum(record.line_ids.filtered(lambda line: line.active).mapped('total_price'))

    @api.depends('line_ids.order_line_ids.order_id', 'line_ids.order_line_ids.active')
    def _compute_rfq_data(self):
        for record in self:
            order_lines = record.line_ids.mapped('order_line_ids').filtered(
                lambda line: line.active and line.order_id
            )
            rfqs = order_lines.mapped('order_id')
            record.rfq_ids = rfqs
            record.rfq_count = len(rfqs)

    @api.model
    def _sequence_unit_code(self, company):
        unit_code = getattr(company, 'company_code', False) or 'GEN'
        return str(unit_code).upper().replace(' ', '')

    def _next_request_no(self, company, purchase_type):
        if not purchase_type:
            raise UserError(_('Procurement Type is required before generating a Purchase Request number.'))
        document_prefix = purchase_type.request_prefix
        if not document_prefix:
            raise UserError(_('Request Prefix is not configured for Procurement Type %s.') % purchase_type.display_name)
        if len(document_prefix) != 4:
            raise UserError(_('Request Prefix must contain exactly 4 characters.'))
        sequence_code = 'SEQ.ERP.PMM.%s.PURCHASE.REQUEST' % self._sequence_unit_code(company)
        sequence_number = self.env['ir.sequence'].with_company(company).next_by_code(sequence_code)
        if not sequence_number:
            raise UserError(_('No Purchase Request sequence found using code %s.') % sequence_code)
        return '%s.%s' % (document_prefix, sequence_number)

    def name_get(self):
        result = []
        for record in self:
            name = record.request_no or record.code or _('New Request')
            if record.request_revise:
                name = '%sR%s' % (name, record.request_revise)
            result.append((record.id, name))
        return result

    @api.constrains('company_id', 'purchase_type_id', 'state', 'line_ids')
    def _check_budget_tracking(self):
        for record in self:
            if record.state in ('approval', 'ready', 'partial', 'done'):
                record.line_ids._check_budget_tracking()
            else:
                record.line_ids.filtered('budget_item_id')._check_budget_tracking()

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            company = self.env['res.company'].browse(vals.get('company_id')) or self.env.company
            purchase_type = self.env['eproc.type'].browse(vals.get('purchase_type_id')).exists() if vals.get('purchase_type_id') else self.env['eproc.type']
            if not vals.get('request_no') or vals.get('request_no') == '/':
                vals['request_no'] = self._next_request_no(company, purchase_type)
            if not vals.get('code') or vals.get('code') == '/':
                vals['code'] = vals.get('request_no') or '/'
            if not vals.get('department_id') and vals.get('user_id'):
                vals['department_id'] = self.env['res.users'].browse(vals['user_id']).department_id.id
        records = super(EprocRequest, self).create(vals_list)
        records.mapped('line_ids.budget_item_id')._check_commitment_ceiling()
        return records

    def write(self, vals):
        transition_to_confirmed = vals.get('state') in ('approval', 'ready')
        if {'state', 'company_id', 'purchase_type_id', 'active', 'line_ids', 'request_type', 'budget_group_id', 'budget_category_id'} & set(vals):
            self.mapped('line_ids.budget_item_id')._lock_tracking()
        if transition_to_confirmed:
            requests_to_confirm = self.filtered(lambda request: request.state in ('draft', 'rejected'))
            requests_to_confirm.mapped('line_ids')._check_budget_tracking(require_validated=True)
            requests_to_confirm._check_budget_header()
            requests_to_confirm._validate_budget_line_amounts()
        if 'request_no' in vals and 'code' not in vals:
            vals['code'] = vals.get('request_no') or '/'
        res = super(EprocRequest, self).write(vals)
        self._check_budget_header()
        if not self.env.context.get('skip_request_state_sync') and 'state' in vals:
            state = vals.get('state')
            if state in ('draft', 'approval', 'rejected'):
                self.mapped('line_ids').with_context(skip_request_line_lock=True).write({'state': 'draft'})
            elif state == 'cancelled':
                self.mapped('line_ids').with_context(skip_request_line_lock=True).write({'state': 'cancelled'})
            elif state == 'expired':
                self.mapped('line_ids').filtered(lambda line: line.active).with_context(skip_request_line_lock=True).write({'state': 'expired'})
            elif state in ('ready', 'partial', 'done'):
                self._sync_realization_state_from_lines()
            self._sync_orderpoint_logs_from_state(state)
        if {'state', 'company_id', 'active', 'line_ids'} & set(vals):
            self.mapped('line_ids.budget_item_id')._check_commitment_ceiling()
        return res



    def _sync_orderpoint_logs_from_state(self, state=False):
        for record in self:
            logs = (record.orderpoint_log_ids | record.line_ids.mapped('orderpoint_log_id')).filtered(lambda log: log)
            if not logs:
                continue
            if (state or record.state) == 'cancelled':
                logs.with_context(allow_orderpoint_log_realize_write=True).write({
                    'state': 'draft',
                    'request_id': False,
                })
            elif (state or record.state) in ('approval', 'ready', 'partial', 'done'):
                logs.with_context(allow_orderpoint_log_realize_write=True).write({
                    'state': 'auto_pr',
                    'request_id': record.id,
                })

    def unlink(self):
        self.write({'active': False})
        return True

    def copy(self, default=None):
        raise UserError(_('Purchase Request cannot be duplicated. Please create a new request.'))

    def _sync_realization_state_from_lines(self):
        for record in self:
            if record.state not in ('ready', 'partial', 'done'):
                continue
            active_lines = record.line_ids.filtered(lambda line: line.active)
            if not active_lines:
                continue
            closed_lines = active_lines.filtered(lambda line: line.state == 'closed')
            cancelled_lines = active_lines.filtered(lambda line: line.state == 'cancelled')
            realizable_lines = active_lines - closed_lines - cancelled_lines
            realizable_lines._compute_pack_qty_processed()
            realizable_lines._compute_pack_qty_remaining()
            realizable_lines._compute_uom_qty_processed()

            line_state_map = {
                'ready': self.env['eproc.request.line'],
                'partial': self.env['eproc.request.line'],
                'done': self.env['eproc.request.line'],
            }
            for line in realizable_lines:
                processed = line._get_pack_qty_processed()
                requested = line.pack_qty or 0.0
                if float_compare(processed, requested, precision_digits=6) >= 0 and requested > 0.0:
                    line_state_map['done'] |= line
                elif float_compare(processed, 0.0, precision_digits=6) > 0:
                    line_state_map['partial'] |= line
                else:
                    line_state_map['ready'] |= line

            for state, lines in line_state_map.items():
                lines.filtered(lambda line: line.state != state).with_context(skip_request_line_lock=True).write(
                    {'state': state})

            if (line_state_map['done'] or closed_lines) and not line_state_map['ready'] and not line_state_map[
                'partial']:
                request_state = 'done'
            elif line_state_map['partial'] or line_state_map['done']:
                request_state = 'partial'
            else:
                request_state = 'ready'
            if record.state != request_state:
                record.with_context(skip_request_state_sync=True).write({'state': request_state})

    def _get_all_approval_logs(self):
        self.ensure_one()
        return self.with_context(active_test=False).approval_ids

    def _get_last_rejected_approval_log(self):
        self.ensure_one()
        return self._get_all_approval_logs().filtered(lambda l: l.state == 'rejected').sorted('approval_date',
                                                                                              reverse=True)[:1]

    def _get_approval_cycle_logs(self, reference_log):
        self.ensure_one()
        if not reference_log:
            return self.env['eproc.approval.log']
        all_logs = self._get_all_approval_logs().filtered(
            lambda log: log.approval_type_id == reference_log.approval_type_id
        )
        active_cycle_logs = all_logs.filtered(lambda log: log.active or log == reference_log)
        cycle_start_dates = active_cycle_logs.mapped('create_date') or [reference_log.create_date]
        cycle_start = min(cycle_start_dates)
        return all_logs.filtered(lambda log: log.create_date and log.create_date >= cycle_start)

    def _get_pending_approval_logs(self):
        self.ensure_one()
        return self._get_all_approval_logs().filtered(lambda l: l.state == 'pending' and l.active == True)

    def _get_current_pending_approval_log(self):
        self.ensure_one()
        return self._get_pending_approval_logs().sorted('sequence')[:1]

    def _position_id_for_metadata(self, position):
        return position.sudo().id if position else False

    def _position_name_for_metadata(self, position, default=False):
        if not position:
            return default
        return position.sudo().name or default

    def _get_position_approver_user_ids(self, approval_log):
        position_id = self._position_id_for_metadata(approval_log.position_id)
        if not position_id:
            return []
        return self.sudo().env['res.users'].search([
            '|',
            ('position_id', '=', position_id),
            ('second_position_id', '=', position_id),
        ]).ids

    def _is_authorized_for_approval_log(self, approval_log, include_owner=False, include_delegate=False):
        allowed_user_ids = self._get_position_approver_user_ids(approval_log)
        if include_delegate and approval_log.delegate_user_id:
            allowed_user_ids.append(approval_log.delegate_user_id.id)
        if include_owner and self.user_id:
            allowed_user_ids.append(self.user_id.id)
        return self.env.user.id in allowed_user_ids or self._is_admin_user()

    def _update_approval_flags(self):
        for rec in self:
            next_log = rec._get_current_pending_approval_log()
            if next_log:
                rec.write({
                    'approval_rule_id': next_log.approval_rule_id.id,
                    'approval_rule_sequence': next_log.sequence,
                    'approval_next_stored': rec._position_name_for_metadata(
                        next_log.position_id) or next_log.delegate_user_id.name,
                })
            else:
                rec.write({
                    'approval_rule_id': False,
                    'approval_rule_sequence': 0,
                    'approval_next_stored': 'Completed',
                })

    def _prepare_auto_request_line_values(self, orderpoint_log, sequence=1, existing_line=False):
        self.ensure_one()
        realized_qty = orderpoint_log.qty_suggested or 0.0
        product = orderpoint_log.product_tmpl_id
        name = (
                getattr(product, 'description_purchase', False)
                or getattr(product, 'description', False)
                or product.name
        )
        return {
            'sequence': sequence,
            'product_tmpl_id': product.id,
            'name': name,
            'pack_id': orderpoint_log.pack_id.id,
            'pack_qty': realized_qty,
            'pack_price': existing_line.pack_price if existing_line else 0.0,
            'pack_rate': orderpoint_log.pack_rate,
            'uom_qty_on_hand': orderpoint_log.qty_on_hand,
            'uom_qty_min': orderpoint_log.qty_safety,
            'uom_qty_max': orderpoint_log.qty_maximum,
            'uom_qty_suggested': orderpoint_log.qty_suggested,
            'uom_id': orderpoint_log.product_uom_id.id,
            'uom_qty': realized_qty,
            'uom_price': existing_line.uom_price if existing_line else 0.0,
            'total_price': existing_line.total_price if existing_line else 0.0,
            'analytic_id': existing_line.analytic_id.id if existing_line else False,
            'budget_item_id': existing_line.budget_item_id.id if existing_line else False,
            'orderpoint_log_id': orderpoint_log.id,
        }

    @api.onchange('request_type')
    def _onchange_request_type(self):
        for record in self:
            if record.request_type != 'auto':
                record.orderpoint_log_ids = [(5, 0, 0)]

    @api.onchange('user_id')
    def _onchange_user_id(self):
        for record in self:
            record.department_id = record.user_id.department_id.id if record.user_id else False

    @api.onchange('orderpoint_log_ids')
    def _onchange_orderpoint_log_ids(self):
        for record in self:
            if record.request_type != 'auto':
                continue
            existing_by_log = {
                line.orderpoint_log_id.id: line
                for line in record.line_ids
                if line.orderpoint_log_id
            }
            commands = [(5, 0, 0)]
            for sequence, log in enumerate(record.orderpoint_log_ids, start=1):
                commands.append((0, 0, record._prepare_auto_request_line_values(
                    log,
                    sequence=sequence,
                    existing_line=existing_by_log.get(log.id),
                )))
            record.line_ids = commands

    def _ensure_auto_request_lines_from_suggestions(self):
        for record in self.filtered(lambda req: req.request_type == 'auto'):
            existing_log_ids = set(record.line_ids.filtered(lambda line: line.active and line.orderpoint_log_id).mapped(
                'orderpoint_log_id').ids)
            sequence = len(record.line_ids)
            values_list = []
            for log in record.orderpoint_log_ids:
                if log.id in existing_log_ids:
                    continue
                sequence += 1
                values = record._prepare_auto_request_line_values(log, sequence=sequence)
                values['request_id'] = record.id
                values_list.append(values)
            if values_list:
                self.env['eproc.request.line'].create(values_list)

    def _release_auto_request_suggestions(self):
        for record in self.filtered(lambda req: req.request_type == 'auto'):
            logs = (record.orderpoint_log_ids | record.line_ids.mapped('orderpoint_log_id')).filtered(
                lambda log: log and log.state == 'draft'
            )
            if logs:
                logs.with_context(allow_orderpoint_log_realize_write=True).write({
                    'state': 'auto_pr',
                    'request_id': record.id,
                })

    def _is_admin_user(self):
        admin_user = self.env.ref('base.user_admin', raise_if_not_found=False)
        return (
                self.env.su
                or self.env.uid == SUPERUSER_ID
                or (admin_user and self.env.uid == admin_user.id)
                or self.env.user.has_group('base.group_system')
        )

    def _is_sender_email_config_error(self, error):
        message = str(error)
        return 'please configure the sender' in message.lower() and 'email address' in message.lower()

    def _eproc_mail_context(self):
        return {
            'mail_notify_force_send': False,
        }

    def _write_with_sender_email_fallback(self, values, label):
        self.ensure_one()
        try:
            with self.env.cr.savepoint():
                return self.with_context(**self._eproc_mail_context()).write(values)
        except UserError as error:
            if not self._is_sender_email_config_error(error):
                raise
            _logger.warning(
                "EProc request write notification email unavailable for request_id=%s label=%s; retrying without tracking. Error: %s",
                self.id,
                label,
                error,
            )
            return self.with_context(
                tracking_disable=True,
                mail_notrack=True,
                mail_create_nosubscribe=True,
                **self._eproc_mail_context(),
            ).write(values)

    def _create_chatter_note_with_inbox_notifications(self, body, partner_ids=None):
        self.ensure_one()
        partner_ids = list(dict.fromkeys(partner_ids or []))
        author_id = self.env.user.partner_id.id if self.env.user.partner_id else False
        subtype_id = self.env.ref('mail.mt_note', raise_if_not_found=False)
        message = self.env['mail.message'].sudo().create({
            'author_id': author_id,
            'body': body,
            'email_from': self.env.user.email_formatted or False,
            'message_type': 'comment',
            'model': self._name,
            'res_id': self.id,
            'record_name': self.display_name,
            'subtype_id': subtype_id.id if subtype_id else False,
        })
        notifications = []
        existing_partner_ids = set(self.env['mail.notification'].sudo().search([
            ('mail_message_id', '=', message.id),
            ('res_partner_id', 'in', partner_ids),
        ]).mapped('res_partner_id').ids)
        for partner_id in partner_ids:
            if partner_id in existing_partner_ids:
                continue
            notifications.append({
                'author_id': author_id,
                'mail_message_id': message.id,
                'res_partner_id': partner_id,
                'notification_type': 'inbox',
                'notification_status': 'sent',
            })
        if notifications:
            self.env['mail.notification'].sudo().create(notifications)

    def action_notify_approver(self, comment=False, action_type='approve'):
        self.ensure_one()
        partner_ids = []
        subscriber_ids = []

        if self.user_id.partner_id:
            partner_ids.append(self.user_id.partner_id.id)
            subscriber_ids.append(self.user_id.partner_id.id)

        approval_logs = self._get_all_approval_logs()
        last_approver_log = approval_logs.filtered(
            lambda x: x.state not in ['pending'] and x.active == True
        ).sorted('sequence', reverse=True)[:1]
        if last_approver_log.action_user_id.partner_id:
            subscriber_ids.append(last_approver_log.action_user_id.partner_id.id)

        next_approver_log = self._get_current_pending_approval_log()

        if next_approver_log and action_type == 'approve':
            position_id = self._position_id_for_metadata(next_approver_log.position_id)
            user_ids = self.env['res.users'].search([
                '|',
                ('position_id', '=', position_id),
                ('second_position_id', '=', position_id),
            ])
            for user_id in user_ids.filtered(lambda x: x.partner_id):
                partner_ids.append(user_id.partner_id.id)
            if next_approver_log.delegate_user_id and next_approver_log.delegate_user_id.partner_id:
                partner_ids.append(next_approver_log.delegate_user_id.partner_id.id)
        partner_ids = list(dict.fromkeys(partner_ids))
        subscriber_ids = list(dict.fromkeys(subscriber_ids))
        for subscriber_id in subscriber_ids:
            if subscriber_id not in self.message_partner_ids.ids:
                self.message_subscribe(partner_ids=[subscriber_id])
        try:
            with self.env.cr.savepoint():
                self.with_context(**self._eproc_mail_context()).message_post(body=comment, partner_ids=partner_ids)
        except UserError as error:
            if not self._is_sender_email_config_error(error):
                raise
            _logger.warning('Eproc request notification email unavailable for request_id=%s; posting chatter-only fallback. Error: %s', self.id, error)
            try:
                with self.env.cr.savepoint():
                    self.with_context(**self._eproc_mail_context()).message_post(body=comment, message_type='comment', subtype_xmlid='mail.mt_note')
            except UserError as fallback_error:
                if not self._is_sender_email_config_error(fallback_error):
                    raise
                self._create_chatter_note_with_inbox_notifications(comment, partner_ids=partner_ids)
        return True


    def _validate_before_confirm(self):
        for record in self:
            if not record.company_id:
                raise UserError(_('Please select a company.'))
            if not record.user_id:
                raise UserError(_('Please select a responsible user.'))
            if not record.department_id:
                raise UserError(_('Please select a department.'))
            if not record.purchase_type_id:
                raise UserError(_('Please select a procurement type.'))
            if not record.approval_type_id:
                raise UserError(_('Please select an approval type.'))
            lines = record.line_ids.filtered(lambda line: line.active)
            if not lines:
                raise UserError(_('Please add at least one request item.'))
            for line in lines:
                if not line.product_tmpl_id:
                    raise UserError(_('Every request line must have a product.'))
                if record.department_id and record.department_id not in line.product_tmpl_id.eproc_department_ids:
                    raise UserError(
                        _('Product %s is not mapped to department %s.')
                        % (line.product_tmpl_id.display_name, record.department_id.display_name)
                    )
                if not line.pack_id:
                    raise UserError(_('Every request line must have a pack type.'))
                if line.pack_qty <= 0:
                    raise UserError(_('Every request line must have a positive pack quantity.'))
                if record.request_type == 'budgeted':
                    record._check_budget_header()
                    line._check_budget_tracking(require_validated=True)
                    budget = line.budget_item_id
                    if (not budget or budget.budget_group_id != record.budget_group_id
                            or budget.budget_category_id != record.budget_category_id
                            or budget.unrealize_amount <= 0
                            or (budget.product_tmpl_id and budget.product_tmpl_id != line.product_tmpl_id)):
                        raise ValidationError(_('Every Budgeted request line requires a matching Budget Item with remaining value.'))
                record._validate_request_approval_type()

    def _validate_budget_line_amounts(self):
        for request in self.filtered(lambda record: record.request_type == 'budgeted'):
            rounding = request.company_id.currency_id.rounding
            for line in request.line_ids.filtered('active'):
                budget = line.budget_item_id
                remaining = budget.unrealize_amount if budget else 0.0
                if (not budget or not math.isfinite(line.total_price) or not math.isfinite(remaining)
                        or remaining <= 0.0
                        or float_compare(line.total_price, remaining, precision_rounding=rounding) > 0):
                    raise ValidationError(_('Line total exceeds the remaining amount for Budget Item %s.') %
                                          (budget.display_name if budget else _('Missing Budget Item')))

    def _validate_request_approval_type(self):
        self.ensure_one()
        domain = [('id', '=', self.approval_type_id.id), ('company_id', '=', self.company_id.id),
                  ('purchase_type_id', '=', self.purchase_type_id.id), ('type', '=', 'request'), ('active', '=', True)]
        if self.request_type == 'budgeted':
            domain += [('budget_group_id', '=', self.budget_group_id.id),
                       ('budget_category_id', '=', self.budget_category_id.id)]
        else:
            domain.append(('department_id', '=', self.department_id.id))
        if not self.env['eproc.approval.type'].search_count(domain):
            raise ValidationError(_('Approval Type does not match this request company, procurement type and department/budget.'))


    def action_confirm(self):
        self.ensure_one()
        if self.state not in ('draft', 'rejected'):
            raise UserError(_('Only Draft or Rejected requests can be confirmed.'))
        was_rejected = self.state == 'rejected'
        self._ensure_auto_request_lines_from_suggestions()
        self._validate_before_confirm()
        self.line_ids._check_budget_tracking(require_validated=True)
        if self.request_type == 'budgeted':
            budgets = self.line_ids.filtered('active').mapped('budget_item_id')
            budgets._lock_tracking()
            self._validate_budget_line_amounts()

        approval_logs = self._get_all_approval_logs()

        last_reject_log = self._get_last_rejected_approval_log() if was_rejected else self.env['eproc.approval.log']
        if was_rejected and last_reject_log:
            last_rejecter_id = last_reject_log.action_user_id.id
            if self.env.user.id not in [self.user_id.id, last_rejecter_id] and not self._is_admin_user():
                raise UserError(
                    _("Only the Creator or the Rejecting Authority can confirm this document after rejection."))

        active_rules = self.approval_type_id.rule_ids.filtered(lambda rule: rule.enabled)
        if not active_rules:
            if approval_logs:
                approval_logs.sudo().write({'active': False})
            self._write_with_sender_email_fallback(
                {
                    'state': 'ready',
                    'request_valid_date': fields.Datetime.now(),
                    'approval_rule_id': False,
                    'approval_rule_sequence': 0,
                    'approval_next_stored': 'Completed',
                },
                'confirm_without_approval_state_ready',
            )
            comment = "New submission complete without Approval."
        else:
            restart_approval = True
            comment = "New submission, please approve for this transaction " + (self.request_no or '')

            if was_rejected and last_reject_log:
                comment = "Submission changed and approval restarted from beginning, please approve this transaction " + (
                            self.request_no or '')
                if float_compare(self.total_price, last_reject_log.amount_snapshot, precision_digits=2) == 0:
                    restart_approval = False
                    comment = "Revision accepted (consistent amount), please approve this transaction " + (
                                self.request_no or '')

            if restart_approval:
                if approval_logs:
                    approval_logs.sudo().write({'active': False})

                log_values = []
                for rule in active_rules:
                    log_values.append({
                        'request_id': self.id,
                        'approval_type_id': self.approval_type_id.id,
                        'approval_rule_id': rule.id,
                        'sequence': int(rule.sequence),
                        'position_id': self._position_id_for_metadata(rule.position_id),
                        'delegate_user_id': rule.delegate_user_id.id,
                        'amount_snapshot': self.total_price or 0.0,
                        'type': rule.type,
                        'show': rule.show,
                        'state': 'pending',
                        'active': True,
                    })
                self.env['eproc.approval.log'].create(log_values)
            else:
                cycle_logs = self._get_approval_cycle_logs(last_reject_log)
                last_reject_log.write({
                    'state': 'pending',
                    'active': True,
                    'notes': 'Revision accepted with no change in amount, resuming approval process.',
                })
                cycle_logs.filtered(lambda l: l.sequence > last_reject_log.sequence).write({'active': True})
                cycle_logs.filtered(
                    lambda l: l.sequence < last_reject_log.sequence and l.state == 'approved'
                ).write({'active': True})

            self._write_with_sender_email_fallback({'state': 'approval'}, 'confirm_state_approval')
            self._update_approval_flags()
        self._release_auto_request_suggestions()
        self.action_notify_approver(comment=comment)
        return True

    def action_approve(self):
        self.ensure_one()
        if self.state != 'approval':
            raise UserError(_('Only requests in Approval state can be approved.'))
        current_log = self._get_current_pending_approval_log()
        if not current_log:
            raise UserError(_("There is no pending approval queue for this document."))

        if not self._is_authorized_for_approval_log(current_log, include_delegate=True):
            raise UserError(
                _("Authority Denied. This document requires approval from position: %s. Your current position: %s.")
                % (
                    self._position_name_for_metadata(current_log.position_id, 'Undefined'),
                    self._position_name_for_metadata(self.env.user.position_id, 'Undefined'),
                )
            )

        user_pos_name = self._position_name_for_metadata(current_log.position_id, "Authorized Position")
        user_name = self.env.user.partner_id.name or "Authorized User"
        comment = f"Approved by {user_name} as {user_pos_name}."
        current_log.write({
            'state': 'approved',
            'action_user_id': self.env.user.id,
            'approval_date': fields.Datetime.now(),
            'amount_snapshot': self.total_price,
            'notes': comment,
        })

        next_log = self._get_current_pending_approval_log()
        self._update_approval_flags()
        if next_log:
            self.action_notify_approver(comment=f"Approved by {user_name} as {user_pos_name}. Awaiting next approval")
        else:
            self._write_with_sender_email_fallback(
                {'state': 'ready', 'request_valid_date': fields.Datetime.now()},
                'approve_complete_state_ready',
            )
            self.action_notify_approver(
                comment=f"Approval completed by {user_name} as {user_pos_name}. Status changed to Ready.")
        return True

    def action_reject_confirm(self):
        self.ensure_one()
        if self.state != 'approval':
            raise UserError(_('Only requests in Approval state can be rejected.'))
        current_log = self._get_current_pending_approval_log()
        if not current_log:
            raise UserError(_("There is no pending approval queue for this document."))
        if not self._is_authorized_for_approval_log(current_log, include_owner=True):
            raise UserError(_("Authority Denied. Only the Creator or Current Approver can reject this request."))
        return {
            'name': _('Reject Confirmation'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.approval.log.wizard',
            'view_mode': 'form',
            'target': 'new',
            'context': {
                'default_model_id': 'eproc.request',
                'default_res_id': self.id,
                'default_action_type': 'reject',
                'active_id': self.id,
                'active_model': 'eproc.request',
            },
        }

    def action_reject(self, reason=False):
        self.ensure_one()
        reason = (reason or '').strip()
        if not reason:
            return self.action_reject_confirm()
        if self.state != 'approval':
            raise UserError(_('Only requests in Approval state can be rejected.'))
        current_log = self._get_current_pending_approval_log()
        if not current_log:
            raise UserError(_("There is no pending approval queue for this document."))
        if not self._is_authorized_for_approval_log(current_log, include_owner=True):
            raise UserError(_("Authority Denied. Only the Creator or Current Approver can reject this request."))
        current_log.write({
            'state': 'rejected',
            'action_user_id': self.env.user.id,
            'approval_date': fields.Datetime.now(),
            'amount_snapshot': self.total_price,
            'notes': reason,
        })
        self._get_all_approval_logs().filtered(lambda log: log.state == 'pending').write({'active': False})
        self._write_with_sender_email_fallback({
            'state': 'rejected',
            'approval_next_stored': "Rejected by %s as %s" % (
                self.env.user.partner_id.name,
                self._position_name_for_metadata(current_log.position_id, 'Authorized Position'),
            ),
        }, 'reject_state_rejected')
        self.action_notify_approver(comment=f"REJECTED: {reason}", action_type='reject')
        return True

    def action_cancel_confirm(self):
        self.ensure_one()
        if self.state not in ('draft', 'approval', 'rejected'):
            raise UserError(_('This request cannot be cancelled.'))
        current_log = self._get_current_pending_approval_log()
        is_owner = self.user_id == self.env.user or self.create_uid == self.env.user
        if self.state == 'approval':
            if not current_log:
                raise UserError(_("There is no pending approval queue for this document."))
            if not self._is_authorized_for_approval_log(current_log, include_owner=True):
                raise UserError(_("Authority Denied. Only the Creator or Current Approver can cancel this request."))
        if self.state in ('draft', 'rejected') and not (self._is_admin_user() or is_owner):
            raise UserError(_('Only the responsible user, creator, or administrator can cancel this request.'))
        return {
            'name': _('Cancel Confirmation (Cannot be undone)'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.approval.log.wizard',
            'view_mode': 'form',
            'target': 'new',
            'context': {
                'default_model_id': 'eproc.request',
                'default_res_id': self.id,
                'default_action_type': 'cancel',
                'active_id': self.id,
                'active_model': 'eproc.request',
            },
        }

    def action_cancel(self, reason=False):
        self.ensure_one()
        reason = (reason or '').strip()
        if not reason:
            return self.action_cancel_confirm()
        if self.state not in ('draft', 'approval', 'rejected'):
            raise UserError(_('This request cannot be cancelled.'))
        current_log = self._get_current_pending_approval_log()
        is_owner = self.user_id == self.env.user or self.create_uid == self.env.user
        if self.state == 'approval':
            if not current_log:
                raise UserError(_("There is no pending approval queue for this document."))
            if not self._is_authorized_for_approval_log(current_log, include_owner=True):
                raise UserError(
                    _("Authority Denied. This document requires cancel from position: %s. Your current position: %s.")
                    % (
                        self._position_name_for_metadata(current_log.position_id, 'Undefined'),
                        self._position_name_for_metadata(self.env.user.position_id, 'Undefined'),
                    )
                )
        if self.state in ('draft', 'rejected') and not (self._is_admin_user() or is_owner):
            raise UserError(_('Only the responsible user, creator, or administrator can cancel this request.'))
        pending_logs = self._get_pending_approval_logs()
        if current_log:
            current_log.write({
                'state': 'cancelled',
                'action_user_id': self.env.user.id,
                'approval_date': fields.Datetime.now(),
                'amount_snapshot': self.total_price,
                'notes': reason,
                'active': False,
            })
            pending_logs = pending_logs - current_log
        pending_logs.write({'active': False})
        self._write_with_sender_email_fallback({
            'state': 'cancelled',
            'cancel_reason': reason,
            'cancel_datetime': fields.Datetime.now(),
            'approval_next_stored': f"Cancelled by {self.env.user.name}",
        }, 'cancel_state_cancelled')
        self.action_notify_approver(comment=f"CANCELLED: {reason}", action_type='cancel')
        return True

    def action_draft(self):
        self.ensure_one()
        if self.state != 'rejected':
            raise UserError(_("Only documents with 'Rejected' status can be set back to Draft."))

        last_reject_log = self._get_last_rejected_approval_log()
        last_rejecter_id = last_reject_log.action_user_id.id if last_reject_log else False
        if self.env.user.id not in [self.user_id.id, last_rejecter_id] and not self._is_admin_user():
            raise UserError(_("Only the Creator or the Rejecting Authority can set this document back to Draft."))

        self._get_all_approval_logs().write({'active': False})
        self._write_with_sender_email_fallback({
            'state': 'draft',
            'request_revise': self.request_revise + 1,
            'approval_rule_id': False,
            'approval_rule_sequence': 0,
            'approval_next_stored': False,
        }, 'draft_reset_state_draft')
        self.action_notify_approver(comment=f"Document reverted to Draft for revision.", action_type='draft')
        return True

    def action_archive(self):
        for record in self:
            record.write({'active': not record.active})
        return True

    def open_line_item(self):
        self.ensure_one()
        return {
            'name': _('Purchase Request Items'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.request.line',
            'view_mode': 'tree,form',
            'domain': [('request_id', '=', self.id)],
            'context': {'create': False, 'delete': False},
            'target': 'current',
        }

    def open_rfq_item(self):
        self.ensure_one()
        return {
            'name': _('RFQs'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.order',
            'view_mode': 'tree,form',
            'domain': [('id', 'in', self.rfq_ids.ids)],
            'context': {
                'create': False,
                'delete': False,
                'tree_view_ref': 'mayapada.view_erp_pmm_transaction_purchase_request_rfq_tree',
            },
            'target': 'current',
        }

    def action_print_purchase_request(self):
        self.ensure_one()
        report_unit = (
            '/Mayapada/Eproc/Purchase_Request_Auto'
            if self.request_type == 'auto'
            else '/Mayapada/Eproc/Purchase_Request'
        )
        return self.env['eproc.dialog.preview'].open_jasper_preview(
            title=_('Purchase Request Preview'),
            report_unit=report_unit,
            params={'REQUEST_ID': self.id},
            company=self.company_id,
            filename=self.request_no or self.code,
            orientation='landscape' if self.request_type == 'auto' else 'portrait'
        )


class EprocDialogPreview(models.TransientModel):
    _name = 'eproc.dialog.preview'
    _description = 'E-Proc Dialog Preview'

    name = fields.Char(string='Title', default=lambda self: _('Preview'))
    report_unit = fields.Char(string='Jasper Report Unit', readonly=True)
    params_json = fields.Text(string='Jasper Parameters', readonly=True)
    company_id = fields.Many2one('res.company', string='Company', readonly=True)
    download_filename = fields.Char(string='Download Filename', readonly=True)
    preview_url = fields.Char(string='Preview URL', readonly=True)
    preview_html = fields.Html(string='Preview', compute='_compute_preview_html', sanitize=False)

    @api.model
    def _get_jasper_credentials(self, company=None):
        company = company or self.env.company
        jasper_base_url = (company.url_host_jasper or '').strip().rstrip('/')
        jasper_user = (company.uname_jasper or '').strip()
        jasper_password = (company.pass_jasper or '').strip()
        if not jasper_base_url:
            raise UserError(_('Jasper server URL is not configured for this company.'))
        if not jasper_user or not jasper_password:
            raise UserError(_('Jasper credentials are not configured for this company.'))
        return jasper_base_url, jasper_user, jasper_password

    @api.model
    def _prepare_jasper_params(self, params=None):
        jasper_params = dict(params or {})
        jasper_params.setdefault('PRINT_BY', self.env.user.name or '')
        return jasper_params

    @api.model
    def _get_jasper_parent_folder_uri(self, report_unit):
        report_unit = (report_unit or '').strip()
        if report_unit and not report_unit.startswith('/'):
            report_unit = '/%s' % report_unit
        if report_unit.startswith('/reports/'):
            parent_folder = report_unit.rsplit('/', 1)[0]
        else:
            parent_folder = '/reports%s' % report_unit.rsplit('/', 1)[0]
        return parent_folder or '/reports'

    @api.model
    def _normalize_jasper_output_format(self, output_format):
        output_format = (output_format or '').strip().lower()
        return {
            'doc': 'docx',
        }.get(output_format, output_format)

    @api.model
    def _build_jasper_report_url(self, report_unit, params=None, company=None):
        if not report_unit:
            raise UserError(_('Jasper report unit is required.'))
        jasper_base_url, jasper_user, jasper_password = self._get_jasper_credentials(company=company)

        flow_url = jasper_base_url
        if not flow_url.endswith('/flow.html'):
            flow_url = '%s/flow.html' % flow_url

        query_params = [
            ('_flowId', 'viewReportFlow'),
            ('ParentFolderUri', self._get_jasper_parent_folder_uri(report_unit)),
            ('reportUnit', report_unit),
            ('decorate', 'no'),
            ('j_username', jasper_user),
            ('j_password', jasper_password),
            ('viewAsDashboardFrame', 'false'),
            ('standAlone', 'true'),
            ('showInputControls', 'false'),
        ]
        for key, value in (params or {}).items():
            query_params.append((key, value))
        return '%s?%s' % (flow_url, urlencode(query_params))

    def _build_jasper_download_url(self, output_format):
        self.ensure_one()
        return '/eproc/jasper/download/%s/%s' % (
            self.id,
            self._normalize_jasper_output_format(output_format),
        )

    @api.model
    def _build_jasper_rest_url(self, company=None, path=''):
        jasper_base_url, jasper_user, jasper_password = self._get_jasper_credentials(company=company)
        if jasper_base_url.endswith('/flow.html'):
            jasper_base_url = jasper_base_url[:-len('/flow.html')]
        path = (path or '').lstrip('/')
        return '%s/%s' % (jasper_base_url, path), jasper_user, jasper_password

    @api.model
    def _format_jasper_report_parameters(self, params=None):
        report_parameters = []
        for key, value in (params or {}).items():
            values = value if isinstance(value, list) else [value]
            report_parameters.append({
                'name': key,
                'value': values,
            })
        return report_parameters

    @api.model
    def _get_jasper_content_type(self, output_format):
        output_format = self._normalize_jasper_output_format(output_format)
        return {
            'pdf': 'application/pdf',
            'doc': 'application/msword',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xls': 'application/vnd.ms-excel',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        }.get(output_format, 'application/octet-stream')

    def _get_jasper_download_filename(self, output_format):
        self.ensure_one()
        output_format = self._normalize_jasper_output_format(output_format)
        filename = (self.download_filename or '').strip()
        if not filename:
            filename = (self.report_unit or '').strip('/').rsplit('/', 1)[-1]
        filename = re.sub(r'[^A-Za-z0-9_. -]+', '_', filename or 'Jasper Report').strip()
        base, extension = filename.rsplit('.', 1) if '.' in filename else (filename, '')
        if extension.lower() == output_format:
            return filename
        if extension.lower() in ('pdf', 'doc', 'docx', 'xls', 'xlsx'):
            filename = base
        return '%s.%s' % (filename or 'Jasper Report', output_format)

    def _execute_jasper_download(self, output_format):
        self.ensure_one()
        output_format = self._normalize_jasper_output_format(output_format)
        company = self.company_id or self.env.company
        execution_url, jasper_user, jasper_password = self._build_jasper_rest_url(
            company=company,
            path='rest_v2/reportExecutions',
        )
        execution = requests.post(
            execution_url,
            auth=(jasper_user, jasper_password),
            json={
                'reportUnitUri': self.report_unit,
                'outputFormat': output_format,
                'parameters': {
                    'reportParameter': self._format_jasper_report_parameters(
                        self._get_stored_jasper_params()
                    ),
                },
            },
            timeout=120,
        )
        if execution.status_code not in (200, 201):
            raise UserError(_('Jasper execution failed: %s') % execution.text)

        xml = ElementTree.fromstring(execution.content)
        request_id_node = next(
            (node for node in xml.iter() if node.tag.split('}')[-1] == 'requestId'),
            None,
        )
        export_id_node = None
        for export_node in xml.iter():
            if export_node.tag.split('}')[-1] != 'export':
                continue
            export_id_node = next(
                (node for node in export_node.iter() if node.tag.split('}')[-1] == 'id'),
                None,
            )
            if export_id_node is not None:
                break
        if request_id_node is None or export_id_node is None:
            raise UserError(_('Invalid Jasper execution response.'))

        output_url, jasper_user, jasper_password = self._build_jasper_rest_url(
            company=company,
            path='rest_v2/reportExecutions/%s/exports/%s/outputResource' % (
                request_id_node.text,
                export_id_node.text,
            ),
        )
        output = requests.get(
            output_url,
            auth=(jasper_user, jasper_password),
            cookies=execution.cookies,
            timeout=120,
        )
        if output.status_code != 200:
            raise UserError(_('Jasper output failed: %s') % output.text)
        return output

    def _get_stored_jasper_params(self):
        self.ensure_one()
        if not self.params_json:
            return {}
        try:
            params = json.loads(self.params_json)
        except (TypeError, ValueError):
            _logger.warning('Invalid Jasper preview parameters on wizard %s', self.id)
            return {}
        return params if isinstance(params, dict) else {}

    def _action_download_jasper(self, output_format):
        self.ensure_one()
        return {
            'type': 'ir.actions.act_url',
            'url': self._build_jasper_download_url(output_format),
            'target': 'download',
        }

    def get_jasper_download_response(self, output_format, inline=False):
        self.ensure_one()
        output_format = self._normalize_jasper_output_format(output_format)
        output = self._execute_jasper_download(output_format)
        filename = self._get_jasper_download_filename(output_format)
        content_type = output.headers.get('content-type') or self._get_jasper_content_type(output_format)
        disposition = (
            'inline; filename="%s"' % filename.replace('"', '')
            if inline
            else content_disposition(filename)
        )
        return request.make_response(output.content, [
            ('Content-Type', content_type),
            ('Content-Disposition', disposition),
        ])

    def action_download_pdf(self):
        return self._action_download_jasper('pdf')

    def action_download_doc(self):
        return self._action_download_jasper('doc')

    def action_download_xls(self):
        return self._action_download_jasper('xls')

    @api.model
    def open_jasper_preview(self, title, report_unit, params=None, company=None, filename=None, orientation='portrait'):
        jasper_params = self._prepare_jasper_params(params)
        wizard = self.create({
            'name': title,
            'report_unit': report_unit,
            'params_json': json.dumps(jasper_params, default=str),
            'company_id': company.id if company else self.env.company.id,
            'download_filename': filename,
        })
        zoom = 150 if orientation == 'portrait' else 'FitH'
        wizard.preview_url = '%s?inline=1#zoom=%s' % (wizard._build_jasper_download_url('pdf'), zoom)
        view = self.env.ref('mayapada.view_eproc_dialog_preview_form', raise_if_not_found=False)
        return {
            'name': title,
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.dialog.preview',
            'res_id': wizard.id,
            'view_mode': 'form',
            'view': view,
            'target': 'new',
            'context': {
                'dialog_size': 'extra-large',
            },
        }

    @api.depends('preview_url')
    def _compute_preview_html(self):
        for record in self:
            if record.preview_url:
                record.preview_html = (
                        '<iframe src="%s" width="100%%" height="80vh" style="border:0; display:block;"></iframe>'
                        % escape(record.preview_url, quote=True)
                )
            else:
                record.preview_html = ''


class EprocAssetRealize(models.Model):
    _name = 'eproc.asset.realize'
    _description = 'E-Proc GRN Realize to Fixed Asset'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'code'
    _order = 'asset_date desc, id desc'

    code = fields.Char(string='Realize No', readonly=True, copy=False, default='/')
    name = fields.Char(string='Title', compute='_compute_name', store=True)
    company_id = fields.Many2one('res.company', string='Company', required=True, default=lambda self: self.env.company,
                                 tracking=True)
    user_id = fields.Many2one('res.users', string='Responsible', required=True, default=lambda self: self.env.user,
                              tracking=True)
    receipt_id = fields.Many2one(
        'eproc.receipt',
        string='GRN',
        copy=False,
        index=True,
        tracking=True,
    )
    asset_name = fields.Char(string='Asset Name', required=True, tracking=True)
    asset_date = fields.Date(string='Asset Date', required=True, default=fields.Date.context_today, tracking=True)
    asset_category_id = fields.Many2one('account.asset.category', string='Asset Category', required=True, tracking=True)
    asset_subcategory_id = fields.Many2one('account.asset.subcategory', string='Asset Sub Category', required=True,
                                           tracking=True)
    asset_receipt_location_id = fields.Many2one('hr.department', string='Asset Receipt Location', required=True,
                                                tracking=True)
    asset_notes = fields.Char(string='Asset Notes')
    asset_total = fields.Float(string='Asset Total Amt.', compute='_compute_asset_calculations', store=True)
    asset_qty = fields.Integer(string='Asset QTY', required=True, default=1, tracking=True)
    asset_value = fields.Float(string='Asset Unit Value', compute='_compute_asset_calculations', store=True)
    asset_method_number = fields.Integer(string='Depreciation Number', required=True, default=60, tracking=True)
    asset_method_period = fields.Integer(string='Depreciation per Month', required=True, default=1, tracking=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', required=True, tracking=True)
    account_id = fields.Many2one('account.account', string='Credit Account', required=True, tracking=True)
    asset_ids = fields.One2many('account.asset.asset', 'eproc_asset_realize_id', string='Assets', readonly=True)
    move_ids = fields.One2many('account.move', 'eproc_asset_realize_id', string='Entries', readonly=True)
    receipt_line_ids = fields.Many2many(
        'eproc.receipt.line',
        'eproc_asset_realize_receipt_rel',
        'eproc_asset_realize_id',
        'receipt_line_id',
        string='Receipt Items',
    )
    realize_line_ids = fields.One2many('eproc.asset.realize.line', 'eproc_asset_realize_id', string='Realize Items')
    asset_count = fields.Integer(string='Asset Count', compute='_compute_counts')
    move_count = fields.Integer(string='Move Count', compute='_compute_counts')
    is_eproc = fields.Boolean(string='Is Eproc', default=True)
    state = fields.Selection([
        ('draft', 'Draft'),
        ('done', 'Done'),
        ('cancelled', 'Cancelled'),
    ], string='State', default='draft', readonly=True, tracking=True)
    active = fields.Boolean(string='Active', default=True, tracking=True)

    @api.depends('code', 'asset_name')
    def _compute_name(self):
        for record in self:
            record.name = '%s %s' % (record.code or '/', record.asset_name or '')

    @api.depends('asset_ids', 'move_ids')
    def _compute_counts(self):
        for record in self:
            record.asset_count = len(record.asset_ids)
            record.move_count = len(record.move_ids)

    @api.depends('realize_line_ids.asset_amount', 'asset_qty', 'company_id')
    def _compute_asset_calculations(self):
        for record in self:
            currency = record.company_id.currency_id
            total = sum(record.realize_line_ids.mapped('asset_amount'))
            if currency:
                total = currency.round(total)
            record.asset_total = total
            record.asset_value = currency.round(total / record.asset_qty) if currency and record.asset_qty else 0.0

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            receipt_id = vals.get('receipt_id')
            if receipt_id:
                receipt = self.env['eproc.receipt'].browse(receipt_id)
                company = self.env['res.company'].browse(vals.get('company_id')) if vals.get(
                    'company_id') else receipt.company_id
                self._validate_receipt_record_for_asset_realize(receipt, company=company)
                vals['company_id'] = receipt.company_id.id
                vals['supplier_id'] = receipt.supplier_id.id
            vals.setdefault('company_id', self.env.company.id)
            vals.setdefault('user_id', self.env.user.id)
            if not vals.get('code') or vals.get('code') == '/':
                vals['code'] = self.env['ir.sequence'].next_by_code('SEQ.ERP.SCM.ASSET.REALIZE') or '/'
        return super(EprocAssetRealize, self).create(vals_list)

    def write(self, vals):
        vals = dict(vals)
        if 'receipt_id' in vals:
            if 'receipt_line_ids' not in vals and 'realize_line_ids' not in vals:
                vals['receipt_line_ids'] = [(5, 0, 0)]
                vals['realize_line_ids'] = [(5, 0, 0)]
        if vals.get('receipt_id'):
            receipt = self.env['eproc.receipt'].browse(vals['receipt_id'])
            for record in self:
                company = self.env['res.company'].browse(vals.get('company_id')) if vals.get(
                    'company_id') else record.company_id
                record._validate_receipt_record_for_asset_realize(receipt, company=company)
            vals['company_id'] = receipt.company_id.id
            vals['supplier_id'] = receipt.supplier_id.id
        if vals and not self.env.context.get('skip_asset_realize_lock'):
            if self.filtered(lambda record: record.state != 'draft'):
                raise UserError(_('Only draft asset realization documents can be edited.'))
        result = super(EprocAssetRealize, self).write(vals)
        if {'receipt_id', 'receipt_line_ids', 'realize_line_ids'} & set(vals):
            self._validate_receipt_realize_line_sync()
        return result

    def copy(self, default=None):
        raise UserError(_('Asset realization documents cannot be duplicated.'))

    def unlink(self):
        raise UserError(_('Asset realization documents cannot be deleted. Cancel the draft instead.'))

    def action_archive(self):
        if self.filtered(lambda record: record.state != 'draft'):
            raise UserError(_('Only draft asset realization documents can be archived.'))
        return super(EprocAssetRealize, self).action_archive()

    def action_unarchive(self):
        if self.filtered(lambda record: record.state != 'draft'):
            raise UserError(_('Only draft asset realization documents can be unarchived.'))
        return super(EprocAssetRealize, self).action_unarchive()

    def _validate_receipt_record_for_asset_realize(self, receipt, company=False, exception_class=ValidationError):
        if not receipt:
            return True
        if receipt.receipt_type != 'PO':
            raise exception_class(_('Only Purchase Order GRNs can be realized to Fixed Asset.'))
        if receipt.state != 'done':
            raise exception_class(_('Only completed Receiving Validation GRNs can be realized to Fixed Asset.'))
        if company and receipt.company_id != company:
            raise exception_class(
                _('The Receiving Validation and Asset Realize document must belong to the same company.'))
        return True

    def _validate_receipt_for_asset_realize(self, exception_class=ValidationError):
        for record in self:
            if not record.receipt_id:
                continue
            record._validate_receipt_record_for_asset_realize(
                record.receipt_id,
                company=record.company_id,
                exception_class=exception_class,
            )
        return True

    def _filter_asset_realize_receipt_lines(self, lines):
        self.ensure_one()
        if not self.receipt_id:
            return self.env['eproc.receipt.line']
        return lines.filtered(lambda line: (
                line.receipt_id == self.receipt_id
                and line.receipt_id.receipt_type == 'PO'
                and line.receipt_id.state == 'done'
                and line.receipt_id.company_id == self.company_id
                and line.receipt_id.supplier_id == self.supplier_id
                and line.product_tmpl_id
                and line.product_tmpl_id.eproc_type == 'non_stock'
                and (not line.eproc_asset_realize_id or line.eproc_asset_realize_id == self)
        ))

    def _validate_receipt_realize_line_sync(self):
        for record in self:
            if not record.receipt_id:
                continue
            selected_line_ids = set(record.receipt_line_ids.ids)
            for receipt_line in record.receipt_line_ids:
                if receipt_line.receipt_id != record.receipt_id:
                    raise ValidationError(_('Receipt Items must belong to the selected GRN.'))
            seen_line_ids = set()
            for realize_line in record.realize_line_ids:
                receipt_line = realize_line.receipt_line_id
                if not receipt_line:
                    raise ValidationError(_('Receipt Item is required.'))
                if receipt_line.receipt_id != record.receipt_id:
                    raise ValidationError(_('Asset to Realize lines must belong to the selected GRN.'))
                if receipt_line.id not in selected_line_ids:
                    raise ValidationError(_('Asset to Realize lines must match the selected Receipt Items.'))
                if receipt_line.id in seen_line_ids:
                    raise ValidationError(_('The same receipt item cannot be realized more than once in one document.'))
                seen_line_ids.add(receipt_line.id)
        return True

    @api.constrains('receipt_id', 'company_id', 'supplier_id', 'receipt_line_ids')
    def _check_receipt_selection(self):
        for record in self:
            if not record.receipt_id:
                raise ValidationError(_('GRN is required.'))
            record._validate_receipt_for_asset_realize()
            if record.receipt_id.company_id != record.company_id:
                raise ValidationError(_('Selected GRN must belong to the realization company.'))
            if record.receipt_id.supplier_id != record.supplier_id:
                raise ValidationError(_('Selected GRN must belong to the realization supplier.'))
            for receipt_line in record.receipt_line_ids:
                if receipt_line.receipt_id != record.receipt_id:
                    raise ValidationError(_('Receipt Items must belong to the selected GRN.'))
                if receipt_line.receipt_id.receipt_type != 'PO' or receipt_line.receipt_id.state != 'done':
                    raise ValidationError(
                        _('Only completed Purchase Order receipt items can be realized to fixed assets.'))
                if receipt_line.product_tmpl_id.eproc_type != 'non_stock':
                    raise ValidationError(_('Only Non Stock receipt items can be realized to fixed assets.'))

    @api.onchange('asset_category_id')
    def _onchange_asset_category_id(self):
        for record in self:
            category = record.asset_category_id
            if not category:
                continue
            if 'method_number' in category._fields and category.method_number:
                record.asset_method_number = category.method_number
            if 'method_period' in category._fields and category.method_period:
                record.asset_method_period = category.method_period

    @api.onchange('supplier_id')
    def _onchange_supplier_id(self):
        for record in self:
            if record.state != 'draft':
                continue
            if record.receipt_id and record.supplier_id != record.receipt_id.supplier_id:
                record.receipt_id = False
            if not record.receipt_line_ids and not record.realize_line_ids:
                continue
            record.receipt_line_ids = [(5, 0, 0)]
            record.realize_line_ids = [(5, 0, 0)]
            return {
                'warning': {
                    'title': _('Supplier Changed'),
                    'message': _('Receipt Items and Realize Items were cleared because the supplier was changed.'),
                }
            }

    @api.onchange('receipt_id')
    def _onchange_receipt_id(self):
        for record in self:
            if record.state != 'draft':
                continue
            old_receipt = record._origin.receipt_id if record._origin else self.env['eproc.receipt']
            receipt_changed = old_receipt != record.receipt_id
            if receipt_changed or not record.receipt_id:
                record.receipt_line_ids = [(5, 0, 0)]
                record.realize_line_ids = [(5, 0, 0)]
            if not record.receipt_id:
                continue
            try:
                record._validate_receipt_record_for_asset_realize(record.receipt_id,
                                                                  company=record.receipt_id.company_id)
            except ValidationError as err:
                record.receipt_id = False
                record.receipt_line_ids = [(5, 0, 0)]
                record.realize_line_ids = [(5, 0, 0)]
                return {'warning': {
                    'title': _('Invalid Receiving Validation'),
                    'message': str(err),
                }}
            record.company_id = record.receipt_id.company_id
            record.supplier_id = record.receipt_id.supplier_id
            if not receipt_changed:
                allowed_lines = record._filter_asset_realize_receipt_lines(record.receipt_line_ids)
                if allowed_lines != record.receipt_line_ids:
                    record.receipt_line_ids = [(6, 0, allowed_lines.ids)]
                record._onchange_receipt_line_ids()

    @api.onchange('receipt_line_ids')
    def _onchange_receipt_line_ids(self):
        for record in self:
            selected_lines = record.receipt_line_ids
            if record.receipt_id:
                selected_lines = record._filter_asset_realize_receipt_lines(selected_lines)
                if selected_lines != record.receipt_line_ids:
                    record.receipt_line_ids = [(6, 0, selected_lines.ids)]
            seen_receipt_line_ids = set()
            stale_realize_lines = self.env['eproc.asset.realize.line']
            for realize_line in record.realize_line_ids:
                receipt_line = realize_line.receipt_line_id
                if (
                        not receipt_line
                        or receipt_line not in selected_lines
                        or receipt_line.id in seen_receipt_line_ids
                        or (record.receipt_id and receipt_line.receipt_id != record.receipt_id)
                ):
                    stale_realize_lines |= realize_line
                    continue
                seen_receipt_line_ids.add(receipt_line.id)
            if stale_realize_lines:
                record.realize_line_ids -= stale_realize_lines
            existing_receipt_line_ids = set(record.realize_line_ids.mapped('receipt_line_id').ids)
            for receipt_line in selected_lines:
                if receipt_line.id in existing_receipt_line_ids:
                    continue
                record.realize_line_ids += self.env['eproc.asset.realize.line'].new({
                    'receipt_line_id': receipt_line.id,
                    'realize_amount': receipt_line.total_netprice,
                })
                existing_receipt_line_ids.add(receipt_line.id)

    def _lock_receipt_lines(self):
        for record in self.filtered(lambda rec: rec.receipt_line_ids):
            self.env.cr.execute(
                'SELECT id FROM eproc_receipt_line WHERE id IN %s FOR UPDATE',
                [tuple(record.receipt_line_ids.ids)],
            )
            record.receipt_line_ids.invalidate_cache()

    def _currency_compare(self, left, right):
        self.ensure_one()
        currency = self.company_id.currency_id
        if currency:
            return float_compare(left, right, precision_rounding=currency.rounding)
        return float_compare(left, right, precision_digits=2)

    def _validate_receipt_lines(self):
        self.ensure_one()
        if not self.receipt_id:
            raise UserError(_('GRN is required.'))
        self._validate_receipt_for_asset_realize(exception_class=UserError)
        if self.receipt_id.company_id != self.company_id:
            raise UserError(_('Selected GRN belongs to another company.'))
        if self.receipt_id.supplier_id != self.supplier_id:
            raise UserError(_('Selected GRN belongs to another supplier.'))
        if not self.receipt_line_ids:
            raise UserError(_('Please select at least one validated GRN receipt item.'))
        realize_receipt_line_ids = self.realize_line_ids.mapped('receipt_line_id').ids
        if len(realize_receipt_line_ids) != len(set(realize_receipt_line_ids)):
            raise UserError(_('The same receipt item cannot be realized more than once in one document.'))
        if (
                set(self.receipt_line_ids.ids) != set(realize_receipt_line_ids)
                or len(self.receipt_line_ids) != len(realize_receipt_line_ids)
        ):
            raise UserError(_('Receipt items and realization lines must match before confirmation.'))
        seen_line_ids = set()
        for line in self.receipt_line_ids:
            if line.id in seen_line_ids:
                raise UserError(_('Receipt item %s is selected more than once.') % (line.display_name or line.id))
            seen_line_ids.add(line.id)
            if line.receipt_id != self.receipt_id:
                raise UserError(
                    _('Receipt item %s does not belong to the selected GRN.') % (line.display_name or line.id))
            if line.receipt_id.company_id != self.company_id:
                raise UserError(_('Receipt item %s belongs to another company.') % (line.display_name or line.id))
            if line.receipt_id.receipt_type != 'PO':
                raise UserError(_('Only Purchase Order receipt items can be realized to fixed assets.'))
            if line.receipt_id.state != 'done':
                raise UserError(_('Only completed receipt items can be realized to fixed assets.'))
            if not line.product_tmpl_id or line.product_tmpl_id.eproc_type != 'non_stock':
                raise UserError(_('Only Non Stock receipt items can be realized to fixed assets.'))
            if line.eproc_asset_realize_id and line.eproc_asset_realize_id != self:
                raise UserError(
                    _('Receipt item %s has already been realized to Fixed Asset by %s.')
                    % (line.display_name or line.id,
                       line.eproc_asset_realize_id.code or line.eproc_asset_realize_id.display_name)
                )
            if line.receipt_id.supplier_id != self.supplier_id:
                raise UserError(_('Receipt item %s belongs to another supplier.') % (line.display_name or line.id))

    def _validate_before_confirm(self):
        for record in self:
            if record.state != 'draft':
                raise UserError(_('Only draft asset realization documents can be confirmed.'))
            required_fields = [
                ('receipt_id', _('GRN')),
                ('asset_name', _('Asset Name')),
                ('asset_date', _('Asset Date')),
                ('asset_category_id', _('Asset Category')),
                ('asset_subcategory_id', _('Asset Sub Category')),
                ('asset_receipt_location_id', _('Asset Receipt Location')),
                ('supplier_id', _('Supplier')),
                ('account_id', _('Credit Account')),
            ]
            for field_name, label in required_fields:
                if not record[field_name]:
                    raise UserError(_('%s is required.') % label)
            if record.asset_qty <= 0:
                raise UserError(_('Asset quantity must be greater than zero.'))
            if not record.realize_line_ids:
                raise UserError(_('Please select receipt items to realize.'))
            if record._currency_compare(record.asset_total, 0.0) <= 0:
                raise UserError(_('Asset total must be greater than zero.'))
            if not record.asset_category_id.account_asset_id:
                raise UserError(
                    _('Asset category %s has no fixed-asset account.') % record.asset_category_id.display_name)
            if record.asset_subcategory_id.category_id and record.asset_subcategory_id.category_id != record.asset_category_id:
                raise UserError(_('Asset sub category must belong to the selected asset category.'))
            if not record.asset_subcategory_id.sequence_id:
                raise UserError(_('Asset sub category %s has no sequence.') % record.asset_subcategory_id.display_name)
            if not record._get_asset_journal():
                raise UserError(_('Asset Journal is not configured for company %s.') % record.company_id.display_name)
            record._validate_receipt_lines()
            record.realize_line_ids._validate_realize_amounts()

    def _get_asset_journal(self):
        self.ensure_one()
        journal = self.env['account.journal']
        if 'journal_id' in self.asset_category_id._fields:
            journal = self.asset_category_id.journal_id
            if journal and journal.company_id and journal.company_id != self.company_id:
                journal = self.env['account.journal']
        if not journal:
            journal = self.env['account.journal'].search([
                ('code', '=', 'AJ'),
                ('name', '=', 'Asset Journal'),
                ('company_id', '=', self.company_id.id),
            ], limit=1)
        return journal

    def _asset_unit_values(self):
        self.ensure_one()
        qty = int(self.asset_qty)
        base_value = self.asset_total / qty
        currency = self.company_id.currency_id
        if not currency:
            return [base_value] * qty
        rounded_value = currency.round(base_value)
        values = [rounded_value] * qty
        values[-1] = currency.round(self.asset_total - sum(values[:-1]))
        return values

    def _prepare_asset_values(self, value, sequence):
        self.ensure_one()
        return {
            'company_id': self.company_id.id,
            'category_id': self.asset_category_id.id,
            'subcategory_id': self.asset_subcategory_id.id,
            'location_id': self.asset_receipt_location_id.id,
            'eproc_asset_realize_id': self.id,
            'method_number': self.asset_method_number,
            'method_period': self.asset_method_period,
            'date': self.asset_date,
            'partner_id': self.supplier_id.id,
            'name': self.asset_name if self.asset_qty == 1 else '%s %s/%s' % (self.asset_name, sequence,
                                                                              self.asset_qty),
            'qty': 1.0,
            'value': value,
            'credit_account_id': self.account_id.id,
        }

    def _prepare_asset_move_values(self, asset):
        self.ensure_one()
        amount = abs(asset.value or 0.0)
        if not amount:
            raise UserError(_('Asset value must be greater than zero.'))
        ref = '%s / %s' % (self.asset_name, asset.code or self.code)
        move_lines = [
            (0, 0, {
                'name': self.asset_name,
                'ref': ref,
                'partner_id': self.supplier_id.id,
                'account_id': self.asset_category_id.account_asset_id.id,
                'date_maturity': self.asset_date,
                'debit': amount,
                'credit': 0.0,
                'account_asset_id': asset.id,
                'eproc_asset_realize_id': self.id,
            }),
            (0, 0, {
                'name': self.asset_name,
                'ref': ref,
                'partner_id': self.supplier_id.id,
                'account_id': self.account_id.id,
                'date_maturity': self.asset_date,
                'debit': 0.0,
                'credit': amount,
                'account_asset_id': asset.id,
                'eproc_asset_realize_id': self.id,
            }),
        ]
        return {
            'company_id': self.company_id.id,
            'journal_id': self._get_asset_journal().id,
            'date': self.asset_date,
            'ref': ref,
            'partner_id': self.supplier_id.id,
            'account_asset_id': asset.id,
            'eproc_asset_realize_id': self.id,
            'line_ids': move_lines,
        }

    def _create_assets_and_moves(self):
        Asset = self.env['account.asset.asset']
        Move = self.env['account.move']
        for record in self:
            if record.asset_ids or record.move_ids:
                raise UserError(_('Assets or journal entries already exist for %s.') % record.code)
            for index, value in enumerate(record._asset_unit_values(), start=1):
                asset = Asset.create(record._prepare_asset_values(value, index))
                move = Move.create(record._prepare_asset_move_values(asset))
                move.action_post()

    def action_confirm(self):
        for record in self:
            if record.state != 'draft':
                raise UserError(_('Only draft asset realization documents can be confirmed.'))
            if record.asset_ids or record.move_ids:
                raise UserError(_('Assets or journal entries already exist for %s.') % record.code)
            record._lock_receipt_lines()
            record._validate_before_confirm()
            record._create_assets_and_moves()
            record.receipt_line_ids.with_context(
                skip_receipt_line_lock=True,
                skip_receipt_line_master_lock=True,
            ).write({'eproc_asset_realize_id': record.id})
            record.with_context(skip_asset_realize_lock=True).write({'state': 'done'})
        return True

    def action_cancel(self):
        for record in self:
            if record.state != 'draft':
                raise UserError(_('Only draft asset realization documents can be cancelled.'))
            record.with_context(skip_asset_realize_lock=True).write({'state': 'cancelled'})
        return True

    def open_assets(self):
        self.ensure_one()
        return {
            'name': _('Assets for %s') % self.code,
            'type': 'ir.actions.act_window',
            'res_model': 'account.asset.asset',
            'view_mode': 'tree,form',
            'domain': [('id', 'in', self.asset_ids.ids)],
            'context': {'create': False, 'edit': False, 'delete': False},
        }

    def open_moves(self):
        self.ensure_one()
        return {
            'name': _('Entries for %s') % self.code,
            'type': 'ir.actions.act_window',
            'res_model': 'account.move',
            'view_mode': 'tree,form',
            'domain': [('id', 'in', self.move_ids.ids)],
            'context': {'create': False, 'edit': False, 'delete': False},
        }

    def action_print_asset_barcode(self):
        self.ensure_one()
        if self.state != 'done':
            raise UserError(_('Only confirmed asset realization documents can print asset barcodes.'))
        if not self.asset_ids:
            raise UserError(_('There are no assets to print.'))
        view = self.env.ref('mayapada.view_eproc_asset_barcode_print_wizard_form', raise_if_not_found=False)
        wizard = self.env['eproc.asset.barcode.print.wizard'].create({
            'realize_id': self.id,
            # 'asset_ids': [(6, 0, self.asset_ids.ids)],
        })
        return {
            'name': _('Print Asset Barcode'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.asset.barcode.print.wizard',
            'res_id': wizard.id,
            'view_mode': 'form',
            'view': view,
            'target': 'new',
            'context': {
                'dialog_size': 'large',
            },
        }


class EprocAssetBarcodePrintWizard(models.TransientModel):
    _name = 'eproc.asset.barcode.print.wizard'
    _description = 'E-Proc Asset Barcode Print Wizard'

    realize_id = fields.Many2one(
        'eproc.asset.realize',
        string='Asset Realize',
        required=True,
        readonly=True,
        ondelete='cascade',
    )
    company_id = fields.Many2one(
        'res.company',
        string='Company',
        related='realize_id.company_id',
        readonly=True,
    )
    asset_ids = fields.Many2many(
        'account.asset.asset',
        'eproc_asset_barcode_print_wizard_asset_rel',
        'wizard_id',
        'asset_id',
        string='Assets to Print',
    )

    def _validate_selected_assets(self):
        for wizard in self:
            if not wizard.asset_ids:
                raise UserError(_('Please select at least one asset to print.'))
            invalid_assets = wizard.asset_ids.filtered(
                lambda asset: (
                    asset.eproc_asset_realize_id != wizard.realize_id
                    or asset.company_id != wizard.company_id
                )
            )
            if invalid_assets:
                raise UserError(_('Only assets from the current asset realization document can be printed.'))
        return True

    def action_print_asset_barcode(self):
        self.ensure_one()
        self._validate_selected_assets()

        realize = self.realize_id

        if realize.state != 'done':
            raise UserError(
                _('Only confirmed asset realization documents can print asset barcodes.')
            )

        selected_asset_ids = sorted(self.asset_ids.ids)

        if not selected_asset_ids:
            raise UserError(
                _('Please select at least one asset to print.')
            )

        asset_ids_csv = ','.join(
            str(asset_id)
            for asset_id in selected_asset_ids
        )

        return self.env['eproc.dialog.preview'].open_jasper_preview(
            title=_('Print Asset Barcode'),
            report_unit='/Mayapada/Eproc/Asset_Barcode',
            params={
                'asset_realize_id': realize.id,
                'asset_ids_csv': asset_ids_csv,
            },
            company=realize.company_id,
            filename='%s Asset Barcode' % (
                realize.code or realize.display_name
            ),
        )


class EprocAssetRealizeLine(models.Model):
    _name = 'eproc.asset.realize.line'
    _description = 'E-Proc GRN Realize to Fixed Asset Line'
    _order = 'id'

    eproc_asset_realize_id = fields.Many2one('eproc.asset.realize', string='Asset Realize', required=True,
                                             ondelete='cascade')
    company_id = fields.Many2one('res.company', related='eproc_asset_realize_id.company_id', store=True, readonly=True)
    receipt_line_id = fields.Many2one('eproc.receipt.line', string='Receipt Item')
    product_tmpl_id = fields.Many2one('product.template', related='receipt_line_id.product_tmpl_id', store=True,
                                      readonly=True)
    name = fields.Char(related='receipt_line_id.name', store=True, readonly=True)
    pack_id = fields.Many2one('eproc.pack', related='receipt_line_id.pack_id', store=True, readonly=True)
    pack_qty = fields.Float(string='Pack Qty', related='receipt_line_id.pack_receipt', store=True, readonly=True)
    pack_price = fields.Float(related='receipt_line_id.pack_price', store=True, readonly=True)
    disc_rate = fields.Float(related='receipt_line_id.disc_rate', store=True, readonly=True)
    tax_ids = fields.Many2many(related='receipt_line_id.tax_ids', readonly=True)
    total_netprice = fields.Float(related='receipt_line_id.total_netprice', store=True, readonly=True)
    asset_amount = fields.Float(
        string='Asset Amount',
        compute='_compute_asset_amount',
        inverse='_inverse_asset_amount',
        store=True,
        readonly=False,
    )
    non_asset_amount = fields.Float(string='Non Asset Amount', compute='_compute_non_asset_amount', store=True)
    realize_amount = fields.Float(string='Amt. to Realize', required=True)
    active = fields.Boolean(string='Active', default=True)

    @api.depends('realize_amount')
    def _compute_asset_amount(self):
        for line in self:
            line.asset_amount = line.realize_amount or 0.0

    def _inverse_asset_amount(self):
        for line in self:
            line.with_context(
                skip_asset_amount_sync=True,
                skip_asset_amount_validation=True,
            ).write({'realize_amount': line.asset_amount or 0.0})

    @api.depends('receipt_line_id.total_netprice', 'asset_amount')
    def _compute_non_asset_amount(self):
        for line in self:
            source_amount = line.receipt_line_id.total_netprice or 0.0
            residual = source_amount - (line.asset_amount or 0.0)
            line.non_asset_amount = max(residual, 0.0)

    @api.model_create_multi
    def create(self, vals_list):
        normalized_vals_list = []
        for incoming_vals in vals_list:
            vals = dict(incoming_vals)
            if 'asset_amount' in vals:
                vals['realize_amount'] = vals.pop('asset_amount') or 0.0
            elif vals.get('realize_amount') is None:
                receipt_line = self.env['eproc.receipt.line']
                if vals.get('receipt_line_id'):
                    receipt_line = receipt_line.browse(vals['receipt_line_id'])
                vals['realize_amount'] = receipt_line.total_netprice if receipt_line else 0.0
            vals.pop('non_asset_amount', None)
            normalized_vals_list.append(vals)
        records = super(EprocAssetRealizeLine, self.with_context(
            skip_asset_amount_validation=True,
        )).create(normalized_vals_list)
        records._validate_realize_amounts()
        return records

    def write(self, vals):
        vals = dict(vals)
        if vals and not self.env.context.get('skip_asset_realize_lock'):
            if self.filtered(lambda line: line.eproc_asset_realize_id.state != 'draft'):
                raise UserError(_('Only draft asset realization lines can be edited.'))
        if 'asset_amount' in vals and not self.env.context.get('skip_asset_amount_sync'):
            vals['realize_amount'] = vals.get('asset_amount') or 0.0
            vals.pop('asset_amount', None)
        vals.pop('non_asset_amount', None)
        result = super(EprocAssetRealizeLine, self).write(vals)
        if (
                not self.env.context.get('skip_asset_amount_validation')
                and {'receipt_line_id', 'realize_amount'} & set(vals)
        ):
            self._validate_realize_amounts()
        return result

    def unlink(self):
        if not self.env.context.get('skip_asset_realize_lock'):
            if self.filtered(lambda line: line.eproc_asset_realize_id.state != 'draft'):
                raise UserError(_('Only draft asset realization lines can be deleted.'))
        return super(EprocAssetRealizeLine, self).unlink()

    def _validate_realize_amounts(self):
        for line in self:
            record = line.eproc_asset_realize_id
            receipt_line = line.receipt_line_id
            if not receipt_line:
                raise ValidationError(_('Receipt Item is required.'))
            if record.company_id and receipt_line.company_id != record.company_id:
                raise ValidationError(_('Receipt item company must match the realization company.'))
            if receipt_line.receipt_id.receipt_type != 'PO' or receipt_line.receipt_id.state != 'done':
                raise ValidationError(_('Only completed Purchase Order receipt items can be realized.'))
            if not receipt_line.product_tmpl_id or receipt_line.product_tmpl_id.eproc_type != 'non_stock':
                raise ValidationError(_('Only Non Stock receipt items can be realized.'))
            if receipt_line.eproc_asset_realize_id and receipt_line.eproc_asset_realize_id != record:
                raise ValidationError(
                    _('Receipt item %s has already been realized to Fixed Asset by %s.')
                    % (receipt_line.display_name or receipt_line.id,
                       receipt_line.eproc_asset_realize_id.code or receipt_line.eproc_asset_realize_id.display_name)
                )
            if record.receipt_id and receipt_line.receipt_id != record.receipt_id:
                raise ValidationError(_('Receipt item must belong to the selected GRN.'))
            if record._currency_compare(line.asset_amount or 0.0, 0.0) < 0:
                raise ValidationError(_('Asset Amount cannot be negative.'))
            if record._currency_compare(line.non_asset_amount or 0.0, 0.0) < 0:
                raise ValidationError(_('Non Asset Amount cannot be negative.'))
            if record._currency_compare(line.asset_amount or 0.0, line.total_netprice or 0.0) > 0:
                raise ValidationError(_(
                    'Asset Amount (%s) for %s cannot be greater than Total Net Price (%s).'
                ) % (line.asset_amount, receipt_line.name or '', line.total_netprice))
            split_total = (line.asset_amount or 0.0) + (line.non_asset_amount or 0.0)
            if record._currency_compare(split_total, line.total_netprice or 0.0) != 0:
                raise ValidationError(_('Asset Amount plus Non Asset Amount must equal Total Net Price for %s.') % (
                            receipt_line.name or receipt_line.display_name))

    @api.constrains('eproc_asset_realize_id', 'receipt_line_id')
    def _check_duplicate_receipt_line(self):
        for record in self.mapped('eproc_asset_realize_id'):
            line_ids = record.realize_line_ids.mapped('receipt_line_id').ids
            if len(line_ids) != len(set(line_ids)):
                raise ValidationError(_('The same receipt item cannot be realized more than once in one document.'))


