class EprocRequestTrackingWizard(models.TransientModel):
    _name = 'eproc.request.tracking.wizard'
    _description = 'PR Tracking Analysis'
    _tracking_states = ('ready', 'partial', 'done', 'closed', 'cancelled', 'expired')

    company_id = fields.Many2one(
        'res.company',
        string='Company',
        default=lambda self: self.env.company,
        required=True,
    )
    date_type = fields.Selection([
        ('request_date', 'Request Date'),
        ('request_valid_date', 'Approval Completed'),
    ], string='Period By', default='request_date', required=True)
    date_start = fields.Date(string='Start Date', default=fields.Date.context_today, required=True)
    date_end = fields.Date(string='End Date', default=fields.Date.context_today, required=True)
    purchase_type_ids = fields.Many2many(
        'eproc.type',
        'eproc_request_tracking_purchase_type_rel',
        'wizard_id',
        'purchase_type_id',
        string='Procurement Type(s)',
    )
    user_ids = fields.Many2many(
        'res.users',
        'eproc_request_tracking_user_rel',
        'wizard_id',
        'user_id',
        string='Responsible(s)',
        default=lambda self: [(6, 0, [self.env.user.id])],
    )
    department_ids = fields.Many2many(
        'hr.department',
        'eproc_request_tracking_department_rel',
        'wizard_id',
        'department_id',
        string='Department(s)',
        default=lambda self: [(6, 0, [self.env.user.department_id.id])] if self.env.user.department_id else False,
    )
    state_ids = fields.Many2many(
        'eproc.request.tracking.state',
        'eproc_request_tracking_state_rel',
        'wizard_id',
        'state_id',
        string='State',
        default=lambda self: self.env.ref('mayapada.eproc_request_tracking_state_ready'),
    )
    request_ids = fields.Many2many(
        'eproc.request',
        'eproc_request_tracking_request_rel',
        'wizard_id',
        'request_id',
        string='Request(s)',
    )

    def name_get(self):
        return [(record.id, _('PR Tracking Analysis')) for record in self]

    def _get_request_domain(self):
        self.ensure_one()
        domain = [('company_id', '=', self.company_id.id)]
        domain.append(('line_ids.state', 'in', self.state_ids.mapped('code') if self.state_ids else self._tracking_states))
        if self.purchase_type_ids:
            domain.append(('purchase_type_id', 'in', self.purchase_type_ids.ids))
        if self.user_ids:
            domain.append(('user_id', 'in', self.user_ids.ids))
        if self.department_ids:
            domain.append(('department_id', 'in', self.department_ids.ids))
        return domain

    @api.onchange('company_id', 'state_ids', 'purchase_type_ids', 'user_ids', 'department_ids')
    def _onchange_tracking_filters(self):
        for record in self:
            record.request_ids = [(5, 0, 0)]
        return {'domain': {'request_ids': self._get_request_domain() if self.company_id else []}}

    def action_show(self):
        self.ensure_one()
        domain = [('company_id', '=', self.company_id.id)]
        if self.date_type:
            if self.date_start:
                date_start = datetime.combine(self.date_start, time.min)
                domain.append((self.date_type, '>=', fields.Datetime.to_string(date_start)))
            if self.date_end:
                date_end = datetime.combine(self.date_end, time.max)
                domain.append((self.date_type, '<=', fields.Datetime.to_string(date_end)))
        domain.append(('state', 'in', self.state_ids.mapped('code') if self.state_ids else self._tracking_states))
        if self.purchase_type_ids:
            domain.append(('purchase_type_id', 'in', self.purchase_type_ids.ids))
        if self.user_ids:
            domain.append(('user_id', 'in', self.user_ids.ids))
        if self.department_ids:
            domain.append(('department_id', 'in', self.department_ids.ids))
        if self.request_ids:
            domain.append(('request_id', 'in', self.request_ids.ids))

        tree_view = self.env.ref('mayapada.view_erp_pmm_reporting_pr_tracking_analysis_tree',
                                 raise_if_not_found=False)
        pivot_view = self.env.ref('mayapada.view_erp_pmm_transaction_purchase_request_line_pivot',
                                  raise_if_not_found=False)
        search_view = self.env.ref('mayapada.view_erp_pmm_transaction_purchase_request_line_search',
                                   raise_if_not_found=False)
        return {
            'name': _('PR Tracking Analysis'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.request.line',
            'view_mode': 'pivot,tree',
            'views': [
                (pivot_view.id if pivot_view else False, 'pivot'),
                (tree_view.id if tree_view else False, 'tree'),
            ],
            'search_view_id': search_view.id if search_view else False,
            'domain': domain,
            'context': {
                'create': False,
                'edit': False,
                'delete': False,
                'duplicate': False,
            },
            'target': 'current',
        }


