class EprocRequestLine(models.Model):
    _name = 'eproc.request.line'
    _description = 'E-Proc Request Line'
    _order = 'request_id, sequence, id'
    _processed_order_states = ('approval', 'purchase', 'partial', 'done')
    _processed_order_line_states = ('ready', 'partial', 'done', 'closed')

    request_id = fields.Many2one('eproc.request', string='Request', ondelete='cascade')
    budget_item_id = fields.Many2one('eproc.budget.item', string='Budget Item', index=True,
        ondelete='restrict', domain="[('company_id', '=', company_id), ('budget_group_id', '=', request_id.budget_group_id), ('budget_category_id', '=', request_id.budget_category_id), ('state', '=', 'validate'), ('active', '=', True), ('unrealize_amount', '>', 0)]")

    @api.onchange('budget_item_id')
    def _onchange_budget_item_id(self):
        for line in self:
            if line.budget_item_id:
                line.analytic_id = line.budget_item_id.analytic_account_id
                line.pack_qty = line.budget_item_id.quantity
                line.pack_price = line.budget_item_id.budget_unit
                line._compute_pack_amounts()
        return {'domain': {'budget_item_id': [('company_id', '=', self.company_id.id),
            ('budget_group_id', '=', self.request_id.budget_group_id.id),
            ('budget_category_id', '=', self.request_id.budget_category_id.id), ('state', '=', 'validate'),
            ('active', '=', True), ('unrealize_amount', '>', 0)]}}

    @api.onchange('request_id')
    def _onchange_request_budget(self):
        for line in self:
            if line.budget_item_id and (line.request_id.request_type != 'budgeted'
                    or line.budget_item_id.budget_group_id != line.request_id.budget_group_id
                    or line.budget_item_id.budget_category_id != line.request_id.budget_category_id):
                line.budget_item_id = False

    def _check_budget_tracking(self, require_validated=False, committed_pr=False):
        for line in self.filtered('active'):
            budget = line.budget_item_id
            if line.request_id.request_type == 'budgeted' and not budget:
                raise ValidationError(_('Every active line of a Budgeted request requires a Budget Item.'))
            if line.product_tmpl_id and line.product_tmpl_id._requires_medical_equipment_budget() and not budget:
                raise ValidationError(_('CapEx Medical Equipment requires a validated Budget Item on every PR line.'))
            if budget:
                budget.check_access_rights('read')
                budget.check_access_rule('read')
                request = line.request_id
                allowed = self.env.companies & self.env.user.company_ids
                if budget.company_id != line.company_id or line.company_id not in allowed:
                    raise ValidationError(_('Budget Item does not match the accessible PR company.'))
                if request.request_type == 'budgeted' and (
                        budget.budget_group_id != request.budget_group_id
                        or budget.budget_category_id != request.budget_category_id
                        or budget.budget_group_id.type != 'group' or budget.budget_category_id.type != 'category'
                        or not budget.budget_group_id.active or not budget.budget_category_id.active
                        or self.env.user not in budget.budget_group_id.user_ids
                        or self.env.user not in budget.budget_category_id.user_ids):
                    raise ValidationError(_('Budget Item does not match the accessible PR budget group and category.'))
                if budget.product_tmpl_id and budget.product_tmpl_id != line.product_tmpl_id:
                    raise ValidationError(_('Budget Item is reserved for another product.'))
                # RFQ converts an already reserved PR commitment; the order still
                # checks the combined PR/PO ceiling before entering approval.
                reserved_pr = (committed_pr and request.active
                               and request.state in ('ready', 'partial', 'done')
                               and line.state != 'cancelled')
                eligible = (budget.state in ('validate', 'reallocate') if reserved_pr
                            else budget.state == 'validate' and budget.unrealize_amount > 0)
                if require_validated and (not eligible or not budget.active or not budget.code):
                    raise ValidationError(_('Select an active, validated Budget Item with remaining value.'))

    @api.constrains('budget_item_id', 'company_id', 'product_tmpl_id', 'request_id', 'active')
    def _check_budget_assignment(self):
        linked = self.filtered('budget_item_id')
        linked._check_budget_tracking()
        self.filtered(lambda line: line.request_id.request_type == 'budgeted' and line.active)._check_budget_tracking()
        self.filtered(lambda line: line.request_id.state in ('approval', 'ready', 'partial', 'done'))._check_budget_tracking()

    company_id = fields.Many2one('res.company', related='request_id.company_id', store=True, readonly=True)
    purchase_type_id = fields.Many2one('eproc.type', related='request_id.purchase_type_id', store=True, readonly=True)
    sequence = fields.Integer(string='Sno', default=0, readonly=True)
    product_tmpl_id = fields.Many2one('product.template', string='Product')
    name = fields.Char(string='Description')
    product_uom_id = fields.Many2one('uom.uom', related='product_tmpl_id.uom_id', store=True, readonly=True)
    pack_id = fields.Many2one('eproc.pack', string='Pack Type')
    pack_qty = fields.Float(string='Pack Qty', default=1.0)
    pack_qty_processed = fields.Float(string='Pack Qty Processed', compute='_compute_pack_qty_processed', store=True,
                                      readonly=True)
    pack_qty_remaining = fields.Float(string='Pack Qty Remaining', compute='_compute_pack_qty_remaining', store=True,
                                      readonly=True)
    pack_qty_available = fields.Float(string='Pack Qty Pending', compute='_compute_pending_qty', store=True,
                                      readonly=True)
    pack_price = fields.Float(string='Pack Price')
    pack_rate = fields.Float(string='Pack Rate')
    uom_id = fields.Many2one('uom.uom', string='UoM')
    uom_qty = fields.Float(string='UoM Qty')
    uom_qty_processed = fields.Float(string='UoM Qty Processed', compute='_compute_uom_qty_processed', store=True,
                                     readonly=True)
    uom_qty_available = fields.Float(string='UoM Qty Pending', compute='_compute_pending_qty', store=True,
                                     readonly=True)
    uom_qty_on_hand = fields.Float(string='UoM Qty On Hand')
    uom_qty_min = fields.Float(string='UoM Qty Min')
    uom_qty_max = fields.Float(string='UoM Qty Max')
    uom_qty_suggested = fields.Float(string='UoM Qty Suggested')
    uom_price = fields.Float(string='UoM Price')
    total_price = fields.Float(string='Total Price')
    analytic_id = fields.Many2one('account.analytic.account', string='Analytic Account')
    orderpoint_log_id = fields.Many2one('eproc.orderpoint.log', string='Suggestion Log')
    order_line_ids = fields.One2many('eproc.order.line', 'request_line_id', string='Purchase Items', readonly=True)
    order_line_valid_ids = fields.Many2many(
        'eproc.order.line', compute='_compute_order_line_valid_ids', string='Purchase No(s)'
    )
    receipt_line_ids = fields.One2many('eproc.receipt.line', 'request_line_id', string='Receiving Items', readonly=True)
    request_no = fields.Char(string='Request No', related='request_id.request_no', store=True, readonly=True)
    request_revise = fields.Integer(string='Request Revise', related='request_id.request_revise', store=True,
                                    readonly=True)
    request_date = fields.Datetime(string='Request Date', related='request_id.request_date', store=True, readonly=True)
    request_valid_date = fields.Datetime(string='Request Valid Date', related='request_id.request_valid_date',
                                         store=True, readonly=True)
    request_expiry_date = fields.Date(
        string='Request Expiry Date',
        related='request_id.request_expiry_date',
        store=True,
        readonly=True,
    )
    request_ref = fields.Char(string='Request Ref', related='request_id.request_ref', store=True, readonly=True)
    request_type = fields.Selection(related='request_id.request_type', store=True, readonly=True)
    request_amount = fields.Float(string='Request Total Price', related='request_id.total_price', store=True,
                                  readonly=True)
    approval_type_id = fields.Many2one('eproc.approval.type', string='Approval Type',
                                       related='request_id.approval_type_id', store=True, readonly=True)
    approval_rule_id = fields.Many2one('eproc.approval.rule', string='Approval Rule',
                                       related='request_id.approval_rule_id', store=True, readonly=True)
    approval_rule_sequence = fields.Integer(string='Approval Rule Sequence',
                                            related='request_id.approval_rule_sequence', store=True, readonly=True)
    approval_next_stored = fields.Char(string='Approval Next Stored', related='request_id.approval_next_stored',
                                       store=True, readonly=True)
    user_id = fields.Many2one('res.users', string='Responsible', related='request_id.user_id', store=True,
                              readonly=True)
    department_id = fields.Many2one('hr.department', string='Department', related='request_id.department_id',
                                    store=True, readonly=True)
    state_parent = fields.Selection(related='request_id.state', string='State Parent', store=True, readonly=True)
    usage_in_7 = fields.Float(string='Usage in Last 7 Day(s)', related='orderpoint_log_id.usage_in_7', readonly=True)
    usage_in_14 = fields.Float(string='Usage in Last 14 Day(s)', related='orderpoint_log_id.usage_in_14', readonly=True)
    usage_in_30 = fields.Float(string='Usage in Last 30 Day(s)', related='orderpoint_log_id.usage_in_30', readonly=True)
    usage_in_90 = fields.Float(string='Usage in Last 90 Day(s)', related='orderpoint_log_id.usage_in_90', readonly=True)
    move_type = fields.Selection(related='orderpoint_log_id.move_type', readonly=True)
    days_safety = fields.Float(string='Days Safety', related='orderpoint_log_id.days_safety', readonly=True)
    days_inventory = fields.Float(string='Days of Inventory', related='orderpoint_log_id.days_inventory', readonly=True)
    days_out = fields.Float(string='Days of Stock Out', related='orderpoint_log_id.days_out', readonly=True)
    days_average = fields.Float(string='Days Average', related='orderpoint_log_id.days_average', readonly=True)
    qty_on_hand = fields.Float(string='Qty On Hand', related='orderpoint_log_id.qty_on_hand', readonly=True)
    qty_max_day = fields.Float(string='Qty Max Day', related='orderpoint_log_id.qty_max_day', readonly=True)
    qty_min_order = fields.Float(string='Qty Min Order', related='orderpoint_log_id.qty_min_order', readonly=True)
    qty_average = fields.Float(string='Qty Average', related='orderpoint_log_id.qty_average', readonly=True)
    qty_safety = fields.Float(string='Qty Safety', related='orderpoint_log_id.qty_safety', readonly=True)
    qty_maximum = fields.Float(string='Qty Maximum', related='orderpoint_log_id.qty_maximum', readonly=True)
    qty_suggested = fields.Float(string='Qty Suggested', related='orderpoint_log_id.qty_suggested', readonly=True)
    state_aging = fields.Selection([
        ('need_approval', 'Stuck Approval (> 2 Days)'),
        ('need_realize', 'Need Realize to RFQ'),
        ('overdue_receipt', 'PO Delivery Overdue'),
    ], string='Aging Status', compute='_compute_state_aging', store=True)
    active = fields.Boolean(string='Active', default=True)
    state = fields.Selection([
        ('draft', 'Draft'),
        ('ready', 'Ready to Procure'),
        ('partial', 'Partial'),
        ('done', 'Completed'),
        ('closed', 'Closed'),
        ('cancelled', 'Cancelled'),
        ('expired', 'Expired'),
    ], string='State', default='draft', readonly=True)

    @api.depends('order_line_ids.state', 'order_line_ids.active')
    def _compute_order_line_valid_ids(self):
        for record in self:
            record.order_line_valid_ids = record.order_line_ids.filtered(
                lambda line: line.active and line.state not in ('draft', 'cancelled', 'expired')
            )

    def _get_realized_order_lines(self):
        self.ensure_one()
        return self.order_line_ids.filtered(
            lambda line: line.active
            and line.order_id.state in self._processed_order_states
            and line.state in self._processed_order_line_states
        )

    def _get_pack_qty_processed(self):
        self.ensure_one()
        return sum(line.pack_qty - line.pack_qty_rebalanced for line in self._get_realized_order_lines())

    @api.depends('order_line_ids.pack_qty', 'order_line_ids.pack_qty_rebalanced',
                 'order_line_ids.uom_qty_rebalanced', 'order_line_ids.state', 'order_line_ids.pack_rate',
                 'order_line_ids.uom_id', 'order_line_ids.pack_id.rate_value', 'order_line_ids.order_id.state',
                 'order_line_ids.active', 'order_line_ids.request_line_id', 'pack_rate', 'pack_id.rate_value', 'uom_id')
    def _compute_pack_qty_processed(self):
        for record in self:
            record.pack_qty_processed = record._get_pack_qty_processed()

    @api.depends('pack_qty', 'pack_qty_processed')
    def _compute_pack_qty_remaining(self):
        for record in self:
            record.pack_qty_remaining = (record.pack_qty or 0.0) - (record.pack_qty_processed or 0.0)

    @api.depends('order_line_ids.uom_qty', 'order_line_ids.uom_qty_rebalanced', 'order_line_ids.state',
                 'order_line_ids.order_id.state', 'order_line_ids.active', 'order_line_ids.request_line_id')
    def _compute_uom_qty_processed(self):
        for record in self:
            record.uom_qty_processed = sum(
                line.uom_qty - line.uom_qty_rebalanced for line in record._get_realized_order_lines()
            )

    @api.depends('pack_qty', 'pack_qty_processed', 'uom_qty', 'uom_qty_processed')
    def _compute_pending_qty(self):
        for record in self:
            record.pack_qty_available = (record.pack_qty or 0.0) - (record.pack_qty_processed or 0.0)
            record.uom_qty_available = (record.uom_qty or 0.0) - (record.uom_qty_processed or 0.0)

    @api.depends('state', 'state_parent', 'order_line_ids', 'receipt_line_ids', 'write_date', 'request_valid_date')
    def _compute_state_aging(self):
        today = fields.Datetime.now()
        for record in self:
            aging_val = False
            if record.state == 'draft' and record.state_parent in ['draft', 'approval',
                                                                   'rejected'] and record.write_date:
                diff = today - record.write_date
                if diff.days >= 2:
                    aging_val = 'need_approval'
            if record.state == 'ready' and not aging_val:
                aging_val = 'need_realize'
            if record.state == 'partial' and record.write_date and (today - record.write_date).days > 5:
                aging_val = 'overdue_receipt'
            record.state_aging = aging_val

    @api.depends('pack_id.rate_value', 'pack_qty', 'pack_price')
    def _compute_pack_amounts(self):
        for record in self:
            rate = record.pack_id.rate_value or 1.0
            record.pack_rate = rate
            record.uom_qty = (record.pack_qty or 0.0) * rate
            record.uom_price = (record.pack_price or 0.0) / rate if rate else 0.0
            record.total_price = (record.pack_price or 0.0) * (record.pack_qty or 0.0)

    def _first_product_pack(self, product):
        if not product:
            return self.env['eproc.pack']
        return product.eproc_pack_ids.filtered(lambda pack: pack.enable)[:1]

    def _product_description(self, product):
        return getattr(product, 'description_purchase', False) or getattr(product, 'description', False) or product.name

    def _sync_product_values(self):
        for record in self:
            product = record.product_tmpl_id
            if not product:
                continue
            if not record.name:
                record.name = record._product_description(product)
            if not record.uom_id:
                record.uom_id = product.uom_id
            if not record.pack_id:
                record.pack_id = record._first_product_pack(product)
            if record.request_id and record.request_id.company_id:
                orderpoint = self.env['eproc.orderpoint'].sudo().search([
                    ('product_tmpl_id', '=', product.id),
                    ('company_id', '=', record.request_id.company_id.id),
                ], limit=1)
                if orderpoint:
                    record.uom_qty_min = orderpoint.qty_safety
                    record.uom_qty_max = orderpoint.qty_maximum
                quants = self.env['eproc.stock.quant'].sudo().search([
                    ('product_tmpl_id', '=', product.id),
                    ('company_id', '=', record.request_id.company_id.id),
                ])
                record.uom_qty_on_hand = sum(quants.mapped('quantity'))

    @api.onchange('product_tmpl_id')
    def _onchange_product_tmpl_id(self):
        self._sync_product_values()
        self._compute_pack_amounts()
        if self.product_tmpl_id:
            packs = self.product_tmpl_id.eproc_pack_ids
            return {'domain': {'pack_id': [('id', 'in', packs.ids)]}}
        return {'domain': {'pack_id': [('id', 'in', [])]}}

    @api.onchange('pack_id', 'pack_qty', 'pack_price')
    def _onchange_pack_amounts(self):
        self._compute_pack_amounts()

    @api.model_create_multi
    def create(self, vals_list):
        self.env['eproc.budget.item'].browse([vals['budget_item_id'] for vals in vals_list if vals.get('budget_item_id')])._lock_tracking()
        next_sequence_by_request = {}
        fallback_sequence = 0
        for vals in vals_list:
            request_id = vals.get('request_id')
            if request_id and request_id not in next_sequence_by_request:
                last_line = self.search(
                    [('request_id', '=', request_id), ('active', '=', True)],
                    order='sequence desc, id desc',
                    limit=1,
                )
                next_sequence_by_request[request_id] = last_line.sequence or 0
            if vals.get('sequence'):
                if request_id:
                    next_sequence_by_request[request_id] = max(
                        next_sequence_by_request.get(request_id, 0),
                        vals['sequence'],
                    )
                continue
            if request_id:
                next_sequence_by_request[request_id] += 1
                vals['sequence'] = next_sequence_by_request[request_id]
            else:
                fallback_sequence += 1
                vals['sequence'] = fallback_sequence
        records = super(EprocRequestLine, self).create(vals_list)
        records.filtered('budget_item_id')._check_budget_tracking(require_validated=True)
        records._sync_product_values()
        records._compute_pack_amounts()
        records.mapped('budget_item_id')._check_commitment_ceiling()
        return records

    def write(self, vals):
        budgets = self.mapped('budget_item_id')
        if vals.get('budget_item_id'):
            budgets |= self.env['eproc.budget.item'].browse(vals['budget_item_id'])
        budgets._lock_tracking()
        if {'budget_item_id', 'request_id', 'product_tmpl_id'} & set(vals):
            for line in self:
                changed = any(key in vals and (vals[key] or False) != line[key].id
                              for key in ('budget_item_id', 'request_id', 'product_tmpl_id'))
                if changed and (line.budget_item_id or vals.get('budget_item_id')):
                    if line.with_context(active_test=False).order_line_ids or line.request_id.state not in ('draft', 'rejected'):
                        raise AccessError(_('Budget links can only change on editable PR items without RFQs.'))
            if vals.get('budget_item_id'):
                budget = self.env['eproc.budget.item'].browse(vals['budget_item_id'])
                if budget.state != 'validate' or not budget.active:
                    raise ValidationError(_('Select an active, validated Budget Item.'))
        res = super(EprocRequestLine, self).write(vals)
        if 'product_tmpl_id' in vals:
            self._sync_product_values()
        if {'pack_id', 'pack_qty', 'pack_price'} & set(vals):
            self._compute_pack_amounts()
        if not self.env.context.get('skip_request_line_lock') and {'pack_qty', 'active'} & set(vals):
            self.mapped('request_id')._sync_realization_state_from_lines()
        if {'pack_id', 'pack_qty', 'pack_price', 'uom_id', 'budget_item_id', 'request_id', 'active', 'state'} & set(vals):
            (budgets | self.mapped('budget_item_id'))._check_commitment_ceiling()
        return res

    def unlink(self):
        self.write({'active': False})
        return True

    def copy(self, default=None):
        raise UserError(_('Purchase Request lines cannot be duplicated.'))

    @api.constrains('request_id', 'sequence', 'active')
    def _check_unique_sequence_per_request(self):
        for line in self.filtered(lambda rec: rec.active and rec.request_id and rec.sequence):
            duplicate = self.search([
                ('id', '!=', line.id),
                ('request_id', '=', line.request_id.id),
                ('sequence', '=', line.sequence),
                ('active', '=', True),
            ], limit=1)
            if duplicate:
                raise ValidationError(_('Sno must be unique per Purchase Request.'))


class EprocOrderLine(models.Model):
        _name = 'eproc.order.line'
        _description = 'E-Proc Order Line'
        _rec_name = 'product_tmpl_id'
        _order = 'order_id, sequence, id'
        _inherit = ['mail.thread', 'mail.activity.mixin']
        budget_item_id = fields.Many2one(related='request_line_id.budget_item_id', string='Budget Item',
            store=True, readonly=True, index=True, copy=False)

        def _budget_source_values(self, vals):
            vals = dict(vals)
            if 'budget_item_id' in vals:
                for line in self or self.new({}):
                    source = self.env['eproc.request.line'].browse(vals['request_line_id']) if vals.get('request_line_id') else (
                        self.env['eproc.request.line'] if 'request_line_id' in vals else line.request_line_id)
                    if (vals['budget_item_id'] or False) != source.budget_item_id.id:
                        raise AccessError(_('PO Budget Item is inherited from its PR and cannot be changed.'))
                vals.pop('budget_item_id')
            return vals

        @api.constrains('request_line_id', 'company_id', 'product_tmpl_id', 'budget_item_id', 'order_id', 'active')
        def _check_budget_source(self):
            for line in self.filtered('active'):
                if (line.product_tmpl_id and line.product_tmpl_id._requires_medical_equipment_budget()
                        and not line.budget_item_id
                        and line.order_id.state in ('approval', 'purchase', 'partial', 'done', 'expired')):
                    raise ValidationError(_('CapEx Medical Equipment PO items require a Budget Item inherited from their PR.'))
            for line in self.filtered('budget_item_id'):
                if line.company_id != line.budget_item_id.company_id:
                    raise ValidationError(_('Budget-linked PO items must match the source PR company.'))

        order_id = fields.Many2one('eproc.order', string='Order', ondelete='cascade', required=True, readonly=True)
        order_no = fields.Char(related='order_id.order_no', string='Order No', store=True, readonly=True)
        order_purchase_no = fields.Char(related='order_id.order_purchase_no', string='Purchase No', store=True, readonly=True)
        order_type = fields.Selection(related='order_id.order_type', string='Order Type', store=True, readonly=True)
        order_date = fields.Datetime(related='order_id.order_date', string='Order Date', store=True, readonly=True)
        order_valid_date = fields.Datetime(related='order_id.order_valid_date', string='Order Valid Date', store=True, readonly=True)
        order_origin = fields.Char(related='order_id.order_origin', string='Order Origin', store=True, readonly=True)
        purchase_type_id = fields.Many2one('eproc.type', related='order_id.purchase_type_id', string='Procurement Type', store=True, readonly=True)
        supplier_id = fields.Many2one('res.partner', related='order_id.supplier_id', string='Supplier', store=True, readonly=True)
        user_id = fields.Many2one('res.users', related='order_id.user_id', string='Responsible', store=True, readonly=True)
        department_id = fields.Many2one('hr.department', related='order_id.department_id', string='Department', store=True, readonly=True)
        company_id = fields.Many2one('res.company', related='order_id.company_id', store=True, readonly=True)
        sequence = fields.Integer(string='Sno', default=0)
        product_tmpl_id = fields.Many2one('product.template', string='Product', required=True, tracking=True)
        allowed_product_tmpl_ids = fields.Many2many('product.template', compute='_compute_allowed_product_tmpl_ids')
        product_categ_id = fields.Many2one('product.category', string='Category', readonly=True)
        date_planned = fields.Datetime(string='Planned Date')
        name = fields.Char(string='Description', tracking=True)
        uom_qty_on_hand = fields.Float(string='UoM Qty On Hand', readonly=True)
        uom_qty_min = fields.Float(string='UoM Qty Min', readonly=True)
        uom_qty_max = fields.Float(string='UoM Qty Max', readonly=True)
        uom_qty_suggested = fields.Float(string='UoM Qty Suggested', readonly=True)
        pack_id = fields.Many2one('eproc.pack', string='Pack Type', required=True, tracking=True)
        pack_qty = fields.Float(string='Pack Qty', default=1.0, required=True, tracking=True)
        pack_qty_processed = fields.Float(string='Pack Qty Processed', readonly=True)
        pack_price = fields.Float(string='Pack Price', required=True, tracking=True)
        pack_rate = fields.Float(string='Pack Rate', readonly=True, tracking=True)
        uom_id = fields.Many2one('uom.uom', string='UoM', readonly=True)
        uom_qty = fields.Float(string='UoM Qty', readonly=True)
        uom_qty_processed = fields.Float(string='UoM Qty Processed', readonly=True)
        uom_price = fields.Float(string='UoM Price')
        disc_rate = fields.Float(string='Disc. Rate', tracking=True)
        tax_ids = fields.Many2many('eproc.taxes', 'eproc_order_line_tax_rel', 'order_line_id', 'tax_id', string='Taxes')
        total_price = fields.Float(string='Total Price', tracking=True)
        total_discount = fields.Float(string='Total Discount', tracking=True)
        total_taxes = fields.Float(string='Total Taxes', tracking=True)
        total_netprice = fields.Float(string='Total NetPrice', tracking=True)
        analytic_id = fields.Many2one('account.analytic.account', string='Analytic Account', tracking=True)
        agreement_line_id = fields.Many2one('eproc.agreement.line', string='Agreement Item')
        orderpoint_log_id = fields.Many2one('eproc.orderpoint.log', string='Suggestion Log')
        request_line_id = fields.Many2one('eproc.request.line', string='Request Item')
        receipt_line_ids = fields.One2many('eproc.receipt.line', 'order_line_id', string='Receiving Lines')
        active = fields.Boolean(string='Active', default=True)
        state = fields.Selection([
            ('draft', 'Draft'),
            ('ready', 'Ready to Receipt'),
            ('partial', 'Partial'),
            ('done', 'Completed'),
            ('closed', 'Closed'),
            ('cancelled', 'Cancelled'),
            ('expired', 'Expired'),
        ], string='State', default='draft', readonly=True, tracking=True)
        def name_get(self):
            if self.env.context.get('tracking_po_number'):
                return [(line.id, line.order_purchase_no or line.order_no or _('Draft')) for line in self]
            return super().name_get()

        state_parent = fields.Selection(related='order_id.state', string='State Parent', store=True, readonly=True)
        state_aging = fields.Selection([
            ('draft', 'Draft'),
            ('need_approval', 'Stuck Approval (> 2 Days)'),
            ('ready', 'Ready'),
            ('normal', 'Normal'),
            ('warning', 'Due Soon'),
            ('overdue', 'Overdue Delivery'),
            ('stuck_po', 'Stuck PO'),
            ('partial', 'Partial'),
            ('done', 'Done'),
            ('closed', 'Closed'),
            ('cancelled', 'Cancelled'),
            ('expired', 'Expired'),
        ], string='Aging Status', compute='_compute_state_aging', store=True, tracking=True)

        pack_qty_rebalanced = fields.Float(string='Pack Qty Rebalanced', default=0, readonly=True, copy=False, tracking=True)
        uom_qty_rebalanced = fields.Float(string='UoM Qty Rebalanced', default=0, readonly=True, copy=False, tracking=True)
        pack_qty_available = fields.Float(string='Pack Qty Pending', compute='_compute_pending_qty', store=True)
        uom_qty_available = fields.Float(string='UoM Qty Pending', compute='_compute_pending_qty', store=True)
        request_no = fields.Char(related='request_line_id.request_id.request_no', string='Source PR', readonly=True)

        @api.depends('pack_qty', 'pack_qty_processed', 'pack_qty_rebalanced',
                     'uom_qty', 'uom_qty_processed', 'uom_qty_rebalanced')
        def _compute_pending_qty(self):
            for line in self:
                # Preserve material negatives so corrupted/over-processed balances are visible.
                line.pack_qty_available = line.pack_qty - line.pack_qty_processed - line.pack_qty_rebalanced
                line.uom_qty_available = line.uom_qty - line.uom_qty_processed - line.uom_qty_rebalanced

        def _lifecycle_rate(self):
            self.ensure_one()
            rate = self.pack_rate or self.pack_id.rate_value or 1.0
            if rate <= 0:
                raise ValidationError(_('Pack conversion must be positive.'))
            return rate

        def _check_lifecycle_quantities(self):
            for line in self:
                rate = line._lifecycle_rate()
                rounding = line.uom_id.rounding or 0.01
                for pack, uom in ((line.pack_qty, line.uom_qty),
                                  (line.pack_qty_processed, line.uom_qty_processed),
                                  (line.pack_qty_rebalanced, line.uom_qty_rebalanced)):
                    if float_compare(pack, 0, precision_digits=PACK_DIGITS) < 0 or float_compare(
                            uom, 0, precision_rounding=rounding) < 0:
                        raise ValidationError(_('PO quantities cannot be negative.'))
                    if not float_is_zero(pack * rate - uom, precision_rounding=rounding):
                        raise ValidationError(_('Pack and UoM quantities are inconsistent on %s.') % line.display_name)
                if float_compare(line.pack_qty_available, 0, precision_digits=PACK_DIGITS) < 0 or float_compare(
                        line.uom_qty_available, 0, precision_rounding=rounding) < 0:
                    raise ValidationError(_('Processed and rebalanced quantities exceed the PO quantity.'))

        def _check_rebalance_eligible(self):
            for line in self:
                line._check_lifecycle_quantities()
                if (not line.active or not line.request_line_id
                        or line.order_id.state not in REBALANCE_STATES
                        or line.state not in ('ready', 'partial', 'expired', 'closed')):
                    raise UserError(_('The selected PO item is not eligible for PR rebalance.'))
                if line.request_line_id.company_id != line.company_id:
                    raise ValidationError(_('The source PR and PO must belong to the same company.'))
                if line.pack_qty_rebalanced or line.uom_qty_rebalanced:
                    raise UserError(_('This PO item has already been rebalanced.'))
                if (float_compare(line.pack_qty_available, 0, precision_digits=PACK_DIGITS) <= 0
                        or float_compare(line.uom_qty_available, 0,
                                         precision_rounding=line.uom_id.rounding or 0.01) <= 0):
                    raise UserError(_('The selected PO item has no pending quantity.'))

        def _rebalance_pending(self, notes=False):
            """Private: caller holds the common PO locks; direct RPC writes are forbidden."""
            self.ensure_one()
            self._check_rebalance_eligible()
            pack_qty, uom_qty = self.pack_qty_available, self.uom_qty_available
            values = {
                'pack_qty_rebalanced': pack_qty, 'uom_qty_rebalanced': uom_qty,
                'state': 'expired' if self.state == 'expired' else 'closed',
            }
            self.with_context(skip_order_line_lock=True)._write_order_line(values)
            self.request_line_id.request_id._sync_realization_state_from_lines()
            self.env['eproc.order.rebalance.log']._record_rebalance(self, pack_qty, uom_qty, notes)
            self.message_post(body=_('PR rebalance: %s pack / %s UoM returned to %s.') % (
                pack_qty, uom_qty, self.request_line_id.request_id.display_name))

        def _check_receiving_eligible(self, receipt_type):
            for line in self:
                if line.order_id.state == 'expired' or line.state == 'expired':
                    raise UserError(_('Expired POs/items cannot be received or returned.'))
                line._check_lifecycle_quantities()
                if receipt_type != 'RT' and (
                        line.order_id.state not in ('purchase', 'partial')
                        or line.state not in ('ready', 'partial') or not line.active
                        or line.pack_qty_rebalanced or line.uom_qty_rebalanced):
                    raise UserError(_('New receipts require an open PO item that has not been closed or rebalanced.'))

        def _get_qty_multiple_mismatch(self):
            self.ensure_one()
            product = self.product_tmpl_id
            pack = self.pack_id
            qty_multiple = product.qty_multiple if product else 0.0
            if not product or not pack or qty_multiple <= 0.0:
                return False

            rate_value = pack.rate_value or 0.0
            smallest_qty = (self.pack_qty or 0.0) * rate_value
            quotient = smallest_qty / qty_multiple
            nearest_multiple = round(quotient) * qty_multiple
            if float_is_zero(smallest_qty - nearest_multiple, precision_digits=6):
                return False

            base_uom = self.uom_id or product.uom_id
            pack_uom = pack.uom_id
            return {
                'line_id': self.id,
                'product': product.display_name,
                'pack_qty': self.pack_qty or 0.0,
                'pack_type': pack_uom.display_name or pack.display_name,
                'pack_uom': pack_uom.display_name or _('Pack'),
                'rate_value': rate_value,
                'smallest_qty': smallest_qty,
                'qty_multiple': qty_multiple,
                'base_uom': base_uom.display_name if base_uom else '',
            }

        @api.depends('state', 'order_id.state', 'date_planned', 'order_id.order_date', 'pack_qty_processed', 'pack_qty')
        def _compute_state_aging(self):
            now = fields.Datetime.now()
            for record in self:
                if record.state in ('done', 'closed', 'cancelled', 'partial'):
                    record.state_aging = record.state
                    continue
                if record.state == 'draft':
                    order_date = record.order_id.order_date
                    if record.order_id.state in ('draft', 'approval', 'rejected') and order_date and (now - order_date).days > 2:
                        record.state_aging = 'need_approval'
                    else:
                        record.state_aging = 'draft'
                    continue
                if record.state == 'ready':
                    if record.date_planned:
                        planned = record.date_planned
                        if now > planned + timedelta(days=30) and record.order_id.state != 'done':
                            record.state_aging = 'stuck_po'
                        elif now > planned and not record.pack_qty_processed:
                            record.state_aging = 'overdue'
                        elif now >= planned - timedelta(days=5):
                            record.state_aging = 'warning'
                        else:
                            record.state_aging = 'normal'
                    else:
                        record.state_aging = 'ready'
                    continue
                record.state_aging = record.state or 'draft'

        @api.depends('supplier_id', 'supplier_id.eproc_item_ids')
        def _compute_allowed_product_tmpl_ids(self):
            for record in self:
                record.allowed_product_tmpl_ids = record.supplier_id.eproc_item_ids if record.supplier_id else self.env['product.template']

        def _clean_line_description(self, value):
            if not value:
                return value
            return tools.html2plaintext(value).strip()

        def _product_description(self, product):
            return self._clean_line_description(getattr(product, 'description_purchase', False) or getattr(product, 'description', False) or product.name)

        def _select_product_pack(self, product):
            if not product:
                return self.env['eproc.pack']
            enabled_packs = product.eproc_pack_ids.filtered(lambda pack: pack.enable)
            default_pack = enabled_packs.filtered(lambda pack: pack.is_default).sorted(lambda pack: (pack.sequence or 0, pack.id))[:1]
            if default_pack:
                return default_pack
            return enabled_packs.sorted(lambda pack: (pack.sequence or 0, pack.id))[:1]

        def _get_agreement_line(self):
            self.ensure_one()
            order = self.order_id
            if (
                    not order
                    or not order._is_stock_order()
                    or not order.agreement_id
                    or not self.product_tmpl_id
                    or not self.pack_id
                    or not self.pack_qty
            ):
                return self.env['eproc.agreement.line']
            domain = [
                ('agreement_id', '=', order.agreement_id.id),
                ('product_tmpl_id', '=', self.product_tmpl_id.id),
                ('pack_id', '=', self.pack_id.id),
                ('pack_min', '<=', self.pack_qty),
                ('pack_max', '>=', self.pack_qty),
            ]
            agreement_line_model = self.env['eproc.agreement.line']
            order_by = 'pack_min desc, id desc'
            if (
                    order.state != 'tender'
                    and order.agreement_id.type == 'rate'
                    and 'effective_date' in agreement_line_model._fields
            ):
                order_date = order._get_agreement_order_date()
                if not order_date:
                    return agreement_line_model
                domain.append(('effective_date', '<=', order_date))
                order_by = 'effective_date desc, pack_min desc, id desc'
            return agreement_line_model.search(domain, order=order_by, limit=1)

        def _apply_agreement_pricing(self, show_warning=False, write_existing=True):
            warning = False
            for record in self:
                order = record.order_id
                if order and not order._is_stock_order():
                    record._onchange_pack_price()
                    continue
                if order and not order._is_editable_for_agreement_pricing():
                    continue
                has_line_data = bool(order and record.product_tmpl_id and record.pack_id and record.pack_qty)
                strict_rate_pricing = bool(
                    order
                    and order.state != 'tender'
                    and (not order.agreement_id or order.agreement_id.type == 'rate')
                )
                agreement_line = record._get_agreement_line()
                if not agreement_line:
                    if has_line_data and strict_rate_pricing:
                        values = {
                            'agreement_line_id': False,
                            'pack_price': 0.0,
                            'disc_rate': 0.0,
                            'tax_ids': [(5, 0, 0)],
                        }
                        if record.id and write_existing:
                            record.with_context(skip_agreement_pricing=True).write(values)
                        else:
                            record.agreement_line_id = False
                            record.pack_price = 0.0
                            record.disc_rate = 0.0
                            record.tax_ids = values['tax_ids']
                            record._onchange_pack_price()
                        warning = {
                            'title': _('Agreement Pricing'),
                            'message': _(
                                'No valid agreement price was found for this product, pack type, quantity, and order date.'
                            ),
                        }
                    else:
                        record._onchange_pack_price()
                        if has_line_data and order.agreement_id:
                            warning = {
                                'title': _('Agreement Pricing'),
                                'message': _(
                                    'No matching agreement line found for this product, pack type, and quantity range.'
                                ),
                            }
                    continue
                values = {
                    'agreement_line_id': agreement_line.id,
                    'pack_price': agreement_line.pack_price or 0.0,
                    'disc_rate': agreement_line.disc_rate or 0.0,
                    'tax_ids': [(6, 0, agreement_line.tax_ids.ids)],
                }
                if record.id and write_existing:
                    record.with_context(skip_agreement_pricing=True).write(values)
                else:
                    record.agreement_line_id = values['agreement_line_id']
                    record.pack_price = values['pack_price']
                    record.disc_rate = values['disc_rate']
                    record.tax_ids = values['tax_ids']
                    record._onchange_pack_price()
            return warning if show_warning and warning else False

        @api.onchange('product_tmpl_id')
        def _onchange_product_tmpl_id(self):
            warning = False
            for record in self:
                product = record.product_tmpl_id
                if not product:
                    continue
                record.name = record._product_description(product)
                record.product_categ_id = getattr(product, 'item_category_id', False).id or product.categ_id.id
                record.uom_id = product.uom_id.id
                if not record.pack_id or record.pack_id not in product.eproc_pack_ids:
                    pack = record._select_product_pack(product)
                    if pack:
                        record.pack_id = pack.id
                        record.pack_rate = pack.rate_value or 1.0
                if not record.pack_qty:
                    record.pack_qty = 1.0
                if record.order_id.order_type != 'auto' and record.order_id.company_id:
                    company_id = record.order_id.company_id.id
                    quants = self.env['eproc.stock.quant'].sudo().search([('product_tmpl_id', '=', product.id)])
                    record.uom_qty_on_hand = sum(quants.mapped('quantity'))
                    orderpoint = self.env['eproc.orderpoint'].sudo().search([('product_tmpl_id', '=', product.id), ('company_id', '=', company_id)], limit=1)
                    record.uom_qty_min = orderpoint.qty_safety if orderpoint else 0.0
                    record.uom_qty_max = orderpoint.qty_maximum if orderpoint else 0.0
                    record.uom_qty_suggested = max((record.uom_qty_max or 0.0) - (record.uom_qty_on_hand or 0.0), 0.0) if orderpoint else 0.0
                result = record._onchange_pack_and_qty()
                if result and result.get('warning'):
                    warning = result['warning']
            result = {'domain': {'product_tmpl_id': [('id', 'in', self.allowed_product_tmpl_ids.ids)]}}
            if warning:
                result['warning'] = warning
            return result

        @api.onchange('pack_id', 'pack_qty')
        def _onchange_pack_and_qty(self):
            warning = False
            for record in self:
                if record.pack_id:
                    record.pack_rate = record.pack_id.rate_value or 1.0
                record.uom_qty = (record.pack_qty or 0.0) * (record.pack_rate or 0.0)
                record.uom_id = record.product_tmpl_id.uom_id.id if record.product_tmpl_id else record.uom_id
                result = record._apply_agreement_pricing(show_warning=True, write_existing=False)
                if result:
                    warning = result
            if warning:
                return {'warning': warning}
            return {}

        @api.onchange('pack_rate', 'pack_qty', 'pack_price', 'disc_rate', 'tax_ids')
        def _onchange_pack_price(self):
            for record in self:
                if record.product_tmpl_id:
                    amount = record.product_tmpl_id._eproc_amount_lookup(record.pack_price or 0.0, record.pack_qty or 0.0, record.disc_rate or 0.0, record.tax_ids)
                else:
                    gross = (record.pack_price or 0.0) * (record.pack_qty or 0.0)
                    discount = gross * ((record.disc_rate or 0.0) / 100.0)
                    tax = (gross - discount) * sum(record.tax_ids.mapped('rate')) / 100.0
                    amount = {'total_price': gross, 'total_discount': discount, 'total_taxes': tax, 'total_netprice': gross - discount + tax}
                record.total_price = amount.get('total_price', 0.0)
                record.total_discount = amount.get('total_discount', 0.0)
                record.total_taxes = amount.get('total_taxes', 0.0)
                record.total_netprice = amount.get('total_netprice', 0.0)
                record.uom_price = (record.pack_price or 0.0) / (record.pack_rate or 1.0) if record.pack_rate else 0.0

        @api.model_create_multi
        def create(self, vals_list):
            vals_list = [self._budget_source_values(vals) for vals in vals_list]
            if any(vals.get('pack_qty_rebalanced') or vals.get('uom_qty_rebalanced') for vals in vals_list):
                raise AccessError(_('Rebalanced quantities can only be set by PR Item Rebalance.'))
            # Explicit zeroes take precedence over context and ir.default values.
            # Copy each dict: batch create must not modify its caller's input.
            vals_list = [dict(vals, pack_qty_rebalanced=0.0, uom_qty_rebalanced=0.0) for vals in vals_list]
            next_sequence_by_order = {}
            for vals in vals_list:
                order = self.env['eproc.order'].browse(vals.get('order_id')) if vals.get('order_id') else self.env['eproc.order']
                if order and (vals.get('sequence') or 0) <= 0:
                    if order.id not in next_sequence_by_order:
                        last_line = self.search([('order_id', '=', order.id)], order='sequence desc, id desc', limit=1)
                        next_sequence_by_order[order.id] = last_line.sequence or 0
                    next_sequence_by_order[order.id] += 1
                    vals['sequence'] = next_sequence_by_order[order.id]
                product = self.env['product.template'].browse(vals.get('product_tmpl_id')) if vals.get('product_tmpl_id') else self.env['product.template']
                if product:
                    vals.setdefault('name', self._product_description(product))
                    vals.setdefault('product_categ_id', getattr(product, 'item_category_id', False).id or product.categ_id.id)
                    vals.setdefault('uom_id', product.uom_id.id)
                    if not vals.get('pack_id'):
                        pack = self._select_product_pack(product)
                        if pack:
                            vals['pack_id'] = pack.id
                            vals.setdefault('pack_rate', pack.rate_value or 1.0)
                if vals.get('name'):
                    vals['name'] = self._clean_line_description(vals['name'])
                vals.setdefault('pack_qty', 1.0)
                if vals.get('pack_id') and not vals.get('pack_rate'):
                    vals['pack_rate'] = self.env['eproc.pack'].browse(vals['pack_id']).rate_value or 1.0
                if vals.get('pack_qty') is not None and vals.get('pack_rate') is not None and not vals.get('uom_qty'):
                    vals['uom_qty'] = (vals.get('pack_qty') or 0.0) * (vals.get('pack_rate') or 0.0)
                if order and order.date_planned and not vals.get('date_planned'):
                    vals['date_planned'] = order.date_planned
            records = super(EprocOrderLine, self).create(vals_list)
            records._apply_agreement_pricing()
            records.mapped('request_line_id.request_id')._sync_realization_state_from_lines()
            records.mapped('order_id').filtered(
                lambda order: order.state in ('approval', 'purchase', 'partial', 'done', 'expired'))._check_budget_ceiling()
            return records

        def write(self, vals):
            if {'pack_qty_rebalanced', 'uom_qty_rebalanced'} & set(vals):
                raise AccessError(_('Rebalanced quantities can only be set by PR Item Rebalance.'))
            return self._write_order_line(vals)

        def _write_order_line(self, vals):
            if {'request_line_id', 'order_id'} & set(vals):
                for line in self:
                    if line.budget_item_id and any(key in vals and (vals[key] or False) != line[key].id
                            for key in ('request_line_id', 'order_id')) and (
                            line.receipt_line_ids or line.order_id.state not in ('draft', 'tender', 'rejected')):
                        raise AccessError(_('A committed budget-linked PO item cannot be moved to another PR or PO.'))
            budgets = self.mapped('budget_item_id')
            if vals.get('request_line_id'):
                budgets |= self.env['eproc.request.line'].browse(vals['request_line_id']).budget_item_id
            budgets._lock_tracking()
            vals = self._budget_source_values(vals)
            # Shared private write path preserves validated rebalance hooks.
            old_request_lines = self.mapped('request_line_id') if 'request_line_id' in vals else self.env['eproc.request.line']
            if vals.get('name'):
                vals['name'] = self._clean_line_description(vals['name'])
            if vals.get('product_tmpl_id'):
                product = self.env['product.template'].browse(vals['product_tmpl_id'])
                if product:
                    if 'name' not in vals:
                        vals['name'] = self._product_description(product)
                    vals.setdefault('product_categ_id', getattr(product, 'item_category_id', False).id or product.categ_id.id)
                    vals.setdefault('uom_id', product.uom_id.id)
                    if 'pack_id' not in vals:
                        pack = self._select_product_pack(product)
                        if pack:
                            vals['pack_id'] = pack.id
                            vals.setdefault('pack_rate', pack.rate_value or 1.0)
            if vals.get('pack_id') and 'pack_rate' not in vals:
                vals['pack_rate'] = self.env['eproc.pack'].browse(vals['pack_id']).rate_value or 1.0
            if any(key in vals for key in ('pack_qty', 'pack_rate')) and 'uom_qty' not in vals and len(self) == 1:
                pack_qty = vals.get('pack_qty', self.pack_qty)
                pack_rate = vals.get('pack_rate', self.pack_rate)
                vals['uom_qty'] = (pack_qty or 0.0) * (pack_rate or 0.0)
            locked = self.filtered(lambda line: line.order_id.state not in ('draft', 'tender', 'rejected'))
            protected = set(vals) - {'state', 'pack_qty_processed', 'uom_qty_processed', 'receipt_line_ids', 'active', 'message_follower_ids', 'message_ids', 'activity_ids'}
            if locked and protected and not self.env.context.get('skip_order_line_lock'):
                raise UserError(_('Order items can only be edited while RFQ is Draft, Tender, or Rejected.'))
            res = super(EprocOrderLine, self).write(vals)
            agreement_trigger_fields = {'order_id', 'product_tmpl_id', 'pack_id', 'pack_qty'}
            amount_trigger_fields = {'pack_qty', 'pack_price', 'pack_rate', 'disc_rate', 'tax_ids'}
            if agreement_trigger_fields & set(vals) and not self.env.context.get('skip_agreement_pricing'):
                self._apply_agreement_pricing()
            elif amount_trigger_fields & set(vals):
                for record in self:
                    record._onchange_pack_price()
            if vals.get('active') or {'pack_qty', 'pack_price', 'pack_rate', 'disc_rate', 'tax_ids', 'request_line_id', 'order_id', 'total_netprice'} & set(vals):
                self.filtered('budget_item_id').mapped('order_id').filtered(
                    lambda order: order.state in ('approval', 'purchase', 'partial', 'done', 'expired'))._check_budget_ceiling()
            if 'state' in vals:
                self.mapped('order_id')._sync_state_from_lines()
            if {'pack_qty', 'state', 'active', 'request_line_id'} & set(vals):
                (old_request_lines | self.mapped('request_line_id')).mapped('request_id')._sync_realization_state_from_lines()
            if {'active', 'state', 'uom_id', 'uom_qty', 'uom_qty_rebalanced', 'total_netprice', 'request_line_id', 'order_id'} & set(vals):
                (budgets | self.mapped('budget_item_id'))._check_commitment_ceiling()
            return res

        @api.constrains('disc_rate')
        def _check_disc_rate_range(self):
            for line in self:
                if line.disc_rate < 0.0 or line.disc_rate > 100.0:
                    raise ValidationError(_('Discount rate must be between 0 and 100.'))

        @api.constrains('product_tmpl_id', 'supplier_id')
        def _check_supplier_product_mapping(self):
            for line in self:
                if line.product_tmpl_id and line.supplier_id and line.product_tmpl_id not in line.supplier_id.eproc_item_ids:
                    raise ValidationError(_('Product %s is not mapped to supplier %s.') % (line.product_tmpl_id.display_name, line.supplier_id.display_name))

        def unlink(self):
            self.mapped('budget_item_id')._lock_tracking()
            if self.filtered(lambda line: line.order_id.state not in ('draft', 'tender')):
                raise UserError(_('Order items can only be deleted while the parent PO is Draft or Tender.'))
            requests = self.mapped('request_line_id.request_id')
            res = super(EprocOrderLine, self).unlink()
            requests._sync_realization_state_from_lines()
            return res


class EprocOrderRebalanceWizard(models.TransientModel):
    _name = 'eproc.order.rebalance.wizard'
    _description = 'PR Item Rebalance'

    order_id = fields.Many2one('eproc.order', string='Purchase No', required=True, readonly=True)
    company_id = fields.Many2one(related='order_id.company_id', string='Company', readonly=True)
    user_id = fields.Many2one('res.users', string='Responsible', default=lambda self: self.env.user, readonly=True)
    notes = fields.Text(string='Notes')
    line_ids = fields.Many2many('eproc.order.line', string='PO Items')

    def action_rebalance(self):
        self.ensure_one()
        self.check_access_rights('write')
        self.check_access_rule('write')
        order = self.order_id.exists()
        if not order or not self.line_ids:
            raise UserError(_('Select a PO and at least one item.'))
        order._lock_lifecycle()
        if order.state not in REBALANCE_STATES:
            raise UserError(_('This PO cannot be rebalanced.'))
        lines = self.line_ids.exists()
        lines.check_access_rights('write')
        lines.check_access_rule('write')
        if any(line.order_id != order or line.company_id != order.company_id for line in lines):
            raise ValidationError(_('All selected items must belong to the selected PO and company.'))
        lines._check_rebalance_eligible()
        requests = lines.mapped('request_line_id.request_id')
        requests.check_access_rights('write')
        requests.check_access_rule('write')
        for line in lines.sorted('id'):
            line._rebalance_pending(self.notes)
        order._sync_state_from_lines()
        order.message_post(body=_('PR Item Rebalance completed by %s for %s item(s).') % (
            self.env.user.display_name, len(lines)))
        return {'type': 'ir.actions.act_window_close'}


class EprocOrderRebalanceLog(models.Model):
    _name = 'eproc.order.rebalance.log'
    _description = 'Permanent PR Item Rebalance History'
    _order = 'id desc'

    order_id = fields.Many2one('eproc.order', required=True, readonly=True, ondelete='restrict')
    line_id = fields.Many2one('eproc.order.line', string='PO Item', required=True, readonly=True, ondelete='restrict')
    request_line_id = fields.Many2one('eproc.request.line', string='PR Item', required=True, readonly=True, ondelete='restrict')
    company_id = fields.Many2one('res.company', required=True, readonly=True)
    pack_qty = fields.Float(string='Pack Qty Rebalanced', readonly=True)
    uom_qty = fields.Float(string='UoM Qty Rebalanced', readonly=True)
    user_id = fields.Many2one('res.users', string='Responsible', required=True, readonly=True)
    date = fields.Datetime(string='Rebalance Time', required=True, readonly=True)
    notes = fields.Text(readonly=True)

    _sql_constraints = [('line_unique', 'unique(line_id)', 'A PO item can only be rebalanced once.')]

    def _record_rebalance(self, line, pack_qty, uom_qty, notes):
        # Only the validated private action creates immutable history. Never trust wizard user_id.
        values = dict(order_id=line.order_id.id, line_id=line.id, request_line_id=line.request_line_id.id,
                      company_id=line.company_id.id, pack_qty=pack_qty, uom_qty=uom_qty,
                      user_id=self.env.uid, date=fields.Datetime.now(), notes=notes)
        return super(EprocOrderRebalanceLog, self.sudo()).create(values)

    @api.model_create_multi
    def create(self, vals_list):
        raise AccessError(_('Rebalance history is created only by PR Item Rebalance.'))

    def write(self, vals):
        raise AccessError(_('Rebalance history cannot be modified.'))

    def unlink(self):
        raise AccessError(_('Rebalance history cannot be deleted.'))


class EprocOrderChangeSupplierWizard(models.TransientModel):
    _name = 'eproc.order.change.supplier.wizard'
    _description = 'E-Proc Order Change Supplier Confirmation'

    order_id = fields.Many2one('eproc.order', string='Purchase Order', required=True, readonly=True)
    company_id = fields.Many2one('res.company', related='order_id.company_id', string='Company', readonly=True)
    purchase_type_id = fields.Many2one('eproc.type', related='order_id.purchase_type_id', string='Procurement Type',
                                       readonly=True)
    supplier_id = fields.Many2one(
        'res.partner',
        string='New Supplier',
        required=True,
        domain="[('is_eproc', '=', True), ('supplier', '=', True), ('eproc_type_id', '=', purchase_type_id), ('supplier_hospital_ids.company_id', '=', company_id)]",
    )

    def action_confirm(self):
        self.ensure_one()
        order = self.order_id
        if order.state not in ('draft', 'tender'):
            raise UserError(_('Supplier can only be changed with line reset while the PO is Draft or Tender.'))
        if self.supplier_id == order.supplier_id:
            return {'type': 'ir.actions.act_window_close'}
        mapping = self.supplier_id._get_eproc_company_mapping(order.company_id)
        if not mapping:
            raise UserError(
                _('Supplier %s is not mapped to company %s.')
                % (self.supplier_id.display_name, order.company_id.display_name)
            )
        order.line_ids.unlink()
        values = {
            'supplier_id': self.supplier_id.id,
            'term_id': getattr(self.supplier_id, 'eproc_term_id', False).id if getattr(self.supplier_id,
                                                                                       'eproc_term_id',
                                                                                       False) else False,
            'agreement_id': False,
            'lead_time': getattr(self.supplier_id, 'eproc_lead_time', 0) or 0,
        }
        values.update(order._prepare_supplier_defaults(self.supplier_id))
        order.with_context(confirm_supplier_change=True).write(values)
        agreement = order._lookup_default_agreement(self.supplier_id)
        if agreement:
            order.with_context(confirm_supplier_change=True).write({
                'agreement_id': agreement.id,
                'lead_time': agreement.lead_time or getattr(self.supplier_id, 'eproc_lead_time', 0) or 0,
            })
        order._update_date_planned()
        return {'type': 'ir.actions.act_window_close'}


class EprocOrderChangeAgreementWizard(models.TransientModel):
    _name = 'eproc.order.change.agreement.wizard'
    _description = 'E-Proc Order Change Agreement Confirmation'

    order_id = fields.Many2one('eproc.order', string='Purchase Order', required=True, readonly=True)
    company_id = fields.Many2one('res.company', related='order_id.company_id', string='Company', readonly=True)
    purchase_type_id = fields.Many2one('eproc.type', string='Procurement Type', readonly=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', readonly=True)
    current_agreement_id = fields.Many2one('eproc.agreement', string='Current Agreement', readonly=True)
    agreement_id = fields.Many2one(
        'eproc.agreement',
        string='New Agreement',
        required=True,
        domain="[('company_id', '=', company_id), ('purchase_type_id', '=', purchase_type_id), '|', '&', ('type', '=', 'rate'), '&', ('supplier_id', '=', supplier_id), ('state', '=', 'validated'), '&', ('type', '=', 'tender'), ('state', 'in', ['tender', 'validated'])]",
    )

    @api.onchange('order_id', 'agreement_id')
    def _onchange_agreement_id(self):
        for record in self:
            if record.order_id:
                return {'domain': {'agreement_id': record.order_id._get_eproc_order_domains()['agreement_id']}}

    def _validate_agreement(self):
        self.ensure_one()
        order = self.order_id
        agreement = self.agreement_id
        if agreement.type == 'rate' and agreement.supplier_id != order.supplier_id:
            raise UserError(_('Selected agreement must belong to the current supplier.'))
        validation_supplier = agreement.supplier_id if agreement.type == 'rate' else order.supplier_id
        validation_order = order.new({
            'company_id': order.company_id.id,
            'purchase_type_id': order.purchase_type_id.id,
            'supplier_id': validation_supplier.id,
            'agreement_id': agreement.id,
            'order_date': order.order_date,
            'stock_type': order.stock_type,
        })
        if not validation_order._is_valid_agreement_for_order():
            raise UserError(_('Selected agreement is not valid for this RFQ supplier, company, and procurement type.'))
        if not validation_supplier._get_eproc_company_mapping(order.company_id):
            raise UserError(
                _('Supplier %s is not mapped to company %s.')
                % (validation_supplier.display_name, order.company_id.display_name)
            )

    def action_confirm(self):
        self.ensure_one()
        order = self.order_id
        if order.state not in ('draft', 'tender'):
            raise UserError(_('Agreement can only be changed with line reset while the RFQ is Draft or Tender.'))
        if self.agreement_id == order.agreement_id:
            return {'type': 'ir.actions.act_window_close'}
        self._validate_agreement()
        order.line_ids.unlink()

        agreement = self.agreement_id
        supplier = agreement.supplier_id if agreement.type == 'rate' else order.supplier_id
        values = {
            'agreement_id': agreement.id,
            'supplier_id': supplier.id,
            'lead_time': agreement.lead_time or getattr(supplier, 'eproc_lead_time', 0) or 0,
        }
        if supplier:
            values['term_id'] = getattr(supplier, 'eproc_term_id', False).id if getattr(supplier, 'eproc_term_id',
                                                                                        False) else False
            values.update(order._prepare_supplier_defaults(supplier))

        order.with_context(confirm_agreement_change=True, skip_order_lock=True).write(values)
        order.with_context(skip_order_lock=True)._update_date_planned()
        return {'type': 'ir.actions.act_window_close'}


