class EprocReceiptPreviewWizard(models.TransientModel):
    _name = 'eproc.receipt.preview.wizard'
    _description = 'Receiving Validation Preview Wizard'

    receipt_id = fields.Many2one('eproc.receipt', required=True, readonly=True)
    report_code = fields.Selection([
        ('receiving_notes', 'Receiving Notes'),
        ('receiving_return', 'Vendor Return'),
    ], required=True, default='receiving_notes', readonly=True)
    title = fields.Char(compute='_compute_preview_fields')
    preview_url = fields.Char(compute='_compute_preview_fields')
    pdf_url = fields.Char(compute='_compute_preview_fields')
    docx_url = fields.Char(compute='_compute_preview_fields')
    xlsx_url = fields.Char(compute='_compute_preview_fields')
    preview_html = fields.Html(compute='_compute_preview_fields', sanitize=False)

    @api.depends('receipt_id', 'report_code')
    def _compute_preview_fields(self):
        for wizard in self:
            receipt = wizard.receipt_id
            if not receipt:
                wizard.title = ''
                wizard.preview_url = ''
                wizard.pdf_url = ''
                wizard.docx_url = ''
                wizard.xlsx_url = ''
                wizard.preview_html = ''
                continue

            is_return = wizard.report_code == 'receiving_return'
            title = receipt.receipt_valid_no or receipt.receipt_no or (
                'Vendor Return' if is_return else 'Receiving Validation'
            )
            route = 'print_return' if is_return else 'print_receiving_validation'
            base_url = '/eproc/receipt/%s?id=%s' % (route, receipt.id)

            wizard.title = title
            wizard.preview_url = base_url + '&format=pdf&inline=1'
            wizard.pdf_url = base_url + '&format=pdf'
            wizard.docx_url = base_url + '&format=docx'
            wizard.xlsx_url = base_url + '&format=xlsx'

            wizard.preview_html = """
                <div class="o_eproc_receipt_preview" style="width:100%%; min-width:1000px;">
                    <div style="display:flex; gap:8px; justify-content:space-between; align-items:center; margin-bottom:10px;">
                        <strong>%s</strong>
                        <div style="display:flex; gap:8px; align-items:center;">
                            <a class="btn btn-primary" href="%s" target="_blank">Download PDF</a>
                            <a class="btn btn-secondary" href="%s" target="_blank">Download Word</a>
                            <a class="btn btn-secondary" href="%s" target="_blank">Download Excel</a>
                        </div>
                    </div>
                    <iframe src="%s" style="width:100%%; height:75vh; border:1px solid #ddd; background:#fff;"></iframe>
                </div>
            """ % (
                py_html.escape(title),
                wizard.pdf_url,
                wizard.docx_url,
                wizard.xlsx_url,
                wizard.preview_url,
            )


class EprocOrderPreviewWizard(models.TransientModel):
    _name = 'eproc.order.preview.wizard'
    _description = 'RFQ / Purchase Order Preview Wizard'

    order_id = fields.Many2one('eproc.order', required=True, readonly=True)
    report_code = fields.Selection([
        ('rfq', 'Request for Quotation'),
        ('po', 'Purchase Order'),
    ], required=True, default='rfq', readonly=True)
    title = fields.Char(compute='_compute_preview_fields')
    preview_url = fields.Char(compute='_compute_preview_fields')
    pdf_url = fields.Char(compute='_compute_preview_fields')
    docx_url = fields.Char(compute='_compute_preview_fields')
    xlsx_url = fields.Char(compute='_compute_preview_fields')
    preview_html = fields.Html(compute='_compute_preview_fields', sanitize=False)

    @api.depends('order_id', 'report_code')
    def _compute_preview_fields(self):
        for wizard in self:
            order = wizard.order_id
            if not order:
                wizard.title = ''
                wizard.preview_url = ''
                wizard.pdf_url = ''
                wizard.docx_url = ''
                wizard.xlsx_url = ''
                wizard.preview_html = ''
                continue

            title = next((
                getattr(order, field_name, False)
                for field_name in ('order_valid_no', 'order_purchase_no', 'order_no', 'name')
                if getattr(order, field_name, False)
            ), 'RFQ / Purchase Order')
            base_url = '/eproc/order/print_rfq_po?id=%s&report=%s' % (
                order.id,
                wizard.report_code,
            )

            wizard.title = title
            wizard.preview_url = base_url + '&format=pdf&inline=1'
            wizard.pdf_url = base_url + '&format=pdf'
            wizard.docx_url = base_url + '&format=docx'
            wizard.xlsx_url = base_url + '&format=xlsx'
            wizard.preview_html = """
                <div class="o_eproc_order_preview" style="width:100%%; min-width:1000px;">
                    <div style="display:flex; gap:8px; justify-content:space-between; align-items:center; margin-bottom:10px;">
                        <strong>%s</strong>
                        <div style="display:flex; gap:8px; align-items:center;">
                            <a class="btn btn-primary" href="%s" target="_blank">Download PDF</a>
                            <a class="btn btn-secondary" href="%s" target="_blank">Download Word</a>
                            <a class="btn btn-secondary" href="%s" target="_blank">Download Excel</a>
                        </div>
                    </div>
                    <iframe src="%s" style="width:100%%; height:75vh; border:1px solid #ddd; background:#fff;"></iframe>
                </div>
            """ % (
                py_html.escape(title),
                wizard.pdf_url,
                wizard.docx_url,
                wizard.xlsx_url,
                wizard.preview_url,
            )


class EprocReceivingBayPreviewWizard(models.TransientModel):
    _name = 'eproc.receiving.bay.preview.wizard'
    _description = 'Receiving Bay Preview Wizard'

    receipt_id = fields.Many2one('eproc.receipt', required=True, readonly=True)
    title = fields.Char(compute='_compute_preview_fields')
    preview_url = fields.Char(compute='_compute_preview_fields')
    pdf_url = fields.Char(compute='_compute_preview_fields')
    docx_url = fields.Char(compute='_compute_preview_fields')
    xlsx_url = fields.Char(compute='_compute_preview_fields')
