    pack_min = fields.Float(string='Pack Min', readonly=True)
    pack_max = fields.Float(string='Pack Max', readonly=True)
    pack_on_hand = fields.Float(string='Pack on Hand', readonly=True)
    pack_order = fields.Float(string='Pack Order', required=True)
    pack_rate = fields.Float(string='Pack Rate', readonly=True)
    uom_id = fields.Many2one('uom.uom', string='UoM', readonly=True)
    uom_request = fields.Float(string='UoM Request', readonly=True)
    uom_available = fields.Float(string='UoM Available', readonly=True)
    uom_to_order = fields.Float(string='UoM to Order', readonly=True)
    uom_min = fields.Float(string='UoM Min', readonly=True)
    uom_max = fields.Float(string='UoM Max', readonly=True)
    uom_on_hand = fields.Float(string='UoM on Hand', readonly=True)
