class EprocStockLot(models.Model):
    _name = 'eproc.stock.lot'
    _description = 'Eproc Stock Lot / Batch'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'name'
    _order = 'id desc'
    _check_company_auto = True

    code = fields.Char(string='Code', required=True, readonly=True, copy=False,
                       default='/', index=True, tracking=True)
    name = fields.Char(string='Lot Name', required=True, readonly=True, tracking=True)
    receipt_line_id = fields.Many2one(
        'eproc.receipt.line', string='Receipt Line', readonly=True, copy=False,
        index=True, ondelete='restrict', check_company=True,
    )
    product_tmpl_id = fields.Many2one(
        'product.template', string='Product', required=True, readonly=True,
        index=True, check_company=True, tracking=True,
    )
    product_uom_id = fields.Many2one(
        'uom.uom', string='UoM', related='product_tmpl_id.uom_id', store=True,
        readonly=True,
    )
    expiration_date = fields.Datetime(
        string='Expiration Date', readonly=True, tracking=True,
    )
    removal_date = fields.Datetime(
        string='Removal Date', readonly=True, tracking=True,
    )
    landing_cost = fields.Float(string='Landing Cost', readonly=True, tracking=True)
    stock_on_hand = fields.Float(
        string='QOH', compute='_compute_stock_on_hand', readonly=True,
        digits='Product Unit of Measure',
    )
    company_id = fields.Many2one(
        'res.company', string='Company', required=True, readonly=True,
        default=lambda self: self.env.company, index=True, tracking=True,
    )
    active = fields.Boolean(string='Active', default=True, readonly=True)
    move_ids = fields.One2many('eproc.stock.move', 'lot_id', string='Movement(s)', readonly=True)
    sync_type = sync.type
    sync_id_api = sync.id_api
    order_line_id = fields.Many2one(
        'eproc.order.line',
        string='Purchase Item',
        readonly=True,
        copy=False,
        index=True,
    )

    _sql_constraints = [
        (
            'eproc_stock_lot_code_uniq',
            'unique(code)',
            'Stock lot code must be unique.',
        ),
        (
            'uniq_lot_per_product',
            'unique(product_tmpl_id, company_id, name)',
            'Lot/Batch number must be unique per product and company.',
        ),
    ]

    def name_get(self):
        return [(record.id, '[%s] %s' % (record.code, record.name)) for record in self]

    @api.depends('move_ids.uom_quantity', 'move_ids.state', 'move_ids.active')
    def _compute_stock_on_hand(self):
        quantities = {}
        if self.ids:
            groups = self.env['eproc.stock.move'].sudo().read_group(
                [
                    ('lot_id', 'in', self.ids),
                    ('location_id.usage', '=', 'internal'),
                    ('company_id', 'in', self.company_id.ids),
                    ('state', '=', 'done'),
                    ('active', '=', True),
                ],
                ['uom_quantity:sum'],
                ['lot_id', 'company_id'],
                lazy=False,
            )
            quantities = {
                (group['lot_id'][0], group['company_id'][0]): group['uom_quantity']
                for group in groups
                if group.get('lot_id') and group.get('company_id')
            }
        for record in self:
            record.stock_on_hand = quantities.get(
                (record.id, record.company_id.id), 0.0,
            )

    def open_stock_move(self):
        self.ensure_one()
        return {
            'name': _('Stock Movement for %s') % (self.name or self.code),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.stock.move',
            'view_mode': 'tree,form,pivot',
            'domain': [('lot_id', '=', self.id)],
            'context': {'create': False, 'edit': False, 'delete': False, 'duplicate': False},
            'target': 'current',
        }

    @api.model
    def _next_code(self, company):
        unit_code = (company.company_code or '').strip().upper()
        if not unit_code:
            raise UserError(_('Company %s has no company code configured.') % company.display_name)
        sequence_code = 'SEQ.ERP.SCM.%s.LOT' % unit_code
        code = self.env['ir.sequence'].sudo().with_company(company).next_by_code(sequence_code)
        if not code:
            raise UserError(_(
                'Stock lot sequence %s is not configured for company %s.'
            ) % (sequence_code, company.display_name))
        return code

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            company = self.env['res.company'].browse(vals.get('company_id')) or self.env.company
            vals['company_id'] = company.id
            if not vals.get('code') or vals.get('code') == '/':
                vals['code'] = self._next_code(company)
        return super().create(vals_list)

    def copy(self, default=None):
        raise UserError(_('Stock lot records cannot be duplicated.'))

    def unlink(self):
        raise UserError(_('Stock lot records cannot be deleted. Please archive the record instead.'))

    @api.model
    def _format_lot_date_for_field(self, model_record, field_name, value):
        if not value or field_name not in model_record._fields:
            return False
        date_value = fields.Date.to_date(value)
        if model_record._fields[field_name].type == 'datetime':
            return fields.Datetime.to_string(datetime.combine(date_value, datetime.min.time()))
        return fields.Date.to_string(date_value)

    @api.model
    def _ensure_from_receipt_line(self, line):
        if not line.lot_name:
            raise UserError(_('Batch/Lot is required for %s.') % line.product_tmpl_id.display_name)

        lot = self.sudo().search([
            ('name', '=', line.lot_name),
            ('product_tmpl_id', '=', line.product_tmpl_id.id),
            ('company_id', '=', line.company_id.id),
        ], limit=1)

        if lot:
            vals = {}
            if line.order_line_id and not lot.order_line_id:
                vals['order_line_id'] = line.order_line_id.id
            if not lot.receipt_line_id:
                vals['receipt_line_id'] = line.id
            if vals:
                lot.sudo().write(vals)
            return lot

        vals = {
            'name': line.lot_name,
            'receipt_line_id': line.id,
            'product_tmpl_id': line.product_tmpl_id.id,
            'expiration_date': self._format_lot_date_for_field(
                self,
                'expiration_date',
                line.lot_expiration_date,
            ),
            'removal_date': self._format_lot_date_for_field(
                self,
                'removal_date',
                line.lot_expiration_date,
            ),
            'landing_cost': line.uom_price,
            'company_id': line.company_id.id,
        }

        if 'order_line_id' in self._fields:
            vals['order_line_id'] = line.order_line_id.id if line.order_line_id else False

        return self.sudo().create(vals)


