    sync_id_api = sync.id_api

    def name_get(self):
        return [(record.id, record.move_no or _('New')) for record in self]

    @api.model
    def _next_code(self, company):
        unit_code = (company.company_code or '').strip().upper()
        if not unit_code:
            raise UserError(_('Company %s has no company code configured.') % company.display_name)
        sequence_code = 'SEQ.ERP.SCM.%s.MOVE' % unit_code
        code = self.env['ir.sequence'].sudo().with_company(company).next_by_code(sequence_code)
        if not code:
            raise UserError(_(
                'Stock movement sequence %s is not configured for company %s.'
            ) % (sequence_code, company.display_name))
        return code

    @api.model
    def _master_code_values(self, vals):
        values = {}
        if 'location_id' in vals:
            location = self.env['stock.location'].browse(vals['location_id']) if vals.get('location_id') else self.env[
                'stock.location']
            values['location_code'] = location.code if location else False
        if 'category_id' in vals:
            category = self.env['product.category'].browse(vals['category_id']) if vals.get('category_id') else \
            self.env['product.category']
            values['category_code'] = category.categ_code if category else False
        return values

    @api.model_create_multi
    def create(self, vals_list):
        if not self.env.context.get('from_system'):
            raise UserError(_('Stock move records are created by the system only.'))
        for vals in vals_list:
            company = self.env['res.company'].browse(vals.get('company_id')) if vals.get(
                'company_id') else self.env.company
            vals['company_id'] = company.id
            vals.setdefault('company_code', company.company_code)
            if not vals.get('move_datetime'):
                vals['move_datetime'] = fields.Datetime.now()
            if not vals.get('move_date') and vals.get('move_datetime'):
                vals['move_date'] = fields.Date.to_date(vals['move_datetime'])
            if not vals.get('move_no') or vals.get('move_no') == '/':
                vals['move_no'] = self._next_code(company)
        records = super().create(vals_list)
        if not self.env.context.get('skip_stock_quant'):
            self.env['eproc.stock.quant']._apply_stock_moves(records)
        return records

    # Mail/chatter-driven writes that must stay allowed even though the ledger is
    # immutable to manual business edits (e.g. message_post sets the main attachment).
    _MAIL_WRITABLE_FIELDS = {
        'message_main_attachment_id', 'message_ids', 'message_follower_ids',
        'message_partner_ids', 'activity_ids',
    }

    def write(self, vals):
        if not self.env.context.get('from_system') and set(vals) - self._MAIL_WRITABLE_FIELDS:
            raise UserError(_('Stock move records cannot be edited manually.'))
        if self.env.context.get('from_system') and any(field in vals for field in ('location_id', 'category_id')):
            vals = dict(vals, **self._master_code_values(vals))
        return super().write(vals)

    def copy(self, default=None):
        raise UserError(_('Stock move records cannot be duplicated.'))

    def unlink(self):
        raise UserError(_('Stock move records cannot be deleted.'))


