class EprocReceiptRetryTCWizard(models.TransientModel):
    _name = 'eproc.receipt.retry.tc.wizard'
    _description = 'Retry Receiving TC Sync Confirmation'

    retry_mode = fields.Selection([
        ('single', 'Single'),
        ('multiple', 'Multiple'),
    ], string='Retry Mode', default='multiple', readonly=True, required=True)
    receipt_ids = fields.Many2many(
        'eproc.receipt',
        'eproc_receipt_retry_tc_wizard_receipt_rel',
        'wizard_id',
        'receipt_id',
        string='Selected Documents',
        readonly=True,
    )
    warning_receipt_ids = fields.Many2many(
        'eproc.receipt',
        'eproc_receipt_retry_tc_wizard_warning_receipt_rel',
        'wizard_id',
        'receipt_id',
        string='Documents With Previous Sent Logs',
        readonly=True,
    )
    warning_log_ids = fields.Many2many(
        'eproc.receipt.log',
        'eproc_receipt_retry_tc_wizard_log_rel',
        'wizard_id',
        'log_id',
        string='Previous TC Logs',
        readonly=True,
    )
    warning_message = fields.Text(
        string='Warning',
        readonly=True,
    )
    selected_count = fields.Integer(
        string='Selected Data',
        readonly=True,
    )
    affected_count = fields.Integer(
        string='Affected Data',
        readonly=True,
    )
    sent_log_count = fields.Integer(
        string='Successfully Sent to TC',
        compute='_compute_single_retry_details',
        readonly=True,
    )
    single_warning_message = fields.Text(
        string='Confirmation',
        compute='_compute_single_retry_details',
        readonly=True,
    )

    @api.depends('retry_mode', 'receipt_ids')
    def _compute_single_retry_details(self):
        Log = self.env['eproc.receipt.log'].with_context(active_test=False)
        for wizard in self:
            sent_count = 0
            if wizard.retry_mode == 'single' and len(wizard.receipt_ids) == 1:
                sent_count = Log.search_count([
                    ('receipt_id', '=', wizard.receipt_ids.id),
                    ('state_tc', '=', 'sent'),
                ])
            wizard.sent_log_count = sent_count
            wizard.single_warning_message = _(
                'This transaction has been successfully sent to TC %s time(s).\n'
                'Are you sure you want to resend this transaction?'
            ) % sent_count if wizard.retry_mode == 'single' else False

    def action_confirm_retry(self):
        self.ensure_one()
        if not self.receipt_ids:
            raise UserError(_('No receiving documents were selected.'))
        source = self.env.context.get('retry_tc_source')
        if self.retry_mode == 'single':
            if len(self.receipt_ids) != 1:
                raise UserError(_('Single retry must target exactly one receiving document.'))
            receipts = self.receipt_ids._get_retry_tc_affected_receipts(source)
            if len(receipts) != 1:
                raise UserError(_('Single retry must target exactly one receiving document.'))
        else:
            receipts = self.receipt_ids._get_retry_tc_affected_receipts(source)
        context = {
            'retry_tc_confirmed': True,
            'retry_tc_source': source,
            'retry_mode': self.retry_mode,
        }
        if self.retry_mode == 'single':
            return receipts.with_context(**context)._execute_retry_interfacing_tc_single()
        return receipts.with_context(**context)._execute_retry_interfacing_tc_batch()


class EprocReceipt(models.Model):
    _name = 'eproc.receipt'
    _description = 'E-Proc Receiving'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'name'
    _order = 'receipt_date desc, id desc'

    @api.constrains('company_id', 'line_ids')
    def _check_budget_tracking_company(self):
        self.mapped('line_ids')._check_budget_source()

    def _lock_receipt_lifecycle(self):
        # Lock the union for the entire batch before processing its first record.
        # Include modification sources now, rather than acquiring them later in
        # a caller-dependent order inside confirm_modify().
        receipts = self | self.mapped('receipt_ref_id')
        receipts.mapped('line_ids.budget_item_id')._lock_tracking()
        receipts.check_access_rights('write')
        receipts.check_access_rule('write')
        # Pricing-only modifications do not change PO quantities and must not
        # acquire new PO/PR write privileges. Their source receipts are locked
        # below together with the rest of the batch.
        physical = self.filtered(lambda record: not record.receipt_ref_id)
        orders = physical.mapped('order_id') | physical.mapped('order_line_ids.order_id') | physical.mapped('line_ids.order_line_id.order_id')
        orders._lock_lifecycle()
        if not receipts:
            return
        self.env.flush_all()
        self.env.cr.execute('SELECT id FROM eproc_receipt WHERE id IN %s ORDER BY id FOR UPDATE', [tuple(receipts.ids)])
        receipts.invalidate_recordset()
        lines = receipts.mapped('line_ids')
        if lines:
            self.env.cr.execute('SELECT id FROM eproc_receipt_line WHERE id IN %s ORDER BY id FOR UPDATE', [tuple(lines.ids)])
            lines.invalidate_recordset()

    @api.constrains('receipt_revise', 'receipt_ref_id', 'receipt_type', 'company_id')
    def _check_receipt_revision_metadata(self):
        for record in self:
            source = record.receipt_ref_id
            if not source:
                if record.receipt_revise != 0:
                    raise ValidationError(_('A physical receipt must have revision zero and no source GRN.'))
                continue
            if (record.receipt_revise <= 0 or record.receipt_revise != source.receipt_revise + 1
                    or record.receipt_type not in ('PO', 'WO') or record.receipt_type != source.receipt_type
                    or record.company_id != source.company_id):
                raise ValidationError(_('GRN revision, type, and company must match a valid source GRN.'))
            record._grn_modification_root(record)

    def _check_physical_receipts(self):
        self._check_receipt_revision_metadata()
        if any(record.receipt_ref_id for record in self):
            raise UserError(_('Use GRN modification confirmation for pricing revisions; physical completion is not allowed.'))

    def _get_user(self):
        return self.env.user.id

    def _get_department(self):
        return self.env.user.department_id.id

    def _get_company(self):
        return self.env.company.id

    sync_type = sync.type
    sync_date = sync.date
    sync_id = sync.id
    sync_id_api = sync.id_api
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    receipt_no = fields.Char(string='Receiving No', readonly=True, copy=False, default='/')
    receipt_valid_no = fields.Char(string='Receiving Valid No', readonly=True, copy=False)
    receipt_date = fields.Datetime(string='Receiving Date', default=fields.Datetime.now, tracking=True)
    receipt_valid_date = fields.Datetime(string='Receiving Valid Date', readonly=True, copy=False)
    receipt_revise = fields.Integer(string='Receiving Revise', readonly=True, copy=False)
    receipt_ref_id = fields.Many2one(
        'eproc.receipt', string='Receipt Ref', copy=False, index=True, ondelete='restrict',
    )
    is_modified = fields.Boolean(string='Is Modified', default=False, copy=False, index=True)
    receipt_ref = fields.Char(string='Receiving Ref', tracking=True)
    receipt_origin = fields.Char(string='Receiving Origin', compute='_compute_receipt_origin', store=True)
    receipt_type = fields.Selection([
        ('WO', 'Without PO'),
        ('PO', 'Purchase Order'),
        ('RT', 'Vendor Return'),
    ], string='Receiving Type', default='PO', required=True, readonly=True, tracking=True)
    receipt_method = fields.Selection([
        ('single', 'Single PO'),
        ('multiple', 'Multiple PO'),
    ], string='Receiving Method', default='single', tracking=True)
    purchase_type_id = fields.Many2one('eproc.type', string='Procurement Type', tracking=True)
    approval_type_id = fields.Many2one('eproc.approval.type', string='Approval Type', tracking=True)
    approval_rule_id = fields.Many2one('eproc.approval.rule', string='Approval Rule', readonly=True)
    approval_rule_sequence = fields.Integer(string='Approval Rule no.', readonly=True)
    approval_next_stored = fields.Char(string='Approval Next Stored', readonly=True)
    user_id = fields.Many2one('res.users', string='Responsible', default=_get_user, tracking=True)
    department_id = fields.Many2one('hr.department', string='Department', default=_get_department, tracking=True)
    company_id = fields.Many2one('res.company', string='Company', default=_get_company, required=True, tracking=True)
    location_receipt_id = fields.Many2one('stock.location', string='Destination Location', tracking=True)
    location_supplier_id = fields.Many2one('stock.location', string='Supplier Location', tracking=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', tracking=True)
    line_ids = fields.One2many('eproc.receipt.line', 'receipt_id', string='Receiving Items')
    allowed_wo_product_tmpl_ids = fields.Many2many(
        'product.template',
        compute='_compute_allowed_wo_product_tmpl_ids',
        string='Allowed WO Products',
    )
    notes = fields.Text(string='Notes')
    total_price = fields.Float(string='Total Price', compute='_compute_totals', store=True)
    total_discount = fields.Float(string='Total Discount', compute='_compute_totals', store=True)
    total_taxes = fields.Float(string='Total Taxes', compute='_compute_totals', store=True)
    total_netprice = fields.Float(string='Total Net', compute='_compute_totals', store=True)
    ap_invoice_signed_total_price = fields.Float(string='AP Invoice Signed Total Price',
                                                 compute='_compute_ap_invoice_signed_totals')
    ap_invoice_signed_total_discount = fields.Float(string='AP Invoice Signed Total Discount',
                                                    compute='_compute_ap_invoice_signed_totals')
    ap_invoice_signed_total_taxes = fields.Float(string='AP Invoice Signed Total Taxes',
                                                 compute='_compute_ap_invoice_signed_totals')
    ap_invoice_signed_total_netprice = fields.Float(string='AP Invoice Signed Total Net',
                                                    compute='_compute_ap_invoice_signed_totals')
    approval_ids = fields.One2many('eproc.approval.log', 'receipt_id', string='Approval Logs')
    request_user_ids = fields.Many2many('res.users', compute='_compute_related_records', string='Request Users')
    request_line_ids = fields.Many2many('eproc.request.line', compute='_compute_related_records',
                                        string='Request Items')
    order_line_ids = fields.Many2many('eproc.order.line', 'eproc_receipt_order_line_rel', 'receipt_id', 'order_line_id',
                                      string='Purchase Items')
    available_order_line_ids = fields.Many2many('eproc.order.line', compute='_compute_available_order_line_ids')
    order_line_count = fields.Integer(compute='_compute_related_records', string='Purchase Items Count')
    order_id = fields.Many2one('eproc.order', string='Purchase No.')
    order_ids = fields.Many2many('eproc.order', compute='_compute_related_records', string='Purchase(s)')
    request_ids = fields.Many2many('eproc.request', compute='_compute_related_records', string='Request(s)')
    move_ids = fields.Many2many('eproc.stock.move', compute='_compute_related_records', string='Entries')
    move_count = fields.Integer(compute='_compute_related_records', string='Entries Count')
    asset_realize_count = fields.Integer(compute='_compute_related_document_counts', string='Asset Realize Count')
    ap_invoice_count = fields.Integer(compute='_compute_related_document_counts', string='AP Invoice Count')
    account_move_ids = fields.Many2many('account.move', 'eproc_receipt_account_move_rel', 'receipt_id', 'move_id',
                                        string='Journal Entries', readonly=True, copy=False)
    payable_invoice_id = fields.Many2one('payable.invoice', string='Payable Invoice No.', copy=False, index=True)
    state = fields.Selection([
        ('draft', 'Draft'),
        ('confirmed', 'Confirmed'),
        ('approval', 'Approval'),
        ('done', 'Completed'),
        ('rejected', 'Rejected'),
        ('cancelled', 'Cancelled'),
    ], string='State', default='draft', readonly=True, tracking=True)
    api_post_payload = fields.Text(string='API Post Payload', readonly=True)
    api_post_response = fields.Text(string='API Post Response', readonly=True)
    api_post_timestamp = fields.Datetime(string='API Post Timestamp', readonly=True)
    api_post_status = fields.Char(string='API Post Status', readonly=True)
    state_tc = fields.Selection([
        ('pending', 'Pending'),
        ('sent', 'Sent'),
        ('failed', 'Failed'),
    ], string='TC Status', readonly=True, copy=False)
    log_ids = fields.One2many('eproc.receipt.log', 'receipt_id', string='TC Logs', readonly=True)
    log_lastupdate = fields.Datetime(string='TC Last Update', readonly=True, copy=False)
    name = fields.Char(string='Title', compute='_compute_name', store=True)
    is_user_department = fields.Boolean(string='User Department', compute='_compute_is_user_department',
                                        search='_search_is_user_department')
    active = fields.Boolean(string='Active', default=True, tracking=True)

    @api.depends('receipt_no', 'receipt_valid_no')
    def _compute_name(self):
        for record in self:
            if record.receipt_valid_no and record.receipt_valid_no != record.receipt_no:
                record.name = '%s (%s)' % (record.receipt_valid_no, record.receipt_no or '/')
            else:
                record.name = record.receipt_no or _('Draft')

    @api.depends('line_ids.total_price', 'line_ids.total_discount', 'line_ids.total_taxes', 'line_ids.total_netprice')
    def _compute_totals(self):
        for record in self:
            record.total_price = sum(record.line_ids.mapped('total_price'))
            record.total_discount = sum(record.line_ids.mapped('total_discount'))
            record.total_taxes = sum(record.line_ids.mapped('total_taxes'))
            record.total_netprice = sum(record.line_ids.mapped('total_netprice'))

    def _ap_invoice_return_receipt_types(self):
        return self.env['payable.invoice']._eproc_invoice_return_receipt_types()

    @api.depends('receipt_type', 'total_price', 'total_discount', 'total_taxes', 'total_netprice')
    def _compute_ap_invoice_signed_totals(self):
        return_types = set(self._ap_invoice_return_receipt_types())
        for record in self:
            sign = -1.0 if record.receipt_type in return_types else 1.0
            record.ap_invoice_signed_total_price = sign * abs(record.total_price or 0.0)
            record.ap_invoice_signed_total_discount = sign * abs(record.total_discount or 0.0)
            record.ap_invoice_signed_total_taxes = sign * abs(record.total_taxes or 0.0)
            record.ap_invoice_signed_total_netprice = sign * abs(record.total_netprice or 0.0)

    def _compute_is_user_department(self):
        department = getattr(self.env.user, 'department_id', False)
        for record in self:
            record.is_user_department = bool(department and record.department_id == department)

    def _search_is_user_department(self, operator, value):
        department = getattr(self.env.user, 'department_id', False)
        if operator not in ('=', '!='):
            raise UserError(_('Unsupported operator for User Department filter.'))
        matched = bool(value)
        if operator == '!=':
            matched = not matched
        if matched:
            return [('department_id', '=', department.id if department else False)]
        return [('department_id', '!=', department.id if department else False)]

    def _eligible_asset_receipt_lines(self):
        self.ensure_one()
        return self.line_ids.filtered(lambda line: (
                line.receipt_id == self
                and self.receipt_type == 'PO'
                and self.state == 'done'
                and line.product_tmpl_id
                and line.product_tmpl_id.eproc_type == 'non_stock'
                and not line.eproc_asset_realize_id
        ))

    def action_create_asset_realize(self):
        self.ensure_one()
        self.check_access_rights('read')
        self.check_access_rule('read')

        if self.receipt_type != 'PO':
            raise UserError(
                _('Only completed Purchase Order GRNs can be realized to Fixed Asset.')
            )

        if self.state != 'done':
            raise UserError(
                _('Only completed Purchase Order GRNs can be realized to Fixed Asset.')
            )

        if not self.company_id:
            raise UserError(
                _('Company is required on the GRN.')
            )

        if not self._eligible_asset_receipt_lines():
            raise UserError(
                _(
                    'No eligible Non Stock receipt items are available '
                    'for asset realization.'
                )
            )

        view = self.env.ref(
            'mayapada.view_dil_scm_asset_realize_form',
            raise_if_not_found=False,
        )

        return {
            'name': _('Realize GRN to Fixed Asset'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.asset.realize',
            'view_mode': 'form',
            'views': (
                [(view.id, 'form')]
                if view
                else [(False, 'form')]
            ),
            'target': 'new',
            'context': {
                'default_receipt_id': self.id,
                'default_company_id': self.company_id.id,
                'default_supplier_id': self.supplier_id.id,
                'dialog_size': 'extra-large',
            },
        }

    @api.depends('order_line_ids', 'order_line_ids.order_id', 'line_ids.order_line_id', 'line_ids.eproc_move_id')
    def _compute_related_records(self):
        for record in self:
            order_lines = record.order_line_ids | record.line_ids.mapped('order_line_id')
            orders = order_lines.mapped('order_id')
            request_lines = order_lines.mapped('request_line_id') if 'request_line_id' in order_lines._fields else \
            self.env['eproc.request.line']
            requests = request_lines.mapped(
                'request_id') if request_lines and 'request_id' in request_lines._fields else self.env['eproc.request']
            record.order_line_count = len(order_lines)
            record.order_ids = orders
            record.request_line_ids = request_lines
            record.request_ids = requests
            record.request_user_ids = requests.mapped('user_id') if requests and 'user_id' in requests._fields else \
            self.env['res.users']
            record.move_ids = record.line_ids.mapped('eproc_move_id')
            record.move_count = len(record.move_ids)

    def _compute_related_document_counts(self):
        receipt_ids = set(self.ids)
        asset_ids_by_receipt = {receipt_id: set() for receipt_id in receipt_ids}
        invoice_ids_by_receipt = {receipt_id: set() for receipt_id in receipt_ids}
        if receipt_ids:
            AssetRealize = self.env['eproc.asset.realize']
            assets = AssetRealize.search([
                '|', '|', '|',
                ('receipt_id', 'in', list(receipt_ids)),
                ('receipt_line_ids.receipt_id', 'in', list(receipt_ids)),
                ('realize_line_ids.receipt_line_id.receipt_id', 'in', list(receipt_ids)),
                ('id', 'in', self.mapped('line_ids.eproc_asset_realize_id').ids),
            ])
            for asset in assets:
                related_receipt_ids = set(asset.receipt_id.ids)
                related_receipt_ids.update(asset.receipt_line_ids.mapped('receipt_id').ids)
                related_receipt_ids.update(asset.realize_line_ids.mapped('receipt_line_id.receipt_id').ids)
                for receipt_id in related_receipt_ids & receipt_ids:
                    asset_ids_by_receipt[receipt_id].add(asset.id)

            for line in self.mapped('line_ids').filtered('eproc_asset_realize_id'):
                if line.receipt_id.id in receipt_ids:
                    asset_ids_by_receipt[line.receipt_id.id].add(line.eproc_asset_realize_id.id)

            Invoice = self.env['payable.invoice']
            invoices = Invoice.search([
                '|',
                ('id', 'in', self.mapped('payable_invoice_id').ids),
                ('invoice_eproc_ids', 'in', list(receipt_ids)),
            ])
            for receipt in self:
                if receipt.payable_invoice_id:
                    invoice_ids_by_receipt[receipt.id].add(receipt.payable_invoice_id.id)
            for invoice in invoices:
                for receipt in invoice.invoice_eproc_ids:
                    if receipt.id in receipt_ids:
                        invoice_ids_by_receipt[receipt.id].add(invoice.id)

        for record in self:
            record.asset_realize_count = len(asset_ids_by_receipt.get(record.id, set()))
            record.ap_invoice_count = len(invoice_ids_by_receipt.get(record.id, set()))

    @api.depends('receipt_type', 'supplier_id', 'supplier_id.eproc_item_ids', 'location_receipt_id', 'company_id')
    def _compute_allowed_wo_product_tmpl_ids(self):
        Product = self.env['product.template']
        for record in self:
            if record.receipt_type != 'WO' or not record.supplier_id or not record.location_receipt_id:
                record.allowed_wo_product_tmpl_ids = Product
                continue
            products = record.supplier_id.eproc_item_ids.filtered(
                lambda product:
                product.is_eproc
                and product.eproc_type == 'stock'
                and record.location_receipt_id in product.eproc_store_ids
                and bool(product.eproc_pack_ids.filtered(lambda pack: pack.enable))
            )
            if 'company_id' in Product._fields and record.company_id:
                products = products.filtered(
                    lambda product: not product.company_id or product.company_id == record.company_id
                )
            record.allowed_wo_product_tmpl_ids = products

    @api.depends('order_id', 'order_line_ids', 'receipt_ref')
    def _compute_receipt_origin(self):
        for record in self:
            orders = record.order_ids or record.order_line_ids.mapped('order_id')
            names = []
            for order in orders:
                names.append(order.order_purchase_no or order.order_no or order.display_name)
            record.receipt_origin = ', '.join([name for name in names if name]) or record.receipt_ref

    @api.depends('company_id', 'purchase_type_id', 'supplier_id', 'receipt_type', 'receipt_method', 'order_id')
    def _compute_available_order_line_ids(self):
        OrderLine = self.env['eproc.order.line']
        for record in self:
            domain = record._get_order_line_domain()
            record.available_order_line_ids = OrderLine.search(domain) if domain else OrderLine

    def _get_order_line_domain(self):
        self.ensure_one()
        domain = []
        if self.company_id:
            domain.append(('company_id', '=', self.company_id.id))
        if self.supplier_id:
            domain.append(('order_id.supplier_id', '=', self.supplier_id.id))
        if self.purchase_type_id:
            domain.append(('order_id.purchase_type_id', '=', self.purchase_type_id.id))
        if self.receipt_method == 'single' and self.order_id:
            domain.append(('order_id', '=', self.order_id.id))
        if self.receipt_type == 'RT':
            domain.append(('pack_qty_processed', '>', 0.0))
        else:
            domain.append(('state', 'in', ('ready', 'partial')))
        domain += [('order_id.state', '!=', 'expired'), ('state', '!=', 'expired')]
        if self.receipt_type != 'RT':
            domain += [('pack_qty_rebalanced', '=', 0), ('uom_qty_rebalanced', '=', 0),
                       ('pack_qty_available', '>', 0)]
        return domain

    def _get_supplier_mapping_locations_from_refs(self, vals=None):
        self.ensure_one()
        vals = vals or {}
        order = self.env['eproc.order'].browse(vals.get('order_id')) if 'order_id' in vals else self.order_id
        supplier_explicit = 'supplier_id' in vals
        company_explicit = 'company_id' in vals
        supplier = self.env['res.partner'].browse(vals.get('supplier_id')) if supplier_explicit else self.supplier_id
        company = self.env['res.company'].browse(vals.get('company_id')) if company_explicit else self.company_id
        if not supplier and order and not supplier_explicit:
            supplier = order.supplier_id
        if not company and order and not company_explicit:
            company = order.company_id
        use_order_locations = bool(
            order
            and (not supplier or order.supplier_id == supplier)
            and (not company or order.company_id == company)
        )
        mapping = supplier._get_eproc_company_mapping(company) if supplier and company else self.env[
            'eproc.supplier.mapping']
        return {
            'location_receipt_id': (
                order.location_receipt_id.id
                if use_order_locations and order.location_receipt_id
                else (mapping.receipt_location_id.id if mapping else False)
            ),
            'location_supplier_id': (
                order.location_supplier_id.id
                if use_order_locations and order.location_supplier_id
                else (mapping.supplier_location_id.id if mapping else False)
            ),
        }

    def _get_location_receipt_from_refs(self, vals=None):
        return self._get_supplier_mapping_locations_from_refs(vals)['location_receipt_id']

    @api.onchange('supplier_id')
    def _onchange_supplier_id(self):
        for record in self:
            if (
                    record.supplier_id
                    and record.company_id
                    and not record.supplier_id._get_eproc_company_mapping(record.company_id)
            ):
                supplier_name = record.supplier_id.display_name
                company_name = record.company_id.display_name
                record.supplier_id = False
                record.location_receipt_id = False
                record.location_supplier_id = False
                return {
                    'warning': {
                        'title': _('Supplier is not applicable'),
                        'message': _('Supplier %s is not mapped to company %s.') % (supplier_name, company_name),
                    },
                    'domain': {'order_line_ids': [('id', 'in', record.available_order_line_ids.ids)]},
                }
            locations = record._get_supplier_mapping_locations_from_refs()
            record.location_receipt_id = locations['location_receipt_id']
            record.location_supplier_id = locations['location_supplier_id']
            if record.supplier_id and not record.purchase_type_id:
                record.purchase_type_id = record.supplier_id.eproc_type_id.id
            return {'domain': {'order_line_ids': [('id', 'in', record.available_order_line_ids.ids)]}}

    @api.onchange('company_id')
    def _onchange_company_supplier_mapping(self):
        for record in self:
            mapping = (
                record.supplier_id._get_eproc_company_mapping(record.company_id)
                if record.supplier_id and record.company_id
                else record.env['eproc.supplier.mapping']
            )
            if record.supplier_id and not mapping:
                record.supplier_id = False
                record.order_id = False
                record.order_line_ids = [(5, 0, 0)]
                record.location_receipt_id = False
                record.location_supplier_id = False
            elif record.supplier_id:
                locations = record._get_supplier_mapping_locations_from_refs()
                record.location_receipt_id = locations['location_receipt_id']
                record.location_supplier_id = locations['location_supplier_id']

    @api.onchange('receipt_type', 'supplier_id', 'location_receipt_id')
    def _onchange_wo_product_mapping(self):
        for record in self:
            if record.receipt_type != 'WO':
                continue
            allowed_products = record.allowed_wo_product_tmpl_ids
            invalid_lines = record.line_ids.filtered(
                lambda line: line.product_tmpl_id and line.product_tmpl_id not in allowed_products
            )
            for line in invalid_lines:
                line.product_tmpl_id = False
                line.product_categ_id = False
                line.name = False
                line.pack_id = False
                line.pack_rate = 0.0

    @api.onchange('order_id')
    def _onchange_order_id(self):
        for record in self:
            order = record.order_id
            if not order:
                record.order_line_ids = [(5, 0, 0)]
                return {'domain': {'order_line_ids': [('id', 'in', record.available_order_line_ids.ids)]}}
            record.supplier_id = order.supplier_id.id
            record.company_id = order.company_id.id or record.company_id.id
            record.purchase_type_id = order.purchase_type_id.id
            locations = record._get_supplier_mapping_locations_from_refs()
            record.location_receipt_id = locations['location_receipt_id']
            record.location_supplier_id = locations['location_supplier_id']
            record.order_line_ids = [(6, 0, record.order_line_ids.filtered(lambda line: line.order_id == order).ids)]
            return {'domain': {'order_line_ids': [('id', 'in', record.available_order_line_ids.ids)]}}

    @api.onchange('receipt_method', 'purchase_type_id')
    def _onchange_receipt_order_line_domain(self):
        for record in self:
            if record.receipt_method == 'single' and record.order_id:
                record.order_line_ids = [
                    (6, 0, record.order_line_ids.filtered(lambda line: line.order_id == record.order_id).ids)]
            return {'domain': {'order_line_ids': [('id', 'in', record.available_order_line_ids.ids)]}}

    @api.onchange('order_line_ids')
    def _onchange_order_line_ids(self):
        def _safe_id(record):
            if not record:
                return False
            return record._origin.id or record.id

        for record in self:
            if record.state != 'draft':
                continue

            selected_order_lines = record.order_line_ids
            selected_order_line_ids = set(
                _safe_id(order_line)
                for order_line in selected_order_lines
                if _safe_id(order_line)
            )

            # Simpan value yang sudah user edit di Receiving Items.
            # Ini penting saat masih create mode, supaya pack_receipt / price / tax tidak balik ke default.
            edited_values_by_order_line = {}
            for line in record.line_ids:
                order_line_id = _safe_id(line.order_line_id)
                if not order_line_id:
                    continue

                # Kalau ada duplicate, keep snapshot dari line pertama.
                # Biasanya line pertama adalah line yang sudah user edit.
                if order_line_id not in edited_values_by_order_line:
                    edited_values_by_order_line[order_line_id] = {
                        'pack_receipt': line.pack_receipt,
                        'pack_price': line.pack_price,
                        'disc_rate': line.disc_rate,
                        'tax_ids': [(6, 0, line.tax_ids.ids)],
                        'lot_id': line.lot_id.id if line.lot_id else False,
                        'lot_name': line.lot_name,
                        'lot_expiration_date': line.lot_expiration_date,
                    }

            # Buang duplicate line untuk order_line_id yang sama.
            # Keep line pertama, remove duplicate berikutnya.
            seen_order_line_ids = set()
            duplicate_lines = self.env['eproc.receipt.line']

            for line in record.line_ids:
                order_line_id = _safe_id(line.order_line_id)
                if not order_line_id:
                    continue

                if order_line_id in seen_order_line_ids:
                    duplicate_lines |= line
                else:
                    seen_order_line_ids.add(order_line_id)

            if duplicate_lines:
                record.line_ids -= duplicate_lines

            existing_order_line_ids = set()
            for line in record.line_ids:
                order_line_id = _safe_id(line.order_line_id)
                if order_line_id:
                    existing_order_line_ids.add(order_line_id)

            next_sequence = max(record.line_ids.mapped('sequence') or [0])

            # Generate line hanya untuk PO item yang belum punya receiving line.
            for order_line in selected_order_lines.sorted(
                    lambda line: (line.order_id.id or 0, line.sequence or 0, line.id)):
                order_line_id = _safe_id(order_line)
                if not order_line_id or order_line_id in existing_order_line_ids:
                    continue

                next_sequence += 1
                line_values = self.env['eproc.receipt.line']._prepare_from_order_line(
                    order_line,
                    record.receipt_type,
                )
                line_values['sequence'] = next_sequence
                line_values['receipt_id'] = record.id

                record.line_ids += self.env['eproc.receipt.line'].new(line_values)
                existing_order_line_ids.add(order_line_id)

            # Restore value yang user sudah edit.
            # Jadi kalau onchange sempat refresh cache, nilai manual tetap balik ke value user.
            for line in record.line_ids:
                order_line_id = _safe_id(line.order_line_id)
                edited_values = edited_values_by_order_line.get(order_line_id)
                if not edited_values:
                    continue

                line.pack_receipt = edited_values['pack_receipt']
                line.pack_price = edited_values['pack_price']
                line.disc_rate = edited_values['disc_rate']
                line.tax_ids = edited_values['tax_ids']
                line.lot_id = edited_values['lot_id']
                line.lot_name = edited_values['lot_name']
                line.lot_expiration_date = edited_values['lot_expiration_date']

    @api.model
    def _sequence_unit_code(self, company):
        unit_code = getattr(company, 'company_code', False)
        if not unit_code:
            raise UserError(_('Company Code is required to generate SCM Receiving sequence for %s.') % (
                        company.display_name or company.id))
        return unit_code

    @api.model
    def _sequence_code(self, receipt_type, valid=False, company=False):
        unit_code = self._sequence_unit_code(company or self.env.company)
        if receipt_type == 'RT':
            return 'SEQ.ERP.SCM.%s.RECEIVING.RETURN' % unit_code
        if valid or receipt_type == 'WO':
            return 'SEQ.ERP.SCM.%s.RECEIVING.VALIDATION' % unit_code
        return 'SEQ.ERP.SCM.%s.RECEIVING.BAY' % unit_code

    @api.model
    def _next_sequence(self, receipt_type, valid=False, company=False):
        company = company or self.env.company
        sequence_code = self._sequence_code(receipt_type, valid=valid, company=company)
        number = self.env['ir.sequence'].with_company(company).next_by_code(sequence_code)
        if not number:
            raise UserError(_('No receiving sequence found for %s.') % sequence_code)
        return number

    @api.model
    def _grn_modification_line_values(self, source_line):
        return {
            'sequence': source_line.sequence,
            'product_tmpl_id': source_line.product_tmpl_id.id,
            'product_categ_id': source_line.product_categ_id.id,
            'name': source_line.name,
            'lot_id': source_line.lot_id.id,
            'lot_name': source_line.lot_name,
            'lot_expiration_date': source_line.lot_expiration_date,
            'pack_id': source_line.pack_id.id,
            'pack_order': source_line.pack_order,
            'pack_processed': source_line.pack_processed,
            'pack_receipt': source_line.pack_receipt,
            'pack_price': source_line.pack_price,
            'pack_rate': source_line.pack_rate,
            'uom_id': source_line.uom_id.id,
            'uom_order': source_line.uom_order,
            'uom_processed': source_line.uom_processed,
            'disc_rate': source_line.disc_rate,
            'tax_ids': [(6, 0, source_line.tax_ids.ids)],
            'analytic_id': source_line.analytic_id.id,
            'orderpoint_log_id': source_line.orderpoint_log_id.id,
            'order_line_id': source_line.order_line_id.id,
            'request_line_id': source_line.request_line_id.id,
            'receipt_line_ref_id': source_line.id,
            'state': 'draft',
        }

    @api.model
    def _grn_modification_root(self, source):
        current = source
        seen = set()
        while current.receipt_ref_id:
            if current.id in seen:
                raise UserError(_('The GRN modification chain contains a loop.'))
            seen.add(current.id)
            parent = current.receipt_ref_id
            if current.receipt_revise != parent.receipt_revise + 1:
                raise UserError(_('The GRN modification chain has a non-sequential revision.'))
            if current.company_id != parent.company_id or current.receipt_type != parent.receipt_type:
                raise UserError(_('The GRN modification chain changes company or receipt type.'))
            current = parent
        if current.id in seen:
            raise UserError(_('The GRN modification chain contains a loop.'))
        if current.receipt_revise != 0:
            raise UserError(_('The GRN modification chain does not end at an original revision.'))
        return current

    @api.model
    def _grn_modification_number(self, source, revision):
        root = self._grn_modification_root(source)
        base_number = root.receipt_valid_no or root.receipt_no
        if not base_number or base_number == '/':
            raise UserError(_('The source GRN has no valid GRN number.'))
        return '%sR%s' % (base_number, revision)

    @api.model
    def _grn_modification_ap_error(self, source):
        invoices = source._get_related_ap_invoice_records()
        invoice = source.payable_invoice_id or invoices[:1]
        if not invoice:
            return False
        invoice_number = getattr(invoice, 'invoice_no', False) or invoice.display_name
        source_number = source.receipt_valid_no or source.receipt_no or source.display_name
        return _(
            'GRN %s cannot be modified because it is related to AP Invoice %s.'
        ) % (source_number, invoice_number)

    @api.model
    def _validate_grn_modification_source(self, source, company=False, current=False):
        if not source or not source.exists():
            raise UserError(_('Please select a source GRN.'))
        source.check_access_rights('read')
        source.check_access_rule('read')
        company = company or self.env.company
        if source.company_id != company:
            raise UserError(_('The source GRN must belong to the same company.'))
        if current and current.id and source.id == current.id:
            raise UserError(_('A GRN modification cannot reference itself.'))
        if source.receipt_type not in ('PO', 'WO'):
            raise UserError(_('Only Purchase Order or Without PO GRNs can be modified.'))
        if source.state != 'done':
            raise UserError(_('Only completed GRNs can be modified.'))
        if 'active' in source._fields and not source.active:
            raise UserError(_('The source GRN must be active.'))
        if source.is_modified:
            raise UserError(_('A newer modification already exists for this source GRN.'))
        if source.receipt_revise > 0 and not source.receipt_ref_id:
            raise UserError(_('The source has a legacy revision value without a valid modification reference.'))
        if not source.receipt_valid_date:
            raise UserError(_('The source GRN has no validation date for the H+1 check.'))
        validation_date = fields.Datetime.context_timestamp(
            self, fields.Datetime.to_datetime(source.receipt_valid_date)
        ).date()
        if validation_date > fields.Date.context_today(self):
            raise UserError(_('GRN modification is only allowed from the next calendar day (H+1).'))
        ap_error = self._grn_modification_ap_error(source)
        if ap_error:
            raise UserError(ap_error)
        self._grn_modification_root(source)
        return True

    @api.model
    def _prepare_grn_modification_values(self, source):
        revision = source.receipt_revise + 1
        revision_number = self._grn_modification_number(source, revision)
        return {
            'receipt_ref_id': source.id,
            'receipt_revise': revision,
            'receipt_no': revision_number,
            'receipt_valid_no': revision_number,
            'receipt_date': fields.Datetime.now(),
            'receipt_valid_date': False,
            'receipt_ref': source.receipt_ref,
            'receipt_type': source.receipt_type,
            'receipt_method': source.receipt_method,
            'purchase_type_id': source.purchase_type_id.id,
            'approval_type_id': False,
            'approval_rule_id': False,
            'approval_rule_sequence': 0,
            'approval_next_stored': False,
            'user_id': source.user_id.id,
            'department_id': source.department_id.id,
            'company_id': source.company_id.id,
            'location_receipt_id': source.location_receipt_id.id,
            'location_supplier_id': source.location_supplier_id.id,
            'supplier_id': source.supplier_id.id,
            'notes': source.notes,
            'order_id': source.order_id.id,
            'order_line_ids': [(6, 0, source.order_line_ids.ids)],
            'line_ids': [(0, 0, self._grn_modification_line_values(line)) for line in source.line_ids],
            'payable_invoice_id': False,
            'account_move_ids': [(5, 0, 0)],
            'is_modified': False,
            'state': 'draft',
            'state_tc': False,
            'api_post_payload': False,
            'api_post_response': False,
            'api_post_timestamp': False,
            'api_post_status': False,
            'log_lastupdate': False,
            'active': True,
        }

    @api.onchange('receipt_ref_id')
    def _onchange_grn_modification_receipt_ref(self):
        for record in self:
            source = record.receipt_ref_id
            if not source:
                record.receipt_revise = 0
                record.receipt_no = '/'
                record.receipt_valid_no = False
                record.line_ids = [(5, 0, 0)]
                continue
            record._validate_grn_modification_source(
                source, company=record.company_id or self.env.company, current=record,
            )
            record.update(record._prepare_grn_modification_values(source))

    @api.model_create_multi
    def create(self, vals_list):
        self._ensure_not_dil_goods_receiving_view(
            _('Creating records is not allowed from the DIL Goods Receiving view.')
        )
        defaults = self.default_get(['receipt_ref_id', 'receipt_revise'])
        vals_list = [dict(vals) for vals in vals_list]
        has_modification = False
        for vals in vals_list:
            source_id = vals.get('receipt_ref_id', defaults.get('receipt_ref_id'))
            revision = vals.get('receipt_revise', defaults.get('receipt_revise', 0)) or 0
            if source_id:
                source = self.env['eproc.receipt'].browse(source_id)
                company = self.env['res.company'].browse(
                    vals.get('company_id') or source.company_id.id
                )
                self._validate_grn_modification_source(source, company=company)
                if revision not in (0, source.receipt_revise + 1):
                    raise ValidationError(_('The GRN revision number must immediately follow its source revision.'))
                prepared = self._prepare_grn_modification_values(source)
                vals.clear()
                vals.update(prepared)
                has_modification = True
            elif revision != 0 or self.env.context.get(
                    'from_dil_grn_modification_view'):
                raise UserError(_('A source GRN is required to create a GRN modification.'))
            else:
                vals.update(receipt_ref_id=False, receipt_revise=0)
            if not vals.get('company_id'):
                vals['company_id'] = self.env.company.id
            if not vals.get('user_id'):
                vals['user_id'] = self.env.user.id
            if not vals.get('department_id'):
                vals['department_id'] = getattr(self.env.user, 'department_id', False).id or False
            if vals.get('supplier_id'):
                supplier = self.env['res.partner'].browse(vals['supplier_id'])
                company = self.env['res.company'].browse(vals['company_id'])
                if not supplier._get_eproc_company_mapping(company):
                    raise ValidationError(
                        _('Supplier %s is not mapped to company %s.')
                        % (supplier.display_name, company.display_name)
                    )
            receipt_type = vals.get('receipt_type') or self.env.context.get('default_receipt_type') or 'PO'
            vals['receipt_type'] = receipt_type
            if not vals.get('receipt_no') or vals.get('receipt_no') == '/':
                company = self.env['res.company'].browse(vals['company_id'])
                vals['receipt_no'] = self._next_sequence(receipt_type, valid=(receipt_type in ('WO', 'RT')),
                                                         company=company)
            if receipt_type in ('WO', 'RT') and not vals.get('receipt_valid_no'):
                vals['receipt_valid_no'] = vals['receipt_no']
            temp = self.new(vals)
            locations = temp._get_supplier_mapping_locations_from_refs(vals)
            if 'location_receipt_id' not in vals:
                vals['location_receipt_id'] = locations['location_receipt_id']
            if 'location_supplier_id' not in vals:
                vals['location_supplier_id'] = locations['location_supplier_id']
        create_self = self.with_context(
            allow_grn_modification_line_create=has_modification,
        )
        records = super(EprocReceipt, create_self).create(vals_list)
        records.filtered(lambda record: record.receipt_type == 'WO')._validate_wo_product_mapping()
        return records

    @api.model
    def fields_get(self, allfields=None, attributes=None):
        result = super(EprocReceipt, self).fields_get(
            allfields=allfields,
            attributes=attributes,
        )

        if (
                (
                        self.env.context.get('from_dil_goods_receiving_view')
                        or self.env.context.get('from_dil_vendor_return_view')
                )
                and 'active' in result
        ):
            result['active'] = dict(result['active'])
            result['active']['readonly'] = True

        return result

    def write(self, vals):
        if {'state', 'is_modified', 'company_id', 'receipt_type', 'line_ids'} & set(vals):
            self.mapped('line_ids.budget_item_id')._lock_tracking()
        self._ensure_not_dil_goods_receiving_view(
            _('Editing records is not allowed from the DIL Goods Receiving view.')
        )
        # Metadata is derived from the validated source only at create. Neither
        # caller-supplied context flags nor technical-field exemptions authorize
        # changing an existing physical receipt into a revision (or vice versa).
        for record in self:
            if ('receipt_revise' in vals and vals['receipt_revise'] != record.receipt_revise
                    or 'receipt_ref_id' in vals and (vals['receipt_ref_id'] or False) != record.receipt_ref_id.id):
                raise AccessError(_('GRN revision and source cannot be changed after creation.'))
        if len(self) > 1 and {'order_id', 'supplier_id', 'company_id'} & set(vals):
            for record in self:
                record.write(dict(vals))
            return True
        has_modification = self.filtered(
            lambda rec: rec.receipt_revise > 0 and rec.receipt_ref_id
        )
        if (
                not self.env.context.get('skip_receipt_lock')
                or (
                    has_modification
                    and not self.env.context.get('grn_modification_internal')
                )
        ):
            self._check_write_allowed(vals)
        if {'order_id', 'supplier_id', 'company_id'} & set(vals):
            locations = self._get_supplier_mapping_locations_from_refs(vals)
            if 'location_receipt_id' not in vals:
                vals['location_receipt_id'] = locations['location_receipt_id']
            if 'location_supplier_id' not in vals:
                vals['location_supplier_id'] = locations['location_supplier_id']
        result = super(EprocReceipt, self).write(vals)
        if {'receipt_type', 'supplier_id', 'location_receipt_id', 'location_supplier_id', 'line_ids'} & set(vals):
            self.filtered(lambda record: record.receipt_type == 'WO')._validate_wo_product_mapping()
        return result

    @api.constrains('supplier_id', 'company_id', 'location_receipt_id', 'location_supplier_id')
    def _check_supplier_mapping_and_locations(self):
        for record in self:
            if record.supplier_id and record.company_id and not record.supplier_id._get_eproc_company_mapping(
                    record.company_id):
                raise ValidationError(
                    _('Supplier %s is not mapped to company %s.')
                    % (record.supplier_id.display_name, record.company_id.display_name)
                )
            for location, label in (
                    (record.location_receipt_id, _('Receipt Location')),
                    (record.location_supplier_id, _('Supplier Location'))):
                if location and (location.company_id != record.company_id or not location.is_eproc):
                    raise ValidationError(_('%s must be an E-Proc location belonging to the receipt company.') % label)
            if record.state not in ('draft', 'cancelled', 'rejected'):
                record._validate_required_locations()

    @api.constrains('state')
    def _check_processed_receipt_mapping_and_locations(self):
        for record in self.filtered(lambda receipt: receipt.state not in ('draft', 'cancelled', 'rejected')):
            if record.supplier_id and record.company_id and not record.supplier_id._get_eproc_company_mapping(
                    record.company_id):
                raise ValidationError(
                    _('Supplier %s is not mapped to company %s.')
                    % (record.supplier_id.display_name, record.company_id.display_name)
                )
            record._validate_required_locations()

    def _validate_required_locations(self):
        for record in self:
            if not record.location_receipt_id:
                raise UserError(_('Receipt Location is required.'))
            if not record.location_supplier_id:
                raise UserError(_('Supplier Location is required.'))

    @api.constrains('receipt_method', 'order_id', 'order_line_ids')
    def _check_single_order_lines(self):
        for record in self:
            if record.receipt_method == 'single' and record.order_id:
                invalid_lines = record.order_line_ids.filtered(lambda line: line.order_id != record.order_id)
                if invalid_lines:
                    raise ValidationError(
                        _('Single PO receipt can only select PO items from the selected purchase order.'))

