    #         return
    #     allowed = self.filtered(lambda rec: rec.state in ('draft', 'confirmed') and rec.receipt_type in ('WO', 'RT'))
    #     locked = self - allowed
    #     if locked:
    #         raise UserError(_('Receiving records can only be edited in Draft, except Accounting may adjust validation/return records while Confirmed.'))

    def _get_actual_changed_receipt_fields(self, vals):
        """Return stored receipt fields whose incoming values really differ."""
        changed_by_receipt = {}
        for record in self:
            changed = set()
            for field_name, new_value in vals.items():
                field = record._fields.get(field_name)
                if not field:
                    continue

                current_value = record[field_name]
                if field.type == 'many2one':
                    current_value = current_value.id or False
                    if hasattr(new_value, 'id'):
                        new_value = new_value.id
                    new_value = new_value or False
                elif field.type in ('many2many', 'one2many'):
                    # line_ids is intentionally handled as an allowed container
                    # by _check_write_allowed; other x2many fields stay protected.
                    changed.add(field_name)
                    continue
                elif field.type == 'boolean':
                    current_value = bool(current_value)
                    new_value = bool(new_value)
                elif field.type == 'integer':
                    current_value = int(current_value or 0)
                    new_value = int(new_value or 0)
                elif field.type in ('float', 'monetary'):
                    current_value = float(current_value or 0.0)
                    new_value = float(new_value or 0.0)
                elif field.type == 'date':
                    current_value = fields.Date.to_date(current_value) if current_value else False
                    new_value = fields.Date.to_date(new_value) if new_value else False
                elif field.type == 'datetime':
                    current_value = fields.Datetime.to_datetime(current_value) if current_value else False
                    new_value = fields.Datetime.to_datetime(new_value) if new_value else False
                elif field.type in ('char', 'text', 'selection'):
                    current_value = current_value or False
                    new_value = new_value or False

                if current_value != new_value:
                    changed.add(field_name)
            changed_by_receipt[record.id] = changed
        return changed_by_receipt

    def _check_write_allowed(self, vals):
        internal_modification = self.env.context.get('grn_modification_internal')
        changed_by_receipt = self._get_actual_changed_receipt_fields(vals)

        modifications = self.filtered(
            lambda rec: rec.receipt_revise > 0 and rec.receipt_ref_id
        )
        if modifications and not internal_modification:
            allowed_modification_fields = {
                'line_ids', 'message_follower_ids', 'message_ids', 'activity_ids',
                'message_main_attachment_id',
                'total_price', 'total_discount', 'total_taxes', 'total_netprice',
            }
            forbidden_fields = set()
            for record in modifications:
                forbidden_fields.update(
                    changed_by_receipt.get(record.id, set()) - allowed_modification_fields
                )
            if forbidden_fields:
                raise UserError(_(
                    'Only Unit Price, Discount Rate, and Taxes may be changed on a draft GRN modification.\n'
                    'Invalid fields: %s'
                ) % ', '.join(sorted(forbidden_fields)))
            edited_modifications = modifications.filtered(
                lambda rec: bool(changed_by_receipt.get(rec.id, set()))
            )
            if edited_modifications.filtered(lambda rec: rec.state != 'draft'):
                raise UserError(_('A completed GRN modification cannot be edited.'))
            return

        if not internal_modification and any(
                'is_modified' in changed_by_receipt.get(record.id, set())
                for record in self
        ):
            raise UserError(_('GRN modification status can only be changed by the confirmation process.'))

        technical_fields = {
            'state', 'approval_rule_id', 'approval_rule_sequence', 'approval_next_stored',
            'approval_ids', 'receipt_valid_no', 'receipt_valid_date',
            'api_post_payload', 'api_post_response', 'api_post_timestamp', 'api_post_status',
            'state_tc', 'log_ids', 'log_lastupdate',
            'active', 'account_move_ids', 'message_follower_ids', 'message_ids',
            'activity_ids', 'message_main_attachment_id',
        }

        if vals and all(
                field in technical_fields
                or field.startswith('message_')
                or field.startswith('activity_')
                for field in vals
        ):
            return

        allowed = self.filtered(
            lambda rec:
            rec.state == 'draft'
            or (
                    rec.state == 'confirmed'
                    and rec.receipt_type in ('WO', 'RT')
            )
            or (
                    rec.state == 'rejected'
                    and rec.receipt_type == 'WO'
            )
        )

        locked = self - allowed
        # if locked:
        #     raise UserError(_(
        #         'Receiving records can only be edited in Draft, except Accounting may adjust validation/return records while Confirmed.'
        #     ))

    def unlink(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Deleting records is not allowed from the DIL Goods Receiving view.')
        )
        raise UserError(_('Receiving records cannot be deleted. Please archive the record instead.'))

    def copy(self, default=None):
        raise UserError(_('Receiving records cannot be duplicated.'))

    def action_archive(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Archiving records is not allowed from the DIL Goods Receiving view.')
        )
        for record in self:
            if record.receipt_revise > 0 and record.receipt_ref_id:
                raise UserError(_('GRN modifications cannot be archived or restored.'))
            if record.state != 'draft':
                raise UserError(_('Only Draft receiving records can be archived or restored.'))
            record.with_context(skip_receipt_lock=True).write({'active': not record.active})
        return True

    def _validate_lines(self):
        self._lock_receipt_lifecycle()
        self._check_physical_receipts()
        for receipt in self.filtered(lambda rec: rec.receipt_type in ('PO', 'RT')):
            quantities = {}
            for line in receipt.line_ids:
                order_line = line.order_line_id
                if not order_line:
                    continue  # Existing validation provides the missing-reference error.
                order_line._check_receiving_eligible(receipt.receipt_type)
                if (line.product_tmpl_id != order_line.product_tmpl_id or line.pack_id != order_line.pack_id
                        or line.uom_id != order_line.uom_id
                        or not float_is_zero(line.pack_rate - order_line._lifecycle_rate(), precision_digits=PACK_DIGITS)):
                    raise ValidationError(_('Receiving item product, pack, UoM, and conversion must match its PO item.'))
                quantity = quantities.get(order_line.id, 0.0) + line.pack_receipt
                quantities[order_line.id] = quantity
                available = order_line.pack_qty_processed if receipt.receipt_type == 'RT' else order_line.pack_qty_available
                available_uom = order_line.uom_qty_processed if receipt.receipt_type == 'RT' else order_line.uom_qty_available
                if (float_compare(quantity, available, precision_digits=PACK_DIGITS) > 0
                        or float_compare(quantity * order_line._lifecycle_rate(), available_uom,
                                         precision_rounding=order_line.uom_id.rounding or 0.01) > 0):
                    raise UserError(_('Receiving/return quantity exceeds the current PO balance for %s.') % order_line.display_name)
                line.with_context(skip_receipt_line_lock=True).write({
                    'pack_order': order_line.pack_qty, 'pack_processed': order_line.pack_qty_processed,
                    'uom_order': order_line.uom_qty, 'uom_processed': order_line.uom_qty_processed,
                })
        for record in self:
            if not record.line_ids:
                raise UserError(_('At least one receiving item is required.'))
            if not record.supplier_id:
                raise UserError(_('Supplier is required.'))
            if not record.supplier_id._get_eproc_company_mapping(record.company_id):
                raise UserError(
                    _('Supplier %s is not mapped to company %s.')
                    % (record.supplier_id.display_name, record.company_id.display_name)
                )
            if not record.location_receipt_id:
                raise UserError(_('Destination Location is required.'))
            if not record.location_supplier_id:
                raise UserError(_('Supplier Location is required.'))
            order_lines = record.order_line_ids | record.line_ids.mapped('order_line_id')
            if record.receipt_type in ('PO', 'RT') and not (record.order_id or order_lines):
                raise UserError(_('Purchase reference is required.'))
            orders = order_lines.mapped('order_id')
            if record.receipt_type in ('PO', 'RT') and order_lines:
                invalid_company = orders.filtered(
                    lambda order: order.company_id and order.company_id != record.company_id)
                if invalid_company:
                    raise UserError(_('Purchase reference must belong to the same company as the receiving record.'))
                invalid_supplier = orders.filtered(
                    lambda order: order.supplier_id and order.supplier_id != record.supplier_id)
                if invalid_supplier:
                    raise UserError(_('All selected PO items must belong to the same supplier.'))
                invalid_purchase_type = orders.filtered(
                    lambda order: order.purchase_type_id and order.purchase_type_id != record.purchase_type_id)
                if invalid_purchase_type:
                    raise UserError(_('All selected PO items must belong to the same procurement type.'))
                if record.receipt_method == 'single' and record.order_id:
                    invalid_order_lines = order_lines.filtered(lambda line: line.order_id != record.order_id)
                    if invalid_order_lines:
                        raise UserError(
                            _('Single PO receiving can only select items from the selected purchase order.'))
                if record.receipt_method == 'single' and len(orders) > 1:
                    raise UserError(_('Single PO receiving can only reference one purchase order.'))
            if record.receipt_type == 'WO':
                record._validate_wo_product_mapping()
            for line in record.line_ids:
                if record.receipt_type in ('PO', 'RT') and not line.order_line_id:
                    raise UserError(_('All Purchase Order receiving lines must come from selected Purchase Items.'))
                line._validate_receipt_line()

    def _validate_wo_product_mapping(self):
        for record in self:
            if record.receipt_type != 'WO':
                continue
            if not record.supplier_id or not record.location_receipt_id:
                continue
            invalid_lines = record.line_ids.filtered(
                lambda line: line.product_tmpl_id and line.product_tmpl_id not in record.allowed_wo_product_tmpl_ids
            )
            if invalid_lines:
                products = ', '.join(invalid_lines.mapped('product_tmpl_id.display_name'))
                raise ValidationError(_(
                    'WO receiving products must be mapped to supplier %s and destination location %s: %s'
                ) % (record.supplier_id.display_name, record.location_receipt_id.display_name, products))
            for line in record.line_ids:
                line._check_wo_product_mapping()

    def _validate_grn_modification_integrity(self, source):
        self.ensure_one()
        header_fields = (
            'receipt_type', 'receipt_method', 'purchase_type_id', 'supplier_id',
            'location_receipt_id', 'location_supplier_id', 'order_id', 'receipt_ref',
            'department_id', 'user_id', 'notes',
        )
        for field_name in header_fields:
            field = self._fields[field_name]
            current_value = self[field_name]
            source_value = source[field_name]
            if field.type == 'many2one':
                matches = current_value.id == source_value.id
            else:
                matches = current_value == source_value
            if not matches:
                raise UserError(_(
                    'GRN modification header field %s no longer matches its source.'
                ) % field.string)
        if set(self.order_line_ids.ids) != set(source.order_line_ids.ids):
            raise UserError(_('The Purchase Items on the GRN modification no longer match its source.'))

        if len(self.line_ids) != len(source.line_ids):
            raise UserError(_('The GRN modification must contain exactly the source GRN lines.'))
        referenced_ids = self.line_ids.mapped('receipt_line_ref_id').ids
        if len(referenced_ids) != len(self.line_ids):
            raise UserError(_('Every GRN modification line must reference one source line.'))
        if len(set(referenced_ids)) != len(referenced_ids):
            raise UserError(_('Each source GRN line may only be referenced once.'))
        if set(referenced_ids) != set(source.line_ids.ids):
            raise UserError(_('GRN modification line references must match all source GRN lines exactly.'))

        immutable_line_fields = (
            'sequence', 'product_tmpl_id', 'product_categ_id', 'name',
            'lot_id', 'lot_name', 'lot_expiration_date', 'pack_id',
            'pack_order', 'pack_processed', 'pack_available', 'pack_receipt',
            'pack_rate', 'uom_id', 'uom_order', 'uom_processed',
            'uom_available', 'uom_receipt', 'analytic_id', 'orderpoint_log_id',
            'order_line_id', 'request_line_id',
        )
        for line in self.line_ids:
            source_line = line.receipt_line_ref_id
            if source_line.receipt_id != source:
                raise UserError(_('A GRN modification line references a line outside its source GRN.'))
            for field_name in immutable_line_fields:
                field = line._fields[field_name]
                current_value = line[field_name]
                source_value = source_line[field_name]
                if field.type == 'many2one':
                    matches = current_value.id == source_value.id
                elif field.type in ('float', 'monetary'):
                    matches = float_compare(
                        current_value or 0.0, source_value or 0.0, precision_digits=6,
                    ) == 0
                else:
                    matches = current_value == source_value
                if not matches:
                    raise UserError(_(
                        'GRN modification line %s changed immutable field %s.'
                    ) % (line.sequence, field.string))
        return True

    def _create_grn_modification_accounting(self, journal_date):
        self.ensure_one()
        if self.account_move_ids:
            raise UserError(_('This GRN modification already has a journal entry.'))
        journal = self.env['account.journal'].search([
            ('name', '=', 'GRN Modification'),
            ('company_id', '=', self.company_id.id),
            ('type', '=', 'general'),
        ], limit=1)
        if not journal:
            raise UserError(_(
                'Please configure a General journal named "GRN Modification" for company %s.'
            ) % self.company_id.display_name)

        move_lines = []
        revision_number = self.receipt_valid_no or self.receipt_no
        for line in self.line_ids:
            difference = line.total_difference or 0.0
            if float_is_zero(difference, precision_digits=2):
                continue
            category = line.product_tmpl_id.categ_id
            cogs_account = category.stock_output_id
            ap_not_invoice_account = category.stock_input_id
            if not cogs_account or not ap_not_invoice_account:
                raise UserError(_(
                    'Please configure Stock Output and Stock Input accounts on product category %s.'
                ) % category.display_name)
            for account in (cogs_account, ap_not_invoice_account):
                if account.company_id and account.company_id != self.company_id:
                    raise UserError(_(
                        'Account %s does not belong to company %s.'
                    ) % (account.display_name, self.company_id.display_name))

            amount = abs(difference)
            debit_account = cogs_account if difference > 0 else ap_not_invoice_account
            credit_account = ap_not_invoice_account if difference > 0 else cogs_account
            line_name = '%s / %s' % (
                revision_number,
                line.product_tmpl_id.display_name or line.name or line.sequence,
            )
            move_lines.extend([
                (0, 0, {
                    'name': line_name,
                    'account_id': debit_account.id,
                    'partner_id': self.supplier_id.id,
                    'debit': amount,
                    'credit': 0.0,
                }),
                (0, 0, {
                    'name': line_name,
                    'account_id': credit_account.id,
                    'partner_id': self.supplier_id.id,
                    'debit': 0.0,
                    'credit': amount,
                }),
            ])

        if not move_lines:
            raise UserError(_('There is no pricing difference to modify.'))
        values = {
            'journal_id': journal.id,
            'company_id': self.company_id.id,
            'date': journal_date,
            'ref': revision_number,
            'line_ids': move_lines,
        }
        move = self.env['account.move'].create(values)
        self.with_context(grn_modification_internal=True).write({
            'account_move_ids': [(4, move.id)],
        })
        return move

    def confirm_modify(self):
        self._lock_receipt_lifecycle()
        self._check_receipt_revision_metadata()
        for record in self.sorted('id'):
            if record.receipt_revise <= 0 or not record.receipt_ref_id:
                raise UserError(_('This record is not a valid GRN modification.'))
            if record.state != 'draft':
                raise UserError(_('Only a Draft GRN modification can be confirmed.'))
            source = record.receipt_ref_id
            record._validate_grn_modification_source(
                source, company=record.company_id, current=record,
            )

            source.flush_recordset(['is_modified'])
            self.env.cr.execute(
                'SELECT id FROM eproc_receipt WHERE id = %s FOR UPDATE',
                [source.id],
            )
            source.invalidate_cache(
                fnames=['is_modified', 'state', 'payable_invoice_id', 'receipt_valid_date'],
            )
            record._validate_grn_modification_source(
                source, company=record.company_id, current=record,
            )
            if record.receipt_revise != source.receipt_revise + 1:
                raise UserError(_('The GRN revision number must immediately follow its source revision.'))
            if record.receipt_type != source.receipt_type:
                raise UserError(_('The GRN modification type must match its source.'))
            record._validate_grn_modification_integrity(source)

            revision_number = record._grn_modification_number(source, record.receipt_revise)
            validation_datetime = fields.Datetime.now()
            journal_date = fields.Date.context_today(record)
            record.with_context(grn_modification_internal=True).write({
                'receipt_no': revision_number,
                'receipt_valid_no': revision_number,
            })
            record.line_ids._compute_amounts()
            record.line_ids._compute_total_difference()
            record._compute_totals()
            record.line_ids.flush_recordset([
                'total_price', 'total_discount', 'total_taxes', 'total_netprice',
                'total_difference',
            ])
            record._create_grn_modification_accounting(journal_date)
            record.line_ids.with_context(
                skip_receipt_line_lock=True,
                grn_modification_internal=True,
            ).write({'state': 'done'})
            record.with_context(grn_modification_internal=True).write({
                'state': 'done',
                'receipt_valid_date': validation_datetime,
                'approval_next_stored': 'Completed',
                'is_modified': False,
            })
            source.with_context(grn_modification_internal=True).write({
                'is_modified': True,
            })
            record.message_post(body=_(
                'GRN pricing modification %s completed from source %s. No physical stock or TC transaction was created.'
            ) % (revision_number, source.receipt_valid_no or source.receipt_no))
        return True

    def action_confirm_srb(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Confirming records is not allowed from the DIL Goods Receiving view.')
        )
        self._lock_receipt_lifecycle()
        self._check_receipt_revision_metadata()
        for record in self.sorted('id'):
            if record.receipt_revise > 0 and record.receipt_ref_id:
                record.confirm_modify()
                continue
            if record.receipt_type != 'PO':
                raise UserError(_('Receiving Bay only supports Purchase Order receipts.'))
            if record.state != 'draft':
                raise UserError(_('Only Draft Receiving Bay records can be confirmed.'))
            record._validate_lines()
            record.with_context(skip_receipt_lock=True).write({'state': 'confirmed'})
            record.message_post(body=_('Receiving Bay confirmed. Waiting for Accounting validation.'))
        return True

    def action_confirm_srv(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Confirming records is not allowed from the DIL Goods Receiving view.')
        )
        self._lock_receipt_lifecycle()
        self._check_receipt_revision_metadata()
        for record in self.sorted('id'):
            if record.receipt_revise > 0 and record.receipt_ref_id:
                record.confirm_modify()
                continue
            if record.receipt_type == 'RT':
                raise UserError(_('Use Purchase Return confirmation for return records.'))
            if record.state not in ('draft', 'confirmed') and not (
                    record.receipt_type == 'WO' and record.state == 'rejected'):
                raise UserError(_('Only Draft or Confirmed receiving validation records can be confirmed.'))
            if record.receipt_type == 'PO' and record.state != 'confirmed':
                raise UserError(_('PO Receiving Validation must continue from a confirmed Receiving Bay record.'))
            if record.receipt_type == 'WO' and not record.approval_type_id:
                raise UserError(_('Approval Matrix is required for Without PO Receiving Validation.'))
            record._validate_lines()
            rules = record._get_enabled_approval_rules() if record.receipt_type == 'WO' else self.env[
                'eproc.approval.rule']
            if not rules:
                record._complete_receipt()
            else:
                last_reject_log = record.approval_ids.filtered(lambda log: log.state == 'rejected').sorted(
                    'approval_date', reverse=True)[:1]
                restart_approval = True
                comment = _('Receiving Validation %s is waiting for approval.') % record.receipt_no
                if record.receipt_type == 'WO' and last_reject_log and float_compare(record.total_netprice,
                                                                                     last_reject_log.amount_snapshot,
                                                                                     precision_digits=2) == 0:
                    restart_approval = False
                    comment = _(
                        'Revision accepted with consistent amount, please continue approval for %s.') % record.receipt_no
                if restart_approval:
                    record.approval_ids.write({'active': False})
                    record._create_approval_logs(rules)
                elif last_reject_log:
                    last_reject_log.write({
                        'state': 'pending',
                        'active': True,
                        'notes': _('Revision accepted with no amount change.'),
                    })
                    record.approval_ids.filtered(lambda log: log.sequence > last_reject_log.sequence).write(
                        {'active': True})
                record.with_context(skip_receipt_lock=True).write({'state': 'approval'})
                record._update_approval_flags()
                record.action_notify_approver(message=comment)
        return True

    def action_confirm_return(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Confirming records is not allowed from the DIL Goods Receiving view.')
        )
        self._lock_receipt_lifecycle()
        self._check_receipt_revision_metadata()
        for record in self.sorted('id'):
            if record.receipt_type != 'RT':
                raise UserError(_('Purchase Return only supports Vendor Return records.'))
            if record.state != 'draft':
                raise UserError(_('Only Draft Purchase Return records can be confirmed.'))
            record._validate_lines()
            record._complete_receipt()
        return True

    def _get_enabled_approval_rules(self):
        self.ensure_one()
        if not self.approval_type_id:
            return self.env['eproc.approval.rule']
        rules = self.approval_type_id.rule_ids
        if 'enabled' in rules._fields:
            rules = rules.filtered(lambda rule: rule.enabled)
        return rules.sorted(key=lambda rule: rule.sequence or 0)

    def _create_approval_logs(self, rules):
        self.ensure_one()
        values_list = []
        for rule in rules:
            position = rule.position_id
            user = self._find_user_for_position(position)
            values_list.append({
                'receipt_id': self.id,
                'approval_type_id': self.approval_type_id.id,
                'approval_rule_id': rule.id,
                'sequence': rule.sequence or 0,
                'position_id': position.id if position else False,
                'delegate_user_id': rule.delegate_user_id.id if rule.delegate_user_id else False,
                'amount_snapshot': self.total_netprice,
                'type': rule.type,
                'show': rule.show,
                'state': 'pending',
                'active': True,
            })
        if values_list:
            self.env['eproc.approval.log'].create(values_list)

    def _find_user_for_position(self, position):
        self.ensure_one()
        if not position:
            return self.env['res.users']
        domain = [('active', '=', True), ('position_id', '=', position.id)]
        if self.company_id:
            domain.append(('company_ids', 'in', [self.company_id.id]))
        return self.env['res.users'].search(domain, limit=1)

    def _get_current_pending_logs(self):
        self.ensure_one()
        return self.approval_ids.filtered(lambda log: log.active and log.state == 'pending')

    def _get_current_approval_log(self):
        self.ensure_one()
        return self._get_current_pending_logs().sorted(key=lambda log: log.sequence or 0)[:1]

    def _update_approval_flags(self):
        for record in self:
            current_log = record._get_current_approval_log()
            if current_log:
                next_name = current_log.position_id.name or current_log.user_id.name or _('Unknown')
                record.with_context(skip_receipt_lock=True).write({
                    'approval_rule_id': current_log.approval_rule_id.id,
                    'approval_rule_sequence': current_log.sequence or 0,
                    'approval_next_stored': next_name,
                })
            else:
                record.with_context(skip_receipt_lock=True).write({
                    'approval_rule_id': False,
                    'approval_rule_sequence': 0,
                    'approval_next_stored': 'Completed',
                })

    def _is_admin_user(self):
        return self.env.user.has_group('base.group_system')

    def _is_current_approver(self, approval_log):
        user = self.env.user
        if self._is_admin_user():
            return True
        position_ids = []
        if getattr(user, 'position_id', False):
            position_ids.append(user.position_id.id)
        if getattr(user, 'second_position_id', False):
            position_ids.append(user.second_position_id.id)
        return (
                (approval_log.position_id and approval_log.position_id.id in position_ids)
                or approval_log.user_id == user
                or approval_log.delegate_user_id == user
        )

    def action_approve(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Approving records is not allowed from the DIL Goods Receiving view.')
        )
        self._lock_receipt_lifecycle()
        self._check_receipt_revision_metadata()
        for record in self.sorted('id'):
            if record.receipt_type != 'WO':
                raise UserError(_('Only Without PO Receiving Validation uses approval.'))
            if record.state != 'approval':
                raise UserError(_('Only Receiving Validation records in Approval state can be approved.'))
            current_log = record._get_current_approval_log()
            if not current_log:
                raise UserError(_('There is no pending approval queue for this document.'))
            if not record._is_current_approver(current_log):
                raise UserError(_('Only the current approver can approve this receiving validation.'))
            current_log.with_context(skip_receipt_lock=True).write({
                'state': 'approved',
                'action_user_id': self.env.user.id,
                'approval_date': fields.Datetime.now(),
                'amount_snapshot': record.total_netprice,
                'notes': _('Approved by %s.') % (self.env.user.partner_id.name or self.env.user.name),
            })
            if record._get_current_approval_log():
                record._update_approval_flags()
                record.action_notify_approver()
            else:
                record._update_approval_flags()
                record._complete_receipt()
                record.action_notify_approver(message=_('Receiving Validation approval completed.'))
        return True

    def action_reject(self, reason=False):
        self._ensure_not_dil_goods_receiving_view(
            _('Rejecting records is not allowed from the DIL Goods Receiving view.')
        )
        for record in self:
            if record.receipt_type != 'WO':
                raise UserError(_('Only Without PO Receiving Validation uses approval rejection.'))
            if record.state != 'approval':
                raise UserError(_('Only Receiving Validation records in Approval state can be rejected.'))
            current_log = record._get_current_approval_log()
            if not current_log:
                raise UserError(_('There is no pending approval queue for this document.'))
            if not (record._is_current_approver(
                    current_log) or self.env.user == record.user_id or self._is_admin_user()):
                raise UserError(_('Only the Creator or Current Approver can reject this receiving validation.'))
            reason = reason or _('No reason provided')
            if current_log:
                current_log.with_context(skip_receipt_lock=True).write({
                    'state': 'rejected',
                    'action_user_id': self.env.user.id,
                    'approval_date': fields.Datetime.now(),
                    'amount_snapshot': record.total_netprice,
                    'notes': reason,
                })
            pending_logs = record._get_current_pending_logs()
            if pending_logs:
                pending_logs.with_context(skip_receipt_lock=True).write({'active': False})
            record.with_context(skip_receipt_lock=True).write({
                'state': 'rejected',
                'approval_next_stored': _('Rejected by %s') % self.env.user.name,
            })
            record.message_post(body=_('REJECTED: %s') % reason)
        return True

    def action_cancel(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Cancelling records is not allowed from the DIL Goods Receiving view.')
        )
        for record in self:
            if record.state not in ('confirmed', 'approval', 'draft'):
                raise UserError(_('Only Draft, Confirmed, or Approval receiving records can be cancelled.'))
            pending_logs = record._get_current_pending_logs()
            if pending_logs:
                pending_logs.with_context(skip_receipt_lock=True).write({'active': False})
            record.with_context(skip_receipt_lock=True).write({
                'state': 'cancelled',
                'approval_next_stored': _('Cancelled by %s') % self.env.user.name,
            })
            record.message_post(body=_('Receiving cancelled by %s.') % self.env.user.name)
        return True

    def action_draft(self):
        self._ensure_not_dil_goods_receiving_view(
            _('Resetting records to Draft is not allowed from the DIL Goods Receiving view.')
        )
        for record in self:
            if record.state not in ('cancelled', 'rejected'):
                raise UserError(_('Only Cancelled or Rejected receiving records can be reset to Draft.'))
            if record.receipt_type == 'WO' and record.state == 'rejected':
                record.approval_ids.sudo().unlink()
            record.with_context(skip_receipt_lock=True).write({
                'state': 'draft',
                'approval_rule_id': False,
                'approval_rule_sequence': 0,
                'approval_next_stored': False,
            })
        return True

    def _complete_receipt(self):
        # Revalidate at the actual stock/accounting boundary, also after approval.
        self._lock_receipt_lifecycle()
        self._check_physical_receipts()
        for record in self.sorted('id'):
            allowed_states = ('confirmed',) if record.receipt_type == 'PO' else (
                ('draft',) if record.receipt_type == 'RT' else ('draft', 'confirmed', 'approval', 'rejected'))
            if record.state not in allowed_states:
                raise UserError(_('This receiving document cannot be completed in its current state.'))
            # A batch can contain multiple receipts for the same PO. Each receipt
            # must see the preceding receipt's completed quantity in this transaction.
            record._validate_lines()
            if record.receipt_type == 'PO' and not record.receipt_valid_no:
                record.with_context(skip_receipt_lock=True).write({
                    'receipt_valid_no': record._next_sequence(record.receipt_type, valid=True,
                                                              company=record.company_id),
                })
            if record.receipt_type in ('WO', 'RT') and not record.receipt_valid_no:
                record.with_context(skip_receipt_lock=True).write({'receipt_valid_no': record.receipt_no})
            record._create_stock_impacts()
            record._create_accounting_impacts()
            record._mark_lines_done()
            # TC interfacing must see the final document state/date and completed impacts.
            record.with_context(skip_receipt_lock=True).write({
                'state': 'done',
                'receipt_valid_date': fields.Datetime.now(),
                'approval_next_stored': 'Completed',
            })
            record.action_interfacing()
            record.message_post(body=_('Receiving completed. Stock and accounting entries were created.'))

    def _mark_lines_done(self):
        for record in self:
            record.line_ids.with_context(skip_receipt_line_lock=True).write({'state': 'done'})
            for order_line in record.line_ids.mapped('order_line_id'):
                completed_lines = order_line.receipt_line_ids.filtered(
                    lambda line: (
                        line.receipt_id.receipt_revise == 0
                        and (line.receipt_id.state == 'done' or line.receipt_id == record)
                    )
                )
                received = sum(completed_lines.filtered(lambda line: not line.is_return).mapped('pack_receipt'))
                returned = sum(completed_lines.filtered(lambda line: line.is_return).mapped('pack_receipt'))
                processed = max(received - returned, 0.0)
                values = {}
                if 'pack_processed' in order_line._fields:
                    values['pack_processed'] = processed
                elif 'pack_qty_processed' in order_line._fields:
                    values['pack_qty_processed'] = processed
                pack_rate = order_line.pack_rate or order_line.pack_id.rate_value or 1.0
                if 'uom_processed' in order_line._fields:
                    values['uom_processed'] = processed * pack_rate
                elif 'uom_qty_processed' in order_line._fields:
                    values['uom_qty_processed'] = processed * pack_rate
                # Return must not reopen a rebalanced item or release more PR allocation.
                if order_line.pack_qty_rebalanced or order_line.uom_qty_rebalanced:
                    values['state'] = 'expired' if order_line.state == 'expired' else 'closed'
                elif processed <= 0:
                    values['state'] = 'ready'
                elif processed < (order_line.pack_qty or 0.0):
                    values['state'] = 'partial'
                else:
                    values['state'] = 'done'
                order_line.write(values)

    def _get_eproc_stock_balance(self, product_tmpl, location, lot=False, order_line=False):
        self.ensure_one()
        domain = [
            ('active', '=', True),
            ('state', '=', 'done'),
            ('company_id', '=', self.company_id.id),
            ('product_tmpl_id', '=', product_tmpl.id),
            ('location_id', '=', location.id),
        ]
        if lot:
            domain.append(('lot_id', '=', lot.id))
        if order_line:
            domain.append(('order_line_id', '=', order_line.id))
        moves = self.env['eproc.stock.move'].search(domain)
        return sum(moves.mapped('uom_quantity'))

    def _lock_eproc_stock_balance(self, line):
        """Serialize returns for one ledger balance to prevent concurrent over-return."""
        self.ensure_one()
        lock_key = 'eproc.stock.move:%s:%s:%s:%s:%s' % (
            self.company_id.id,
            line.product_tmpl_id.id,
            self.location_receipt_id.id,
            line.lot_id.id or 0,
            line.order_line_id.id or 0,
        )
        self.env.cr.execute('SELECT pg_advisory_xact_lock(hashtext(%s))', [lock_key])

    def _validate_return_stock_balance(self, line, quantity):
        self.ensure_one()
        self._lock_eproc_stock_balance(line)
        available = self._get_eproc_stock_balance(
            line.product_tmpl_id,
            self.location_receipt_id,
            lot=line.lot_id,
            order_line=line.order_line_id,
        )
        rounding = line.uom_id.rounding if line.uom_id else 0.01
        if float_compare(quantity, available, precision_rounding=rounding) > 0:
            lot_name = line.lot_id.display_name or line.lot_name or _('N/A')
            raise UserError(_(
                'Return quantity cannot exceed available received quantity for %s / lot %s.'
            ) % (line.product_tmpl_id.display_name, lot_name))

    @api.model
    def _get_lot_expiry(self, line):
        if line.lot_expiration_date:
            return line.lot_expiration_date
        lot = line.lot_id
        for field_name in ('expiration_date', 'life_date', 'use_date'):
            if lot and field_name in lot._fields and lot[field_name]:
                return lot[field_name]
        return False

    @api.model
    def _format_lot_expiry_date(self, line):
        lot_expiry = self._get_lot_expiry(line)
        return fields.Date.to_string(fields.Date.to_date(lot_expiry)) if lot_expiry else False

    def _create_stock_impacts(self):
        StockMove = self.env['eproc.stock.move']
        for record in self:
            for line in record.line_ids:
                if 'eproc_move_id' in line._fields and line.eproc_move_id:
                    continue
                existing_move = StockMove.search([
                    ('receipt_line_id', '=', line.id),
                    ('active', '=', True),
                ], limit=1)
                if existing_move:
                    if 'eproc_move_id' in line._fields:
                        line.with_context(skip_receipt_line_lock=True).write({
                            'eproc_move_id': existing_move.id,
                        })
                    continue
                if not line.product_tmpl_id:
                    raise UserError(_('Product is required on all receiving lines.'))
                if line.product_tmpl_id.tracking_type == 'lot' and record.receipt_type not in ('RT', 'PRT'):
                    line._ensure_lot()
                qty = line.uom_receipt
                rounding = line.uom_id.rounding if line.uom_id else 0.01
                if not record.location_receipt_id:
                    raise UserError(_('Destination Location is required.'))
                if float_compare(qty, 0.0, precision_rounding=rounding) <= 0:
                    raise UserError(
                        _('Stock move quantity must be greater than zero for %s.') % line.product_tmpl_id.display_name)

                move_type = 'GOODS_RETURN' if record.receipt_type in ('RT', 'PRT') else 'GOODS_RECEIVE'
                uom_quantity = abs(qty)
                pack_quantity = abs(line.pack_receipt)
                if record.receipt_type in ('RT', 'PRT'):
                    if line.product_tmpl_id.tracking_type == 'lot' and not line.lot_id:
                        raise UserError(
                            _('An existing Batch/Lot is required for return of %s.') % line.product_tmpl_id.display_name)
                    record._validate_return_stock_balance(line, qty)
                    uom_quantity = -abs(qty)
                    pack_quantity = -abs(line.pack_receipt)
                    if line.lot_id:
                        lot_expiry = record._get_lot_expiry(line)
                        line.with_context(skip_receipt_line_lock=True).write({
                            'lot_name': line.lot_id.name,
                            'lot_expiration_date': fields.Date.to_string(
                                fields.Date.to_date(lot_expiry)) if lot_expiry else False,
                        })
                elif record.receipt_type not in ('PO', 'WO'):
                    raise UserError(_('Unsupported receiving type for stock impact: %s.') % record.receipt_type)

                eproc_lot = line.lot_id.sudo() if line.lot_id else False

                move_vals = {
                    'move_type': move_type,
                    'move_no': record.receipt_valid_no or record.receipt_no,
                    'move_ref': record.receipt_ref,
                    'move_datetime': fields.Datetime.now(),
                    'receipt_id': record.id,
                    'receipt_line_id': line.id,
                    'order_id': line.order_line_id.order_id.id if line.order_line_id else False,
                    'order_line_id': line.order_line_id.id if line.order_line_id else False,
                    'company_id': record.company_id.id,
                    'supplier_id': record.supplier_id.id if record.supplier_id else False,
                    'product_tmpl_id': line.product_tmpl_id.id,
                    'product_code': line.product_tmpl_id.default_code,
                    'product_name': line.product_tmpl_id.display_name,
                    'category_id': line.product_categ_id.id or line.product_tmpl_id.categ_id.id,
                    'category_code': (line.product_categ_id or line.product_tmpl_id.categ_id).categ_code,
                    'uom_id': line.uom_id.id,
                    'uom_code': line.uom_id.name,
                    'uom_quantity': uom_quantity,
                    'pack_id': line.pack_id.id if line.pack_id else False,
                    'pack_quantity': pack_quantity,
                    'location_id': record.location_receipt_id.id,
                    'location_code': record.location_receipt_id.code,
                    'location_name': record.location_receipt_id.display_name,
                    'lot_id': eproc_lot.id if eproc_lot else False,
                    'lot_code': eproc_lot.code if eproc_lot else False,
                    'lot_name': eproc_lot.name if eproc_lot else False,
                    'lot_expiry': eproc_lot.expiration_date if eproc_lot else False,
                    'cost_unit': line.uom_netprice or line.uom_price or 0.0,
                    'cost_total': line.total_netprice or 0.0,
                    'state': 'done',
                }
                try:
                    with self.env.cr.savepoint():
                        move = StockMove.with_context(from_system=True).create(move_vals)
                except Exception as err:
                    record.message_post(body=_('Automatic stock move/quant update failed: %s') % err)
                    raise
                # line.move_id is native stock.move. The custom eproc.stock.move ledger must be stored only in eproc_move_id.
                if 'eproc_move_id' in line._fields:
                    line.with_context(skip_receipt_line_lock=True).write({
                        'eproc_move_id': move.id,
                    })

    def _create_eproc_ledger_move(self, line, qty):
        """Create the custom SCM stock ledger row for a receipt line."""
        self.ensure_one()
        if line.eproc_move_id:
            return line.eproc_move_id
        company = self.company_id
        is_return = self.receipt_type == 'RT'
        location = self.location_receipt_id
        categ = line.product_categ_id or line.product_tmpl_id.categ_id
        order_line = line.order_line_id
        request_line = order_line.request_line_id if order_line and 'request_line_id' in order_line._fields else False
        eproc_lot = line.lot_id.sudo() if line.lot_id else False
        moment = self.receipt_valid_date or fields.Datetime.now()
        order_item_no = order_line.sequence if order_line else line.sequence
        move = self.env['eproc.stock.move'].sudo().with_context(from_system=True).create({
            'move_type': 'GOODS_RETURN' if is_return else 'GOODS_RECEIVE',
            'move_ref': self.receipt_ref or self.receipt_valid_no or self.receipt_no,
            'move_date': moment,
            'move_datetime': moment,
            'product_tmpl_id': line.product_tmpl_id.id,
            'product_code': line.product_tmpl_id.default_code,
            'product_name': line.product_tmpl_id.name,
            'category_id': categ.id if categ else False,
            'category_code': categ.categ_code if categ else False,
            'uom_id': line.uom_id.id,
            'uom_code': line.uom_id.name,
            'uom_quantity': (-1.0 if is_return else 1.0) * (qty or 0.0),
            'location_id': location.id if location else False,
            'location_code': location.code if location else False,
            'location_name': location.display_name if location else False,
            'lot_id': eproc_lot.id if eproc_lot else False,
            'lot_code': eproc_lot.code if eproc_lot else False,
            'lot_name': eproc_lot.name if eproc_lot else False,
            'lot_expiry': eproc_lot.expiration_date if eproc_lot else False,
            'state': 'done',
            'order_no': self.order_id.order_no if self.order_id else False,
            'order_item_no': str(order_item_no) if order_item_no else False,
            'order_id': str(self.order_id.id) if self.order_id else False,
            'order_item_id': str(line.order_line_id.id) if line.order_line_id else False,
            'cost_unit': 0.0,
            'cost_total': 0.0,
            'company_code': company.company_code,
            'company_id': company.id,
        })
        line.with_context(skip_receipt_line_lock=True).write({'eproc_move_id': move.id})
        return move

    def _get_receipt_accounts(self, line):
        category = line.product_tmpl_id.categ_id
        inventory = category.property_stock_valuation_account_id
        input_account = category.property_stock_account_input_categ_id
        if not inventory or not input_account:
            raise UserError(
                _('Please configure inventory valuation and stock input accounts for %s.') % line.product_tmpl_id.display_name)
        return inventory, input_account

    def _create_accounting_impacts(self):
        AccountMove = self.env['account.move']
        for record in self:
            if record.account_move_ids:
                continue
            journal = self.env['account.journal'].search([
                ('name', 'ilike', 'Stock Journal'),
                ('company_id', '=', record.company_id.id),
            ], limit=1)
            if not journal:
                journal = self.env['account.journal'].search([
                    ('type', '=', 'general'),
                    ('company_id', '=', record.company_id.id),
                ], limit=1)
            if not journal:
                raise UserError(_('No Stock Journal/general journal found for %s.') % record.company_id.display_name)
            move_lines = []
            for line in record.line_ids:
                if float_is_zero(line.total_netprice, precision_digits=2):
                    continue
                inventory, input_account = record._get_receipt_accounts(line)
                amount = abs(line.total_netprice)
                if record.receipt_type == 'RT':
                    debit_account = input_account
                    credit_account = inventory
                else:
                    debit_account = inventory
                    credit_account = input_account
                move_lines.append((0, 0, {
                    'name': line.name or record.name,
                    'account_id': debit_account.id,
                    'partner_id': record.supplier_id.id,
                    'debit': amount,
                    'credit': 0.0,
                }))
                move_lines.append((0, 0, {
                    'name': line.name or record.name,
                    'account_id': credit_account.id,
                    'partner_id': record.supplier_id.id,
                    'debit': 0.0,
                    'credit': amount,
                }))
            if move_lines:
                values = {
                    'journal_id': journal.id,
                    'date': fields.Date.context_today(record),
                    'ref': record.receipt_valid_no or record.receipt_no,
                    'line_ids': move_lines,
                }
                if 'company_id' in AccountMove._fields:
                    values['company_id'] = record.company_id.id
                move = AccountMove.create(values)
                record.with_context(skip_receipt_lock=True).write({'account_move_ids': [(4, move.id)]})

    def _tc_field_value(self, record, field_name, default=False):
        if record and field_name in record._fields:
            value = record[field_name]
            return value if value is not False else default
        return default

    def _tc_date_to_string(self, value):
        if not value:
            return False
        if isinstance(value, str):
            return value[:10]
        return fields.Date.to_string(fields.Date.to_date(value))

    def _tc_validate_receipt_data(self):
        self.ensure_one()
        self._validate_required_locations()
        if not self.receipt_valid_no:
            raise UserError(_('Receiving Valid No is required for TC sync.'))
        if not self.receipt_valid_date:
            raise UserError(_('Receiving Valid Date is required for TC sync.'))
        if not self.company_id.company_code:
            raise UserError(_('Company Code is required for TC sync.'))
        if not self.location_receipt_id.code:
            raise UserError(_('Destination Location Code is required for TC sync.'))
        stock_lines = self._get_tc_eligible_lines()
        if not stock_lines:
            raise UserError(_('No stock product lines are available to send to TC.'))
        for line in stock_lines:
            if not line.product_tmpl_id:
                raise UserError(_('Product is required on all receiving lines for TC sync.'))
            product_name = line.product_tmpl_id.display_name
            if not line.product_tmpl_id.default_code:
                raise UserError(_('Product Code is required for TC sync of %s.') % product_name)
            category = line.product_categ_id or line.product_tmpl_id.categ_id
            if not category or not category.categ_code:
                raise UserError(_('Product Category Code is required for TC sync of %s.') % product_name)
            if not line.uom_id or not line.uom_id.uom_code:
                raise UserError(_('UoM Code is required for TC sync of %s.') % product_name)
            rounding = line.uom_id.rounding or 0.01
            if float_is_zero(line.uom_receipt or 0.0, precision_rounding=rounding):
                raise UserError(_('TC sync UoM receipt quantity must not be zero for %s.') % product_name)
            if line.product_tmpl_id.tracking_type == 'lot' and not (line.lot_id or line.lot_name):
                raise UserError(_('Batch/Lot is required for TC sync of %s.') % line.product_tmpl_id.display_name)

    def _get_tc_eligible_lines(self):
        self.ensure_one()
        return self.line_ids.filtered(
            lambda line: line.product_tmpl_id and line.product_tmpl_id.eproc_type == 'stock'
        )

    def _prepare_tc_interfacing_lines(self):
        self.ensure_one()
        receipt_no = self.receipt_valid_no or self.receipt_no
        receipt_date = self._tc_date_to_string(self.receipt_valid_date or self.receipt_date)
        origin = self.receipt_origin or self.receipt_ref
        location = self.location_receipt_id
        supplier_location = self.location_supplier_id
        company = self.company_id
        responsible = self.user_id.partner_id.name or self.user_id.name
        result = []

        for line in self._get_tc_eligible_lines():
            product = line.product_tmpl_id
            category = line.product_categ_id or self._tc_field_value(product, 'item_category_id') or product.categ_id
            lot = line.lot_id
            qty = abs(line.uom_receipt or 0.0)
            if self.receipt_type in ('RT', 'PRT'):
                qty = -qty
            result.append({
                'receipt_no': receipt_no,
                'receipt_date': receipt_date,
                'origin': origin,
                'supplier_code': '001',
                'supplier_name': 'ERP',
                'item_code': product.default_code,
                'item_name': product.display_name or product.name,
                'item_categ_code': self._tc_field_value(category, 'categ_code') or self._tc_field_value(category,
                                                                                                        'code'),
                'item_categ_name': category.display_name if category else False,
                'uom_code': self._tc_field_value(line.uom_id, 'uom_code') or self._tc_field_value(line.uom_id,
                                                                                                  'code') or line.uom_id.name,
                'uom_name': line.uom_id.name,
                'uom_quantity': qty,
                'location_code': self._tc_field_value(location, 'code') or self._tc_field_value(location, 'barcode'),
                'location_name': location.display_name if location else False,
                'supplier_location_code': self._tc_field_value(supplier_location, 'code') or self._tc_field_value(
                    supplier_location, 'barcode'),
                'supplier_location_name': supplier_location.display_name if supplier_location else False,
                'lot_code': self._tc_field_value(lot, 'code'),
                'lot_name': line.lot_name or (lot.name if lot else False),
                'lot_expiry': self._format_lot_expiry_date(line),
                'responsible': responsible,
                'company_code': self._tc_field_value(company, 'company_code'),
            })
        return result

    def _prepare_tc_api_receipt_line(self, line):
        self.ensure_one()
        quantity = abs(line.uom_receipt or 0.0)
        rounding = line.uom_id.rounding or 0.01
        if float_is_zero(quantity, precision_rounding=rounding):
            raise UserError(
                _('TC sync UoM receipt quantity must not be zero for %s.')
                % line.product_tmpl_id.display_name
            )

        sign = -1 if self.receipt_type == 'RT' else 1
        total_price = abs(line.total_price or 0.0)
        total_discount = abs(line.total_discount or 0.0)
        total_taxes = abs(line.total_taxes or 0.0)
        total_netprice = abs(line.total_netprice or 0.0)
        category = line.product_categ_id or line.product_tmpl_id.categ_id

        return {
            'sequence': line.sequence,
            'product_tmpl_id': line.product_tmpl_id.default_code,
            'product_categ_id': category.categ_code,
            'name': line.name,
            'lot_name': line.lot_name or (line.lot_id.name if line.lot_id else False),
            'lot_expiration_date': self._format_lot_expiry_date(line),
            'uom_id': line.uom_id.uom_code,
            'uom_receipt': sign * quantity,
            'uom_price': float_round(total_price / quantity, precision_digits=2),
            'uom_netprice': float_round(
                (total_price - total_discount) / quantity,
                precision_digits=2,
            ),
            'uom_discount': float_round(total_discount / quantity, precision_digits=2),
            'uom_taxes': float_round(total_taxes / quantity, precision_digits=2),
            'total_price': sign * total_price,
            'total_discount': sign * total_discount,
            'total_taxes': sign * total_taxes,
            'total_netprice': sign * total_netprice,
        }

    def _prepare_tc_api_receipt_lines(self):
        self.ensure_one()
        return [
            self._prepare_tc_api_receipt_line(line)
            for line in self._get_tc_eligible_lines()
        ]

    def _prepare_tc_receipt_payload(self):
        self.ensure_one()
        sign = -1 if self.receipt_type == 'RT' else 1
        return {
            'receipt_valid_date': self._tc_date_to_string(self.receipt_valid_date),
            'receipt_valid_no': self.receipt_valid_no,
            'receipt_ref': self.receipt_ref,
            'receipt_origin': self.receipt_origin,
            'receipt_type': self.receipt_type,
            'company_id': self.company_id.company_code,
            'location_receipt_id': self.location_receipt_id.code,
            'supplier_id': '0001',
            'notes': self.notes,
            'total_amount': sign * abs(self.total_price or 0.0),
            'total_discount': sign * abs(self.total_discount or 0.0),
            'total_taxes': sign * abs(self.total_taxes or 0.0),
            'total_net': sign * abs(self.total_netprice or 0.0),
            'line_ids': self._prepare_tc_api_receipt_lines(),
        }

    def _prepare_tc_receipt_txt_content(self):
        self.ensure_one()
        delimiter = '^^^'
        empty_value = '-'

        def clean(value):
            if value in (False, None):
                return empty_value

            value = str(value).replace(delimiter, ' ')
            for char in ('\n', '\r', '\t'):
                value = value.replace(char, ' ')

            value = value.strip()
            return value or empty_value

        columns = [
            'receipt_no',
            'receipt_date',
            'origin',
            'supplier_code',
            'supplier_name',
            'item_code',
            'item_name',
            'item_categ_code',
            'item_categ_name',
            'uom_code',
            'uom_name',
            'uom_quantity',
            'location_code',
            'location_name',
            'supplier_location_code',
            'supplier_location_name',
            'lot_code',
            'lot_name',
            'lot_expiry',
            'responsible',
            'company_code',
        ]

        rows = [
            delimiter.join(clean(line.get(column)) for column in columns)
            for line in self._prepare_tc_interfacing_lines()
        ]

        return '\n'.join(rows) + ('\n' if rows else '')

    def _is_tc_interface_success(self):
        self.ensure_one()
        if self.env.context.get('force_tc_interface'):
            return False
        status = (self.state_tc or self.api_post_status or '').strip().lower()
        return status in ('sent', 'success', 'generated', 'done', 'completed')

    def _write_tc_log(self, status=False, payload=False, response=False, log=False, log_sharing_fullpath=False,
                      log_filename=False):
        def _pretty_log_text(value):
            if value is False:
                return False
            if isinstance(value, (dict, list)):
                return json.dumps(value, indent=2, default=str)
            if isinstance(value, str):
                try:
                    parsed = json.loads(value)
                    return json.dumps(parsed, indent=2, default=str)
                except Exception:
                    return value
            return str(value)

        for record in self:
            values = {}

            if payload is not False and 'api_post_payload' in record._fields:
                values['api_post_payload'] = _pretty_log_text(payload)

            if response is not False and 'api_post_response' in record._fields:
                values['api_post_response'] = _pretty_log_text(response)

            if status is not False and 'api_post_status' in record._fields:
                values['api_post_status'] = status

            if 'api_post_timestamp' in record._fields:
                values['api_post_timestamp'] = fields.Datetime.now()

            if status in ('pending', 'sent', 'failed') and 'state_tc' in record._fields:
                values['state_tc'] = status

            if 'log_lastupdate' in record._fields:
                values['log_lastupdate'] = fields.Datetime.now()

            if values:
                record.with_context(skip_receipt_lock=True).write(values)

            if log:
                log_values = {}

                if status in ('pending', 'sent', 'failed'):
                    log_values['state_tc'] = status

                if response is not False:
                    log_values['log_response'] = _pretty_log_text(response)

                if payload is not False:
                    log_values['log_payload'] = _pretty_log_text(payload)

                if log_sharing_fullpath:
                    log_values['log_sharing_fullpath'] = log_sharing_fullpath

                if log_filename:
                    log_values['log_filename'] = log_filename

                if log_values:
                    log.sudo().write(log_values)

    def _create_tc_interfacing_log(self, payload, log_type, txt_content=False):
        self.ensure_one()
        company = self.company_id
        payload_content = txt_content if txt_content is not False else json.dumps(payload, indent=2, default=str)
        log = self.env['eproc.receipt.log'].sudo().create({
            'receipt_id': self.id,
            'receipt_valid_no': self.receipt_valid_no or self.receipt_no,
            'company_id': company.id if company else False,
            'log_user_id': self.env.user.id,
            'log_datetime': fields.Datetime.now(),
            'log_payload': payload_content,
            'log_type': log_type,
            'log_api_url': company.sync_tc_api_url if company and log_type == 'api' and 'sync_tc_api_url' in company._fields else False,
            'log_sharing_path': company.sync_tc_sharing_path if company and log_type == 'txt' and 'sync_tc_sharing_path' in company._fields else False,
            'state_tc': 'pending',
        })
        self._write_tc_log(status='pending', payload=payload_content, response=_('TC sync pending.'), log=log)
        return log

    def _is_tc_login_response(self, response):
        content_type = (response.headers.get('Content-Type') or '').lower()
        body = (response.text or '').lower()
        return (
                'text/html' in content_type
                or '<form' in body and ('/web/login' in body or 'login' in body)
                or 'odoo' in body and 'login' in body
        )

    def _send_tc_by_api(self, payload, log):
        self.ensure_one()
        company = self.company_id
        url = company.sync_tc_api_url if company and 'sync_tc_api_url' in company._fields else False
        if not url:
            message = _('TC API URL is not configured.')
            self._write_tc_log(status='failed', payload=payload, response=message, log=log)
            self.message_post(body=message)
            if self.env.context.get('force_tc_interface'):
                raise UserError(message)
            return False

        headers = {'Content-Type': 'application/json'}
        auth = None
        token = False
        for field_name in ('sync_tc_token', 'sync_tc_api_token', 'sync_tc_auth_token'):
            token = self._tc_field_value(company, field_name)
            if token:
                headers['Authorization'] = 'Bearer %s' % token
                break
        api_key = self._tc_field_value(company, 'sync_tc_api_key')
        if api_key:
            headers['X-API-Key'] = api_key
        login = self._tc_field_value(company, 'sync_tc_api_login') or self._tc_field_value(company, 'sync_tc_login')
        password = self._tc_field_value(company, 'sync_tc_api_password') or self._tc_field_value(company,
                                                                                                 'sync_tc_password')
        if login and password:
            auth = (login, password)

        # API sender: plain JSON unless TC auth fields are configured on company.
        try:
            response = requests.post(url, json=payload, headers=headers, auth=auth, timeout=30)
            response_text = response.text or ''
            status = 'sent' if 200 <= response.status_code < 300 and not self._is_tc_login_response(
                response) else 'failed'
            self._write_tc_log(status=status, payload=payload, response=response_text, log=log)
            if status == 'sent':
                self.message_post(body=_('TC API sync success.'))
                return True
            message = _('TC API sync failed with HTTP %s: %s') % (response.status_code, response_text)
            self.message_post(body=message)
            if self.env.context.get('force_tc_interface'):
                raise UserError(message)
            return False
        except requests.RequestException as err:
            message = _('TC API sync failed: %s') % err
            self._write_tc_log(status='failed', payload=payload, response=message, log=log)
            self.message_post(body=message)
            if self.env.context.get('force_tc_interface'):
                raise UserError(message)
            return False

    def _generate_tc_txt(self, txt_content, log):
        self.ensure_one()
        company = self.company_id
        base_dir = company.sync_tc_sharing_path if company and 'sync_tc_sharing_path' in company._fields else False

        def fail(message):
            self._write_tc_log(status='failed', payload=txt_content, response=message, log=log)
            self.message_post(body=message)
            if self.env.context.get('force_tc_interface'):
                raise UserError(message)
            return False

        if not base_dir:
            return fail(_('TC sharing path is not configured.'))
        if not os.path.isdir(base_dir):
            return fail(_('TC sharing path is not a directory: %s') % base_dir)
        if not os.access(base_dir, os.W_OK):
            return fail(_('TC sharing path is not writable: %s') % base_dir)

        target_dir = os.path.join(base_dir, 'receiving')
        receipt_no = self.receipt_valid_no or self.receipt_no or 'receipt'
        safe_receipt_no = re.sub(r'[^A-Za-z0-9_.-]+', '_',
                                 receipt_no.replace('/', '_').replace('\\', '_').replace(':', '_').replace(' ', '_'))
        receipt_date = fields.Date.to_date(
            self.receipt_valid_date or self.receipt_date or fields.Date.context_today(self))
        filename = '%s_%s.txt' % (receipt_date.strftime('%Y%m%d'), safe_receipt_no)
        full_path = os.path.join(target_dir, filename)
        try:
            os.makedirs(target_dir, exist_ok=True)
            with open(full_path, 'w', encoding='utf-8') as txt_file:
                txt_file.write(txt_content)
            attachment = self.env['ir.attachment'].sudo().create({
                'name': filename,
                'res_model': 'eproc.receipt',
                'res_id': self.id,
                'type': 'binary',
                'datas': base64.b64encode(txt_content.encode('utf-8')).decode('ascii'),
                'mimetype': 'text/plain',
            })
            if log:
                log.sudo().write({
                    'attachment_id': attachment.id,
                })
            self._write_tc_log(
                status='sent',
                payload=txt_content,
                response=full_path,
                log=log,
                log_sharing_fullpath=full_path,
                log_filename=filename,
            )
            self.message_post(body=_('TC TXT generated: %s') % full_path)
            return True
        except OSError as err:
            return fail(_('TC TXT generation failed: %s') % err)

    def action_interfacing(self):
        # Receiving TC integration uses the Feature 815 API JSON contract only.
        success = True
        for record in self:
            if record.receipt_revise > 0 and record.receipt_ref_id:
                raise UserError(_('GRN modifications cannot be sent to TrackCare.'))
            if record.state != 'done':
                if record.env.context.get('force_tc_interface'):
                    raise UserError(_('TC sync can only run after the receipt is completed.'))
                continue
            if record.receipt_type not in ('PO', 'WO', 'RT'):
                continue
            if record._is_tc_interface_success():
                record.message_post(body=_('TC sync skipped because it was already completed.'))
                continue

            stock_lines = record._get_tc_eligible_lines()
            if not stock_lines:
                message = _('No stock product lines are available to send to TC.')
                if record.env.context.get('force_tc_interface'):
                    raise UserError(message)
                record.message_post(body=_(
                    'Automatic TC sync was skipped because this document does not contain any stock product lines.'
                ))
                continue

            company = record.company_id
            if not company or 'sync_tc_active' not in company._fields or not company.sync_tc_active:
                message = _('TC sync skipped because it is disabled for this company.')
                record.message_post(body=message)
                continue

            payload = None
            log = False
            try:
                if company.sync_tc_type != 'api':
                    raise UserError(_(
                        'Receiving TrackCare integration supports API JSON only. '
                        'Configure the company TC Sync Type as API (sync_tc_type = api).'
                    ))
                record._tc_validate_receipt_data()
                payload = record._prepare_tc_receipt_payload()
                log = record._create_tc_interfacing_log(payload, 'api')
                success = record._send_tc_by_api(payload, log) and success
            except UserError as err:
                message = str(err)
                record._write_tc_log(
                    status='failed',
                    payload=payload if payload is not None else False,
                    response=message,
                    log=log,
                )
                record.message_post(body=_('TC sync failed: %s') % message)
                if record.env.context.get('force_tc_interface'):
                    raise
                success = False
            except Exception as err:
                _logger.exception('Unexpected TC sync failure for eproc.receipt %s', record.id)
                message = _('TC sync failed: %s') % err
                record._write_tc_log(
                    status='failed',
                    payload=payload if payload is not None else False,
                    response=message,
                    log=log,
                )
                record.message_post(body=message)
                if record.env.context.get('force_tc_interface'):
                    raise UserError(message)
                success = False
        return success

    def action_retry_interfacing_tc(self):
        self.ensure_one()
        source = self.env.context.get('retry_tc_source') or self._get_retry_tc_default_source()
        self._validate_retry_interfacing_tc_batch(source)
        affected_receipts = self._get_retry_tc_affected_receipts(source)
        warning_receipts = affected_receipts._get_retry_tc_previously_sent_receipts()
        warning_logs = warning_receipts._get_retry_tc_confirmation_logs()
        if not self.env.context.get('retry_tc_confirmed'):
            return self._open_retry_tc_confirmation_wizard(
                warning_logs,
                source,
                affected_receipts=affected_receipts,
                warning_receipts=warning_receipts,
                retry_mode='single',
            )
        return affected_receipts._execute_retry_interfacing_tc_single()

    def _get_retry_tc_document_name(self):
        self.ensure_one()
        return self.receipt_valid_no or self.receipt_no or self.display_name

    def _get_retry_tc_default_source(self):
        receipt_types = set(self.mapped('receipt_type'))
        if receipt_types and receipt_types <= {'PO', 'WO'}:
            return 'receiving_validation'
        if receipt_types and receipt_types <= {'RT'}:
            return 'purchase_return'
        return False

    def _get_retry_tc_affected_receipts(self, source=False):
        self._validate_retry_interfacing_tc_batch(source)
        affected_receipts = self.filtered(lambda receipt: bool(receipt._get_tc_eligible_lines()))
        if not affected_receipts:
            raise UserError(_('No stock product lines are available to send to TC.'))
        return affected_receipts

    def _execute_retry_interfacing_tc_single(self):
        self.ensure_one()
        self._ensure_not_dil_goods_receiving_view(
            _('Retrying TC sync is not allowed from the DIL Goods Receiving view.')
        )
        self.with_context(force_tc_interface=True).action_interfacing()
        return True

    def _validate_retry_interfacing_tc_batch(self, source=False):
        if not self:
            raise UserError(_('Please select at least one receiving document.'))
        self._ensure_not_dil_goods_receiving_view(
            _('Retrying TC sync is not allowed from the DIL Goods Receiving view.')
        )

        if self.filtered(lambda receipt: receipt.receipt_revise > 0 and receipt.receipt_ref_id):
            raise UserError(_('GRN modifications cannot be sent or retried to TrackCare.'))

        invalid_state_receipts = self.filtered(lambda receipt: receipt.state != 'done')
        if invalid_state_receipts:
            invalid_names = '\n'.join(
                '- %s' % receipt._get_retry_tc_document_name()
                for receipt in invalid_state_receipts
            )
            raise UserError(_(
                'Only completed receiving documents can be retried.\n\n'
                'Invalid documents:\n%s'
            ) % invalid_names)

        allowed_types_by_source = {
            'receiving_validation': ('PO', 'WO'),
            'purchase_return': ('RT',),
        }
        if source not in allowed_types_by_source:
            raise UserError(_('Invalid TC retry source.'))

        allowed_types = allowed_types_by_source[source]
        invalid_type_receipts = self.filtered(
            lambda receipt: receipt.receipt_type not in allowed_types
        )
        if invalid_type_receipts:
            invalid_names = '\n'.join(
                '- %s (%s)' % (
                    receipt._get_retry_tc_document_name(),
                    receipt.receipt_type or '-',
                )
                for receipt in invalid_type_receipts
            )
            if source == 'receiving_validation':
                message = _(
                    'Retry TC Sync from Receiving Validation only accepts '
                    'Purchase Order and Without PO receiving documents.'
                )
            else:
                message = _(
                    'Retry TC Sync from Purchase Return only accepts '
                    'Vendor Return documents.'
                )
            raise UserError(_('%s\n\nInvalid documents:\n%s') % (
                message,
                invalid_names,
            ))
        return True

    def _get_retry_tc_confirmation_logs(self):
        if not self:
            return self.env['eproc.receipt.log']
        return self.env['eproc.receipt.log'].with_context(
            active_test=False
        ).search([
            ('receipt_id', 'in', self.ids),
            ('state_tc', '=', 'sent'),
        ])

    def _get_retry_tc_previously_sent_receipts(self):
        if not self:
            return self.env['eproc.receipt']
        sent_logs = self._get_retry_tc_confirmation_logs()
        return sent_logs.mapped('receipt_id') & self

    def _prepare_retry_tc_warning_message(self, warning_receipts):
        warning_receipts = warning_receipts & self
        if not warning_receipts:
            return False
        lines = [
            _('Some affected data has already been successfully sent to TC.'),
            _('Confirming this action will resend the affected data to TC.'),
        ]
        return '\n'.join(lines)

    def _open_retry_tc_confirmation_wizard(self, warning_logs, source, affected_receipts=False, warning_receipts=False, retry_mode='multiple'):
        affected_receipts = affected_receipts or self._get_retry_tc_affected_receipts(source)
        warning_receipts = warning_receipts if warning_receipts is not False else warning_logs.mapped('receipt_id')
        warning_receipts = warning_receipts & affected_receipts & self
        wizard = self.env['eproc.receipt.retry.tc.wizard'].create({
            'retry_mode': retry_mode,
            'receipt_ids': [(6, 0, self.ids)],
            'warning_receipt_ids': [(6, 0, warning_receipts.ids)],
            'warning_log_ids': [(6, 0, warning_logs.ids)],
            'warning_message': affected_receipts._prepare_retry_tc_warning_message(warning_receipts) if retry_mode == 'multiple' else False,
            'selected_count': len(self),
            'affected_count': len(warning_receipts),
        })
        return {
            'name': _('Confirm Retry TC Sync'),
            'type': 'ir.actions.act_window',
            'res_model': 'eproc.receipt.retry.tc.wizard',
            'view_mode': 'form',
            'res_id': wizard.id,
            'target': 'new',
            'context': {
                'retry_tc_source': source,
                'retry_mode': retry_mode,
                'dialog_size': 'extra-large',
            },
        }

    def _execute_retry_interfacing_tc_batch(self):
        source = self.env.context.get('retry_tc_source')
        self._validate_retry_interfacing_tc_batch(source)
        processed = 0
        for receipt in self:
            try:
                receipt.with_context(force_tc_interface=True).action_interfacing()
            except UserError as err:
                raise UserError(_('TC sync retry failed for %s:\n%s') % (
                    receipt._get_retry_tc_document_name(),
                    err,
                )) from err
            except Exception as err:
                raise UserError(_('TC sync retry failed for %s:\n%s') % (
                    receipt._get_retry_tc_document_name(),
                    err,
                )) from err
            processed += 1

        message = _('TC sync retry completed for %s document(s).') % processed
        return {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': _('Retry TC Sync'),
                'message': message,
                'type': 'success',
                'sticky': False,
            },
        }

    def action_retry_interfacing_tc_batch(self):
        source = self.env.context.get('retry_tc_source') or self._get_retry_tc_default_source()
        self._validate_retry_interfacing_tc_batch(source)
        affected_receipts = self._get_retry_tc_affected_receipts(source)
        warning_receipts = affected_receipts._get_retry_tc_previously_sent_receipts()
        warning_logs = warning_receipts._get_retry_tc_confirmation_logs()
        if not self.env.context.get('retry_tc_confirmed'):
            return self._open_retry_tc_confirmation_wizard(
                warning_logs,
                source,
                affected_receipts=affected_receipts,
                warning_receipts=warning_receipts,
                retry_mode='multiple',
            )
        return affected_receipts._execute_retry_interfacing_tc_batch()

    def action_download_latest_tc_txt(self):
        self.ensure_one()
        self._ensure_not_dil_goods_receiving_view(
            _('Downloading TC TXT is not allowed from the DIL Goods Receiving view.')
        )
        logs = self.log_ids.filtered(
            lambda log:
            log.log_type == 'txt'
            and log.state_tc == 'sent'
            and log.attachment_id
        ).sorted('log_datetime', reverse=True)
        if not logs:
            raise UserError(_('No generated TC TXT file found.'))
        return logs[0].action_download_txt()

    def _post_tc_payload(self):
        return self.action_interfacing()

    def action_notify_approver(self, message=False):
        for record in self:
            current_log = record._get_current_approval_log()
            partner_ids = set(record.user_id.partner_id.ids)
            if current_log:
                if current_log.user_id:
                    partner_ids.update(current_log.user_id.partner_id.ids)
                if current_log.position_id:
                    partner_ids.update(record._find_user_for_position(current_log.position_id).mapped('partner_id').ids)
            body = message or (_('Receiving Validation %s is waiting for approval by %s.') % (record.receipt_no,
                                                                                              record.approval_next_stored or _(
                                                                                                  'next approver')))
            record.message_post(body=body, partner_ids=list(partner_ids))
        return True

