    def _get_related_ap_invoice_records(self):
        self.ensure_one()
        domain = [('invoice_eproc_ids', 'in', [self.id])]
        if self.payable_invoice_id:
            domain = ['|', ('id', '=', self.payable_invoice_id.id)] + domain
        return self.env['payable.invoice'].with_context(active_test=False).search(domain)

    def action_open_ap_invoice(self):
        self.ensure_one()
        invoices = self._get_related_ap_invoice_records()
        action_ref = self.env.ref('mayapada.payable_invoice_action', raise_if_not_found=False)
        action = action_ref.read()[0] if action_ref else {
            'type': 'ir.actions.act_window',
            'name': _('AP Invoice'),
            'res_model': 'payable.invoice',
            'view_mode': 'tree,form',
        }
        action.update({
            'domain': [('id', 'in', invoices.ids)],
            'context': dict(self.env.context, create=False),
        })
        return action

