class ReceivableInvoiceReceipt(models.Model):
    _name = 'receivable.invoice.receipt'
    _description = 'AR Tenant Invoice Receipt Allocation'
    _check_company_auto = True

    invoice_id = fields.Many2one(
        'receivable.invoice', string='Invoice No.', required=True,
        ondelete='restrict', index=True, check_company=True,
    )
    invoice_item_id = fields.Many2one(
        'receivable.invoice.item', string='Invoice Item',
        ondelete='restrict', index=True, check_company=True,
    )
    name = fields.Char(string='Description', readonly=True)
    account_id = fields.Many2one(
        'account.account', string='Account', readonly=True, check_company=True,
    )
    receipt_id = fields.Many2one(
        'receivable.receipt', string='Receipt No.', required=True,
        ondelete='restrict', index=True, check_company=True,
    )
    receipt_date = fields.Datetime(
        related='receipt_id.receipt_date', string='Receipt Date', readonly=True,
    )
    receipt_type = fields.Selection(
        related='receipt_id.receipt_type', string='Receipt Type', readonly=True,
    )
    receipt_ref = fields.Char(
        related='receipt_id.receipt_ref', string='Receipt Ref.', readonly=True,
    )
    receipt_state = fields.Selection(
        related='receipt_id.state', string='State', readonly=True,
    )
    invoice_balance = fields.Float(string='Invoice Balance', readonly=True)
    receipt_amount = fields.Float(string='Receipt Amount', required=True, default=0.0)
    ending_balance = fields.Float(
        string='Ending Balance', compute='_compute_ending_balance', store=True,
    )
    company_id = fields.Many2one(related='invoice_id.company_id', store=True)
    active = fields.Boolean(string='Active', default=True)

    @api.depends('invoice_balance', 'receipt_amount')
    def _compute_ending_balance(self):
        for record in self:
            record.ending_balance = record.invoice_balance - record.receipt_amount

    @api.onchange('invoice_item_id')
    def _onchange_invoice_item_id(self):
        for record in self:
            if record.invoice_item_id:
                record.invoice_id = record.invoice_item_id.invoice_id
                record.name = record.invoice_item_id.name
                record.account_id = record.invoice_item_id.account_id
                record.invoice_balance = record.invoice_item_id.amount

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            receipt = self.env['receivable.receipt'].browse(vals.get('receipt_id'))
            if receipt and receipt.state != 'draft':
                raise UserError(_('Tenant invoice settlements can only be changed in draft.'))
            item = self.env['receivable.invoice.item'].browse(vals.get('invoice_item_id'))
            if item:
                vals.setdefault('invoice_id', item.invoice_id.id)
                vals.setdefault('name', item.name)
                vals.setdefault('account_id', item.account_id.id)
                vals.setdefault('invoice_balance', item.amount)
            invoice = self.env['receivable.invoice'].browse(vals.get('invoice_id'))
            if invoice and 'invoice_balance' not in vals:
                vals['invoice_balance'] = invoice.invoice_balance
        records = super().create(vals_list)
        records.mapped('receipt_id')._sync_receipt_invoice_ids()
        return records

    def write(self, vals):
        if self.mapped('receipt_id').filtered(lambda receipt: receipt.state != 'draft'):
            raise UserError(_('Tenant invoice settlements can only be changed in draft.'))
        if vals.get('invoice_item_id'):
            item = self.env['receivable.invoice.item'].browse(vals['invoice_item_id'])
            vals = dict(vals)
            vals.setdefault('invoice_id', item.invoice_id.id)
            vals.setdefault('name', item.name)
            vals.setdefault('account_id', item.account_id.id)
            vals.setdefault('invoice_balance', item.amount)
        values = dict(vals)
        result = super().write(values)
        self.mapped('receipt_id')._sync_receipt_invoice_ids()
        return result

    def unlink(self):
        receipts = self.mapped('receipt_id')
        if self.mapped('receipt_id').filtered(lambda receipt: receipt.state != 'draft'):
            raise UserError(_('Tenant invoice settlements can only be changed in draft.'))
        result = super().unlink()
        receipts._sync_receipt_invoice_ids()
        return result

    @api.constrains('receipt_id', 'invoice_id', 'active')
    def _check_duplicate_invoice_id(self):
        for record in self.filtered(lambda line: line.receipt_id and line.invoice_id and line.active):
            duplicate = self.search([
                ('id', '!=', record.id),
                ('receipt_id', '=', record.receipt_id.id),
                ('invoice_id', '=', record.invoice_id.id),
                ('active', '=', True),
            ], limit=1)
            if duplicate:
                raise exceptions.ValidationError(_(
                    'The same tenant invoice cannot be settled more than once in one receipt.'
                ))

    @api.constrains('invoice_id', 'invoice_item_id')
    def _check_invoice_item_source(self):
        for record in self.filtered('invoice_item_id'):
            if record.invoice_item_id.invoice_id != record.invoice_id:
                raise exceptions.ValidationError(_('Invoice item must belong to the selected Tenant Invoice.'))

    @api.constrains('receipt_amount', 'invoice_balance')
    def _check_receipt_amount(self):
        for record in self:
            if record.receipt_amount < 0:
                raise exceptions.ValidationError(_('Receipt amount cannot be negative.'))
            if record.receipt_amount > record.invoice_balance:
                raise exceptions.ValidationError(_('Receipt amount cannot exceed the invoice balance.'))


