def _tariff_wizard_open_new(record):
    context = dict(record.env.context)
    context['dialog_size'] = 'extra-large'
    return {
        'type': 'ir.actions.act_window',
        'res_model': record._name,
        'view_mode': 'form',
        'target': 'new',
        'context': context,
    }


def _tariff_wizard_stay_open(record, message=None):
    context = dict(record.env.context)
    context['dialog_size'] = 'extra-large'
    next_action = {
        'type': 'ir.actions.act_window',
        'res_model': record._name,
        'res_id': record.id,
        'view_mode': 'form',
        'views': [(False, 'form')],
        'target': 'new',
        'context': context,
    }
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': _('Success'),
            'message': message or _('Data has been updated successfully.'),
            'type': 'success',
            'sticky': False,
            'next': next_action,
        },
    }


