class TariffExistingExportWizard(models.TransientModel):
    _name = 'tariff.existing.export.wizard'
    _description = 'Existing Tariff Data Export'

    company_id = fields.Many2one(
        'res.company', string='Company', required=True,
        default=lambda self: self.env.company,
    )
    export_type = fields.Selection([
        ('pricelist', 'Tariff Pricelist'),
        ('dependency', 'Tariff Dependency'),
        ('markup', 'Tariff Markup'),
    ], string='Export Type', required=True, default='pricelist')
    pricelist_ids = fields.Many2many(
        'tariff.pricelist', string='Selected Pricelist',
        default=lambda self: self._default_selected('tariff.pricelist'),
    )
    dependency_ids = fields.Many2many(
        'tariff.dependency', string='Selected Dependency',
        default=lambda self: self._default_selected('tariff.dependency'),
    )
    markup_ids = fields.Many2many(
        'tariff.markup', string='Selected Markup',
        default=lambda self: self._default_selected('tariff.markup'),
    )

    def _default_selected(self, model):
        if self.env.context.get('active_model') != model:
            return []
        return [(6, 0, self.env.context.get('active_ids') or [])]

    def action_close(self):
        return {'type': 'ir.actions.act_window_close'}

    def _export_headers(self):
        return {
            'pricelist': [
                'Tariff Type', 'Tariff', 'Service Category', 'Item Category',
                'Product', 'Bed Type', 'New Price', 'New Effective Date',
            ],
            'dependency': [
                'Tariff', 'Bed Type', 'Service Category', 'Depend Tariff',
                'Depend BedType', 'Depend Rate', 'Active',
            ],
            'markup': [
                'Tariff', 'Markup Level', 'Bed Type', 'Item Category',
                'Product', 'Price Level', 'From Price', 'To Price',
                'Markup Rate', 'Active',
            ],
        }[self.export_type]

    @staticmethod
    def _record_value(record):
        return record.code or record.display_name or record.name or ''

    def _export_rows(self):
        self.ensure_one()
        selected = self['%s_ids' % self.export_type]
        if not selected:
            raise UserError(_('Select one or more records in the tariff list before exporting.'))
        model = selected._name

        records = self.env[model].with_context(active_test=False).search([
            ('company_id', '=', self.company_id.id),
            ('id', 'in', selected.ids),
            ('active', '=', True),
        ], order='id')
        if not records:
            raise UserError(_('No selected active records found for this company and export type.'))

        if self.export_type == 'pricelist':
            tariff_types = dict(self.env[model]._fields['tariff_type'].selection)
            earliest_date = fields.Date.context_today(self) + timedelta(days=2)
            return [[
                tariff_types.get(rec.tariff_type, rec.tariff_type),
                self._record_value(rec.tariff_id),
                rec.category_id.complete_name or rec.category_id.name or '',
                (rec.item_category_id.complete_name or rec.item_category_id.name or '')
                if rec.item_category_id else '',
                ('[%s] %s' % (rec.product_tmpl_id.default_code, rec.product_tmpl_id.name)
                 if rec.product_tmpl_id.default_code else rec.product_tmpl_id.name),
                self._record_value(rec.bed_type_id),
                rec.new_price if rec.new_effective else rec.current_price,
                max(rec.new_effective or rec.current_effective or earliest_date,
                    earliest_date).strftime('%d/%m/%Y'),
            ] for rec in records]

        if self.export_type == 'dependency':
            return [[
                self._record_value(rec.tariff_id),
                self._record_value(rec.bed_type_id),
                rec.category_id.complete_name or rec.category_id.name or '',
                self._record_value(rec.depend_tariff_id),
                self._record_value(rec.depend_bed_type_id),
                rec.depend_rate,
                rec.active,
            ] for rec in records]

        markup_levels = dict(self.env[model]._fields['markup_level'].selection)
        return [[
            self._record_value(rec.tariff_id),
            markup_levels.get(rec.markup_level, rec.markup_level),
            self._record_value(rec.bed_type_id),
            rec.category_id.complete_name or rec.category_id.name or '',
            ('[%s] %s' % (rec.product_tmpl_id.default_code, rec.product_tmpl_id.name)
             if rec.product_tmpl_id and rec.product_tmpl_id.default_code
             else rec.product_tmpl_id.name if rec.product_tmpl_id else ''),
            rec.markup_tier,
            rec.from_price,
            rec.to_price,
            rec.markup_rate,
            rec.active,
        ] for rec in records]

    def action_export(self):
        self.ensure_one()
        import xlwt

        workbook = xlwt.Workbook()
        sheet = workbook.add_sheet('Existing Data')
        header_style = xlwt.easyxf('font: bold on;')
        headers = self._export_headers()
        for col, header in enumerate(headers):
            sheet.write(0, col, header, header_style)
            sheet.col(col).width = max(16, len(header) + 4) * 256
        for row_idx, row in enumerate(self._export_rows(), start=1):
            for col, value in enumerate(row):
                sheet.write(row_idx, col, value if value is not None else '')

        output = io.BytesIO()
        workbook.save(output)
        filename = 'tariff_%s_existing_%s.xls' % (
            self.export_type,
            fields.Date.context_today(self).strftime('%Y%m%d'),
        )
        attachment = self.env['ir.attachment'].create({
            'name': filename,
            'type': 'binary',
            'datas': base64.b64encode(output.getvalue()),
            'res_model': self._name,
            'res_id': self.id,
            'mimetype': 'application/vnd.ms-excel',
        })
        return {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % attachment.id,
            'target': 'self',
        }


