# Tariff Markup
TARIFF_MARKUP_TIERS = [
    ('1', 'Level 1'),
    ('2', 'Level 2'),
    ('3', 'Level 3'),
    ('4', 'Level 4'),
]

TARIFF_MARKUP_DEFAULT_RANGES = {
    '1': (0.0, 0.0),
    '2': (0.0, 0.0),
    '3': (0.0, 0.0),
    '4': (0.0, 0.0),
}


class TariffMarkup(models.Model):
    _name = 'tariff.markup'
    _description = 'Tariff Markup'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _order = 'tariff_id, markup_level, bed_type_id, category_id, product_tmpl_id, markup_tier, id desc'
    _rec_name = 'tariff_id'

    @api.model
    def fields_get(self, allfields=None, attributes=None):
        fields = super(TariffMarkup, self).fields_get(allfields=allfields, attributes=attributes)
        return _disable_tariff_active_archive_field(fields)

    sync_type = sync.type
    sync_id_api = sync.id_api

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company', string='Company', required=True, default=_get_company, tracking=True)
    tariff_id = fields.Many2one('hospital.tariff', string='Tariff', required=True, tracking=True)
    patient_type = fields.Selection(
        related='bed_type_id.patient_type',
        string='Patient Type',
        store=True,
        readonly=True,
    )
    bed_type_id = fields.Many2one('hospital.bed.type', string='Bed Type', tracking=True)
    category_id = fields.Many2one('product.category', string='Item Category', tracking=True)
    product_tmpl_id = fields.Many2one('product.template', string='Item', tracking=True)
    product_uom_id = fields.Many2one(related='product_tmpl_id.uom_id', string='UoM', store=True, readonly=True)
    markup_tier = fields.Selection(
        TARIFF_MARKUP_TIERS,
        string='Price Level',
        default='1',
        required=True,
        tracking=True,
    )
    from_price = fields.Float(string='From Price', default=0.0, required=True, tracking=True)
    to_price = fields.Float(string='To Price', default=9999999999999.0, required=True, tracking=True)
    markup_rate = fields.Float(string='MarkUp Rate (%)', default=0.0, required=True, tracking=True)
    markup_level = fields.Selection([
        ('0', 'Item'),
        ('1', 'Category'),
    ], string='MarkUp Level', default='1', required=True, tracking=True)
    user_id = fields.Many2one('res.users', string='Responsible', default=lambda self: self.env.user, readonly=True, tracking=True)
    active = fields.Boolean(string='Active', default=True, tracking=True)


    @api.constrains('markup_rate')
    def _check_markup_rate(self):
        for rec in self:
            if rec.markup_rate < 0 or rec.markup_rate > 100:
                raise exceptions.ValidationError(_('MarkUp Rate must be between 0 and 100.'))

    @api.constrains('tariff_id', 'bed_type_id')
    def _check_base_tariff_opd_bed_type(self):
        for rec in self:
            if rec.tariff_id.id < 0 and rec.bed_type_id.id == -1:
                raise exceptions.ValidationError(
                    _('Base Tariff cannot use OPD Bed Type for markup.'))

    @api.constrains(
        'company_id', 'tariff_id', 'markup_level', 'bed_type_id', 'category_id',
        'product_tmpl_id', 'markup_tier', 'from_price', 'to_price', 'active')
    def _check_markup_price_range(self):
        for rec in self:
            if rec.from_price < 0 or rec.to_price < rec.from_price:
                raise exceptions.ValidationError(
                    _('To Price must be greater than or equal to From Price.'))
            if not rec.active:
                continue
            domain = [
                ('id', '!=', rec.id),
                ('company_id', '=', rec.company_id.id),
                ('tariff_id', '=', rec.tariff_id.id),
                ('markup_level', '=', rec.markup_level),
                ('bed_type_id', '=', rec.bed_type_id.id),
                ('category_id', '=', rec.category_id.id),
                ('product_tmpl_id', '=', rec.product_tmpl_id.id if rec.product_tmpl_id else False),
                ('active', '=', True),
                ('from_price', '<=', rec.to_price),
                ('to_price', '>=', rec.from_price),
            ]
            if self.search_count(domain):
                raise exceptions.ValidationError(_(
                    'Active markup price ranges cannot overlap for the same tariff, bed type, and category/item.'))

    @api.constrains('markup_level', 'bed_type_id', 'category_id', 'product_tmpl_id')
    def _check_markup_level_fields(self):
        for rec in self:
            if rec.markup_level == '0' and (not rec.bed_type_id or not rec.category_id or not rec.product_tmpl_id):
                raise exceptions.ValidationError(_('Bed Type, Category, and Item are required for item markup.'))
            if rec.markup_level == '1' and (not rec.bed_type_id or not rec.category_id):
                raise exceptions.ValidationError(_('Bed Type and Category are required for category markup.'))
            if rec.markup_level == '0' and rec.category_id.eproc_type != 'item_category':
                raise exceptions.ValidationError(_('Item markup must use an item category.'))
            if rec.markup_level == '1' and rec.category_id.eproc_type != 'item_category':
                raise exceptions.ValidationError(_('Category markup must use an item category.'))

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            self._archive_existing_active(vals)
        return super(TariffMarkup, self).create(vals_list)

    @api.model
    def _archive_existing_active(self, vals):
        key_fields = [
            'company_id', 'tariff_id', 'markup_level', 'bed_type_id',
            'category_id', 'markup_tier',
        ]
        if vals.get('active') is False or not all(vals.get(field) for field in key_fields):
            return
        domain = [(field, '=', vals[field]) for field in key_fields] + [('active', '=', True)]
        if vals.get('markup_level') == '0':
            if not vals.get('product_tmpl_id'):
                return
            domain.append(('product_tmpl_id', '=', vals['product_tmpl_id']))
        else:
            domain.append(('product_tmpl_id', '=', False))
        existing = self.search(domain)
        if existing:
            existing.write({'active': False, 'user_id': vals.get('user_id') or self.env.user.id})

    def scheduler_baseprice_agreegation(self):
        return self.env['tariff.aggregation'].scheduler_baseprice_agreegation()

    def scheduler_pricelist_realization(self):
        return self.env['tariff.pricelist'].scheduler_pricelist_realization()

    def scheduler_pricelist_final(self):
        return self.env['tariff.pricelist.fixed']._scheduler_pricelist_final()


class TariffMarkupWizard(models.TransientModel):
    _name = 'tariff.markup.wizard'
    _description = 'Tariff Markup Wizard'

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company', string='Company', required=True, default=_get_company, readonly=True)
    tariff_id = fields.Many2one('hospital.tariff', string='Tariff', required=True)
    markup_level = fields.Selection([
        ('0', 'Item'),
        ('1', 'Category'),
    ], string='MarkUp Level', default='1', required=True)
    patient_type = fields.Selection([
        ('IP', 'In Patient'),
        ('OP', 'Out Patient'),
        ('AAE', 'Emergency'),
        ('MCU', 'MCU'),
        ('ODC', 'DayCare'),
        ('ALL', 'ALL'),
    ], string='Patient Type', default='ALL')
    bed_type_id = fields.Many2one('hospital.bed.type', string='BedType')
    category_id = fields.Many2one('product.category', string='Item Category', required=True)
    product_tmpl_id = fields.Many2one('product.template', string='Item')
    product_uom_id = fields.Many2one('uom.uom', string='UoM', related='product_tmpl_id.uom_id', readonly=True)
    line_ids = fields.One2many('tariff.markup.rel', 'wizard_id', string='Items', context={'active_test': False})
    data_loaded = fields.Boolean(string='Data Loaded', compute='_compute_data_loaded')

    def _compute_data_loaded(self):
        for rec in self:
            rec.data_loaded = bool(rec.line_ids)

    @api.onchange('markup_level')
    def _onchange_markup_level(self):
        self.line_ids = [(5, 0, 0)]
        self.category_id = False
        self.product_tmpl_id = False
        if self.markup_level == '1':
            self.product_tmpl_id = False
        return {'domain': {
            'category_id': self._get_category_domain(),
            'product_tmpl_id': self._get_product_domain(),
        }}

    def _get_category_domain(self):
        self.ensure_one()
        return [
            ('company_id', '=', self.company_id.id),
            ('is_eproc', '=', True),
            ('active', '=', True),
            ('eproc_type', '=', 'item_category'),
        ]

    def _get_product_domain(self):
        self.ensure_one()
        domain = [
            ('company_id', '=', self.company_id.id),
            ('is_eproc', '=', True),
            ('eproc_type', '=', 'non_stock'),
            ('eproc_subtype', '!=', 'procedure'),
        ]
        if self.category_id:
            domain.append(('item_category_id', '=', self.category_id.id))
        return domain

    def _product_matches_category(self, product=False, category=False):
        product = product or self.product_tmpl_id
        category = category or self.category_id
        if not product or not category:
            return True
        return product.item_category_id == category

    @api.onchange('category_id')
    def _onchange_category_id(self):
        if self.product_tmpl_id and not self._product_matches_category():
            self.product_tmpl_id = False
        self.line_ids = [(5, 0, 0)]
        return {'domain': {'product_tmpl_id': self._get_product_domain()}}

    @api.onchange('product_tmpl_id')
    def _onchange_product_tmpl_id(self):
        if self.product_tmpl_id and not self._product_matches_category():
            self.product_tmpl_id = False
        self.line_ids = [(5, 0, 0)]
        return {'domain': {'product_tmpl_id': self._get_product_domain()}}

    @api.onchange('patient_type')
    def _onchange_patient_type(self):
        domain = self._get_bed_type_domain()
        if self.patient_type == 'ALL':
            self.bed_type_id = False
        if self.bed_type_id and self.patient_type != 'ALL' and self.bed_type_id.patient_type != self.patient_type:
            self.bed_type_id = False
            self.line_ids = [(5, 0, 0)]
        return {'domain': {'bed_type_id': domain}}

    @api.onchange('tariff_id')
    def _onchange_tariff_id(self):
        if self.tariff_id and self.tariff_id.id < 0 and self.bed_type_id and self.bed_type_id.id == -1:
            self.bed_type_id = False
            self.line_ids = [(5, 0, 0)]
        return {'domain': {'bed_type_id': self._get_bed_type_domain()}}

    @api.onchange('bed_type_id')
    def _onchange_bed_type_id(self):
        if self.bed_type_id and self.bed_type_id.patient_type:
            self.patient_type = self.bed_type_id.patient_type
        self.line_ids = [(5, 0, 0)]

    def action_clear(self):
        self.ensure_one()
        self.line_ids.unlink()
        return _tariff_wizard_open_new(self)

    def _get_bed_type_domain(self):
        self.ensure_one()
        domain = [
            ('company_id', '=', self.company_id.id),
            ('is_eproc', '=', True),
        ]
        if self.tariff_id and self.tariff_id.id < 0:
            domain.append(('id', '>', 0))
        if self.patient_type != 'ALL':
            domain.append(('patient_type', '=', self.patient_type))
        return domain

    def _get_bed_types(self):
        self.ensure_one()
        domain = self._get_bed_type_domain()
        if self.bed_type_id:
            domain.append(('id', '=', self.bed_type_id.id))
        return self.env['hospital.bed.type'].search(domain, order='name')

    def _get_existing_markup(self, bed_type=False, category=False, product=False, markup_tier=False):
        self.ensure_one()
        domain = [
            ('company_id', '=', self.company_id.id),
            ('tariff_id', '=', self.tariff_id.id),
            ('markup_level', '=', self.markup_level),
        ]
        if bed_type:
            domain.append(('bed_type_id', '=', bed_type.id))
        if category:
            domain.append(('category_id', '=', category.id))
        if product:
            domain.append(('product_tmpl_id', '=', product.id))
        elif self.markup_level == '1':
            domain.append(('product_tmpl_id', '=', False))
        if markup_tier:
            domain.append(('markup_tier', '=', markup_tier))
        return self.env['tariff.markup'].with_context(active_test=False).search(domain, order='active desc, id desc', limit=1)

    def _get_tier_vals(self, existing, markup_tier):
        from_price, to_price = TARIFF_MARKUP_DEFAULT_RANGES[markup_tier]
        return {
            'markup_tier': markup_tier,
            'from_price': existing.from_price if existing else from_price,
            'to_price': existing.to_price if existing else to_price,
            'markup_rate': existing.markup_rate if existing else 0.0,
            'active': existing.active if existing else True,
        }

    def action_view(self):
        self.ensure_one()
        if not self.tariff_id:
            raise exceptions.ValidationError(_('Tariff is required.'))
        if self.tariff_id.id < 0 and self.bed_type_id.id == -1:
            raise exceptions.ValidationError(_('Base Tariff cannot use OPD Bed Type for markup.'))
        if self.patient_type != 'ALL' and not self.bed_type_id:
            raise exceptions.ValidationError(_('BedType is required when Patient Type is not ALL.'))
        self.line_ids.unlink()
        bed_types = self._get_bed_types()
        if not bed_types:
            raise exceptions.ValidationError(_('No E-Proc bed type found for this company and patient type.'))
        vals_list = []
        if self.markup_level == '0':
            if not self.category_id:
                raise exceptions.ValidationError(_('Item Category is required for item markup.'))
            if self.category_id.eproc_type != 'item_category':
                raise exceptions.ValidationError(_('Item markup must use an item category.'))
            if self.product_tmpl_id:
                if not self.product_tmpl_id.uom_id:
                    raise exceptions.ValidationError(_('Product UoM is required for item %s.') % self.product_tmpl_id.display_name)
                products = self.product_tmpl_id
            else:
                products = self.env['product.template'].search([
                    ('company_id', '=', self.company_id.id),
                    ('is_eproc', '=', True),
                    ('eproc_type', '=', 'non_stock'),
                    ('eproc_subtype', '!=', 'procedure'),
                    ('item_category_id', '=', self.category_id.id),
                ], order='name')
                if not products:
                    raise exceptions.ValidationError(_('No item found for the selected category.'))
                missing_uom = products.filtered(lambda product: not product.uom_id)
                if missing_uom:
                    raise exceptions.ValidationError(_('Product UoM is required for item %s.') % missing_uom[0].display_name)
            for bed_type in bed_types:
                for product in products:
                    for markup_tier, __tier_name in TARIFF_MARKUP_TIERS:
                        existing = self._get_existing_markup(
                            bed_type=bed_type, category=self.category_id,
                            product=product, markup_tier=markup_tier)
                        vals = {
                            'patient_type': bed_type.patient_type,
                            'bed_type_id': bed_type.id,
                            'category_id': self.category_id.id,
                            'product_tmpl_id': product.id,
                        }
                        vals.update(self._get_tier_vals(existing, markup_tier))
                        vals_list.append((0, 0, vals))
        else:
            if self.category_id and self.category_id.eproc_type != 'item_category':
                raise exceptions.ValidationError(_('Category markup must use an item category.'))
            categories = self.category_id or self.env['product.category'].search([
                ('company_id', '=', self.company_id.id),
                ('is_eproc', '=', True),
                ('active', '=', True),
                ('eproc_type', '=', 'item_category'),
            ], order='name')
            if not categories:
                raise exceptions.ValidationError(_('No E-Proc item category found for this company.'))
            for bed_type in bed_types:
                for category in categories:
                    for markup_tier, __tier_name in TARIFF_MARKUP_TIERS:
                        existing = self._get_existing_markup(
                            bed_type=bed_type, category=category,
                            markup_tier=markup_tier)
                        vals = {
                            'patient_type': bed_type.patient_type,
                            'bed_type_id': bed_type.id,
                            'category_id': category.id,
                        }
                        vals.update(self._get_tier_vals(existing, markup_tier))
                        vals_list.append((0, 0, vals))
        self.line_ids = vals_list
        return {
            'type': 'ir.actions.act_window',
            'res_model': self._name,
            'res_id': self.id,
            'view_mode': 'form',
            'target': 'new',
            'context': dict(self.env.context),
        }

    def action_update(self):
        self.ensure_one()
        line_ids = self.with_context(active_test=False).line_ids
        if not line_ids:
            raise exceptions.ValidationError(_('Please click View Data before Update Data.'))
        Markup = self.env['tariff.markup']
        for line in line_ids:
            product = line.product_tmpl_id if self.markup_level == '0' else False
            if self.markup_level == '0':
                if not product:
                    continue
                if not product.uom_id:
                    raise exceptions.ValidationError(_('Product UoM is required for item %s.') % product.display_name)
            category = line.category_id or self.category_id
            bed_type = line.bed_type_id or self.bed_type_id
            if self.tariff_id.id < 0 and bed_type.id == -1:
                raise exceptions.ValidationError(_('Base Tariff cannot use OPD Bed Type for markup.'))
            existing = self._get_existing_markup(
                bed_type=bed_type, category=category, product=product,
                markup_tier=line.markup_tier)
            if not line.active:
                if existing:
                    existing.write({'active': False, 'user_id': self.env.user.id})
                continue
            if line.markup_rate == 0:
                if existing and existing.active:
                    existing.write({'active': False, 'user_id': self.env.user.id})
                continue
            vals = {
                'company_id': self.company_id.id,
                'tariff_id': self.tariff_id.id,
                'bed_type_id': bed_type.id,
                'category_id': category.id,
                'product_tmpl_id': product.id if product else False,
                'markup_tier': line.markup_tier,
                'from_price': line.from_price,
                'to_price': line.to_price,
                'markup_rate': line.markup_rate,
                'markup_level': self.markup_level,
                'user_id': self.env.user.id,
                'active': True,
            }
            if existing:
                existing.write(vals)
            else:
                Markup.create(vals)
        return _tariff_wizard_stay_open(self)


class TariffMarkupRel(models.TransientModel):
    _name = 'tariff.markup.rel'
    _description = 'Tariff Markup Wizard Line'

    wizard_id = fields.Many2one('tariff.markup.wizard', string='Parent', required=True, ondelete='cascade')
    patient_type = fields.Selection([
        ('IP', 'In Patient'),
        ('OP', 'Out Patient'),
        ('AAE', 'Emergency'),
        ('MCU', 'MCU'),
        ('ODC', 'DayCare'),
        ('ALL', 'ALL'),
    ], string='Patient Type', default='ALL', readonly=True)
    bed_type_id = fields.Many2one('hospital.bed.type', string='Bed Type', readonly=True)
    category_id = fields.Many2one('product.category', string='Item Category', readonly=True)
    product_tmpl_id = fields.Many2one('product.template', string='Item', readonly=True)
    product_uom_id = fields.Many2one('uom.uom', string='UoM', related='product_tmpl_id.uom_id', readonly=True)
    markup_tier = fields.Selection(TARIFF_MARKUP_TIERS, string='Price Level', required=True, readonly=True)
    from_price = fields.Float(string='From Price', required=True)
    to_price = fields.Float(string='To Price', required=True)
    markup_rate = fields.Float(string='MarkUp Rate (%)', default=0.0, required=True)
    active = fields.Boolean(string='Active', default=True)

    @api.onchange('markup_rate')
    def _onchange_markup_rate(self):
        for rec in self:
            if rec.markup_rate == 0:
                rec.active = False

    @api.constrains('markup_rate')
    def _check_markup_rate(self):
        for rec in self:
            if rec.markup_rate < 0 or rec.markup_rate > 100:
                raise exceptions.ValidationError(_('MarkUp Rate must be between 0 and 100.'))

    @api.constrains('from_price', 'to_price')
    def _check_price_range(self):
        for rec in self:
            if rec.from_price < 0 or rec.to_price < rec.from_price:
                raise exceptions.ValidationError(
                    _('To Price must be greater than or equal to From Price.'))


# Tariff Aggregation (buat rekomendasi baseprice dari harga penerimaan barang/PO)
class TariffAggregation(models.Model):
    _name = 'tariff.aggregation'
    _description = 'Tariff Aggregation BasePrice'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _order = 'calculated_date desc, category_id, product_tmpl_id, id desc'
    _rec_name = 'product_tmpl_id'

    @api.model
    def fields_get(self, allfields=None, attributes=None):
        fields = super(TariffAggregation, self).fields_get(allfields=allfields, attributes=attributes)
        return _disable_tariff_active_archive_field(fields)

    def name_get(self):
        result = []
        for rec in self:
            name = rec.product_tmpl_id.display_name or '/'
            result.append((rec.id, name))
        return result

    sync_type = sync.type
    sync_id_api = sync.id_api

    @api.model
    def _get_company(self):
        return self.env.company.id

    calculated_date = fields.Datetime(string='Calculated Date', required=True, default=fields.Datetime.now, readonly=True)
    company_id = fields.Many2one('res.company', string='Company', required=True, default=_get_company, readonly=True)
    category_id = fields.Many2one('product.category', string='Category', required=True, readonly=True)
    item_category_id = fields.Many2one('product.category', string='Item Category', readonly=True)
    product_tmpl_id = fields.Many2one('product.template', string='Product', required=True, readonly=True)
    current_price = fields.Float(string='Current Price', readonly=True)
    current_effective = fields.Date(string='Current Effective', readonly=True)
    receive_price = fields.Float(string='Receive Price', readonly=True)
    receive_effective = fields.Date(string='Receive Date', readonly=True)
    uepr_price = fields.Float(string='UEPR Price', readonly=True)
    uepr_effective = fields.Date(string='UEPR Effective', readonly=True)
    changes_type = fields.Selection([
        ('receiving', 'Receiving'),
        ('pricelist', 'Vendor Pricelist'),
    ], string='Changes Type', default='pricelist', required=True, readonly=True)
    agreement_no = fields.Char(string='Vendor Pricelist', readonly=True)
    receipt_id = fields.Many2one('eproc.receipt', string='Receipt No', readonly=True)
    receipt_line_id = fields.Many2one('eproc.receipt.line', string='Receipt Item', readonly=True)
    supplier_id = fields.Many2one('res.partner', string='Supplier', readonly=True)
    pricelist_id = fields.Many2one('tariff.pricelist', string='Current Pricelist', readonly=True)
    tariff_id = fields.Many2one('hospital.tariff', string='Tariff Type', readonly=True)
    pricelist_ids = fields.Many2many('tariff.pricelist', compute='_compute_pricelist_ids', string='Base Pricelists')
    state = fields.Selection([
        ('pending', 'Pending'),
        ('release', 'Release'),
        ('ignore', 'Ignored'),
    ], string='State', default='pending', readonly=True, tracking=True)
    active = fields.Boolean(string='Active', default=True)


    @api.model
    def _get_base_tariff(self, company=False):
        company = company or self.env.company
        Tariff = self.env['hospital.tariff'].sudo()
        domain = ['|', ('company_id', '=', False), ('company_id', '=', company.id), ('id', '=', -1), ('is_eproc', '=', True)]
        return Tariff.search(domain, order='id', limit=1)

    @api.depends('company_id', 'product_tmpl_id', 'category_id', 'item_category_id', 'tariff_id')
    def _compute_pricelist_ids(self):
        Pricelist = self.env['tariff.pricelist'].sudo()
        for rec in self:
            domain = [
                ('company_id', '=', rec.company_id.id),
                ('tariff_type', '=', 'base_price'),
                ('product_tmpl_id', '=', rec.product_tmpl_id.id),
                ('active', '=', True),
                ('tariff_id', '=', -1),
                ('state', '=', 'active')
            ]
            if rec.category_id:
                domain.append(('category_id', '=', rec.category_id.id))
            domain.append(('item_category_id', '=', rec.item_category_id.id or False))
            rec.pricelist_ids = Pricelist.search(domain).filtered(lambda pricelist: pricelist.bed_type_id.id == -1)

    @api.model
    def _get_product_category(self, product):
        return product.categ_id

    @api.model
    def _get_product_item_category(self, product):
        return product.item_category_id

    @api.model
    def _get_current_base_pricelist(self, company, tariff, category, item_category, product):
        pricelists = self.env['tariff.pricelist'].sudo().search([
            ('company_id', '=', company.id),
            ('tariff_type', '=', 'base_price'),
            ('tariff_id', '=', tariff.id),
            ('category_id', '=', category.id),
            ('product_tmpl_id', '=', product.id),
            ('item_category_id', '=', item_category.id if item_category else False),
            ('active', '=', True),
            ('state', '=', 'active'),
        ], order='current_effective desc, id desc')
        return pricelists.filtered(lambda pricelist: pricelist.bed_type_id.id == -1)[:1]

    @api.model
    def _get_base_bed_types(self, company):
        bed_types = self.env['hospital.bed.type'].sudo().search([
            '|',
            ('company_id', '=', False),
            ('company_id', '=', company.id),
        ], order='id')
        return bed_types.filtered(lambda bed_type: bed_type.id == -1)

    @api.model
    def _get_receiving_price(self, line):
        return line.uom_netprice or line.uom_price or 0.0

    @api.model
    def _get_aggregation_products(self, line):
        Product = self.env['product.template'].sudo()
        return Product.search([
            ('stock_item_id', '=', line.product_tmpl_id.id),
            ('is_eproc', '=', True),
            ('active', '=', True),
        ])

    @api.model
    def _prepare_from_receipt_line(self, line, tariff=False, product=False):
        company = line.company_id or self.env.company
        tariff = tariff or self._get_base_tariff(company)
        if not tariff:
            return False
        product = product or line.product_tmpl_id
        category = self._get_product_category(product) or line.product_categ_id
        item_category = self._get_product_item_category(product)
        if not product or not category:
            return False
        if category.is_item and not item_category:
            return False
        current = self._get_current_base_pricelist(company, tariff, category, item_category, product)
        receive_price = self._get_receiving_price(line)
        if not receive_price:
            return False
        current_price = (current.current_price or 0.0) if current else 0.0
        if current and receive_price <= current_price:
            return False
        return {
            'calculated_date': fields.Datetime.now(),
            'company_id': company.id,
            'category_id': category.id,
            'item_category_id': item_category.id if item_category else False,
            'product_tmpl_id': product.id,
            'current_price': current_price,
            'current_effective': current.current_effective if current else False,
            'receive_price': receive_price,
            'receive_effective': fields.Date.to_date(line.receipt_date) if line.receipt_date else fields.Date.context_today(self),
            'uepr_price': receive_price,
            'uepr_effective': fields.Date.to_date(line.receipt_date) if line.receipt_date else fields.Date.context_today(self),
            'changes_type': 'receiving',
            'agreement_no': False,
            'receipt_id': line.receipt_id.id,
            'receipt_line_id': line.id,
            'supplier_id': line.supplier_id.id,
            'pricelist_id': current.id if current else False,
            'tariff_id': tariff.id,
            'state': 'pending',
            'active': True,
        }

    @api.model
    def _scheduler_baseprice_aggregation(self):
        ReceiptLine = self.env['eproc.receipt.line'].sudo()
        domain = [
            ('receipt_type', '=', 'PO'),
            ('state', 'in', ['done', 'closed']),
            ('product_tmpl_id.is_eproc', '=', True),
            ('product_tmpl_id.eproc_type', '=', 'stock'),
        ]
        lines = ReceiptLine.search(domain, order='uom_netprice desc, receipt_date desc, id desc')
        processed = set()
        for line in lines:
            price = self._get_receiving_price(line)
            if not price:
                continue
            for product in self._get_aggregation_products(line):
                key = (line.company_id.id, product.id)
                if key in processed:
                    continue
                vals = self._prepare_from_receipt_line(line, product=product)
                if not vals:
                    continue
                processed.add(key)
                existing = self.search([
                    ('company_id', '=', vals['company_id']),
                    ('product_tmpl_id', '=', vals['product_tmpl_id']),
                    ('receipt_line_id', '=', vals['receipt_line_id']),
                    ('active', '=', True),
                ], limit=1)
                aggregation = existing or self.create(vals)
                if existing and existing.state == 'pending':
                    existing.write(vals)
                if aggregation.product_tmpl_id.auto_baseprice == 'auto' and aggregation.state == 'pending':
                    aggregation.with_context(enforce_aggregation_h2=True)._realize_to_baseprice(
                        vals['tariff_id'], vals['uepr_effective'])
        return True

    def action_ignore(self):
        self.filtered(lambda rec: rec.state == 'pending').write({'state': 'ignore'})
        return True

    @api.model
    def _get_automatic_new_effective(self, effective):
        minimum_effective = fields.Date.context_today(self) + timedelta(days=2)
        effective = fields.Date.to_date(effective) or minimum_effective
        return max(effective, minimum_effective)

    def _realize_to_baseprice(self, tariff_id=False, new_effective=False):
        Pricelist = self.env['tariff.pricelist'].sudo()
        pending_records = self.filtered(lambda rec: rec.state == 'pending')
        winners = {}
        for rec in pending_records:
            key = (
                rec.company_id.id,
                rec.product_tmpl_id.id,
                rec.category_id.id,
                rec.item_category_id.id or False,
            )
            rank = (
                rec.uepr_price or rec.receive_price or 0.0,
                fields.Date.to_string(rec.uepr_effective or rec.receive_effective) or '',
                fields.Datetime.to_string(rec.calculated_date) or '',
                rec.id,
            )
            current = winners.get(key)
            if not current or rank > current[0]:
                winners[key] = (rank, rec)

        winner_records = self.browse([winner.id for rank, winner in winners.values()])
        superseded = pending_records - winner_records
        if superseded:
            superseded_vals = {'state': 'release'}
            if tariff_id:
                superseded_vals['tariff_id'] = tariff_id
            superseded.write(superseded_vals)

        for rec in winner_records:
            tariff = self.env['hospital.tariff'].browse(tariff_id) if tariff_id else rec.tariff_id or rec._get_base_tariff(rec.company_id)
            if not tariff:
                raise exceptions.ValidationError(_('BaseTariff is not configured.'))
            uepr_price = rec.uepr_price or rec.receive_price or 0.0
            uepr_effective = rec.uepr_effective or rec.receive_effective
            effective = new_effective or uepr_effective or fields.Date.context_today(rec)
            if self.env.context.get('enforce_aggregation_h2'):
                effective = rec._get_automatic_new_effective(effective)
            existing_lines = rec.pricelist_ids.filtered(
                lambda x: x.tariff_id.id == tariff.id
                and x.tariff_type == 'base_price'
                and x.bed_type_id.id == -1
                and x.active
            )
            if not existing_lines:
                bed_types = rec._get_base_bed_types(rec.company_id)
                if not bed_types:
                    raise exceptions.ValidationError(_('Base Price bed type with ID less than 0 is not configured.'))
                existing_lines = Pricelist.browse()
                for bed_type in bed_types:
                    existing_lines |= Pricelist.create({
                        'company_id': rec.company_id.id,
                        'tariff_type': 'base_price',
                        'tariff_id': tariff.id,
                        'category_id': rec.category_id.id,
                        'item_category_id': rec.item_category_id.id or False,
                        'product_tmpl_id': rec.product_tmpl_id.id,
                        'bed_type_id': bed_type.id,
                        'current_price': rec.current_price,
                        'current_effective': rec.current_effective,
                        'new_price': uepr_price,
                        'new_effective': effective,
                        'prev_price': rec.current_price,
                        'prev_effective': rec.current_effective,
                        'state': 'draft',
                        'state_tc': 'pending',
                        'is_eproc': True,
                        'active': True,
                    })
                rec.write({'state': 'release', 'tariff_id': tariff.id})
                continue
            draft_lines = existing_lines.filtered(lambda line: line.state == 'draft')
            for draft_bed_type in draft_lines.mapped('bed_type_id'):
                bed_type_drafts = draft_lines.filtered(
                    lambda line: line.bed_type_id == draft_bed_type
                )
                active_line = existing_lines.filtered(
                    lambda line: line.state == 'active'
                    and line.bed_type_id == draft_bed_type
                )[:1]
                current_price = active_line.current_price if active_line else 0.0
                current_effective = active_line.current_effective if active_line else False
                bed_type_drafts.write({'active': False, 'state': 'expired'})
                Pricelist.create({
                    'company_id': rec.company_id.id,
                    'tariff_type': 'base_price',
                    'tariff_id': tariff.id,
                    'category_id': rec.category_id.id,
                    'item_category_id': rec.item_category_id.id or False,
                    'product_tmpl_id': rec.product_tmpl_id.id,
                    'bed_type_id': draft_bed_type.id,
                    'current_price': current_price,
                    'current_effective': current_effective,
                    'new_price': uepr_price,
                    'new_effective': effective,
                    'prev_price': current_price,
                    'prev_effective': current_effective,
                    'state': 'draft',
                    'state_tc': 'pending',
                    'is_eproc': True,
                    'active': True,
                })

            draft_bed_type_ids = set(draft_lines.mapped('bed_type_id').ids)
            lines_without_draft = existing_lines.filtered(
                lambda line: line.state == 'active'
                and line.bed_type_id.id not in draft_bed_type_ids
            )
            for existing in lines_without_draft:
                vals = {
                    'company_id': rec.company_id.id,
                    'tariff_type': 'base_price',
                    'tariff_id': tariff.id,
                    'category_id': rec.category_id.id,
                    'item_category_id': rec.item_category_id.id or False,
                    'product_tmpl_id': rec.product_tmpl_id.id,
                    'bed_type_id': existing.bed_type_id.id,
                    'current_price': existing.current_price,
                    'current_effective': existing.current_effective,
                    'new_price': uepr_price,
                    'new_effective': effective,
                    'prev_price': existing.current_price,
                    'prev_effective': existing.current_effective,
                    'state': 'draft',
                    'state_tc': 'pending',
                    'is_eproc': True,
                    'active': True,
                }
                Pricelist.create(vals)
            rec.write({'state': 'release', 'tariff_id': tariff.id})
        return True

    def action_realize_wizard(self):
        return {
            'type': 'ir.actions.act_window',
            'name': _('Realize to BasePrice'),
            'res_model': 'tariff.aggregation.wizard',
            'view_mode': 'form',
            'view_id': self.env.ref('mayapada.view_acc_tariff_aggregation_wizard').id,
            'target': 'new',
            'context': {
                'default_aggregation_ids': [(6, 0, self.ids)],
                'active_ids': self.ids,
                'dialog_size': 'extra-large',
            },
        }

    def scheduler_baseprice_agreegation(self):
        return self._scheduler_baseprice_aggregation()

    def scheduler_baseprice_aggregation(self):
        return self._scheduler_baseprice_aggregation()

    def sync_baseprice_aggregation_unit(self):
        return self._scheduler_baseprice_aggregation()

    def sync_baseprice_pricelist_unit(self):
        pending = self.search([('state', '=', 'pending'), ('active', '=', True)])
        return pending.with_context(enforce_aggregation_h2=True)._realize_to_baseprice()


class TariffAggregationWizard(models.TransientModel):
    _name = 'tariff.aggregation.wizard'
    _description = 'Tariff Aggregation Wizard'

    @api.model
    def _get_company(self):
        return self.env.company.id

    @api.model
    def _get_base_tariff(self):
        return self.env['tariff.aggregation']._get_base_tariff(self.env.company).id

    @api.model
    def _default_aggregations(self):
        active_ids = self.env.context.get('active_ids') or []
        return [(6, 0, active_ids)]

    company_id = fields.Many2one('res.company', string='Company', required=True, default=_get_company, readonly=True)
    user_id = fields.Many2one('res.users', string='Responsible', required=True, default=lambda self: self.env.user.id, readonly=True)
    new_effective = fields.Date(string='Set New Effective', required=True, default=fields.Date.today() + timedelta(days=2))
    tariff_id = fields.Many2one('hospital.tariff', string='Tariff Type', required=True, default=_get_base_tariff, readonly=True)
    aggregation_ids = fields.Many2many('tariff.aggregation', 'tariff_aggregation_wizard_rel', 'wizard_id', 'aggregation_id', string='Aggregation Items', default=_default_aggregations)
    confirmation_required = fields.Boolean(string='Confirmation Required', readonly=True)
    draft_pricelist_ids = fields.Many2many(
        'tariff.pricelist',
        'tariff_aggregation_wizard_draft_pricelist_rel',
        'wizard_id',
        'pricelist_id',
        string='Existing Draft Pricelists',
        readonly=True,
    )

    def _check_new_effective(self):
        for rec in self:
            expected_min_date = fields.Date.today(rec) + timedelta(days=2)
            if rec.new_effective < expected_min_date:
                _logger.info("ppp new_effective: %s, today: %s", rec.new_effective, expected_min_date)
                raise UserError(_('New Effective must be at least 2 days from today.'))

    def _get_existing_draft_pricelists(self, aggregations):
        draft_pricelists = self.env['tariff.pricelist'].sudo().browse()
        for aggregation in aggregations:
            draft_pricelists |= aggregation.pricelist_ids.sudo().filtered(
                lambda pricelist: pricelist.tariff_id == self.tariff_id
                and pricelist.tariff_type == 'base_price'
                and pricelist.bed_type_id.id == -1
                and pricelist.state == 'draft'
                and pricelist.active
            )
        return draft_pricelists

    def _get_pending_aggregations(self):
        self._check_new_effective()
        aggregations = self.aggregation_ids.filtered(lambda aggregation: aggregation.state == 'pending')
        if not aggregations:
            raise exceptions.ValidationError(_('Please select pending aggregation records.'))
        return aggregations

    def action_clear(self):
        self.ensure_one()
        return _tariff_wizard_open_new(self)

    def action_update(self):
        self.ensure_one()
        aggregations = self._get_pending_aggregations()
        draft_pricelists = self._get_existing_draft_pricelists(aggregations)
        if draft_pricelists:
            self.write({
                'confirmation_required': True,
                'draft_pricelist_ids': [(6, 0, draft_pricelists.ids)],
            })
            return _tariff_wizard_reopen(self)

        aggregations._realize_to_baseprice(self.tariff_id.id, self.new_effective)
        return _tariff_wizard_stay_open(self)

    def action_confirm_update(self):
        self.ensure_one()
        aggregations = self._get_pending_aggregations()
        aggregations._realize_to_baseprice(self.tariff_id.id, self.new_effective)
        self.write({
            'confirmation_required': False,
            'draft_pricelist_ids': [(5, 0, 0)],
        })
        return _tariff_wizard_stay_open(self)

