    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'request_no'
    _order = 'id desc'

    request_no = fields.Char(default='/', required=True, readonly=True, copy=False, index=True)
    request_date = fields.Datetime(default=fields.Datetime.now, required=True)
    request_valid_date = fields.Datetime(readonly=True, copy=False)
    company_id = fields.Many2one('res.company', required=True, default=lambda self: self.env.company)
    budget_group_id = fields.Many2one('eproc.budget.group', required=True, string='Group Division')
    budget_category_id = fields.Many2one('eproc.budget.group', required=True, string='Budget Category')
    user_id = fields.Many2one('res.users', required=True, readonly=True, default=lambda self: self.env.user)
    period_year = fields.Integer(required=True, default=lambda self: fields.Date.context_today(self.with_context(tz=BUSINESS_TZ)).year)
    budget_type = fields.Selection([('initial', 'Initial'), ('reallocate', 'Re-Allocate Item'),
                                    ('efficiency', 'Re-Allocate Efficiency')], required=True, default='initial')
    budget_item_ids = fields.One2many('eproc.budget.item', 'request_id', string='New Budget Request', copy=False)
    allocation_ids = fields.One2many('eproc.budget.allocation', 'request_id', string='Source Allocation', copy=False)
    budget_source_ids = fields.Many2many('eproc.budget.item', compute='_compute_source_totals', string='Budget Sources')
    budget_pending_total = fields.Float(compute='_compute_source_totals', string='Available Unrealized Total')
    budget_efficiency_total = fields.Float(compute='_compute_source_totals', string='Available Efficiency Total')
    budget_total = fields.Float(compute='_compute_budget_total', store=True)
    notes = fields.Text()
    active = fields.Boolean(default=True)
    state = fields.Selection([('draft', 'Draft'), ('approval', 'Approval'), ('validate', 'Validated'),
                              ('rejected', 'Rejected'), ('cancel', 'Cancelled')], default='draft', readonly=True, tracking=True)
    approval_type_id = fields.Many2one('eproc.approval.type', string='Approval Type')
    approval_rule_id = fields.Many2one('eproc.approval.rule', readonly=True, copy=False)
    approval_rule_sequence = fields.Integer(readonly=True, copy=False)
    approval_next_stored = fields.Char(string='Next Approval', readonly=True, copy=False)
